          {/* Existing Vendor Portal Modal */}
          <VendorPortalModal
            isOpen={vendorPortalOpen}
            onClose={() => setVendorPortalOpen(false)}
          />
        </main>
      </SmoothScroll>
    </AudioProvider>


  );
}

"use client";

import React, { useRef, useMemo } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

export type LightingMode = "noon" | "sunset" | "night";

interface ArchitecturalCaveProps {
  scrollProgress: number;
  lightingMode: LightingMode;
  wireframeMode: boolean;
}

export function ArchitecturalCave({
  scrollProgress,
  lightingMode,
  wireframeMode
}: ArchitecturalCaveProps) {
  const caveGroupRef = useRef<THREE.Group>(null);
  const colonnadeRef = useRef<THREE.Group>(null);
  const waterRef = useRef<THREE.Mesh>(null);
  const skylightGlowRef = useRef<THREE.Mesh>(null);

  // Colors based on lighting mode
  const { stoneColor, accentGlow, waterColor, roughness } = useMemo(() => {
    switch (lightingMode) {
      case "noon":
        return {
          stoneColor: "#78716c", // Warm natural concrete/travertine
          accentGlow: "#ffffff",
          waterColor: "#0f766e",
          roughness: 0.35
        };
      case "sunset":
        return {
          stoneColor: "#7c2d12", // Terracotta ochre raking light
          accentGlow: "#f59e0b",
          waterColor: "#115e59",
          roughness: 0.4
        };
      case "night":
      default:
        return {
          stoneColor: "#1c1917", // Nocturnal basalt
          accentGlow: "#fbbf24",
          waterColor: "#042f2e",
          roughness: 0.25
        };
    }
  }, [lightingMode]);

  useFrame((state, delta) => {
    if (colonnadeRef.current) {
      // Subtle architectural breathing
      colonnadeRef.current.position.y = Math.sin(state.clock.elapsedTime * 0.6) * 0.05;
    }
    if (skylightGlowRef.current) {
      const pulse = Math.sin(state.clock.elapsedTime * 1.5) * 0.15 + 0.85;
      (skylightGlowRef.current.material as THREE.MeshStandardMaterial).emissiveIntensity = pulse * 1.8;
    }
    if (waterRef.current) {
      // Subtle caustic shimmer
      (waterRef.current.material as THREE.MeshStandardMaterial).roughness =
        0.1 + Math.sin(state.clock.elapsedTime * 2.0) * 0.05;
    }
  });

  return (
    <group ref={caveGroupRef} position={[0, -0.5, 0]}>
      {/* 1. MONOLITHIC BRUTALIST CAVE WALLS (Carved Subterranean Strata) */}
      <group position={[0, 3, -12]}>
        {/* Rear Mega-Wall */}
        <mesh receiveShadow>
          <boxGeometry args={[45, 24, 2]} />
          <meshStandardMaterial
            color={stoneColor}
            roughness={roughness}
            metalness={0.2}
            wireframe={wireframeMode}
          />
        </mesh>

        {/* Diagonal Slanted Strata / Light-Well Canopy */}
        <mesh position={[0, 11, 4]} rotation={[-0.45, 0, 0]} receiveShadow>
          <boxGeometry args={[42, 14, 1.8]} />
          <meshStandardMaterial
            color={stoneColor}
            roughness={roughness}
            metalness={0.25}
            wireframe={wireframeMode}
          />
        </mesh>
      </group>

      {/* 2. ARCHITECTURAL TRAVERTINE COLONNADE & PAVILION */}
      <group ref={colonnadeRef} position={[0, 0, 0]}>
        {/* Stepped Plinth / Terrace Floor */}
        <mesh position={[0, -0.4, 0]} receiveShadow>
          <boxGeometry args={[16, 0.8, 16]} />
          <meshStandardMaterial
            color={lightingMode === "night" ? "#292524" : "#a8a29e"}
            roughness={0.2}
            metalness={0.1}
            wireframe={wireframeMode}
          />
        </mesh>

        {/* Rhythmic Architectural Columns */}
        {[-5.5, -2.75, 2.75, 5.5].map((x, i) => (
          <group key={i} position={[x, 2.5, -3.5]}>
            <mesh castShadow receiveShadow>
              <boxGeometry args={[0.7, 6.2, 0.7]} />
              <meshStandardMaterial
                color={lightingMode === "night" ? "#44403c" : "#d6d3d1"}
                roughness={0.25}
                metalness={0.2}
                wireframe={wireframeMode}
              />
            </mesh>
            {/* Column Capital / Lighting Accent */}
            <mesh position={[0, 3.15, 0]}>
              <boxGeometry args={[0.9, 0.15, 0.9]} />
              <meshStandardMaterial
                color={accentGlow}
                emissive={accentGlow}
                emissiveIntensity={lightingMode === "night" ? 1.5 : 0.3}
              />
            </mesh>
          </group>
        ))}

        {/* Cantilevered Floating Roof Slab */}
        <mesh position={[0, 5.7, -2]} castShadow receiveShadow>
          <boxGeometry args={[15, 0.6, 12]} />
          <meshStandardMaterial
            color={stoneColor}
            roughness={roughness}
            metalness={0.3}
            wireframe={wireframeMode}
          />
        </mesh>

        {/* Central Skylight Oculus Void & Glowing Core */}
        <mesh ref={skylightGlowRef} position={[0, 5.8, -2]} rotation={[Math.PI / 2, 0, 0]}>
          <ringGeometry args={[1.5, 2.2, 32]} />
          <meshStandardMaterial
            color={accentGlow}
            emissive={accentGlow}
            emissiveIntensity={2.0}
            side={THREE.DoubleSide}
          />
        </mesh>
      </group>

      {/* 3. REFLECTIVE SUBTERRANEAN WATER POOL (Floor Basin) */}
      <mesh
        ref={waterRef}
        rotation={[-Math.PI / 2, 0, 0]}
        position={[0, -0.65, 4]}
        receiveShadow
      >
        <planeGeometry args={[38, 28, 64, 64]} />
        <meshStandardMaterial
          color={waterColor}
          roughness={0.08}
          metalness={0.9}
          transparent
          opacity={0.88}
          wireframe={wireframeMode}
        />
      </mesh>

      {/* 4. FLOATING ARCHITECTURAL BEACONS / AMBIENT PRISMS */}
      <group position={[0, 1.5, 0]}>
        {[...Array(6)].map((_, i) => {
          const angle = (i / 6) * Math.PI * 2;
          const radius = 6.5;
          const x = Math.cos(angle) * radius;
          const z = Math.sin(angle) * radius;
          return (
            <mesh key={i} position={[x, 0.5 + (i % 2) * 0.4, z]} rotation={[0, angle, 0.3]}>
              <octahedronGeometry args={[0.28, 0]} />
              <meshStandardMaterial
                color={accentGlow}
                emissive={accentGlow}
                emissiveIntensity={lightingMode === "night" ? 1.8 : 0.5}
                roughness={0.1}
                metalness={0.8}
                wireframe={wireframeMode}
              />
            </mesh>
          );
        })}
      </group>
    </group>
  );
}

"use client";

import React, { useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

export function IglooDome({ scrollProgress }: { scrollProgress: number }) {
  const groupRef = useRef<THREE.Group>(null);
  const cageRef = useRef<THREE.LineSegments>(null);
  const innerRef = useRef<THREE.Mesh>(null);

  useFrame((state, delta) => {
    if (!groupRef.current) return;
    // Gentle idle rotation
    groupRef.current.rotation.y += delta * 0.05;

    // React to scroll progress: slowly explode or rotate facets as user scrolls
    if (cageRef.current) {
      cageRef.current.rotation.y -= delta * 0.03;
    }

    if (innerRef.current) {
      const pulse = Math.sin(state.clock.elapsedTime * 1.5) * 0.15 + 0.85;
      (innerRef.current.material as THREE.MeshStandardMaterial).emissiveIntensity = pulse * 1.5;
    }
  });

  return (
    <group ref={groupRef} position={[0, -0.2, 0]}>
      {/* Outer Faceted Geometric Dome */}
      <mesh castShadow receiveShadow>
        <sphereGeometry args={[2.8, 14, 10, 0, Math.PI * 2, 0, Math.PI * 0.52]} />
        <meshStandardMaterial
          color="#dbeafe"
          roughness={0.25}
          metalness={0.1}
          transparent
          opacity={0.88}
          flatShading={true}
          side={THREE.DoubleSide}
        />
      </mesh>

      {/* Wireframe Outline Cage (Iconic Igloo.inc geometric lattice) */}
      <lineSegments ref={cageRef} scale={[1.015, 1.015, 1.015]}>
        <wireframeGeometry args={[new THREE.SphereGeometry(2.8, 14, 10, 0, Math.PI * 2, 0, Math.PI * 0.52)]} />
        <lineBasicMaterial color="#93c5fd" transparent opacity={0.45} linewidth={1} />
      </lineSegments>

      {/* Igloo Entrance Tunnel */}
      <group position={[0, 0.4, 2.6]} rotation={[0, 0, 0]}>
        <mesh castShadow receiveShadow>
          <cylinderGeometry args={[0.9, 1.0, 1.4, 8, 1, true, -Math.PI * 0.5, Math.PI]} />
          <meshStandardMaterial
            color="#bfdbfe"
            roughness={0.3}
            metalness={0.1}
            flatShading
            side={THREE.DoubleSide}
          />
        </mesh>
      </group>

      {/* Inner Warm/Cyan Core Glow */}
      <mesh ref={innerRef} position={[0, 0.8, 0]}>
        <icosahedronGeometry args={[0.9, 2]} />
        <meshStandardMaterial
          color="#38bdf8"
          emissive="#0284c7"
          emissiveIntensity={1.2}
          roughness={0.1}
          metalness={0.9}
          wireframe
        />
      </mesh>

      {/* Floating Shard Rings around the dome */}
      <group position={[0, 1.2, 0]} rotation={[0.2, 0, 0.3]}>
        {[...Array(12)].map((_, i) => {
          const angle = (i / 12) * Math.PI * 2;
          const radius = 3.6 + Math.sin(i * 1.5) * 0.4;
          const x = Math.cos(angle) * radius;
          const z = Math.sin(angle) * radius;
          const y = (i % 2 === 0 ? 0.3 : -0.3);
          return (
            <mesh key={i} position={[x, y, z]} rotation={[i, i * 0.5, 0]}>
              <boxGeometry args={[0.22, 0.22, 0.08]} />
              <meshStandardMaterial
                color="#60a5fa"
                metalness={0.8}
                roughness={0.2}
                transparent
                opacity={0.7}
              />
            </mesh>
          );
        })}
      </group>
    </group>
  );
}

"use client";

import React, { useEffect, useState, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { loadDracoGeometry } from "@/utils/dracoLoader";

interface IglooWorldProps {
  scrollProgress: number;
}

export function IglooWorld({ scrollProgress }: IglooWorldProps) {
  const [iglooGeom, setIglooGeom] = useState<THREE.BufferGeometry | null>(null);
  const [outlineGeom, setOutlineGeom] = useState<THREE.BufferGeometry | null>(null);
  const [mountainGeom, setMountainGeom] = useState<THREE.BufferGeometry | null>(null);
  const [groundGeom, setGroundGeom] = useState<THREE.BufferGeometry | null>(null);
  const [ringGeom, setRingGeom] = useState<THREE.BufferGeometry | null>(null);
  const [ring2Geom, setRing2Geom] = useState<THREE.BufferGeometry | null>(null);

  const ringRef = useRef<THREE.Mesh>(null);
  const ring2Ref = useRef<THREE.Mesh>(null);
  const coreRef = useRef<THREE.Mesh>(null);
  const iglooGroup = useRef<THREE.Group>(null);

  useEffect(() => {
    loadDracoGeometry("/assets/geometries/igloo.drc").then(setIglooGeom).catch(() => {});
    loadDracoGeometry("/assets/geometries/igloo/igloo_outline.drc").then(setOutlineGeom).catch(() => {});
    loadDracoGeometry("/assets/geometries/mountain.drc").then(setMountainGeom).catch(() => {});
    loadDracoGeometry("/assets/geometries/ground.drc").then(setGroundGeom).catch(() => {});
    loadDracoGeometry("/assets/geometries/shattered_ring.drc").then(setRingGeom).catch(() => {});
    loadDracoGeometry("/assets/geometries/shattered_ring2.drc").then(setRing2Geom).catch(() => {});
  }, []);

  useFrame((state, delta) => {
    // Idle rotation of the rings and subtle core breathing
    if (ringRef.current) {
      ringRef.current.rotation.y += delta * 0.12;
      ringRef.current.rotation.z += delta * 0.05;
    }
    if (ring2Ref.current) {
      ring2Ref.current.rotation.y -= delta * 0.08;
      ring2Ref.current.rotation.x += delta * 0.04;
    }
    if (coreRef.current) {
      const pulse = Math.sin(state.clock.elapsedTime * 2.0) * 0.2 + 0.8;
      (coreRef.current.material as THREE.MeshStandardMaterial).emissiveIntensity = pulse * 2.2;
    }
    if (iglooGroup.current) {
      // Subtle float
      iglooGroup.current.position.y = Math.sin(state.clock.elapsedTime * 0.8) * 0.08;
    }
  });

  return (
    <group position={[0, 0, 0]}>
      {/* 1. MOUNTAINS (Glacial backdrop) */}
      {mountainGeom && (
        <mesh
          geometry={mountainGeom}
          position={[0, -2, -18]}
          scale={[1.8, 1.8, 1.8]}
        >
          <meshStandardMaterial
            color="#1e1b4b"
            roughness={0.65}
            metalness={0.1}
            flatShading
          />
        </mesh>
      )}

      {/* 2. GROUND TERRAIN (Snow & Ice) */}
      {groundGeom && (
        <mesh
          geometry={groundGeom}
          position={[0, -1.8, 0]}
          scale={[1.2, 1.2, 1.2]}
          receiveShadow
        >
          <meshStandardMaterial
            color="#0d0c18"
            roughness={0.4}
            metalness={0.25}
            flatShading
          />
        </mesh>
      )}

      {/* 3. CENTRAL IGLOO GROUP */}
      <group ref={iglooGroup} position={[0, 0, 0]}>
        {/* Real Draco Igloo Model */}
        {iglooGeom ? (
          <mesh
            geometry={iglooGeom}
            scale={[1.0, 1.0, 1.0]}
            castShadow
            receiveShadow
          >
            <meshStandardMaterial
              color="#e0e7ff"
              roughness={0.2}
              metalness={0.15}
              transparent
              opacity={0.92}
              flatShading
              side={THREE.DoubleSide}
            />
          </mesh>
        ) : (
          /* Procedural Fallback while geometry parses */
          <mesh castShadow receiveShadow>
            <sphereGeometry args={[2.5, 16, 12, 0, Math.PI * 2, 0, Math.PI * 0.52]} />
            <meshStandardMaterial
              color="#dbeafe"
              roughness={0.25}
              metalness={0.1}
              transparent
              opacity={0.88}
              flatShading
              side={THREE.DoubleSide}
            />
          </mesh>
        )}

        {/* Real Igloo Wireframe Lattice Outline */}
        {outlineGeom ? (
          <lineSegments geometry={outlineGeom} scale={[1.008, 1.008, 1.008]}>
            <lineBasicMaterial color="#67e8f9" transparent opacity={0.65} linewidth={1} />
          </lineSegments>
        ) : (
          <lineSegments scale={[1.01, 1.01, 1.01]}>
            <wireframeGeometry args={[new THREE.SphereGeometry(2.5, 16, 12, 0, Math.PI * 2, 0, Math.PI * 0.52)]} />
            <lineBasicMaterial color="#93c5fd" transparent opacity={0.45} linewidth={1} />
          </lineSegments>
        )}

        {/* Inner Glowing Core */}
        <mesh ref={coreRef} position={[0, 0.8, 0]}>
          <icosahedronGeometry args={[0.7, 2]} />
          <meshStandardMaterial
            color="#38bdf8"
            emissive="#0284c7"
            emissiveIntensity={1.8}
            roughness={0.1}
            metalness={0.9}
            wireframe
          />
        </mesh>
      </group>

      {/* 4. ORBITING SHATTERED RINGS */}
      {ringGeom && (
        <mesh
          ref={ringRef}
          geometry={ringGeom}
          position={[0, 1.2, 0]}
          scale={[1.1, 1.1, 1.1]}
        >
          <meshStandardMaterial
            color="#38bdf8"
            emissive="#0369a1"
            emissiveIntensity={0.6}
            metalness={0.85}
            roughness={0.15}
            transparent
            opacity={0.85}
            flatShading
          />
        </mesh>
      )}

      {ring22GeomCheck(ring2Geom, ring2Ref)}
    </group>
  );
}

function ring22GeomCheck(
  geom: THREE.BufferGeometry | null,
  ref: React.RefObject<THREE.Mesh | null>
) {
  if (!geom) return null;
  return (
    <mesh
      ref={ref as unknown as React.RefObject<THREE.Mesh | null>}
      geometry={geom}
      position={[0, 1.4, 0]}
      scale={[1.2, 1.2, 1.2]}
    >
      <meshStandardMaterial
        color="#818cf8"
        emissive="#4338ca"
        emissiveIntensity={0.5}
        metalness={0.9}
        roughness={0.2}
        transparent
        opacity={0.8}
        flatShading
      />
    </mesh>
  );
}

"use client";

import React, { useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

// Snow particle arrays are generated once at module load so Math.random
// is never invoked during component render (react-hooks/purity).
function createSnowArrays(count: number): [Float32Array, Float32Array] {
  const pos = new Float32Array(count * 3);
  const sc = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    pos[i * 3 + 0] = (Math.random() - 0.5) * 28;
    pos[i * 3 + 1] = (Math.random() - 0.5) * 35 - 5;
    pos[i * 3 + 2] = (Math.random() - 0.5) * 20;
    sc[i] = Math.random() * 0.04 + 0.015;
  }
  return [pos, sc];
}

const DEFAULT_COUNT = 800;
const [DEFAULT_POSITIONS, DEFAULT_SCALES] = createSnowArrays(DEFAULT_COUNT);

export function ParticleSnow({ count = DEFAULT_COUNT }: { count?: number }) {
  const pointsRef = useRef<THREE.Points>(null);

  const [positions, scales] = useMemo(() => {
    if (count === DEFAULT_COUNT) return [DEFAULT_POSITIONS, DEFAULT_SCALES];
    return createSnowArrays(count);
  }, [count]);

  useFrame((_, delta) => {
    if (!pointsRef.current) return;
    const array = pointsRef.current.geometry.attributes.position.array as Float32Array;
    for (let i = 0; i < count; i++) {
      // Gently drift downwards and sideways
      array[i * 3 + 1] -= delta * 0.4;
      array[i * 3 + 0] += Math.sin(array[i * 3 + 1] * 0.5) * 0.005;

      // Wrap around when falling past bottom
      if (array[i * 3 + 1] < -25) {
        array[i * 3 + 1] = 12;
      }
    }
    pointsRef.current.geometry.attributes.position.needsUpdate = true;
  });

  return (
    <points ref={pointsRef}>
      <bufferGeometry>
        <bufferAttribute
          attach="attributes-position"
          args={[positions, 3]}
        />
      </bufferGeometry>
      <pointsMaterial
        size={0.06}
        color="#bae6fd"
        transparent
        opacity={0.65}
        blending={THREE.AdditiveBlending}
        depthWrite={false}
      />
    </points>
  );
}

