export type AuditEventSeverity =
  | "Informational"
  | "Warning"
  | "Critical";

export type AuditEventOutcome =
  | "Success"
  | "Failed"
  | "Denied"
  | "Pending";

export type AuditEventCategory =
  | "Authentication"
  | "Client Management"
  | "Vendor Management"
  | "Project Management"
  | "Invoice Management"
  | "Financial Approval"
  | "Cash Settlement"
  | "Document Access"
  | "Configuration"
  | "Security"
  | "Other";

export interface AdminAuditEvent {
  id: string;
  eventReference: string;
  occurredAt: string;

  actorId: string | null;
  actorName: string;
  actorRole: string;

  action: string;
  category: AuditEventCategory;
  severity: AuditEventSeverity;
  outcome: AuditEventOutcome;

  entityType?: string;
  entityReference?: string;

  description: string;

  ipAddress?: string;
  source?: string;

  correlationId?: string;
  reason?: string;

