    field: string;
    previousValue: string | null;
    newValue: string | null;
  }[];
}

export interface AuditLogSummary {
  totalEvents: number;
  criticalEvents: number;
  failedEvents: number;
  deniedEvents: number;
}

export interface AdminAuditLogViewerProps {
  events: AdminAuditEvent[];
  summary?: AuditLogSummary;

  loading?: boolean;
  error?: string;

  currentPage: number;
  totalPages: number;
  totalRecords: number;

  onRefresh?: () => void;
  onPageChange: (page: number) => void;

  onExport?: (filters: {
    search: string;
    category: string;
    severity: string;
    outcome: string;
    fromDate: string;
    toDate: string;
  }) => void;

  onOpenEntity?: (
    entityType: string,
    entityReference: string
  ) => void;

  onOpenActor?: (actorId: string) => void;
}

type AuditFilter = {
  search: string;
  category: string;
  severity: string;
  outcome: string;
  fromDate: string;
  toDate: string;
};

const INITIAL_FILTERS: AuditFilter = {
  search: "",
  category: "All",
  severity: "All",
  outcome: "All",
  fromDate: "",
  toDate: "",
};

const CATEGORIES: AuditEventCategory[] = [
  "Authentication",
  "Client Management",
  "Vendor Management",
  "Project Management",
  "Invoice Management",
  "Financial Approval",
  "Cash Settlement",
  "Document Access",
  "Configuration",
  "Security",
  "Other",
];

const SEVERITIES: AuditEventSeverity[] = [
  "Informational",
  "Warning",
  "Critical",
];

const OUTCOMES: AuditEventOutcome[] = [
  "Success",
  "Failed",
  "Denied",
  "Pending",
];

function formatDateTime(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return value;
  }

  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: true,
  }).format(date);
}

function severityClass(severity: AuditEventSeverity) {
  switch (severity) {
    case "Critical":
      return "bg-[#F8E8E5] text-[#A04F43]";

    case "Warning":
      return "bg-[#F5EFDF] text-[#98743F]";

    default:
      return "bg-[#EAEFEA] text-[#607A60]";
  }
}

function outcomeClass(outcome: AuditEventOutcome) {
  switch (outcome) {
    case "Success":
      return "bg-[#EAF1E8] text-[#547A51]";

    case "Failed":
    case "Denied":
      return "bg-[#F8EAE7] text-[#9A5147]";

    default:
      return "bg-[#F4EFE2] text-[#94743F]";
  }
}

export function AdminAuditLogViewer({
  events,
  summary,
  loading = false,
  error,
  currentPage,
  totalPages,
  totalRecords,
  onRefresh,
  onPageChange,
  onExport,
  onOpenEntity,
  onOpenActor,
}: AdminAuditLogViewerProps) {
  const [filters, setFilters] =
    useState<AuditFilter>(INITIAL_FILTERS);

  const [selectedEvent, setSelectedEvent] =
    useState<AdminAuditEvent | null>(null);

  const [showFilters, setShowFilters] = useState(false);

  const visibleEvents = useMemo(() => {
    const query = filters.search.trim().toLowerCase();

    return events.filter((event) => {
      if (
        query &&
        ![
          event.eventReference,
          event.actorName,
          event.actorRole,
          event.action,
          event.description,
          event.entityReference ?? "",
          event.entityType ?? "",
          event.correlationId ?? "",
        ].some((value) => value.toLowerCase().includes(query))
      ) {
        return false;
      }

      if (
        filters.category !== "All" &&
        event.category !== filters.category
      ) {
        return false;
      }

      if (
        filters.severity !== "All" &&
        event.severity !== filters.severity
      ) {
        return false;
      }

      if (
        filters.outcome !== "All" &&
        event.outcome !== filters.outcome
      ) {
        return false;
      }

      const eventDate = new Date(event.occurredAt);

      if (Number.isNaN(eventDate.getTime())) {
        return false;
      }

      if (filters.fromDate) {
        const from = new Date(`${filters.fromDate}T00:00:00`);

        if (eventDate < from) return false;
      }

      if (filters.toDate) {
        const to = new Date(`${filters.toDate}T23:59:59.999`);

        if (eventDate > to) return false;
      }

      return true;
    });
  }, [events, filters]);

  const activeFilterCount = [
    filters.category !== "All",
    filters.severity !== "All",
    filters.outcome !== "All",
    Boolean(filters.fromDate),
    Boolean(filters.toDate),
  ].filter(Boolean).length;

  function updateFilter<K extends keyof AuditFilter>(
    key: K,
    value: AuditFilter[K]
  ) {
    setFilters((current) => ({
      ...current,
      [key]: value,
    }));
  }

  function clearFilters() {
    setFilters(INITIAL_FILTERS);
  }

  function handleExport() {
    onExport?.({
      search: filters.search,
      category: filters.category,
      severity: filters.severity,
      outcome: filters.outcome,
      fromDate: filters.fromDate,
      toDate: filters.toDate,
    });
  }

  const hasDateError =
    Boolean(filters.fromDate && filters.toDate) &&
    filters.fromDate > filters.toDate;

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-9 md:px-10 md:py-12 lg:px-12">

      {/* Header */}
      <header className="flex flex-col justify-between gap-6 border-b border-[#D8D6D0] pb-8 md:flex-row md:items-end">
        <div>
          <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
            Administration / Governance
          </p>

          <h1 className="mt-4 font-serif text-4xl text-[#171717] md:text-5xl">
            Audit Log
          </h1>

          <p className="mt-3 max-w-xl text-sm leading-7 text-[#77736C]">
            Review recorded administrative actions, security events,
            financial decisions and changes across the platform.
          </p>

          <div className="mt-4 flex flex-wrap items-center gap-3">
            <span className="inline-flex items-center gap-2 font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
              <LockKeyhole size={12} />
              Read-only event history
            </span>

            <span className="h-1 w-1 rounded-full bg-[#A58A64]" />

            <span className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
              {totalRecords.toLocaleString("en-IN")} records
            </span>
          </div>
        </div>

        <div className="flex flex-wrap gap-3">
          {onExport && (
            <button
              type="button"
              onClick={handleExport}
              disabled={loading || hasDateError}
              className="inline-flex items-center gap-2 border border-[#D8D6D0] bg-white px-5 py-3 text-[10px] uppercase tracking-widest text-[#55514A] hover:border-[#A58A64] disabled:opacity-40"
            >
              <ArrowDownToLine size={14} />
              Export Logs
            </button>
          )}

          {onRefresh && (
            <button
              type="button"
              onClick={onRefresh}
              disabled={loading}
              className="inline-flex items-center gap-2 bg-[#171717] px-5 py-3 text-[10px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:opacity-40"
            >
              <RefreshCw size={14} />
              Refresh
            </button>
          )}
        </div>
      </header>

      {error && (
        <div
          role="alert"
          className="mt-6 flex items-start gap-3 border border-[#E3C9C5] bg-[#FAF3F1] p-5"
        >
          <AlertCircle
            size={18}
            className="mt-0.5 shrink-0 text-[#9A5147]"
          />

          <p className="text-xs leading-6 text-[#805B55]">
            {error}
          </p>
        </div>
      )}

      {/* Summary */}
      {summary && (
        <section className="mt-9 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
          <SummaryCard
            label="Total Events"
            value={summary.totalEvents}
            icon={<Activity size={18} />}
          />

          <SummaryCard
            label="Critical Events"
            value={summary.criticalEvents}
            icon={<ShieldAlert size={18} />}
            warning
          />

          <SummaryCard
            label="Failed Events"
            value={summary.failedEvents}
            icon={<AlertCircle size={18} />}
            warning
          />

          <SummaryCard
            label="Denied Actions"
            value={summary.deniedEvents}
            icon={<ShieldCheck size={18} />}
          />
        </section>
      )}

      {/* Search and Filters */}
      <section className="mt-9">
        <div className="flex flex-col gap-4 lg:flex-row">
          <div className="relative flex-1">
            <Search
              size={16}
              className="absolute left-4 top-1/2 -translate-y-1/2 text-[#99958D]"
            />

            <input
              value={filters.search}
              onChange={(event) =>
                updateFilter("search", event.target.value)
              }
              placeholder="Search event, actor, reference or action..."
              aria-label="Search audit events"
              className="h-12 w-full border border-[#D8D6D0] bg-white pl-11 pr-4 text-xs text-[#33312D] outline-none placeholder:text-[#AAA69E] focus:border-[#A58A64]"
            />
          </div>

          <button
            type="button"
            onClick={() => setShowFilters((value) => !value)}
            aria-expanded={showFilters}
            className="inline-flex h-12 items-center justify-center gap-2 border border-[#D8D6D0] bg-white px-5 text-[10px] uppercase tracking-widest text-[#55514A]"
          >
            <Filter size={14} />
            Filters

            {activeFilterCount > 0 && (
              <span className="flex h-5 w-5 items-center justify-center rounded-full bg-[#A58A64] text-[9px] text-white">
                {activeFilterCount}
              </span>
            )}

            <ChevronDown
              size={13}
              className={showFilters ? "rotate-180" : ""}
            />
          </button>
        </div>

        {showFilters && (
          <div className="mt-3 grid grid-cols-1 gap-4 border border-[#D8D6D0] bg-white p-5 md:grid-cols-2 xl:grid-cols-5">
            <FilterSelect
              label="Category"
              value={filters.category}
              options={["All", ...CATEGORIES]}
              onChange={(value) =>
                updateFilter("category", value)
              }
            />

            <FilterSelect
              label="Severity"
              value={filters.severity}
              options={["All", ...SEVERITIES]}
              onChange={(value) =>
                updateFilter("severity", value)
              }
            />

            <FilterSelect
              label="Outcome"
              value={filters.outcome}
              options={["All", ...OUTCOMES]}
              onChange={(value) =>
                updateFilter("outcome", value)
              }
            />

            <label className="block">
              <span className="mb-2 block font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
                From Date
              </span>

              <input
                type="date"
                value={filters.fromDate}
                onChange={(event) =>
                  updateFilter("fromDate", event.target.value)
                }
                className="h-10 w-full border border-[#D8D6D0] px-3 text-xs text-[#55514A] outline-none focus:border-[#A58A64]"
              />
            </label>

            <label className="block">
              <span className="mb-2 block font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
                To Date
              </span>

              <input
                type="date"
                value={filters.toDate}
                onChange={(event) =>
                  updateFilter("toDate", event.target.value)
                }
                className="h-10 w-full border border-[#D8D6D0] px-3 text-xs text-[#55514A] outline-none focus:border-[#A58A64]"
              />
            </label>

            <div className="flex items-center justify-between gap-3 md:col-span-2 xl:col-span-5">
              {hasDateError ? (
                <p className="text-[10px] text-[#9A5147]">
                  The start date cannot be after the end date.
                </p>
              ) : (
                <p className="text-[10px] text-[#99958D]">
                  Filters apply to the currently loaded event records.
                </p>
              )}

              <button
                type="button"
                onClick={clearFilters}
                className="inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#987543]"
              >
                <X size={13} />
                Clear Filters
              </button>
            </div>
          </div>
        )}
      </section>

      {/* Event List */}
      <section className="mt-8">
        <div className="flex items-end justify-between border-b border-[#D8D6D0] pb-4">
          <div>
            <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
              Recorded Activity
            </p>

            <h2 className="mt-2 font-serif text-2xl text-[#171717]">
              System Events
            </h2>
          </div>

          <p className="font-mono text-[9px] text-[#99958D]">
            {visibleEvents.length.toLocaleString("en-IN")} SHOWN
          </p>
        </div>

        {loading ? (
          <div className="flex min-h-64 items-center justify-center">
            <p className="font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
              Loading audit records...
            </p>
          </div>
        ) : hasDateError ? (
          <div className="mt-5 border border-[#E3C9C5] bg-[#FAF3F1] p-8 text-center">
            <p className="text-xs text-[#805B55]">
              Correct the date range to view audit events.
            </p>
          </div>
        ) : visibleEvents.length === 0 ? (
          <div className="mt-5 border border-[#D8D6D0] bg-white p-12 text-center">
            <Activity
              size={28}
              className="mx-auto text-[#A58A64]"
            />

            <h3 className="mt-4 font-serif text-xl text-[#171717]">
              No matching events
            </h3>

            <p className="mt-2 text-xs text-[#77736C]">
              Try changing your search terms or filters.
            </p>
          </div>
        ) : (
          <div className="mt-5 space-y-3">
            {visibleEvents.map((event) => (
              <AuditEventCard
                key={event.id}
                event={event}
                onOpen={() => setSelectedEvent(event)}
              />
            ))}
          </div>
        )}
      </section>

      {/* Pagination */}
      {!loading && totalPages > 1 && (
        <div className="mt-8 flex flex-wrap items-center justify-between gap-4 border-t border-[#D8D6D0] pt-5">
          <p className="text-[10px] text-[#77736C]">
            Page {currentPage} of {totalPages}
            {" · "}
            {totalRecords.toLocaleString("en-IN")} total records
          </p>

          <div className="flex gap-2">
            <button
              type="button"
              disabled={currentPage <= 1}
              onClick={() => onPageChange(currentPage - 1)}
              className="border border-[#D8D6D0] bg-white px-4 py-2 text-[9px] uppercase tracking-widest text-[#55514A] disabled:opacity-40"
            >
              Previous
            </button>

            <button
              type="button"
              disabled={currentPage >= totalPages}
              onClick={() => onPageChange(currentPage + 1)}
              className="border border-[#171717] bg-[#171717] px-4 py-2 text-[9px] uppercase tracking-widest text-white disabled:opacity-40"
            >
              Next
            </button>
          </div>
        </div>
      )}

      {/* Detail Drawer */}
      {selectedEvent && (
        <AuditEventDetail
          event={selectedEvent}
          onClose={() => setSelectedEvent(null)}
          onOpenActor={onOpenActor}
          onOpenEntity={onOpenEntity}
        />
      )}
    </main>
  );
}

function SummaryCard({
  label,
  value,
  icon,
  warning = false,
}: {
  label: string;
  value: number;
  icon: ReactNode;
  warning?: boolean;
}) {
  return (
    <div className="border border-[#D8D6D0] bg-white p-5">
      <div className="flex items-center justify-between">
        <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
          {label}
        </p>

        <span className={warning ? "text-[#9A5147]" : "text-[#A58A64]"}>
          {icon}
        </span>
      </div>

      <p className="mt-5 font-serif text-3xl text-[#171717]">
        {value.toLocaleString("en-IN")}
      </p>
    </div>
  );
}

function FilterSelect({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: string;
  options: string[];
  onChange: (value: string) => void;
}) {
  return (
    <label className="block">
      <span className="mb-2 block font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
        {label}
      </span>

      <select
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="h-10 w-full border border-[#D8D6D0] bg-white px-3 text-xs text-[#55514A] outline-none focus:border-[#A58A64]"
      >
        {options.map((option) => (
          <option key={option} value={option}>
            {option}
          </option>
        ))}
      </select>
    </label>
  );
}

function AuditEventCard({
  event,
  onOpen,
}: {
  event: AdminAuditEvent;
  onOpen: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onOpen}
      className="w-full border border-[#D8D6D0] bg-white p-5 text-left transition-colors hover:border-[#A58A64] md:p-6"
    >
      <div className="flex flex-col justify-between gap-5 xl:flex-row xl:items-center">
        <div className="flex min-w-0 items-start gap-4">
          <div className="flex h-10 w-10 shrink-0 items-center justify-center border border-[#E5E2DC] bg-[#FAF9F6] text-[#A58A64]">
            {event.severity === "Critical" ? (
              <ShieldAlert size={17} />
            ) : event.category === "Authentication" ? (
              <LockKeyhole size={17} />
            ) : (
              <Activity size={17} />
            )}
          </div>

          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2">
              <span className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                {event.eventReference}
              </span>

              <span
                className={`px-2 py-1 text-[8px] uppercase tracking-widest ${severityClass(event.severity)}`}
              >
                {event.severity}
              </span>

              <span
                className={`px-2 py-1 text-[8px] uppercase tracking-widest ${outcomeClass(event.outcome)}`}
              >
                {event.outcome}
              </span>
            </div>

            <h3 className="mt-3 break-words font-serif text-xl text-[#171717]">
              {event.action}
            </h3>

            <p className="mt-2 max-w-3xl text-xs leading-6 text-[#77736C]">
              {event.description}
            </p>

            <div className="mt-3 flex flex-wrap gap-x-4 gap-y-2 text-[9px] text-[#99958D]">
              <span>{event.category}</span>

              {event.entityReference && (
                <span>
                  {event.entityType}: {event.entityReference}
                </span>
              )}

              <span>{event.actorRole}</span>
            </div>
          </div>
        </div>

        <div className="flex shrink-0 items-center justify-between gap-4 border-t border-[#E5E2DC] pt-4 xl:border-0 xl:pt-0">
          <div className="xl:text-right">
            <p className="text-xs text-[#55514A]">
              {event.actorName}
            </p>

            <p className="mt-2 font-mono text-[9px] text-[#99958D]">
              {formatDateTime(event.occurredAt)}
            </p>
          </div>

          <ArrowUpRight
            size={16}
            className="text-[#A58A64]"
          />
        </div>
      </div>
    </button>
  );
}

function AuditEventDetail({
  event,
  onClose,
  onOpenActor,
  onOpenEntity,
}: {
  event: AdminAuditEvent;
  onClose: () => void;
  onOpenActor?: (actorId: string) => void;
  onOpenEntity?: (
    entityType: string,
    entityReference: string
  ) => void;
}) {
  return (
    <div
      className="fixed inset-0 z-[100] flex justify-end bg-black/40"
      role="presentation"
      onMouseDown={(mouseEvent) => {
        if (mouseEvent.target === mouseEvent.currentTarget) {
          onClose();
        }
      }}
    >
      <aside
        role="dialog"
        aria-modal="true"
        aria-labelledby="audit-detail-title"
        className="h-full w-full max-w-2xl overflow-y-auto bg-[#F7F5F0] shadow-2xl"
      >
        <header className="sticky top-0 z-10 flex items-center justify-between border-b border-[#D8D6D0] bg-[#F7F5F0] px-6 py-5">
          <div>
            <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
              Audit Event Details
            </p>

            <h2
              id="audit-detail-title"
              className="mt-2 font-serif text-2xl text-[#171717]"
            >
              Event Record
            </h2>
          </div>

          <button
            type="button"
            onClick={onClose}
            aria-label="Close event details"
            className="border border-[#D8D6D0] bg-white p-2 text-[#55514A]"
          >
            <X size={17} />
          </button>
        </header>

        <div className="space-y-7 p-6">
          <section className="border border-[#D8D6D0] bg-white p-5">
            <div className="flex flex-wrap items-center gap-2">
              <span className="font-mono text-[9px] text-[#A58A64]">
                {event.eventReference}
              </span>

              <span
                className={`px-2 py-1 text-[8px] uppercase tracking-widest ${severityClass(event.severity)}`}
              >
                {event.severity}
              </span>

              <span
                className={`px-2 py-1 text-[8px] uppercase tracking-widest ${outcomeClass(event.outcome)}`}
              >
                {event.outcome}
              </span>
            </div>

            <h3 className="mt-4 font-serif text-2xl text-[#171717]">
              {event.action}
            </h3>

            <p className="mt-3 text-xs leading-7 text-[#77736C]">
              {event.description}
            </p>
          </section>

          <DetailSection title="Event Information">
            <DetailRow label="Category" value={event.category} />
            <DetailRow label="Event ID" value={event.id} />
            <DetailRow
              label="Occurred At"
              value={formatDateTime(event.occurredAt)}
            />

            <DetailRow
              label="Correlation ID"
              value={event.correlationId ?? "Not provided"}
            />

            <DetailRow
              label="Source"
              value={event.source ?? "Not provided"}
            />
          </DetailSection>

          <DetailSection title="Actor Information">
            <DetailRow label="Actor" value={event.actorName} />
            <DetailRow label="Role" value={event.actorRole} />
            <DetailRow
              label="Actor ID"
              value={event.actorId ?? "System / Unavailable"}
            />

            {event.actorId && onOpenActor && (
              <button
                type="button"
                onClick={() => onOpenActor(event.actorId!)}
                className="mt-3 inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#987543]"
              >
                <UserRound size={13} />
                Open Actor Record
              </button>
            )}
          </DetailSection>

          <DetailSection title="Related Entity">
            <DetailRow
              label="Entity Type"
              value={event.entityType ?? "Not linked"}
            />

            <DetailRow
              label="Entity Reference"
              value={event.entityReference ?? "Not linked"}
            />

            {event.entityType &&
              event.entityReference &&
              onOpenEntity && (
                <button
                  type="button"
                  onClick={() =>
                    onOpenEntity(
                      event.entityType!,
                      event.entityReference!
                    )
                  }
                  className="mt-3 inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#987543]"
                >
                  <Eye size={13} />
                  Open Related Record
                </button>
              )}
          </DetailSection>

          {(event.ipAddress || event.reason) && (
            <DetailSection title="Additional Context">
              {event.ipAddress && (
                <DetailRow
                  label="IP Address"
                  value={event.ipAddress}
                />
              )}

              {event.reason && (
                <DetailRow
                  label="Reason"
                  value={event.reason}
                />
              )}
            </DetailSection>
          )}

          {event.changes && event.changes.length > 0 && (
            <DetailSection title="Recorded Field Changes">
              <div className="space-y-3">
                {event.changes.map((change, index) => (
                  <div
                    key={`${change.field}-${index}`}
                    className="border border-[#E5E2DC] p-4"
                  >
                    <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                      {change.field}
                    </p>

                    <div className="mt-3 grid grid-cols-1 gap-3 sm:grid-cols-2">
                      <div>
                        <p className="text-[8px] uppercase tracking-widest text-[#99958D]">
                          Previous Value
                        </p>

                        <p className="mt-2 break-words text-xs text-[#77736C]">
                          {change.previousValue ?? "Not available"}
                        </p>
                      </div>

                      <div>
                        <p className="text-[8px] uppercase tracking-widest text-[#99958D]">
                          New Value
                        </p>

                        <p className="mt-2 break-words text-xs text-[#33312D]">
                          {change.newValue ?? "Not available"}
                        </p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </DetailSection>
          )}

          <div className="flex items-start gap-3 border border-[#D8D6D0] bg-white p-4">
            <LockKeyhole
              size={17}
              className="mt-0.5 shrink-0 text-[#A58A64]"
            />

            <p className="text-[10px] leading-6 text-[#77736C]">
              This interface does not provide audit record editing
              or deletion. Record integrity and retention must be
              enforced by the backend.
            </p>
          </div>
        </div>
      </aside>
    </div>
  );
}

function DetailSection({
  title,
  children,
}: {
  title: string;
  children: ReactNode;
}) {
  return (
    <section>
      <h3 className="mb-3 font-mono text-[9px] uppercase tracking-[0.18em] text-[#A58A64]">
        {title}
      </h3>

      <div className="border border-[#D8D6D0] bg-white p-5">
        {children}
      </div>
    </section>
  );
}

function DetailRow({
  label,
  value,
}: {
  label: string;
  value: string;
}) {
  return (
    <div className="flex flex-col justify-between gap-2 border-b border-[#EAE7E0] py-3 last:border-0 sm:flex-row">
      <span className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
        {label}
      </span>

      <span className="break-all text-xs text-[#33312D] sm:max-w-[65%] sm:text-right">
        {value}
      </span>
    </div>
  );
}

import { useMemo, useState } from "react";
import type { ReactNode } from "react";
import {
  AlertTriangle,
  Archive,
  CheckCircle2,
  Clock3,
  Database,
  Download,
  Eye,
  RefreshCw,
  RotateCcw,
  Search,
  ShieldCheck,
} from "lucide-react";

export type BackupStatus =
  | "SUCCESS"
  | "FAILED"
  | "IN_PROGRESS"
  | "PARTIAL"
  | "UNKNOWN";

export type BackupVerification =
  | "VERIFIED"
  | "FAILED"
  | "PENDING"
  | "NOT_TESTED";

export type RecoveryRequestStatus =
  | "REQUESTED"
  | "PENDING_APPROVAL"
  | "APPROVED"
  | "REJECTED"
  | "IN_PROGRESS"
  | "COMPLETED"
  | "FAILED";

export type BackupRecord = {
  id: string;
  name: string;
  backupType: "FULL" | "INCREMENTAL" | "DIFFERENTIAL" | "UNKNOWN";
  status: BackupStatus;
  verification: BackupVerification;
  createdAt: string;
  completedAt?: string;
  sizeBytes?: number;
  retentionUntil?: string;
  coveredSystems: string[];
  reference?: string;
};

export type RecoveryRequest = {
  id: string;
  backupId: string;
  targetDescription: string;
  requestedBy: string;
  requestedAt: string;
  status: RecoveryRequestStatus;
  reviewedBy?: string;
  completedAt?: string;
  reason: string;
};

type Props = {
  backups: BackupRecord[];
  recoveryRequests: RecoveryRequest[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onOpenBackup?: (backup: BackupRecord) => void;
  onOpenRecoveryRequest?: (request: RecoveryRequest) => void;
  onReviewRecoveryRequest?: (
    request: RecoveryRequest,
    decision: "APPROVE" | "REJECT"
  ) => void;
};

const backupStatusStyles: Record<BackupStatus, string> = {
  SUCCESS: "bg-emerald-50 text-emerald-700",
  FAILED: "bg-red-50 text-red-700",
  IN_PROGRESS: "bg-blue-50 text-blue-700",
  PARTIAL: "bg-amber-50 text-amber-800",
  UNKNOWN: "bg-stone-100 text-stone-600",
};

const verificationStyles: Record<BackupVerification, string> = {
  VERIFIED: "bg-emerald-50 text-emerald-700",
  FAILED: "bg-red-50 text-red-700",
  PENDING: "bg-amber-50 text-amber-800",
  NOT_TESTED: "bg-stone-100 text-stone-600",
};

const recoveryStatusStyles: Record<RecoveryRequestStatus, string> = {
  REQUESTED: "bg-blue-50 text-blue-700",
  PENDING_APPROVAL: "bg-amber-50 text-amber-800",
  APPROVED: "bg-indigo-50 text-indigo-700",
  REJECTED: "bg-red-50 text-red-700",
  IN_PROGRESS: "bg-orange-50 text-orange-800",
  COMPLETED: "bg-emerald-50 text-emerald-700",
  FAILED: "bg-red-50 text-red-700",
};

function formatDate(value?: string) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function formatBytes(value?: number) {
  if (value === undefined || !Number.isFinite(value) || value < 0) {
    return "Not recorded";
  }

  if (value === 0) return "0 Bytes";

  const units = ["Bytes", "KB", "MB", "GB", "TB"];
  const index = Math.min(
    Math.floor(Math.log(value) / Math.log(1024)),
    units.length - 1
  );

  return `${(value / Math.pow(1024, index)).toFixed(2)} ${units[index]}`;
}

function Badge({
  children,
  className,
}: {
  children: ReactNode;
  className: string;
}) {
  return (
    <span
      className={`inline-flex rounded-full px-2.5 py-1 text-[10px] font-semibold tracking-wide ${className}`}
    >
      {children}
    </span>
  );
}

function Metric({
  label,
  value,
  icon,
}: {
  label: string;
  value: number;
  icon: ReactNode;
}) {
  return (
    <div className="rounded-xl border border-stone-200 bg-white p-4">
      <div className="flex items-center justify-between">
        <p className="text-xs text-stone-500">{label}</p>
        <span className="text-stone-400">{icon}</span>
      </div>
      <p className="mt-3 text-2xl font-semibold">{value}</p>
    </div>
  );
}

export default function AdminBackupRecoveryCenter({
  backups,
  recoveryRequests,
  loading = false,
  error,
  onRefresh,
  onOpenBackup,
  onOpenRecoveryRequest,
  onReviewRecoveryRequest,
}: Props) {
  const [activeTab, setActiveTab] = useState<"backups" | "recovery">(
    "backups"
  );
  const [search, setSearch] = useState("");
  const [backupStatusFilter, setBackupStatusFilter] = useState("ALL");
  const [verificationFilter, setVerificationFilter] = useState("ALL");
  const [recoveryFilter, setRecoveryFilter] = useState("ALL");

  const metrics = useMemo(
    () => ({
      total: backups.length,
      successful: backups.filter((item) => item.status === "SUCCESS").length,
      failed: backups.filter((item) => item.status === "FAILED").length,
      unverified: backups.filter(
        (item) =>
          item.verification === "PENDING" ||
          item.verification === "NOT_TESTED"
      ).length,
    }),
    [backups]
  );

  const filteredBackups = useMemo(() => {
    const query = search.trim().toLowerCase();

    return backups.filter((backup) => {
      const searchable = [
        backup.id,
        backup.name,
        backup.backupType,
        ...backup.coveredSystems,
      ]
        .join(" ")
        .toLowerCase();

      return (
        (!query || searchable.includes(query)) &&
        (backupStatusFilter === "ALL" ||
          backup.status === backupStatusFilter) &&
        (verificationFilter === "ALL" ||
          backup.verification === verificationFilter)
      );
    });
  }, [backups, search, backupStatusFilter, verificationFilter]);

  const filteredRequests = useMemo(() => {
    const query = search.trim().toLowerCase();

    return recoveryRequests.filter((request) => {
      const searchable = [
        request.id,
        request.backupId,
        request.targetDescription,
        request.requestedBy,
        request.reason,
        request.reviewedBy ?? "",
      ]
        .join(" ")
        .toLowerCase();

      return (
        (!query || searchable.includes(query)) &&
        (recoveryFilter === "ALL" || request.status === recoveryFilter)
      );
    });
  }, [recoveryRequests, search, recoveryFilter]);

  return (
    <main className="min-h-screen bg-[#f7f6f3] px-4 py-6 text-stone-900 sm:px-6 lg:px-8">
      <div className="mx-auto max-w-7xl space-y-6">
        <header className="flex flex-col justify-between gap-4 md:flex-row md:items-center">
          <div>
            <p className="mb-2 flex items-center gap-2 text-xs text-stone-500">
              <Database size={14} />
              Administration / Backup & Recovery
            </p>
            <h1 className="text-2xl font-semibold tracking-tight">
              Backup & Recovery
            </h1>
            <p className="mt-1 text-sm text-stone-500">
              Review backup records, verification evidence, and recovery
              requests.
            </p>
          </div>

          <button
            type="button"
            onClick={onRefresh}
            disabled={!onRefresh || loading}
            className="inline-flex items-center justify-center gap-2 rounded-lg border border-stone-300 bg-white px-4 py-2.5 text-sm font-medium hover:bg-stone-50 disabled:opacity-50"
          >
            <RefreshCw
              size={15}
              className={loading ? "animate-spin" : ""}
            />
            Refresh records
          </button>
        </header>

        {error && (
          <div
            role="alert"
            className="flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
          >
            <AlertTriangle size={18} />
            {error}
          </div>
        )}

        <section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          <Metric
            label="Backup records"
            value={metrics.total}
            icon={<Archive size={18} />}
          />
          <Metric
            label="Successful records"
            value={metrics.successful}
            icon={<CheckCircle2 size={18} />}
          />
          <Metric
            label="Failed records"
            value={metrics.failed}
            icon={<AlertTriangle size={18} />}
          />
          <Metric
            label="Not fully verified"
            value={metrics.unverified}
            icon={<ShieldCheck size={18} />}
          />
        </section>

        <section className="overflow-hidden rounded-xl border border-stone-200 bg-white">
          <div className="flex flex-col gap-3 border-b border-stone-200 p-4 lg:flex-row lg:items-center lg:justify-between">
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() => setActiveTab("backups")}
                className={`rounded-lg px-4 py-2 text-sm font-medium ${
                  activeTab === "backups"
                    ? "bg-stone-900 text-white"
                    : "text-stone-500 hover:bg-stone-100"
                }`}
              >
                Backup records
              </button>
              <button
                type="button"
                onClick={() => setActiveTab("recovery")}
                className={`rounded-lg px-4 py-2 text-sm font-medium ${
                  activeTab === "recovery"
                    ? "bg-stone-900 text-white"
                    : "text-stone-500 hover:bg-stone-100"
                }`}
              >
                Recovery requests
                {recoveryRequests.filter(
                  (item) => item.status === "PENDING_APPROVAL"
                ).length > 0 && (
                  <span className="ml-2 rounded-full bg-amber-100 px-2 py-0.5 text-[10px] text-amber-800">
                    {
                      recoveryRequests.filter(
                        (item) => item.status === "PENDING_APPROVAL"
                      ).length
                    }
                  </span>
                )}
              </button>
            </div>

            <div className="relative w-full lg:max-w-xs">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400"
              />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search records..."
                className="w-full rounded-lg border border-stone-200 py-2 pl-9 pr-3 text-sm outline-none focus:border-stone-500"
              />
            </div>
          </div>

          {activeTab === "backups" ? (
            <>
              <div className="flex flex-wrap gap-3 border-b border-stone-100 bg-stone-50/60 p-4">
                <select
                  aria-label="Filter backup status"
                  value={backupStatusFilter}
                  onChange={(event) =>
                    setBackupStatusFilter(event.target.value)
                  }
                  className="rounded-lg border border-stone-200 bg-white px-3 py-2 text-sm"
                >
                  <option value="ALL">All backup statuses</option>
                  {Object.keys(backupStatusStyles).map((status) => (
                    <option key={status} value={status}>
                      {status.replaceAll("_", " ")}
                    </option>
                  ))}
                </select>

                <select
                  aria-label="Filter verification status"
                  value={verificationFilter}
                  onChange={(event) =>
                    setVerificationFilter(event.target.value)
                  }
                  className="rounded-lg border border-stone-200 bg-white px-3 py-2 text-sm"
                >
                  <option value="ALL">All verification statuses</option>
                  {Object.keys(verificationStyles).map((status) => (
                    <option key={status} value={status}>
                      {status.replaceAll("_", " ")}
                    </option>
                  ))}
                </select>
              </div>

              {loading ? (
                <div className="p-12 text-center text-sm text-stone-500">
                  Loading backup records...
                </div>
              ) : filteredBackups.length === 0 ? (
                <div className="p-12 text-center">
                  <Archive size={28} className="mx-auto text-stone-300" />
                  <p className="mt-3 text-sm font-medium">
                    No backup records found
                  </p>
                </div>
              ) : (
                <div className="divide-y divide-stone-100">
                  {filteredBackups.map((backup) => (
                    <article
                      key={backup.id}
                      className="p-4 transition hover:bg-stone-50/70 sm:p-5"
                    >
                      <div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-start">
                        <div className="min-w-0 flex-1">
                          <div className="flex flex-wrap items-center gap-2">
                            <span className="font-mono text-xs text-stone-400">
                              {backup.id}
                            </span>
                            <Badge className={backupStatusStyles[backup.status]}>
                              {backup.status.replaceAll("_", " ")}
                            </Badge>
                            <Badge
                              className={verificationStyles[backup.verification]}
                            >
                              {backup.verification.replaceAll("_", " ")}
                            </Badge>
                          </div>

                          <h2 className="mt-2 text-sm font-semibold">
                            {backup.name}
                          </h2>

                          <div className="mt-3 grid gap-2 text-xs text-stone-500 sm:grid-cols-2">
                            <p>Type: {backup.backupType}</p>
                            <p>Size: {formatBytes(backup.sizeBytes)}</p>
                            <p>Created: {formatDate(backup.createdAt)}</p>
                            <p>Completed: {formatDate(backup.completedAt)}</p>
                            <p>
                              Retention until: {formatDate(backup.retentionUntil)}
                            </p>
                          </div>

                          {backup.coveredSystems.length > 0 && (
                            <div className="mt-3 flex flex-wrap gap-1.5">
                              {backup.coveredSystems.map((system) => (
                                <span
                                  key={system}
                                  className="rounded-md border border-stone-200 bg-white px-2 py-1 text-[10px] text-stone-600"
                                >
                                  {system}
                                </span>
                              ))}
                            </div>
                          )}
                        </div>

                        <button
                          type="button"
                          onClick={() => onOpenBackup?.(backup)}
                          disabled={!onOpenBackup}
                          className="inline-flex items-center gap-2 self-start rounded-lg border border-stone-200 px-3 py-2 text-xs font-medium hover:bg-stone-100 disabled:opacity-50"
                        >
                          <Eye size={14} />
                          View record
                        </button>
                      </div>
                    </article>
                  ))}
                </div>
              )}
            </>
          ) : (
            <>
              <div className="border-b border-stone-100 bg-stone-50/60 p-4">
                <select
                  aria-label="Filter recovery request status"
                  value={recoveryFilter}
                  onChange={(event) => setRecoveryFilter(event.target.value)}
                  className="rounded-lg border border-stone-200 bg-white px-3 py-2 text-sm"
                >
                  <option value="ALL">All request statuses</option>
                  {Object.keys(recoveryStatusStyles).map((status) => (
                    <option key={status} value={status}>
                      {status.replaceAll("_", " ")}
                    </option>
                  ))}
                </select>
              </div>

              {loading ? (
                <div className="p-12 text-center text-sm text-stone-500">
                  Loading recovery requests...
                </div>
              ) : filteredRequests.length === 0 ? (
                <div className="p-12 text-center">
                  <RotateCcw size={28} className="mx-auto text-stone-300" />
                  <p className="mt-3 text-sm font-medium">
                    No recovery requests found
                  </p>
                </div>
              ) : (
                <div className="divide-y divide-stone-100">
                  {filteredRequests.map((request) => (
                    <article key={request.id} className="p-4 sm:p-5">
                      <div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-start">
                        <div className="min-w-0 flex-1">
                          <div className="flex flex-wrap items-center gap-2">
                            <span className="font-mono text-xs text-stone-400">
                              {request.id}
                            </span>
                            <Badge
                              className={recoveryStatusStyles[request.status]}
                            >
                              {request.status.replaceAll("_", " ")}
                            </Badge>
                          </div>

                          <h2 className="mt-2 text-sm font-semibold">
                            {request.targetDescription}
                          </h2>
                          <p className="mt-1 text-sm leading-6 text-stone-500">
                            {request.reason}
                          </p>

                          <div className="mt-3 grid gap-2 text-xs text-stone-500 sm:grid-cols-2">
                            <p>Backup reference: {request.backupId}</p>
                            <p>Requested by: {request.requestedBy}</p>
                            <p>Requested: {formatDate(request.requestedAt)}</p>
                            <p>Reviewed by: {request.reviewedBy || "Not recorded"}</p>
                            <p>Completed: {formatDate(request.completedAt)}</p>
                          </div>
                        </div>

                        <div className="flex flex-wrap items-center gap-2">
                          {request.status === "PENDING_APPROVAL" &&
                            onReviewRecoveryRequest && (
                              <>
                                <button
                                  type="button"
                                  onClick={() =>
                                    onReviewRecoveryRequest(request, "REJECT")
                                  }
                                  className="rounded-lg border border-red-200 px-3 py-2 text-xs font-medium text-red-700 hover:bg-red-50"
                                >
                                  Reject
                                </button>
                                <button
                                  type="button"
                                  onClick={() =>
                                    onReviewRecoveryRequest(request, "APPROVE")
                                  }
                                  className="rounded-lg bg-stone-900 px-3 py-2 text-xs font-medium text-white hover:bg-stone-700"
                                >
                                  Approve
                                </button>
                              </>
                            )}

                          <button
                            type="button"
                            onClick={() => onOpenRecoveryRequest?.(request)}
                            disabled={!onOpenRecoveryRequest}
                            className="rounded-lg border border-stone-200 px-3 py-2 text-xs font-medium hover:bg-stone-100 disabled:opacity-50"
                          >
                            View details
                          </button>
                        </div>
                      </div>
                    </article>
                  ))}
                </div>
              )}
            </>
          )}
        </section>

        <section className="rounded-xl border border-amber-200 bg-amber-50/60 p-4">
          <div className="flex items-start gap-3">
            <ShieldCheck
              size={19}
              className="mt-0.5 shrink-0 text-amber-800"
            />
            <div>
              <h2 className="text-sm font-semibold">
                Recovery and evidence safeguards
              </h2>
              <p className="mt-1 text-xs leading-5 text-stone-600">
                A successful backup job does not prove that data can be
                restored. Verification should include documented restore
                testing. Recovery requires explicit authorization, target
                validation, preservation checks, and an auditable execution
                record. Never expose backup credentials or sensitive storage
                paths in this interface.
              </p>
            </div>
          </div>
        </section>

        <p className="flex items-center gap-2 text-xs text-stone-400">
          <Download size={13} />
          This component displays records only. It does not download backups
          or execute recovery operations.
        </p>
      </div>
    </main>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  Search,
  RefreshCw,
  Wallet,
  Building2,
  UserRound,
  CalendarDays,
  IndianRupee,
  ShieldCheck,
  AlertCircle,
  CheckCircle2,
  Clock3,
  FileText,
  ArrowUpRight,
  X,
  MessageSquare,
  LockKeyhole,
} from "lucide-react";

export type CashVendorAcknowledgement =
  | "Pending"
  | "Acknowledged"
  | "Disputed"
  | "Expired";

export type CashFinanceStatus =
  | "Awaiting Vendor"
  | "Pending Verification"
  | "Under Verification"
  | "Verified"
  | "Rejected"
  | "Disputed";

export type CashSettlementStatus =
  | "Initiated"
  | "Awaiting Acknowledgement"
  | "Awaiting Finance Verification"
  | "Under Review"
  | "Verified"
  | "Rejected"
  | "Disputed"
  | "Cancelled";

export interface CashSettlementHistoryEntry {
  id: string;
  actorName: string;
  actorRole: string;
  action: string;
  remarks?: string;
  timestamp: string;
}

export interface AdminCashSettlementRecord {
  id: string;
  reference: string;

  vendorId: string;
  vendorName: string;

  projectId?: string;
  projectReference?: string;
  projectName?: string;

  relatedInvoiceId?: string;
  relatedInvoiceReference?: string;

  amount: number;
  currency: "INR";

  initiatedBy: string;
  initiatedAt: string;

  settlementDate?: string;
  settlementDescription: string;

  vendorAcknowledgement: CashVendorAcknowledgement;
  vendorAcknowledgedAt?: string;
  vendorResponse?: string;

  financeStatus: CashFinanceStatus;
  financeVerifiedBy?: string;
  financeVerifiedAt?: string;
  financeRemarks?: string;

  overallStatus: CashSettlementStatus;

  evidenceCount: number;
  hasRequiredEvidence: boolean;

  currentUserCanVerify: boolean;
  currentUserInitiated: boolean;

  history: CashSettlementHistoryEntry[];
}

export interface CashSettlementSummary {
  totalCount: number;
  totalValue: number;
  awaitingVendor: number;
  awaitingFinance: number;
  verifiedCount: number;
  disputedCount: number;
}

export interface CashFinanceDecision {
  decision: "Verify" | "Reject" | "Request Clarification";
  remarks: string;
}

interface AdminCashSettlementManagementProps {
  settlements: AdminCashSettlementRecord[];
  summary?: CashSettlementSummary;

  loading?: boolean;
  error?: string;
  processingSettlementId?: string;

  onRefresh?: () => void;

  onOpenSettlement?: (settlementId: string) => void;

  onOpenVendor?: (vendorId: string) => void;

  onOpenProject?: (projectId: string) => void;

  onOpenInvoice?: (invoiceId: string) => void;

  onOpenEvidence?: (settlementId: string) => void;

  onSubmitFinanceDecision: (
    settlementId: string,
    decision: CashFinanceDecision
  ) => Promise<void>;
}

type SettlementFilter =
  | "All"
  | "Awaiting Acknowledgement"
  | "Awaiting Finance Verification"
  | "Verified"
  | "Disputed"
  | "Rejected";

function formatCurrency(value: number) {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 2,
  }).format(value);
}

function formatDate(value?: string) {
  if (!value) return "Not available";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
}

function settlementStatusStyle(status: CashSettlementStatus) {
  switch (status) {
    case "Verified":
      return "bg-[#EAF1E8] text-[#547A51]";

    case "Awaiting Acknowledgement":
    case "Awaiting Finance Verification":
    case "Under Review":
      return "bg-[#F4EFE2] text-[#94743F]";

    case "Disputed":
    case "Rejected":
      return "bg-[#F8EAE7] text-[#9A5147]";

    default:
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

function acknowledgementStyle(status: CashVendorAcknowledgement) {
  switch (status) {
    case "Acknowledged":
      return "bg-[#EAF1E8] text-[#547A51]";

    case "Disputed":
    case "Expired":
      return "bg-[#F8EAE7] text-[#9A5147]";

    default:
      return "bg-[#F4EFE2] text-[#94743F]";
  }
}

function financeStatusStyle(status: CashFinanceStatus) {
  switch (status) {
    case "Verified":
      return "bg-[#EAF1E8] text-[#547A51]";

    case "Pending Verification":
    case "Under Verification":
      return "bg-[#F4EFE2] text-[#94743F]";

    case "Rejected":
    case "Disputed":
      return "bg-[#F8EAE7] text-[#9A5147]";

    default:
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

function isValidAmount(value: number) {
  return Number.isFinite(value) && value > 0;
}

export function AdminCashSettlementManagement({
  settlements,
  summary,
  loading = false,
  error,
  processingSettlementId,
  onRefresh,
  onOpenSettlement,
  onOpenVendor,
  onOpenProject,
  onOpenInvoice,
  onOpenEvidence,
  onSubmitFinanceDecision,
}: AdminCashSettlementManagementProps) {
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState<SettlementFilter>("All");

  const [selectedSettlement, setSelectedSettlement] =
    useState<AdminCashSettlementRecord | null>(null);

  const [decision, setDecision] =
    useState<CashFinanceDecision["decision"]>("Verify");

  const [remarks, setRemarks] = useState("");
  const [actionError, setActionError] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const calculatedSummary = useMemo<CashSettlementSummary>(() => ({
    totalCount: settlements.length,

    totalValue: settlements.reduce(
      (total, item) => total + item.amount,
      0
    ),

    awaitingVendor: settlements.filter(
      (item) =>
        item.overallStatus === "Awaiting Acknowledgement"
    ).length,

    awaitingFinance: settlements.filter(
      (item) =>
        item.overallStatus === "Awaiting Finance Verification" ||
        item.overallStatus === "Under Review"
    ).length,

    verifiedCount: settlements.filter(
      (item) => item.overallStatus === "Verified"
    ).length,

    disputedCount: settlements.filter(
      (item) => item.overallStatus === "Disputed"
    ).length,
  }), [settlements]);

  const totals = summary ?? calculatedSummary;

  const filteredSettlements = useMemo(() => {
    const query = search.trim().toLowerCase();

    return settlements.filter((item) => {
      const matchesSearch =
        !query ||
        item.reference.toLowerCase().includes(query) ||
        item.vendorName.toLowerCase().includes(query) ||
        item.vendorId.toLowerCase().includes(query) ||
        (item.projectName ?? "").toLowerCase().includes(query) ||
        (item.projectReference ?? "").toLowerCase().includes(query) ||
        (item.relatedInvoiceReference ?? "").toLowerCase().includes(query);

      const matchesFilter =
        filter === "All" ||
        item.overallStatus === filter;

      return matchesSearch && matchesFilter;
    });
  }, [settlements, search, filter]);

  function openSettlement(item: AdminCashSettlementRecord) {
    setSelectedSettlement(item);
    setDecision("Verify");
    setRemarks("");
    setActionError("");
  }

  function closeSettlement() {
    if (submitting) return;

    setSelectedSettlement(null);
    setActionError("");
  }

  async function submitDecision() {
    if (!selectedSettlement || submitting) return;

    setActionError("");

    if (!selectedSettlement.currentUserCanVerify) {
      setActionError(
        "Your account is not authorised to verify this settlement."
      );
      return;
    }

    if (selectedSettlement.currentUserInitiated) {
      setActionError(
        "The settlement initiator cannot independently verify the same settlement."
      );
      return;
    }

    if (
      selectedSettlement.vendorAcknowledgement !== "Acknowledged"
    ) {
      setActionError(
        "Vendor acknowledgement is required before finance verification."
      );
      return;
    }

    if (
      !selectedSettlement.hasRequiredEvidence &&
      decision !== "Request Clarification"
    ) {
      setActionError(
        "Required settlement evidence is missing. Request clarification before verification."
      );
      return;
    }

    if (
      (decision === "Reject" ||
        decision === "Request Clarification") &&
      !remarks.trim()
    ) {
      setActionError("A written reason is required.");
      return;
    }

    if (!isValidAmount(selectedSettlement.amount)) {
      setActionError(
        "The settlement amount is invalid. Do not verify this record."
      );
      return;
    }

    setSubmitting(true);

    try {
      await onSubmitFinanceDecision(selectedSettlement.id, {
        decision,
        remarks: remarks.trim(),
      });

      setSelectedSettlement(null);
      setRemarks("");
    } catch (err) {
      setActionError(
        err instanceof Error
          ? err.message
          : "The finance decision could not be submitted."
      );
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-9 md:px-10 md:py-12 lg:px-12">

      {/* Header */}
      <header className="flex flex-col justify-between gap-6 border-b border-[#D8D6D0] pb-8 md:flex-row md:items-end">
        <div>
          <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
            Administration / Finance / Cash Settlements
          </p>

          <h1 className="mt-4 font-serif text-4xl text-[#171717] md:text-5xl">
            Cash Settlements
          </h1>

          <p className="mt-3 max-w-xl text-sm leading-7 text-[#77736C]">
            Monitor vendor acknowledgements, settlement evidence,
            finance verification and disputed cash transactions.
          </p>
        </div>

        {onRefresh && (
          <button
            type="button"
            onClick={onRefresh}
            disabled={loading}
            className="inline-flex w-fit items-center gap-2 border border-[#D8D6D0] bg-white px-5 py-3 text-[10px] uppercase tracking-widest text-[#55514A] hover:border-[#A58A64] disabled:opacity-50"
          >
            <RefreshCw size={14} />
            Refresh Settlements
          </button>
        )}
      </header>

      {error && (
        <div
          role="alert"
          className="mt-6 flex items-start gap-3 border border-[#E3C9C5] bg-[#FAF3F1] p-5"
        >
          <AlertCircle
            size={18}
            className="mt-0.5 shrink-0 text-[#9A5147]"
          />
          <p className="text-xs leading-6 text-[#805B55]">
            {error}
          </p>
        </div>
      )}

      {/* Summary */}
      <section className="mt-9 grid grid-cols-2 gap-px border border-[#D8D6D0] bg-[#D8D6D0] lg:grid-cols-3 xl:grid-cols-6">
        <SummaryCard
          label="Total Records"
          value={totals.totalCount.toLocaleString("en-IN")}
        />

        <SummaryCard
          label="Total Settlement Value"
          value={formatCurrency(totals.totalValue)}
        />

        <SummaryCard
          label="Awaiting Vendor"
          value={totals.awaitingVendor.toLocaleString("en-IN")}
        />

        <SummaryCard
          label="Awaiting Finance"
          value={totals.awaitingFinance.toLocaleString("en-IN")}
        />

        <SummaryCard
          label="Verified"
          value={totals.verifiedCount.toLocaleString("en-IN")}
        />

        <SummaryCard
          label="Disputed"
          value={totals.disputedCount.toLocaleString("en-IN")}
        />
      </section>

      {/* Governance Notice */}
      <section className="mt-6 flex items-start gap-4 border border-[#D8D6D0] bg-white p-5 md:p-6">
        <LockKeyhole
          size={20}
          className="mt-0.5 shrink-0 text-[#A58A64]"
        />

        <div>
          <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
            Two-Party Verification
          </p>

          <p className="mt-2 text-xs leading-6 text-[#666159]">
            A vendor acknowledgement records the vendor&apos;s response.
            Finance must independently verify the settlement and its
            evidence. Neither action alone proves that money was
            correctly transferred.
          </p>
        </div>
      </section>

      {/* Search */}
      <section className="mt-10">
        <div className="relative">
          <Search
            size={17}
            className="absolute left-4 top-1/2 -translate-y-1/2 text-[#99958D]"
          />

          <input
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            placeholder="Search settlement, vendor, project or invoice..."
            aria-label="Search cash settlements"
            className="h-12 w-full border border-[#D8D6D0] bg-white pl-11 pr-4 text-sm outline-none focus:border-[#A58A64]"
          />
        </div>

        <div className="mt-4 flex flex-wrap gap-2">
          {(
            [
              "All",
              "Awaiting Acknowledgement",
              "Awaiting Finance Verification",
              "Verified",
              "Disputed",
              "Rejected",
            ] as SettlementFilter[]
          ).map((item) => (
            <button
              key={item}
              type="button"
              onClick={() => setFilter(item)}
              aria-pressed={filter === item}
              className={`border px-4 py-3 text-[9px] uppercase tracking-widest transition-colors ${
                filter === item
                  ? "border-[#171717] bg-[#171717] text-white"
                  : "border-[#D8D6D0] bg-white text-[#77736C] hover:border-[#A58A64]"
              }`}
            >
              {item}
            </button>
          ))}
        </div>
      </section>

      {/* Settlement Register */}
      <section className="mt-9">
        <div className="flex items-end justify-between border-b border-[#D8D6D0] pb-5">
          <div>
            <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
              Finance Records
            </p>

            <h2 className="mt-3 font-serif text-2xl text-[#171717]">
              Settlement Register
            </h2>
          </div>

          <p className="font-mono text-[9px] text-[#99958D]">
            {filteredSettlements.length} RECORDS
          </p>
        </div>

        {loading ? (
          <div className="flex min-h-64 items-center justify-center">
            <p className="font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
              Loading settlement records...
            </p>
          </div>
        ) : filteredSettlements.length === 0 ? (
          <div className="mt-5 border border-[#D8D6D0] bg-white px-6 py-16 text-center">
            <Wallet
              size={28}
              strokeWidth={1.3}
              className="mx-auto text-[#A58A64]"
            />

            <h3 className="mt-5 font-serif text-2xl text-[#171717]">
              No settlements found
            </h3>

            <p className="mt-3 text-xs text-[#77736C]">
              No settlement records match your search or filter.
            </p>
          </div>
        ) : (
          <div className="mt-5 space-y-3">
            {filteredSettlements.map((item) => (
              <SettlementCard
                key={item.id}
                item={item}
                processing={
                  processingSettlementId === item.id
                }
                onOpen={() => openSettlement(item)}
              />
            ))}
          </div>
        )}
      </section>

      {/* Detail and Verification Drawer */}
      {selectedSettlement && (
        <div
          className="fixed inset-0 z-[70] flex justify-end bg-black/50"
          role="presentation"
          onMouseDown={(event) => {
            if (event.target === event.currentTarget) {
              closeSettlement();
            }
          }}
        >
          <aside
            role="dialog"
            aria-modal="true"
            aria-labelledby="settlement-detail-title"
            className="flex h-full w-full max-w-3xl flex-col overflow-y-auto bg-[#F2F0EB] shadow-2xl"
          >
            {/* Drawer Header */}
            <div className="sticky top-0 z-10 flex items-center justify-between border-b border-[#D8D6D0] bg-[#F2F0EB] px-6 py-5 md:px-8">
              <div>
                <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                  Settlement / {selectedSettlement.reference}
                </p>

                <h2
                  id="settlement-detail-title"
                  className="mt-2 font-serif text-2xl text-[#171717]"
                >
                  Settlement Verification
                </h2>
              </div>

              <button
                type="button"
                onClick={closeSettlement}
                disabled={submitting}
                aria-label="Close settlement details"
                className="text-[#77736C] disabled:opacity-40"
              >
                <X size={21} />
              </button>
            </div>

            <div className="flex-1 space-y-7 p-6 md:p-8">

              {/* Settlement Identity */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex h-12 w-12 shrink-0 items-center justify-center border border-[#E5E2DC] bg-[#FAF9F6] text-[#A58A64]">
                    <Wallet size={20} />
                  </div>

                  <span
                    className={`px-3 py-2 text-[8px] uppercase tracking-widest ${settlementStatusStyle(selectedSettlement.overallStatus)}`}
                  >
                    {selectedSettlement.overallStatus}
                  </span>
                </div>

                <h3 className="mt-5 break-words font-serif text-3xl text-[#171717]">
                  {selectedSettlement.reference}
                </h3>

                <p className="mt-3 font-serif text-3xl text-[#171717]">
                  {formatCurrency(selectedSettlement.amount)}
                </p>

                <div className="mt-6 space-y-4 border-t border-[#E5E2DC] pt-5">
                  <DetailLine
                    icon={<Building2 size={14} />}
                    label="Vendor"
                    value={selectedSettlement.vendorName}
                  />

                  <DetailLine
                    icon={<UserRound size={14} />}
                    label="Initiated By"
                    value={selectedSettlement.initiatedBy}
                  />

                  <DetailLine
                    icon={<CalendarDays size={14} />}
                    label="Initiated At"
                    value={formatDate(selectedSettlement.initiatedAt)}
                  />

                  <DetailLine
                    icon={<CalendarDays size={14} />}
                    label="Settlement Date"
                    value={formatDate(selectedSettlement.settlementDate)}
                  />
                </div>

                <p className="mt-5 border-t border-[#E5E2DC] pt-5 text-xs leading-7 text-[#666159]">
                  {selectedSettlement.settlementDescription}
                </p>

                {onOpenVendor && (
                  <button
                    type="button"
                    onClick={() =>
                      onOpenVendor(selectedSettlement.vendorId)
                    }
                    className="mt-5 inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#987543]"
                  >
                    Open Vendor Record
                    <ArrowUpRight size={14} />
                  </button>
                )}
              </section>

              {/* Project and Invoice */}
              {(selectedSettlement.projectId ||
                selectedSettlement.relatedInvoiceId) && (
                <section className="border border-[#D8D6D0] bg-white p-6">
                  <SectionHeading>Related Records</SectionHeading>

                  {selectedSettlement.projectName && (
                    <div className="mt-5">
                      <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
                        Project
                      </p>

                      <p className="mt-2 text-sm text-[#33312D]">
                        {selectedSettlement.projectName}
                      </p>

                      {selectedSettlement.projectReference && (
                        <p className="mt-1 font-mono text-[9px] text-[#A58A64]">
                          {selectedSettlement.projectReference}
                        </p>
                      )}

                      {selectedSettlement.projectId && onOpenProject && (
                        <button
                          type="button"
                          onClick={() =>
                            onOpenProject(selectedSettlement.projectId!)
                          }
                          className="mt-3 text-[9px] uppercase tracking-widest text-[#987543]"
                        >
                          Open Project
                        </button>
                      )}
                    </div>
                  )}

                  {selectedSettlement.relatedInvoiceReference && (
                    <div className="mt-5 border-t border-[#E5E2DC] pt-5">
                      <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
                        Related Invoice
                      </p>

                      <p className="mt-2 text-sm text-[#33312D]">
                        {selectedSettlement.relatedInvoiceReference}
                      </p>

                      {selectedSettlement.relatedInvoiceId && onOpenInvoice && (
                        <button
                          type="button"
                          onClick={() =>
                            onOpenInvoice(
                              selectedSettlement.relatedInvoiceId!
                            )
                          }
                          className="mt-3 text-[9px] uppercase tracking-widest text-[#987543]"
                        >
                          Open Invoice
                        </button>
                      )}
                    </div>
                  )}
                </section>
              )}

              {/* Vendor Acknowledgement */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <SectionHeading>Vendor Acknowledgement</SectionHeading>

                <div className="mt-5 flex flex-wrap items-center justify-between gap-3">
                  <p className="text-xs text-[#77736C]">
                    Vendor response
                  </p>

                  <span
                    className={`px-3 py-2 text-[8px] uppercase tracking-widest ${acknowledgementStyle(selectedSettlement.vendorAcknowledgement)}`}
                  >
                    {selectedSettlement.vendorAcknowledgement}
                  </span>
                </div>

                {selectedSettlement.vendorAcknowledgedAt && (
                  <p className="mt-4 text-[10px] text-[#77736C]">
                    Acknowledged at:{" "}
                    {formatDate(selectedSettlement.vendorAcknowledgedAt)}
                  </p>
                )}

                {selectedSettlement.vendorResponse && (
                  <div className="mt-5 border-t border-[#E5E2DC] pt-5">
                    <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
                      Vendor Response
                    </p>

                    <p className="mt-3 whitespace-pre-wrap text-xs leading-6 text-[#55514A]">
                      {selectedSettlement.vendorResponse}
                    </p>
                  </div>
                )}

                {selectedSettlement.vendorAcknowledgement !== "Acknowledged" && (
                  <div className="mt-5 border border-[#E3C9C5] bg-[#FAF3F1] p-4 text-xs leading-6 text-[#805B55]">
                    Finance verification is blocked until the vendor&apos;s
                    acknowledgement is confirmed by the server.
                  </div>
                )}
              </section>

              {/* Finance Status */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <SectionHeading>Finance Verification Status</SectionHeading>

                <div className="mt-5 flex flex-wrap items-center justify-between gap-3">
                  <p className="text-xs text-[#77736C]">
                    Finance status
                  </p>

                  <span
                    className={`px-3 py-2 text-[8px] uppercase tracking-widest ${financeStatusStyle(selectedSettlement.financeStatus)}`}
                  >
                    {selectedSettlement.financeStatus}
                  </span>
                </div>

                {selectedSettlement.financeVerifiedBy && (
                  <div className="mt-5 space-y-3 border-t border-[#E5E2DC] pt-5">
                    <DetailLine
                      icon={<UserRound size={14} />}
                      label="Finance Reviewer"
                      value={selectedSettlement.financeVerifiedBy}
                    />

                    <DetailLine
                      icon={<CalendarDays size={14} />}
                      label="Finance Decision Date"
                      value={formatDate(selectedSettlement.financeVerifiedAt)}
                    />
                  </div>
                )}

                {selectedSettlement.financeRemarks && (
                  <p className="mt-5 border-t border-[#E5E2DC] pt-5 text-xs leading-6 text-[#55514A]">
                    {selectedSettlement.financeRemarks}
                  </p>
                )}
              </section>

              {/* Evidence */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <div className="flex items-center justify-between gap-3">
                  <SectionHeading>Settlement Evidence</SectionHeading>

                  <span className="font-mono text-[9px] text-[#99958D]">
                    {selectedSettlement.evidenceCount} FILES
                  </span>
                </div>

                <p className="mt-3 text-xs leading-6 text-[#77736C]">
                  {selectedSettlement.hasRequiredEvidence
                    ? "The server reports the required evidence is present. Inspect the actual supporting records before verification."
                    : "Required evidence is reported missing. Request clarification before verification."}
                </p>

                {selectedSettlement.evidenceCount > 0 && onOpenEvidence && (
                  <button
                    type="button"
                    onClick={() =>
                      onOpenEvidence(selectedSettlement.id)
                    }
                    className="mt-5 inline-flex items-center gap-2 border border-[#D8D6D0] px-5 py-3 text-[9px] uppercase tracking-widest text-[#55514A] hover:border-[#A58A64]"
                  >
                    <FileText size={14} />
                    Inspect Evidence
                    <ArrowUpRight size={13} />
                  </button>
                )}
              </section>

              {/* History */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <SectionHeading>Settlement History</SectionHeading>

                {selectedSettlement.history.length === 0 ? (
                  <p className="mt-5 text-xs text-[#77736C]">
                    No history records are available.
                  </p>
                ) : (
                  <div className="mt-5 space-y-5">
                    {selectedSettlement.history.map((entry) => (
                      <div
                        key={entry.id}
                        className="border-l border-[#D8D6D0] pl-4"
                      >
                        <p className="text-xs text-[#33312D]">
                          {entry.action}
                        </p>

                        <p className="mt-1 text-[10px] text-[#77736C]">
                          {entry.actorName} · {entry.actorRole}
                        </p>

                        {entry.remarks && (
                          <p className="mt-2 text-xs leading-6 text-[#77736C]">
                            {entry.remarks}
                          </p>
                        )}

                        <p className="mt-2 font-mono text-[8px] text-[#99958D]">
                          {formatDate(entry.timestamp)}
                        </p>
                      </div>
                    ))}
                  </div>
                )}
              </section>

              {/* Finance Decision */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <SectionHeading>Finance Decision</SectionHeading>

                <p className="mt-3 text-xs leading-6 text-[#77736C]">
                  Record an independent finance decision after
                  checking the vendor acknowledgement and supporting evidence.
                </p>

                <label className="mt-6 block">
                  <span className="mb-2 block font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                    Decision
                  </span>

                  <select
                    value={decision}
                    onChange={(event) => {
                      setDecision(
                        event.target.value as CashFinanceDecision["decision"]
                      );
                      setActionError("");
                    }}
                    disabled={
                      submitting ||
                      !selectedSettlement.currentUserCanVerify ||
                      selectedSettlement.currentUserInitiated ||
                      selectedSettlement.vendorAcknowledgement !== "Acknowledged"
                    }
                    className="h-12 w-full border border-[#D8D6D0] bg-white px-3 text-xs outline-none focus:border-[#A58A64] disabled:opacity-50"
                  >
                    <option value="Verify">Verify Settlement</option>
                    <option value="Reject">Reject Settlement</option>
                    <option value="Request Clarification">
                      Request Clarification
                    </option>
                  </select>
                </label>

                <label className="mt-5 block">
                  <span className="mb-2 block font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                    Finance Remarks
                    {(decision === "Reject" ||
                      decision === "Request Clarification") &&
                      " · Required"}
                  </span>

                  <textarea
                    value={remarks}
                    onChange={(event) => setRemarks(event.target.value)}
                    rows={4}
                    maxLength={2000}
                    disabled={submitting}
                    placeholder="Record verification findings, rejection reasons or clarification required..."
                    className="w-full resize-y border border-[#D8D6D0] bg-white p-4 text-xs leading-6 outline-none focus:border-[#A58A64] disabled:opacity-50"
                  />

                  <span className="mt-2 block text-right font-mono text-[8px] text-[#99958D]">
                    {remarks.length}/2000
                  </span>
                </label>

                {actionError && (
                  <div
                    role="alert"
                    className="mt-5 border border-[#E3C9C5] bg-[#FAF3F1] p-4 text-xs leading-6 text-[#805B55]"
                  >
                    {actionError}
                  </div>
                )}

                <button
                  type="button"
                  onClick={submitDecision}
                  disabled={
                    submitting ||
                    !selectedSettlement.currentUserCanVerify ||
                    selectedSettlement.currentUserInitiated ||
                    selectedSettlement.vendorAcknowledgement !== "Acknowledged" ||
                    processingSettlementId === selectedSettlement.id
                  }
                  className="mt-6 flex w-full items-center justify-center gap-2 bg-[#171717] px-5 py-4 text-[9px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:cursor-not-allowed disabled:opacity-40"
                >
                  {submitting ? (
                    <>
                      <RefreshCw size={14} className="animate-spin" />
                      Submitting Decision...
                    </>
                  ) : (
                    <>
                      <ShieldCheck size={15} />
                      Submit Finance Decision
                    </>
                  )}
                </button>

                <p className="mt-4 text-[9px] leading-5 text-[#99958D]">
                  Verification records a finance decision. It does not
                  initiate a bank transfer or replace bank reconciliation.
                </p>
              </section>
            </div>

            <div className="sticky bottom-0 border-t border-[#D8D6D0] bg-[#F2F0EB] p-5">
              <button
                type="button"
                onClick={closeSettlement}
                disabled={submitting}
                className="w-full border border-[#D8D6D0] px-5 py-4 text-[9px] uppercase tracking-widest text-[#77736C] disabled:opacity-40"
              >
                Close Settlement
              </button>
            </div>
          </aside>
        </div>
      )}
    </main>
  );
}

function SummaryCard({
  label,
  value,
}: {
  label: string;
  value: string;
}) {
  return (
    <div className="bg-white p-5 md:p-6">
      <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
        {label}
      </p>

      <p className="mt-5 break-words font-serif text-2xl text-[#171717] md:text-3xl">
        {value}
      </p>
    </div>
  );
}

function SettlementCard({
  item,
  processing,
  onOpen,
}: {
  item: AdminCashSettlementRecord;
  processing: boolean;
  onOpen: () => void;
}) {
  return (
    <article className="border border-[#D8D6D0] bg-white p-5 md:p-7">
      <div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-start">
        <div className="flex min-w-0 items-start gap-4">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center border border-[#E5E2DC] bg-[#FAF9F6] text-[#A58A64]">
            <Wallet size={19} />
          </div>

          <div className="min-w-0">
            <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
              {item.reference}
            </p>

            <h3 className="mt-2 break-words font-serif text-2xl text-[#171717]">
              {item.vendorName}
            </h3>

            <p className="mt-2 text-xs text-[#77736C]">
              {item.projectName || "No linked project"}
            </p>
          </div>
        </div>

        <div className="flex flex-wrap gap-2 lg:justify-end">
          <span
            className={`px-3 py-2 text-[8px] uppercase tracking-widest ${settlementStatusStyle(item.overallStatus)}`}
          >
            {item.overallStatus}
          </span>

          {processing && (
            <span className="text-[8px] uppercase tracking-widest text-[#94743F]">
              Processing...
            </span>
          )}
        </div>
      </div>

      <div className="mt-6 grid grid-cols-1 gap-4 border-t border-[#E5E2DC] pt-5 sm:grid-cols-3">
        <Metric
          label="Settlement Amount"
          value={formatCurrency(item.amount)}
        />

        <Metric
          label="Vendor Acknowledgement"
          value={item.vendorAcknowledgement}
        />

        <Metric
          label="Finance Verification"
          value={item.financeStatus}
        />
      </div>

      <div className="mt-6 flex flex-col justify-between gap-4 border-t border-[#E5E2DC] pt-5 sm:flex-row sm:items-center">
        <p className="text-[10px] text-[#77736C]">
          Initiated: {formatDate(item.initiatedAt)}
        </p>

        <button
          type="button"
          onClick={onOpen}
          className="inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#987543] hover:text-[#171717]"
        >
          Review Settlement
          <ArrowUpRight size={14} />
        </button>
      </div>
    </article>
  );
}

function Metric({
  label,
  value,
}: {
  label: string;
  value: string;
}) {
  return (
    <div className="min-w-0">
      <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
        {label}
      </p>

      <p className="mt-2 break-words text-sm text-[#33312D]">
        {value}
      </p>
    </div>
  );
}

function DetailLine({
  icon,
  label,
  value,
}: {
  icon: ReactNode;
  label: string;
  value: string;
}) {
  return (
    <div className="flex min-w-0 items-start gap-3">
      <span className="mt-0.5 shrink-0 text-[#A58A64]">
        {icon}
      </span>

      <div className="min-w-0">
        <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
          {label}
        </p>

        <p className="mt-1 break-words text-xs text-[#55514A]">
          {value}
        </p>
      </div>
    </div>
  );
}

function SectionHeading({ children }: { children: ReactNode }) {
  return (
    <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
      {children}
    </p>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  Search,
  Users,
  Mail,
  Phone,
  MapPin,
  Building2,
  FolderKanban,
  ArrowUpRight,
  RefreshCw,
  ShieldCheck,
  UserPlus,
  X,
  AlertCircle,
  Clock3,
  KeyRound,
} from "lucide-react";

export type AdminClientStatus =
  | "Active"
  | "Inactive"
  | "Suspended";

export type ClientPortalAccessStatus =
  | "Not Invited"
  | "Invitation Pending"
  | "Active"
  | "Expired"
  | "Suspended";

export interface AdminClientProject {
  id: string;
  reference: string;
  name: string;
  status:
    | "Planning"
    | "Under Design"
    | "Under Execution"
    | "On Hold"
    | "Completed";
}

export interface AdminClientRecord {
  id: string;
  reference: string;
  fullName: string;
  email: string;
  phone: string;
  organisation?: string;
  location?: string;
  status: AdminClientStatus;
  portalAccess: ClientPortalAccessStatus;
  createdAt: string;
  lastUpdated: string;
  projects: AdminClientProject[];
}

interface AdminClientManagementProps {
  clients: AdminClientRecord[];
  loading?: boolean;
  updatingClientId?: string;
  error?: string;

  onRefresh?: () => void;

  onOpenClient?: (clientId: string) => void;

  onInviteClient: (
    clientId: string
  ) => Promise<void>;

  onUpdateClientStatus: (
    clientId: string,
    status: AdminClientStatus
  ) => Promise<void>;

  onUpdatePortalAccess: (
    clientId: string,
    action: "resend" | "revoke"
  ) => Promise<void>;

  onOpenProject?: (projectId: string) => void;
}

type ClientStatusFilter = "All" | AdminClientStatus;
type PortalFilter = "All" | ClientPortalAccessStatus;

const CLIENT_STATUSES: AdminClientStatus[] = [
  "Active",
  "Inactive",
  "Suspended",
];

const PORTAL_STATUSES: ClientPortalAccessStatus[] = [
  "Not Invited",
  "Invitation Pending",
  "Active",
  "Expired",
  "Suspended",
];

function formatDate(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  }).format(date);
}

function getClientStatusStyle(status: AdminClientStatus) {
  switch (status) {
    case "Active":
      return "bg-[#EAF1E8] text-[#547A51]";
    case "Suspended":
      return "bg-[#F8EAE7] text-[#9A5147]";
    default:
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

function getPortalStatusStyle(status: ClientPortalAccessStatus) {
  switch (status) {
    case "Active":
      return "bg-[#EAF1E8] text-[#547A51]";
    case "Invitation Pending":
      return "bg-[#F4EFE2] text-[#94743F]";
    case "Expired":
    case "Suspended":
      return "bg-[#F8EAE7] text-[#9A5147]";
    default:
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

export function AdminClientManagement({
  clients,
  loading = false,
  updatingClientId,
  error,
  onRefresh,
  onOpenClient,
  onInviteClient,
  onUpdateClientStatus,
  onUpdatePortalAccess,
  onOpenProject,
}: AdminClientManagementProps) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] =
    useState<ClientStatusFilter>("All");
  const [portalFilter, setPortalFilter] =
    useState<PortalFilter>("All");

  const [selectedClient, setSelectedClient] =
    useState<AdminClientRecord | null>(null);

  const [actionLoading, setActionLoading] = useState(false);
  const [actionError, setActionError] = useState("");

  const counts = useMemo(() => ({
    total: clients.length,
    active: clients.filter(
      (client) => client.status === "Active"
    ).length,
    suspended: clients.filter(
      (client) => client.status === "Suspended"
    ).length,
    portalActive: clients.filter(
      (client) => client.portalAccess === "Active"
    ).length,
    invitationsPending: clients.filter(
      (client) => client.portalAccess === "Invitation Pending"
    ).length,
  }), [clients]);

  const filteredClients = useMemo(() => {
    const query = search.trim().toLowerCase();

    return clients.filter((client) => {
      const matchesSearch =
        !query ||
        client.fullName.toLowerCase().includes(query) ||
        client.reference.toLowerCase().includes(query) ||
        client.email.toLowerCase().includes(query) ||
        client.phone.toLowerCase().includes(query) ||
        (client.organisation ?? "").toLowerCase().includes(query) ||
        (client.location ?? "").toLowerCase().includes(query);

      const matchesStatus =
        statusFilter === "All" ||
        client.status === statusFilter;

      const matchesPortal =
        portalFilter === "All" ||
        client.portalAccess === portalFilter;

      return matchesSearch && matchesStatus && matchesPortal;
    });
  }, [clients, search, statusFilter, portalFilter]);

  async function runAction(action: () => Promise<void>) {
    if (actionLoading) return;

    setActionLoading(true);
    setActionError("");

    try {
      await action();
    } catch (err) {
      setActionError(
        err instanceof Error
          ? err.message
          : "The operation could not be completed."
      );
    } finally {
      setActionLoading(false);
    }
  }

  function clearFilters() {
    setSearch("");
    setStatusFilter("All");
    setPortalFilter("All");
  }

  function openClient(client: AdminClientRecord) {
    setSelectedClient(client);
    setActionError("");
  }

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-9 md:px-10 md:py-12 lg:px-12">

      {/* Header */}
      <header className="flex flex-col justify-between gap-6 border-b border-[#D8D6D0] pb-8 md:flex-row md:items-end">
        <div>
          <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
            Administration / Client Records
          </p>

          <h1 className="mt-4 font-serif text-4xl text-[#171717] md:text-5xl">
            Client Management
          </h1>

          <p className="mt-3 max-w-xl text-sm leading-7 text-[#77736C]">
            Manage client records, project associations and
            invitation-controlled portal access.
          </p>
        </div>

        {onRefresh && (
          <button
            type="button"
            onClick={onRefresh}
            disabled={loading}
            className="inline-flex w-fit items-center gap-2 border border-[#D8D6D0] bg-white px-5 py-3 text-[10px] uppercase tracking-widest text-[#55514A] hover:border-[#A58A64] disabled:opacity-50"
          >
            <RefreshCw size={14} />
            Refresh Clients
          </button>
        )}
      </header>

      {/* Error */}
      {error && (
        <div
          role="alert"
          className="mt-6 flex items-start gap-3 border border-[#E3C9C5] bg-[#FAF3F1] p-5"
        >
          <AlertCircle
            size={18}
            className="mt-0.5 shrink-0 text-[#9A5147]"
          />
          <p className="text-xs leading-6 text-[#805B55]">
            {error}
          </p>
        </div>
      )}

      {/* Summary */}
      <section className="mt-9 grid grid-cols-2 gap-px border border-[#D8D6D0] bg-[#D8D6D0] lg:grid-cols-5">
        <SummaryCard label="Total Clients" value={counts.total} />
        <SummaryCard label="Active Clients" value={counts.active} />
        <SummaryCard label="Suspended" value={counts.suspended} />
        <SummaryCard label="Portal Accounts Active" value={counts.portalActive} />
        <SummaryCard label="Invitations Pending" value={counts.invitationsPending} />
      </section>

      {/* Search and Filters */}
      <section className="mt-10">
        <div className="relative">
          <Search
            size={17}
            className="absolute left-4 top-1/2 -translate-y-1/2 text-[#99958D]"
          />

          <input
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            placeholder="Search client, reference, email, phone or organisation..."
            aria-label="Search clients"
            className="h-12 w-full border border-[#D8D6D0] bg-white pl-11 pr-4 text-sm outline-none focus:border-[#A58A64]"
          />
        </div>

        <div className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-2">
          <FilterSelect
            label="Client Status"
            value={statusFilter}
            onChange={(value) =>
              setStatusFilter(value as ClientStatusFilter)
            }
            options={["All", ...CLIENT_STATUSES]}
          />

          <FilterSelect
            label="Portal Access"
            value={portalFilter}
            onChange={(value) =>
              setPortalFilter(value as PortalFilter)
            }
            options={["All", ...PORTAL_STATUSES]}
          />
        </div>

        {(search || statusFilter !== "All" || portalFilter !== "All") && (
          <div className="mt-4 flex items-center justify-between gap-3">
            <p className="text-xs text-[#77736C]">
              Showing {filteredClients.length} of {clients.length} clients
            </p>

            <button
              type="button"
              onClick={clearFilters}
              className="text-[9px] uppercase tracking-widest text-[#987543]"
            >
              Clear Filters
            </button>
          </div>
        )}
      </section>

      {/* Client Register */}
      <section className="mt-9">
        <div className="flex items-end justify-between border-b border-[#D8D6D0] pb-5">
          <div>
            <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
              Client Directory
            </p>

            <h2 className="mt-3 font-serif text-2xl text-[#171717]">
              Registered Clients
            </h2>
          </div>

          <p className="font-mono text-[9px] text-[#99958D]">
            {filteredClients.length} RECORDS
          </p>
        </div>

        {loading ? (
          <div className="flex min-h-64 items-center justify-center">
            <p className="font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
              Loading client records...
            </p>
          </div>
        ) : filteredClients.length === 0 ? (
          <div className="mt-5 border border-[#D8D6D0] bg-white px-6 py-16 text-center">
            <Users
              size={28}
              strokeWidth={1.3}
              className="mx-auto text-[#A58A64]"
            />

            <h3 className="mt-5 font-serif text-2xl text-[#171717]">
              No clients found
            </h3>

            <p className="mt-3 text-xs text-[#77736C]">
              No client records match your current search and filters.
            </p>
          </div>
        ) : (
          <div className="mt-5 space-y-3">
            {filteredClients.map((client) => (
              <ClientCard
                key={client.id}
                client={client}
                onOpen={() => openClient(client)}
              />
            ))}
          </div>
        )}
      </section>

      {/* Client Detail Drawer */}
      {selectedClient && (
        <div
          className="fixed inset-0 z-[60] flex justify-end bg-black/50"
          role="presentation"
          onMouseDown={(event) => {
            if (
              event.target === event.currentTarget &&
              !actionLoading
            ) {
              setSelectedClient(null);
            }
          }}
        >
          <aside
            role="dialog"
            aria-modal="true"
            aria-labelledby="client-detail-title"
            className="flex h-full w-full max-w-2xl flex-col overflow-y-auto bg-[#F2F0EB] shadow-2xl"
          >
            {/* Drawer Header */}
            <div className="sticky top-0 z-10 flex items-center justify-between border-b border-[#D8D6D0] bg-[#F2F0EB] px-6 py-5 md:px-8">
              <div>
                <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                  Client Record / {selectedClient.reference}
                </p>

                <h2
                  id="client-detail-title"
                  className="mt-2 font-serif text-2xl text-[#171717]"
                >
                  Client Details
                </h2>
              </div>

              <button
                type="button"
                onClick={() => setSelectedClient(null)}
                disabled={actionLoading}
                aria-label="Close client details"
                className="text-[#77736C] disabled:opacity-40"
              >
                <X size={21} />
              </button>
            </div>

            <div className="flex-1 space-y-7 p-6 md:p-8">

              {/* Identity */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex h-12 w-12 shrink-0 items-center justify-center border border-[#E5E2DC] bg-[#FAF9F6] text-[#A58A64]">
                    <Users size={20} />
                  </div>

                  <span
                    className={`px-3 py-2 text-[8px] uppercase tracking-widest ${getClientStatusStyle(selectedClient.status)}`}
                  >
                    {selectedClient.status}
                  </span>
                </div>

                <h3 className="mt-5 font-serif text-3xl text-[#171717]">
                  {selectedClient.fullName}
                </h3>

                {selectedClient.organisation && (
                  <p className="mt-2 text-xs text-[#77736C]">
                    {selectedClient.organisation}
                  </p>
                )}

                <div className="mt-6 space-y-4 border-t border-[#E5E2DC] pt-5">
                  <DetailLine
                    icon={<Mail size={15} />}
                    label="Email"
                    value={selectedClient.email}
                  />

                  <DetailLine
                    icon={<Phone size={15} />}
                    label="Phone"
                    value={selectedClient.phone}
                  />

                  {selectedClient.location && (
                    <DetailLine
                      icon={<MapPin size={15} />}
                      label="Location"
                      value={selectedClient.location}
                    />
                  )}
                </div>
              </section>

              {/* Account Status */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <SectionHeading>Client Account</SectionHeading>

                <div className="mt-4 flex flex-wrap items-center justify-between gap-3">
                  <p className="text-xs text-[#77736C]">
                    Account status
                  </p>

                  <span
                    className={`px-3 py-2 text-[8px] uppercase tracking-widest ${getClientStatusStyle(selectedClient.status)}`}
                  >
                    {selectedClient.status}
                  </span>
                </div>

                <label className="mt-5 block">
                  <span className="mb-2 block font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                    Update Account Status
                  </span>

                  <select
                    value={selectedClient.status}
                    disabled={
                      actionLoading ||
                      updatingClientId === selectedClient.id
                    }
                    onChange={(event) => {
                      const status = event.target.value as AdminClientStatus;

                      void runAction(() =>
                        onUpdateClientStatus(
                          selectedClient.id,
                          status
                        )
                      );
                    }}
                    className="h-11 w-full border border-[#D8D6D0] bg-white px-3 text-xs outline-none focus:border-[#A58A64]"
                  >
                    {CLIENT_STATUSES.map((status) => (
                      <option key={status} value={status}>
                        {status}
                      </option>
                    ))}
                  </select>
                </label>
              </section>

              {/* Portal Access */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <div className="flex items-start gap-3">
                  <ShieldCheck
                    size={20}
                    className="mt-0.5 shrink-0 text-[#A58A64]"
                  />

                  <div>
                    <SectionHeading>Portal Access Control</SectionHeading>

                    <p className="mt-2 text-xs leading-6 text-[#77736C]">
                      Client access is invitation-controlled.
                      Account activation and revocation must be
                      confirmed by the authentication service.
                    </p>
                  </div>
                </div>

                <div className="mt-5 flex flex-wrap items-center justify-between gap-3 border-y border-[#E5E2DC] py-4">
                  <p className="text-xs text-[#77736C]">
                    Current portal status
                  </p>

                  <span
                    className={`px-3 py-2 text-[8px] uppercase tracking-widest ${getPortalStatusStyle(selectedClient.portalAccess)}`}
                  >
                    {selectedClient.portalAccess}
                  </span>
                </div>

                {selectedClient.portalAccess === "Not Invited" && (
                  <button
                    type="button"
                    disabled={
                      actionLoading ||
                      selectedClient.status !== "Active"
                    }
                    onClick={() =>
                      void runAction(() =>
                        onInviteClient(selectedClient.id)
                      )
                    }
                    className="mt-5 inline-flex w-full items-center justify-center gap-2 bg-[#171717] px-5 py-4 text-[9px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:cursor-not-allowed disabled:opacity-40"
                  >
                    <UserPlus size={15} />
                    Send Portal Invitation
                  </button>
                )}

                {selectedClient.portalAccess === "Invitation Pending" && (
                  <div className="mt-5 space-y-3">
                    <button
                      type="button"
                      disabled={actionLoading}
                      onClick={() =>
                        void runAction(() =>
                          onUpdatePortalAccess(
                            selectedClient.id,
                            "resend"
                          )
                        )
                      }
                      className="inline-flex w-full items-center justify-center gap-2 border border-[#D8D6D0] px-5 py-4 text-[9px] uppercase tracking-widest text-[#55514A] hover:border-[#A58A64] disabled:opacity-40"
                    >
                      <Mail size={15} />
                      Resend Invitation
                    </button>

                    <button
                      type="button"
                      disabled={actionLoading}
                      onClick={() =>
                        void runAction(() =>
                          onUpdatePortalAccess(
                            selectedClient.id,
                            "revoke"
                          )
                        )
                      }
                      className="w-full border border-[#E3C9C5] px-5 py-4 text-[9px] uppercase tracking-widest text-[#9A5147] disabled:opacity-40"
                    >
                      Revoke Invitation
                    </button>
                  </div>
                )}

                {selectedClient.portalAccess === "Expired" && (
                  <button
                    type="button"
                    disabled={
                      actionLoading ||
                      selectedClient.status !== "Active"
                    }
                    onClick={() =>
                      void runAction(() =>
                        onInviteClient(selectedClient.id)
                      )
                    }
                    className="mt-5 inline-flex w-full items-center justify-center gap-2 bg-[#171717] px-5 py-4 text-[9px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:opacity-40"
                  >
                    <RefreshCw size={15} />
                    Issue New Invitation
                  </button>
                )}

                {selectedClient.portalAccess === "Active" && (
                  <button
                    type="button"
                    disabled={actionLoading}
                    onClick={() =>
                      void runAction(() =>
                        onUpdatePortalAccess(
                          selectedClient.id,
                          "revoke"
                        )
                      )
                    }
                    className="mt-5 w-full border border-[#E3C9C5] px-5 py-4 text-[9px] uppercase tracking-widest text-[#9A5147] disabled:opacity-40"
                  >
                    Revoke Portal Access
                  </button>
                )}

                {selectedClient.portalAccess === "Suspended" && (
                  <p className="mt-5 text-xs leading-6 text-[#9A5147]">
                    Portal access is currently suspended. Reactivation
                    must follow the studio&apos;s authorised access-review
                    procedure.
                  </p>
                )}
              </section>

              {/* Linked Projects */}
              <section>
                <div className="flex items-end justify-between border-b border-[#D8D6D0] pb-4">
                  <div>
                    <SectionHeading>Project Association</SectionHeading>

                    <h3 className="mt-3 font-serif text-2xl text-[#171717]">
                      Linked Projects
                    </h3>
                  </div>

                  <p className="font-mono text-[9px] text-[#99958D]">
                    {selectedClient.projects.length} PROJECTS
                  </p>
                </div>

                {selectedClient.projects.length === 0 ? (
                  <div className="mt-4 border border-[#D8D6D0] bg-white p-7 text-center">
                    <FolderKanban
                      size={24}
                      className="mx-auto text-[#A58A64]"
                    />

                    <p className="mt-3 text-xs text-[#77736C]">
                      No projects are linked to this client.
                    </p>
                  </div>
                ) : (
                  <div className="mt-4 space-y-3">
                    {selectedClient.projects.map((project) => (
                      <button
                        key={project.id}
                        type="button"
                        disabled={!onOpenProject}
                        onClick={() => onOpenProject?.(project.id)}
                        className="flex w-full items-center justify-between gap-4 border border-[#D8D6D0] bg-white p-5 text-left hover:border-[#A58A64] disabled:cursor-default"
                      >
                        <span className="min-w-0">
                          <span className="block font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                            {project.reference}
                          </span>

                          <span className="mt-2 block font-serif text-xl text-[#171717]">
                            {project.name}
                          </span>

                          <span className="mt-2 block text-[9px] text-[#77736C]">
                            {project.status}
                          </span>
                        </span>

                        <ArrowUpRight
                          size={17}
                          className="shrink-0 text-[#A58A64]"
                        />
                      </button>
                    ))}
                  </div>
                )}
              </section>

              {/* Record Metadata */}
              <section className="grid grid-cols-2 gap-3">
                <MetadataCard
                  label="Client Created"
                  value={formatDate(selectedClient.createdAt)}
                />

                <MetadataCard
                  label="Last Updated"
                  value={formatDate(selectedClient.lastUpdated)}
                />
              </section>

              {actionError && (
                <div
                  role="alert"
                  className="border border-[#E3C9C5] bg-[#FAF3F1] p-4 text-xs leading-6 text-[#805B55]"
                >
                  {actionError}
                </div>
              )}
            </div>

            {/* Drawer Footer */}
            <div className="sticky bottom-0 border-t border-[#D8D6D0] bg-[#F2F0EB] p-5">
              <div className="flex flex-col-reverse gap-3 sm:flex-row">
                <button
                  type="button"
                  onClick={() => setSelectedClient(null)}
                  disabled={actionLoading}
                  className="flex-1 border border-[#D8D6D0] px-5 py-4 text-[9px] uppercase tracking-widest text-[#77736C] disabled:opacity-40"
                >
                  Close
                </button>

                {onOpenClient && (
                  <button
                    type="button"
                    onClick={() => onOpenClient(selectedClient.id)}
                    className="flex-1 bg-[#171717] px-5 py-4 text-[9px] uppercase tracking-widest text-white hover:bg-[#A58A64]"
                  >
                    Open Full Client Record
                  </button>
                )}
              </div>
            </div>
          </aside>
        </div>
      )}
    </main>
  );

}

function SummaryCard({
  label,
  value,
}: {
  label: string;
  value: number;
}) {
  return (
    <div className="bg-white p-5 md:p-6">
      <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
        {label}
      </p>

      <p className="mt-5 font-serif text-3xl text-[#171717]">
        {value.toLocaleString("en-IN")}
      </p>
    </div>
