          </option>
        ))}
      </select>
    </label>
  );
}

"use client";

import {
  Activity,
  AlertCircle,
  ArrowDownRight,
  ArrowRight,
  ArrowUpRight,
  Banknote,
  Building2,
  CalendarDays,
  CheckCircle2,
  Clock3,
  FileText,
  FolderKanban,
  IndianRupee,
  ShieldCheck,
  Users,
} from "lucide-react";

export type AdminActivityType =
  | "project"
  | "invoice"
  | "approval"
  | "payment"
  | "client"
  | "vendor"
  | "system";

export interface AdminDashboardMetrics {
  activeProjects: number;
  completedProjects: number;
  totalClients: number;
  activeVendors: number;
  newEnquiries: number;
  pendingApprovals: number;
  outstandingReceivables: number;
  overdueReceivables: number;
  pendingInvoices: number;
}

export interface AdminProjectSummary {
  id: string;
  reference: string;
  name: string;
  clientName: string;
  status:
    | "Planning"
    | "Under Design"
    | "Under Execution"
    | "On Hold"
    | "Completed";
  progressPercentage?: number;
  updatedAt: string;
}

export interface AdminApprovalSummary {
  id: string;
  reference: string;
  title: string;
  category: string;
  amount?: number;
  currency?: string;
  submittedBy: string;
  submittedAt: string;
  priority: "Normal" | "High" | "Urgent";
}

export interface AdminActivity {
  id: string;
  type: AdminActivityType;
  title: string;
  description: string;
  actorName: string;
  occurredAt: string;
}

export interface AdminDashboardData {
  metrics: AdminDashboardMetrics;
  projects: AdminProjectSummary[];
  approvals: AdminApprovalSummary[];
  activities: AdminActivity[];
  lastUpdatedAt?: string;
}

interface AdminDashboardOverviewProps {
  data: AdminDashboardData | null;
  loading?: boolean;
  error?: string;
  onRefresh?: () => void;
  onOpenProjects?: () => void;
  onOpenApprovals?: () => void;
  onOpenEnquiries?: () => void;
  onOpenFinance?: () => void;
  onOpenProject?: (projectId: string) => void;
  onOpenApproval?: (approvalId: string) => void;
  onOpenActivity?: (activityId: string) => void;
}

function formatCurrency(
  amount: number,
  currency = "INR"
) {
  if (!Number.isFinite(amount)) return "—";

  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency,
    maximumFractionDigits: 0,
  }).format(amount);
}

function formatDate(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
}

function getProjectStatusStyle(status: AdminProjectSummary["status"]) {
  switch (status) {
    case "Completed":
      return "bg-[#EAF1E8] text-[#547A51]";
    case "Under Execution":
      return "bg-[#EAF0F5] text-[#58738C]";
    case "Under Design":
      return "bg-[#F4EFE2] text-[#94743F]";
    case "On Hold":
      return "bg-[#F8EAE7] text-[#9A5147]";
    default:
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

function getPriorityStyle(priority: AdminApprovalSummary["priority"]) {
  switch (priority) {
    case "Urgent":
      return "bg-[#F8EAE7] text-[#9A5147]";
    case "High":
      return "bg-[#F4EFE2] text-[#94743F]";
    default:
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

function getActivityIcon(type: AdminActivityType) {
  switch (type) {
    case "project":
      return FolderKanban;
    case "invoice":
      return FileText;
    case "approval":
      return CheckCircle2;
    case "payment":
      return Banknote;
    case "client":
      return Users;
    case "vendor":
      return Building2;
    default:
      return Activity;
  }
}

export function AdminDashboardOverview({
  data,
  loading = false,
  error,
  onRefresh,
  onOpenProjects,
  onOpenApprovals,
  onOpenEnquiries,
  onOpenFinance,
  onOpenProject,
  onOpenApproval,
  onOpenActivity,
}: AdminDashboardOverviewProps) {
  if (loading && !data) {
    return (
      <div className="flex min-h-[450px] items-center justify-center bg-[#F2F0EB]">
        <p className="font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
          Loading studio operations...
        </p>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="bg-[#F2F0EB] p-6 md:p-10">
        <div
          role="alert"
          className="border border-[#E3C9C5] bg-[#FAF3F1] p-6"
        >
          <div className="flex items-start gap-3">
            <AlertCircle className="mt-0.5 text-[#9A5147]" size={20} />
            <div>
              <h2 className="font-serif text-2xl text-[#171717]">
                Dashboard unavailable
              </h2>
              <p className="mt-2 text-sm leading-6 text-[#805B55]">
                {error || "Dashboard data could not be loaded."}
              </p>
            </div>
          </div>

          {onRefresh && (
            <button
              type="button"
              onClick={onRefresh}
              className="mt-5 bg-[#171717] px-6 py-3 text-[10px] uppercase tracking-widest text-white"
            >
              Retry
            </button>
          )}
        </div>
      </div>
    );
  }

  const { metrics } = data;

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-9 md:px-10 md:py-12 lg:px-12">

      {/* Heading */}
      <header className="flex flex-col justify-between gap-5 border-b border-[#D8D6D0] pb-8 md:flex-row md:items-end">
        <div>
          <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
            Studio Operations / Dashboard
          </p>

          <h1 className="mt-4 font-serif text-4xl text-[#171717] md:text-5xl">
            Operations Overview
          </h1>

          <p className="mt-3 max-w-xl text-sm leading-7 text-[#77736C]">
            Monitor projects, financial activity, enquiries and
            operational decisions across the studio.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-4">
          {data.lastUpdatedAt && (
            <p className="font-mono text-[9px] text-[#99958D]">
              Updated: {formatDate(data.lastUpdatedAt)}
            </p>
          )}

          {onRefresh && (
            <button
              type="button"
              onClick={onRefresh}
              disabled={loading}
              className="border border-[#D8D6D0] bg-white px-5 py-3 text-[10px] uppercase tracking-widest text-[#55514A] hover:border-[#A58A64] disabled:opacity-50"
            >
              {loading ? "Refreshing..." : "Refresh Data"}
            </button>
          )}
        </div>
      </header>

      {/* Partial refresh error */}
      {error && (
        <div
          role="alert"
          className="mt-6 border border-[#E3C9C5] bg-[#FAF3F1] px-5 py-4 text-xs leading-6 text-[#805B55]"
        >
          {error} Previously loaded dashboard data is still displayed.
        </div>
      )}

      {/* Main Metrics */}
      <section className="mt-9">
        <SectionLabel>Operational Summary</SectionLabel>

        <div className="mt-5 grid grid-cols-1 gap-px border border-[#D8D6D0] bg-[#D8D6D0] sm:grid-cols-2 xl:grid-cols-4">
          <MetricCard
            label="Active Projects"
            value={metrics.activeProjects}
            icon={<FolderKanban size={19} />}
            onClick={onOpenProjects}
          />

          <MetricCard
            label="Completed Projects"
            value={metrics.completedProjects}
            icon={<CheckCircle2 size={19} />}
            onClick={onOpenProjects}
          />

          <MetricCard
            label="Registered Clients"
            value={metrics.totalClients}
            icon={<Users size={19} />}
          />

          <MetricCard
            label="Active Vendors"
            value={metrics.activeVendors}
            icon={<Building2 size={19} />}
          />
        </div>
      </section>

      {/* Attention Required */}
      <section className="mt-11">
        <SectionLabel>Attention Required</SectionLabel>

        <div className="mt-5 grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
          <AttentionCard
            label="Pending Approvals"
            value={metrics.pendingApprovals}
            description="Decisions awaiting authorised review"
            icon={<ClipboardIcon />}
            onClick={onOpenApprovals}
          />

          <AttentionCard
            label="New Enquiries"
            value={metrics.newEnquiries}
            description="Enquiries requiring follow-up"
            icon={<Users size={19} />}
            onClick={onOpenEnquiries}
          />

          <AttentionCard
            label="Pending Invoices"
            value={metrics.pendingInvoices}
            description="Invoices awaiting processing"
            icon={<FileText size={19} />}
            onClick={onOpenFinance}
          />

          <AttentionCard
            label="Overdue Receivables"
            value={formatCurrency(metrics.overdueReceivables)}
            description="Outstanding amounts past due"
            icon={<Clock3 size={19} />}
            onClick={onOpenFinance}
            monetary
          />
        </div>
      </section>

      {/* Finance */}
      <section className="mt-11">
        <SectionLabel>Financial Position</SectionLabel>

        <div className="mt-5 grid grid-cols-1 gap-px border border-[#D8D6D0] bg-[#D8D6D0] md:grid-cols-2">
          <div className="bg-white p-7 md:p-9">
            <div className="flex items-center justify-between">
              <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
                Outstanding Receivables
              </p>
              <IndianRupee size={19} className="text-[#A58A64]" />
            </div>

            <p className="mt-6 font-serif text-3xl text-[#171717] md:text-4xl">
              {formatCurrency(metrics.outstandingReceivables)}
            </p>

            <p className="mt-3 text-xs leading-6 text-[#77736C]">
              Total unpaid receivables recorded by the finance system.
            </p>

            {onOpenFinance && (
              <button
                type="button"
                onClick={onOpenFinance}
                className="mt-7 inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#987543]"
              >
                View Finance Records
                <ArrowUpRight size={14} />
              </button>
            )}
          </div>

          <div className="bg-white p-7 md:p-9">
            <div className="flex items-center justify-between">
              <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
                Overdue Receivables
              </p>
              <Clock3 size={19} className="text-[#A58A64]" />
            </div>

            <p className="mt-6 font-serif text-3xl text-[#171717] md:text-4xl">
              {formatCurrency(metrics.overdueReceivables)}
            </p>

            <p className="mt-3 text-xs leading-6 text-[#77736C]">
              Unpaid receivables classified as overdue by the backend.
            </p>

            {onOpenFinance && (
              <button
                type="button"
                onClick={onOpenFinance}
                className="mt-7 inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#987543]"
              >
                Review Receivables
                <ArrowUpRight size={14} />
              </button>
            )}
          </div>
        </div>
      </section>

      {/* Project and Approval Columns */}
      <section className="mt-12 grid grid-cols-1 gap-9 xl:grid-cols-2">

        {/* Projects */}
        <div>
          <div className="flex items-end justify-between gap-4 border-b border-[#D8D6D0] pb-5">
            <div>
              <SectionLabel>Project Activity</SectionLabel>
              <h2 className="mt-3 font-serif text-2xl text-[#171717]">
                Recent Projects
              </h2>
            </div>

            {onOpenProjects && (
              <button
                type="button"
                onClick={onOpenProjects}
                className="text-[9px] uppercase tracking-widest text-[#987543]"
              >
                View All
              </button>
            )}
          </div>

          <div className="mt-5 space-y-3">
            {data.projects.length === 0 ? (
              <EmptyState message="No project records available." />
            ) : (
              data.projects.map((project) => (
                <button
                  key={project.id}
                  type="button"
                  onClick={() => onOpenProject?.(project.id)}
                  disabled={!onOpenProject}
                  className="w-full border border-[#D8D6D0] bg-white p-5 text-left transition-colors hover:border-[#A58A64] disabled:cursor-default"
                >
                  <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start">
                    <div className="min-w-0">
                      <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                        {project.reference}
                      </p>

                      <h3 className="mt-2 truncate font-serif text-xl text-[#171717]">
                        {project.name}
                      </h3>

                      <p className="mt-2 text-xs text-[#77736C]">
                        Client: {project.clientName}
                      </p>
                    </div>

                    <span
                      className={`w-fit px-3 py-2 text-[9px] uppercase tracking-widest ${getProjectStatusStyle(project.status)}`}
                    >
                      {project.status}
                    </span>
                  </div>

                  {typeof project.progressPercentage === "number" && (
                    <div className="mt-5">
                      <div className="flex justify-between font-mono text-[9px] text-[#99958D]">
                        <span>Reported Progress</span>
                        <span>
                          {project.progressPercentage}%
                        </span>
                      </div>

                      <div className="mt-2 h-1.5 overflow-hidden bg-[#ECEAE5]">
                        <div
                          className="h-full bg-[#A58A64]"
                          style={{
                            width: `${Math.min(
                              100,
                              Math.max(0, project.progressPercentage)
                            )}%`,
                          }}
                        />
                      </div>
                    </div>
                  )}

                  <p className="mt-4 font-mono text-[9px] text-[#99958D]">
                    Updated: {formatDate(project.updatedAt)}
                  </p>
                </button>
              ))
            )}
          </div>
        </div>

        {/* Approvals */}
        <div>
          <div className="flex items-end justify-between gap-4 border-b border-[#D8D6D0] pb-5">
            <div>
              <SectionLabel>Decision Queue</SectionLabel>
              <h2 className="mt-3 font-serif text-2xl text-[#171717]">
                Pending Approvals
              </h2>
            </div>

            {onOpenApprovals && (
              <button
                type="button"
                onClick={onOpenApprovals}
                className="text-[9px] uppercase tracking-widest text-[#987543]"
              >
                View All
              </button>
            )}
          </div>

          <div className="mt-5 space-y-3">
            {data.approvals.length === 0 ? (
              <EmptyState message="No pending approval records available." />
            ) : (
              data.approvals.map((approval) => (
                <button
                  key={approval.id}
                  type="button"
                  onClick={() => onOpenApproval?.(approval.id)}
                  disabled={!onOpenApproval}
                  className="w-full border border-[#D8D6D0] bg-white p-5 text-left transition-colors hover:border-[#A58A64] disabled:cursor-default"
                >
                  <div className="flex flex-wrap items-center justify-between gap-3">
                    <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                      {approval.reference}
                    </p>

                    <span
                      className={`px-3 py-2 text-[9px] uppercase tracking-widest ${getPriorityStyle(approval.priority)}`}
                    >
                      {approval.priority}
                    </span>
                  </div>

                  <h3 className="mt-4 font-serif text-xl text-[#171717]">
                    {approval.title}
                  </h3>

                  <p className="mt-2 text-xs text-[#77736C]">
                    {approval.category}
                  </p>

                  {typeof approval.amount === "number" && (
                    <p className="mt-4 font-serif text-xl text-[#33312D]">
                      {formatCurrency(
                        approval.amount,
                        approval.currency || "INR"
                      )}
                    </p>
                  )}

                  <div className="mt-5 flex flex-col gap-2 border-t border-[#E5E2DC] pt-4">
                    <p className="text-[10px] text-[#77736C]">
                      Submitted by: {approval.submittedBy}
                    </p>

                    <p className="font-mono text-[9px] text-[#99958D]">
                      {formatDate(approval.submittedAt)}
                    </p>
                  </div>
                </button>
              ))
            )}
          </div>
        </div>
      </section>

      {/* Recent Activity */}
      <section className="mt-12">
        <div className="border-b border-[#D8D6D0] pb-5">
          <SectionLabel>System Activity</SectionLabel>

          <h2 className="mt-3 font-serif text-2xl text-[#171717]">
            Recent Activity
          </h2>
        </div>

        <div className="mt-5 border border-[#D8D6D0] bg-white">
          {data.activities.length === 0 ? (
            <EmptyState message="No activity records available." />
          ) : (
            data.activities.map((activity, index) => {
              const Icon = getActivityIcon(activity.type);

              return (
                <button
                  key={activity.id}
                  type="button"
                  onClick={() => onOpenActivity?.(activity.id)}
                  disabled={!onOpenActivity}
                  className={`flex w-full items-start gap-4 p-5 text-left hover:bg-[#FAF9F6] disabled:cursor-default md:p-6 ${
                    index !== data.activities.length - 1
                      ? "border-b border-[#E5E2DC]"
                      : ""
                  }`}
                >
                  <span className="flex h-10 w-10 shrink-0 items-center justify-center border border-[#E5E2DC] bg-[#FAF9F6] text-[#A58A64]">
                    <Icon size={17} />
                  </span>

                  <span className="min-w-0 flex-1">
                    <span className="block text-sm text-[#33312D]">
                      {activity.title}
                    </span>

                    <span className="mt-2 block text-xs leading-6 text-[#77736C]">
                      {activity.description}
                    </span>

                    <span className="mt-3 block font-mono text-[9px] text-[#99958D]">
                      {activity.actorName} · {formatDate(activity.occurredAt)}
                    </span>
                  </span>

                  <ArrowRight
                    size={15}
                    className="mt-2 shrink-0 text-[#A58A64]"
                  />
                </button>
              );
            })
          )}
        </div>
      </section>

      {/* Governance Notice */}
      <section className="mt-12 flex items-start gap-4 border border-[#D8D6D0] bg-white p-6">
        <ShieldCheck
          size={21}
          className="mt-0.5 shrink-0 text-[#A58A64]"
        />

        <div>
          <h3 className="text-sm font-medium text-[#33312D]">
            Administrative control and accountability
          </h3>

          <p className="mt-2 text-xs leading-7 text-[#77736C]">
            Dashboard figures are informational summaries. Financial
            approval, payment verification, vendor settlement and
            access-control decisions must be completed through their
            authorised workflows and recorded by the backend.
          </p>
        </div>
      </section>
    </main>
  );
}

function SectionLabel({ children }: { children: React.ReactNode }) {
  return (
    <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
      {children}
    </p>
  );
}

function MetricCard({
  label,
  value,
  icon,
  onClick,
}: {
  label: string;
  value: number;
  icon: React.ReactNode;
  onClick?: () => void;
}) {
  const content = (
    <>
      <div className="flex items-center justify-between gap-3">
        <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
          {label}
        </p>

        <span className="text-[#A58A64]">{icon}</span>
      </div>

      <p className="mt-7 font-serif text-4xl text-[#171717]">
        {value.toLocaleString("en-IN")}
      </p>
    </>
  );

  return onClick ? (
    <button
      type="button"
      onClick={onClick}
      className="bg-white p-6 text-left transition-colors hover:bg-[#FAF9F6] md:p-7"
    >
      {content}
    </button>
  ) : (
    <div className="bg-white p-6 md:p-7">{content}</div>
  );
}

function AttentionCard({
  label,
  value,
  description,
  icon,
  onClick,
  monetary = false,
}: {
  label: string;
  value: number | string;
  description: string;
  icon: React.ReactNode;
  onClick?: () => void;
  monetary?: boolean;
}) {
  const content = (
    <>
      <div className="flex items-center justify-between gap-3">
        <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
          {label}
        </p>

        <span className="text-[#A58A64]">{icon}</span>
      </div>

      <p
        className={`mt-6 font-serif text-[#171717] ${
          monetary ? "text-2xl" : "text-4xl"
        }`}
      >
        {monetary ? value : Number(value).toLocaleString("en-IN")}
      </p>

      <p className="mt-3 text-[10px] leading-5 text-[#77736C]">
        {description}
      </p>
    </>
  );

  return onClick ? (
    <button
      type="button"
      onClick={onClick}
      className="border border-[#D8D6D0] bg-white p-6 text-left transition-colors hover:border-[#A58A64]"
    >
      {content}
    </button>
  ) : (
    <div className="border border-[#D8D6D0] bg-white p-6">
      {content}
    </div>
  );
}

function EmptyState({ message }: { message: string }) {
  return (
    <div className="border border-[#D8D6D0] bg-white px-5 py-12 text-center">
      <CalendarDays
        size={23}
        strokeWidth={1.4}
        className="mx-auto text-[#A58A64]"
      />

      <p className="mt-4 text-xs text-[#77736C]">{message}</p>
    </div>
  );
}

function ClipboardIcon() {
  return <FileText size={19} />;
}

"use client";

import { useMemo, useState } from "react";
import type { ReactNode } from "react";
import {
  AlertCircle,
  CheckCircle2,
  Clock3,
  Eye,
  FileText,
  Filter,
  LockKeyhole,
  Search,
  ShieldCheck,
  XCircle,
} from "lucide-react";

export type DataAccessRequestStatus =
  | "PENDING"
  | "UNDER_REVIEW"
  | "APPROVED"
  | "REJECTED"
  | "REVOKED"
  | "EXPIRED";

export type DataAccessCategory =
  | "CLIENT_DATA"
  | "PROJECT_DATA"
  | "FINANCIAL_DATA"
  | "VENDOR_DATA"
  | "DOCUMENTS"
  | "AUDIT_RECORDS"
  | "OTHER";

export interface DataAccessRequest {
  id: string;
  requesterId: string;
  requesterName: string;
  requesterRole: string;
  category: DataAccessCategory;
  resourceName: string;
  requestedPermissions: string[];
  justification: string;
  status: DataAccessRequestStatus;
  requestedAt: string;
  reviewedAt?: string;
  reviewedBy?: string;
  expiresAt?: string;
  accessGranted?: boolean;
}

interface AdminDataAccessRequestCenterProps {
  requests: DataAccessRequest[];
  loading?: boolean;
  error?: string | null;
  currentUserId?: string;
  onRefresh?: () => void;
  onViewDetails?: (request: DataAccessRequest) => void;
  onReviewRequest?: (
    request: DataAccessRequest,
    decision: "APPROVE" | "REJECT"
  ) => void;
}

const statusConfig: Record<
  DataAccessRequestStatus,
  { label: string; className: string; icon: ReactNode }
> = {
  PENDING: {
    label: "Pending",
    className: "bg-amber-50 text-amber-700",
    icon: <Clock3 size={14} />,
  },
  UNDER_REVIEW: {
    label: "Under review",
    className: "bg-blue-50 text-blue-700",
    icon: <Eye size={14} />,
  },
  APPROVED: {
    label: "Approved",
    className: "bg-emerald-50 text-emerald-700",
    icon: <CheckCircle2 size={14} />,
  },
  REJECTED: {
    label: "Rejected",
    className: "bg-red-50 text-red-700",
    icon: <XCircle size={14} />,
  },
  REVOKED: {
    label: "Revoked",
    className: "bg-slate-100 text-slate-600",
    icon: <LockKeyhole size={14} />,
  },
  EXPIRED: {
    label: "Expired",
    className: "bg-slate-100 text-slate-600",
    icon: <AlertCircle size={14} />,
  },
};

const categoryLabels: Record<DataAccessCategory, string> = {
  CLIENT_DATA: "Client data",
  PROJECT_DATA: "Project data",
  FINANCIAL_DATA: "Financial data",
  VENDOR_DATA: "Vendor data",
  DOCUMENTS: "Documents",
  AUDIT_RECORDS: "Audit records",
  OTHER: "Other",
};

const filters = [
  "ALL",
  "PENDING",
  "UNDER_REVIEW",
  "APPROVED",
  "REJECTED",
  "REVOKED",
  "EXPIRED",
] as const;

type RequestFilter = (typeof filters)[number];

function formatDate(value?: string) {
  if (!value) return "—";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function StatusBadge({
  status,
}: {
  status: DataAccessRequestStatus;
}) {
  const config = statusConfig[status];

  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium ${config.className}`}
    >
      {config.icon}
      {config.label}
    </span>
  );
}

function MetricCard({
  label,
  value,
  description,
  icon,
}: {
  label: string;
  value: number;
  description: string;
  icon: ReactNode;
}) {
  return (
    <div className="rounded-xl border border-[#e9e5dd] bg-white p-5">
      <div className="flex items-center justify-between">
        <p className="text-sm text-[#77736c]">{label}</p>
        <span className="text-[#9b8358]">{icon}</span>
      </div>

      <p className="mt-3 text-3xl font-semibold text-[#292821]">
        {value.toLocaleString("en-IN")}
      </p>

      <p className="mt-1 text-xs text-[#918c83]">{description}</p>
    </div>
  );
}

export default function AdminDataAccessRequestCenter({
  requests,
  loading = false,
  error,
  currentUserId,
  onRefresh,
  onViewDetails,
  onReviewRequest,
}: AdminDataAccessRequestCenterProps) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] =
    useState<RequestFilter>("ALL");
  const [categoryFilter, setCategoryFilter] =
    useState<DataAccessCategory | "ALL">("ALL");

  const metrics = useMemo(
    () => ({
      total: requests.length,
      pending: requests.filter(
        (request) => request.status === "PENDING"
      ).length,
      underReview: requests.filter(
        (request) => request.status === "UNDER_REVIEW"
      ).length,
      approved: requests.filter(
        (request) => request.status === "APPROVED"
      ).length,
      rejected: requests.filter(
        (request) => request.status === "REJECTED"
      ).length,
    }),
    [requests]
  );

  const filteredRequests = useMemo(() => {
    const query = search.trim().toLowerCase();

    return requests
      .filter((request) => {
        const matchesStatus =
          statusFilter === "ALL" ||
          request.status === statusFilter;

        const matchesCategory =
          categoryFilter === "ALL" ||
          request.category === categoryFilter;

        const searchable = [
          request.id,
          request.requesterName,
          request.requesterId,
          request.requesterRole,
          request.resourceName,
          request.justification,
          request.requestedPermissions.join(" "),
        ]
          .join(" ")
          .toLowerCase();

        return (
          matchesStatus &&
          matchesCategory &&
          (!query || searchable.includes(query))
        );
      })
      .sort(
        (a, b) =>
          new Date(b.requestedAt).getTime() -
          new Date(a.requestedAt).getTime()
      );
  }, [requests, search, statusFilter, categoryFilter]);

  function canReview(request: DataAccessRequest) {
    const isPending =
      request.status === "PENDING" ||
      request.status === "UNDER_REVIEW";

    const isRequester =
      Boolean(currentUserId) &&
      request.requesterId === currentUserId;

    const isPreviousReviewer =
      Boolean(currentUserId) &&
      request.reviewedBy === currentUserId;

    return isPending && !isRequester && !isPreviousReviewer;
  }

  return (
    <main className="space-y-7">
      <header className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center">
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-[#9b8358]">
            <ShieldCheck size={15} />
            Data governance
          </div>

          <h1 className="text-2xl font-semibold tracking-tight text-[#25241f]">
            Data Access Requests
          </h1>

          <p className="mt-1 max-w-2xl text-sm text-[#77736c]">
            Review requests for restricted client, project, financial,
            vendor, document, and audit information.
          </p>
        </div>

        <button
          type="button"
          onClick={onRefresh}
          disabled={!onRefresh || loading}
          className="rounded-lg border border-[#ded9cf] bg-white px-4 py-2.5 text-sm font-medium text-[#34322c] hover:bg-[#f8f6f1] disabled:opacity-50"
        >
          Refresh
        </button>
      </header>

      {error && (
        <div
          role="alert"
          className="flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
        >
          <AlertCircle size={18} className="mt-0.5 shrink-0" />
          {error}
        </div>
      )}

      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">
        <MetricCard
          label="Total requests"
          value={metrics.total}
          description="All supplied request records"
          icon={<FileText size={19} />}
        />
        <MetricCard
          label="Pending"
          value={metrics.pending}
          description="Awaiting review"
          icon={<Clock3 size={19} />}
        />
        <MetricCard
          label="Under review"
          value={metrics.underReview}
          description="Review in progress"
          icon={<Eye size={19} />}
        />
        <MetricCard
          label="Approved"
          value={metrics.approved}
          description="Marked approved"
          icon={<CheckCircle2 size={19} />}
        />
        <MetricCard
          label="Rejected"
          value={metrics.rejected}
          description="Marked rejected"
          icon={<XCircle size={19} />}
        />
      </section>

      <section className="overflow-hidden rounded-xl border border-[#e9e5dd] bg-white">
        <div className="space-y-4 border-b border-[#eeeae3] p-5">
          <div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-center">
            <div>
              <h2 className="font-semibold text-[#292821]">
                Request register
              </h2>
              <p className="mt-1 text-xs text-[#918c83]">
                {filteredRequests.length} matching requests
              </p>
            </div>

            <div className="relative w-full lg:max-w-sm">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#918c83]"
              />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search requester or resource..."
                className="w-full rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[#a58c5d]"
              />
            </div>
          </div>

          <div className="grid gap-3 md:grid-cols-2">
            <select
              value={statusFilter}
              onChange={(event) =>
                setStatusFilter(event.target.value as RequestFilter)
              }
              className="rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] px-3 py-2.5 text-sm outline-none focus:border-[#a58c5d]"
            >
              {filters.map((filter) => (
                <option key={filter} value={filter}>
                  {filter === "ALL"
                    ? "All statuses"
                    : statusConfig[filter].label}
                </option>
              ))}
            </select>

            <select
              value={categoryFilter}
              onChange={(event) =>
                setCategoryFilter(
                  event.target.value as DataAccessCategory | "ALL"
                )
              }
              className="rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] px-3 py-2.5 text-sm outline-none focus:border-[#a58c5d]"
            >
              <option value="ALL">All data categories</option>
              {Object.entries(categoryLabels).map(([key, label]) => (
                <option key={key} value={key}>
                  {label}
                </option>
              ))}
            </select>
          </div>
        </div>

        {loading ? (
          <div className="p-12 text-center text-sm text-[#77736c]">
            Loading access requests...
          </div>
        ) : filteredRequests.length === 0 ? (
          <div className="p-12 text-center">
            <LockKeyhole size={30} className="mx-auto text-[#b3aa9b]" />
            <p className="mt-3 font-medium text-[#34322c]">
              No access requests found
            </p>
            <p className="mt-1 text-sm text-[#918c83]">
              Try changing the search or filters.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[1250px] text-left">
              <thead className="bg-[#faf9f6] text-xs uppercase tracking-wider text-[#918c83]">
                <tr>
                  <th className="px-5 py-3 font-medium">Requester</th>
                  <th className="px-5 py-3 font-medium">Resource</th>
                  <th className="px-5 py-3 font-medium">Category</th>
                  <th className="px-5 py-3 font-medium">Permissions</th>
                  <th className="px-5 py-3 font-medium">Requested</th>
                  <th className="px-5 py-3 font-medium">Status</th>
                  <th className="px-5 py-3 text-right font-medium">
                    Actions
                  </th>
                </tr>
              </thead>

              <tbody className="divide-y divide-[#f0ede7]">
                {filteredRequests.map((request) => (
                  <tr
                    key={request.id}
                    className="hover:bg-[#fcfbf9]"
                  >
                    <td className="px-5 py-4">
                      <p className="text-sm font-medium text-[#34322c]">
                        {request.requesterName}
                      </p>
                      <p className="mt-1 text-xs text-[#918c83]">
                        {request.requesterRole}
                      </p>
                      <p className="mt-1 font-mono text-xs text-[#aaa397]">
                        {request.requesterId}
                      </p>
                    </td>

                    <td className="px-5 py-4">
                      <p className="text-sm text-[#34322c]">
                        {request.resourceName}
                      </p>
                      <p className="mt-1 font-mono text-xs text-[#aaa397]">
                        {request.id}
                      </p>
                    </td>

                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {categoryLabels[request.category]}
                    </td>

                    <td className="px-5 py-4">
                      <div className="flex max-w-[230px] flex-wrap gap-1.5">
                        {request.requestedPermissions
                          .slice(0, 3)
                          .map((permission) => (
                            <span
                              key={permission}
                              className="rounded-md bg-[#f3f1ec] px-2 py-1 text-xs text-[#68645c]"
                            >
                              {permission}
                            </span>
                          ))}
                        {request.requestedPermissions.length > 3 && (
                          <span className="rounded-md bg-[#f3f1ec] px-2 py-1 text-xs text-[#68645c]">
                            +{request.requestedPermissions.length - 3}
                          </span>
                        )}
                      </div>
                    </td>

                    <td className="px-5 py-4 text-xs text-[#77736c]">
                      {formatDate(request.requestedAt)}
                    </td>

                    <td className="px-5 py-4">
                      <StatusBadge status={request.status} />
                    </td>

                    <td className="px-5 py-4">
                      <div className="flex justify-end gap-2">
                        <button
                          type="button"
                          onClick={() => onViewDetails?.(request)}
                          disabled={!onViewDetails}
                          title="View request details"
                          className="rounded-lg border border-[#e8e3da] p-2 text-[#77736c] hover:bg-[#f7f5f0] disabled:opacity-40"
                        >
                          <Eye size={15} />
                        </button>

                        {canReview(request) && (
                          <button
                            type="button"
                            onClick={() =>
                              onReviewRequest?.(request, "APPROVE")
                            }
                            disabled={!onReviewRequest}
                            title="Open approval review"
                            className="rounded-lg border border-[#e8e3da] p-2 text-[#9b8358] hover:bg-[#f7f5f0] disabled:opacity-40"
                          >
                            <ShieldCheck size={15} />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>

      <section className="rounded-xl border border-[#e9e5dd] bg-[#faf9f6] p-5">
        <div className="flex items-start gap-3">
          <ShieldCheck
            size={19}
            className="mt-0.5 shrink-0 text-[#9b8358]"
          />

          <div>
            <h3 className="text-sm font-semibold text-[#34322c]">
              Access approval safeguards
            </h3>

            <ul className="mt-2 space-y-1.5 text-xs leading-5 text-[#77736c]">
              <li>
                • Require a clear business justification and specific
                resource scope for every request.
              </li>
              <li>
                • Enforce least-privilege permissions and time-bound
                access grants.
              </li>
              <li>
                • The requester must not approve their own request.
              </li>
              <li>
                • Enforce maker-checker separation and approval authority
                on the backend.
              </li>
              <li>
                • Approval must not automatically grant access until
                the backend completes the authorization workflow.
              </li>
              <li>
                • Record reviewer identity, decision reason, timestamps,
                and access revocation history.
              </li>
            </ul>
          </div>
        </div>
      </section>
    </main>
  );
}

"use client";

import { useMemo, useState } from "react";
import type { ReactNode } from "react";
import {
  AlertCircle,
  Archive,
  CheckCircle2,
  Clock3,
  Download,
  Eye,
  FileSpreadsheet,
  FileText,
  Filter,
  LockKeyhole,
  Search,
  ShieldCheck,
  XCircle,
} from "lucide-react";

export type DataExportStatus =
  | "PENDING"
  | "UNDER_REVIEW"
  | "APPROVED"
  | "PROCESSING"
  | "READY"
  | "REJECTED"
  | "EXPIRED"
  | "CANCELLED";

export type DataExportFormat = "CSV" | "XLSX" | "PDF" | "JSON";

export type DataExportCategory =
  | "PROJECTS"
  | "CLIENTS"
  | "VENDORS"
  | "FINANCIAL"
  | "INVOICES"
  | "AUDIT_LOGS"
  | "DOCUMENT_METADATA"
  | "OTHER";

export interface DataExportRequest {
  id: string;
  requesterId: string;
  requesterName: string;
  requesterRole: string;
  category: DataExportCategory;
  datasetDescription: string;
  format: DataExportFormat;
  recordCount?: number;
  containsSensitiveData: boolean;
  maskingRequired: boolean;
  status: DataExportStatus;
  requestedAt: string;
  reviewedAt?: string;
  reviewedBy?: string;
  expiresAt?: string;
  fileSizeBytes?: number;
  downloadAvailable: boolean;
}

interface AdminDataExportGovernanceCenterProps {
  requests: DataExportRequest[];
  loading?: boolean;
  error?: string | null;
  currentUserId?: string;
  onRefresh?: () => void;
  onViewDetails?: (request: DataExportRequest) => void;
  onReviewRequest?: (
    request: DataExportRequest,
    decision: "APPROVE" | "REJECT"
  ) => void;
  onDownload?: (request: DataExportRequest) => void;
}

const statusConfig: Record<
  DataExportStatus,
  { label: string; className: string; icon: ReactNode }
> = {
  PENDING: {
    label: "Pending",
    className: "bg-amber-50 text-amber-700",
    icon: <Clock3 size={14} />,
  },
  UNDER_REVIEW: {
    label: "Under review",
    className: "bg-blue-50 text-blue-700",
    icon: <Eye size={14} />,
  },
  APPROVED: {
    label: "Approved",
    className: "bg-emerald-50 text-emerald-700",
    icon: <CheckCircle2 size={14} />,
  },
  PROCESSING: {
    label: "Processing",
    className: "bg-blue-50 text-blue-700",
    icon: <Clock3 size={14} />,
  },
  READY: {
    label: "Ready",
    className: "bg-emerald-50 text-emerald-700",
    icon: <Download size={14} />,
  },
  REJECTED: {
    label: "Rejected",
    className: "bg-red-50 text-red-700",
    icon: <XCircle size={14} />,
  },
  EXPIRED: {
    label: "Expired",
    className: "bg-slate-100 text-slate-600",
    icon: <Archive size={14} />,
  },
  CANCELLED: {
    label: "Cancelled",
    className: "bg-slate-100 text-slate-600",
    icon: <XCircle size={14} />,
  },
};

const categoryLabels: Record<DataExportCategory, string> = {
  PROJECTS: "Projects",
  CLIENTS: "Clients",
  VENDORS: "Vendors",
  FINANCIAL: "Financial records",
  INVOICES: "Invoices",
  AUDIT_LOGS: "Audit logs",
  DOCUMENT_METADATA: "Document metadata",
  OTHER: "Other",
};

const filters = [
  "ALL",
  "PENDING",
  "UNDER_REVIEW",
  "APPROVED",
  "PROCESSING",
  "READY",
  "REJECTED",
  "EXPIRED",
  "CANCELLED",
] as const;

type ExportFilter = (typeof filters)[number];

function formatDate(value?: string) {
  if (!value) return "—";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function formatFileSize(bytes?: number) {
  if (bytes === undefined || !Number.isFinite(bytes) || bytes < 0) {
    return "—";
  }

  if (bytes < 1024) return `${bytes} B`;

  const units = ["KB", "MB", "GB", "TB"];
  let size = bytes / 1024;
  let unitIndex = 0;

  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024;
    unitIndex += 1;
  }

  return `${size.toFixed(1)} ${units[unitIndex]}`;
}

function StatusBadge({ status }: { status: DataExportStatus }) {
  const config = statusConfig[status];

  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium ${config.className}`}
    >
      {config.icon}
      {config.label}
    </span>
  );
}

function MetricCard({
  label,
  value,
  description,
  icon,
}: {
  label: string;
  value: number;
  description: string;
  icon: ReactNode;
}) {
  return (
    <div className="rounded-xl border border-[#e9e5dd] bg-white p-5">
      <div className="flex items-center justify-between">
        <p className="text-sm text-[#77736c]">{label}</p>
        <span className="text-[#9b8358]">{icon}</span>
      </div>

      <p className="mt-3 text-3xl font-semibold text-[#292821]">
        {value.toLocaleString("en-IN")}
      </p>

      <p className="mt-1 text-xs text-[#918c83]">{description}</p>
    </div>
  );
}

export default function AdminDataExportGovernanceCenter({
  requests,
  loading = false,
  error,
  currentUserId,
  onRefresh,
  onViewDetails,
  onReviewRequest,
  onDownload,
}: AdminDataExportGovernanceCenterProps) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] =
    useState<ExportFilter>("ALL");
  const [categoryFilter, setCategoryFilter] =
    useState<DataExportCategory | "ALL">("ALL");

  const metrics = useMemo(
    () => ({
      total: requests.length,
      pending: requests.filter(
        (request) =>
          request.status === "PENDING" ||
          request.status === "UNDER_REVIEW"
      ).length,
      processing: requests.filter(
        (request) => request.status === "PROCESSING"
      ).length,
      ready: requests.filter(
        (request) => request.status === "READY"
      ).length,
      sensitive: requests.filter(
        (request) => request.containsSensitiveData
      ).length,
    }),
    [requests]
  );

  const filteredRequests = useMemo(() => {
    const query = search.trim().toLowerCase();

    return requests
      .filter((request) => {
        const matchesStatus =
          statusFilter === "ALL" ||
          request.status === statusFilter;

        const matchesCategory =
          categoryFilter === "ALL" ||
          request.category === categoryFilter;

        const searchable = [
          request.id,
          request.requesterId,
          request.requesterName,
          request.requesterRole,
          request.datasetDescription,
          request.format,
          request.category,
        ]
          .join(" ")
          .toLowerCase();

        return (
          matchesStatus &&
          matchesCategory &&
          (!query || searchable.includes(query))
        );
      })
      .sort(
        (a, b) =>
          new Date(b.requestedAt).getTime() -
          new Date(a.requestedAt).getTime()
      );
  }, [requests, search, statusFilter, categoryFilter]);

  function canReview(request: DataExportRequest) {
    const awaitingReview =
      request.status === "PENDING" ||
      request.status === "UNDER_REVIEW";

    const isRequester =
      Boolean(currentUserId) &&
      request.requesterId === currentUserId;

    const isPreviousReviewer =
      Boolean(currentUserId) &&
      request.reviewedBy === currentUserId;

    return awaitingReview && !isRequester && !isPreviousReviewer;
  }

  function canDownload(request: DataExportRequest) {
    return (
      request.status === "READY" &&
      request.downloadAvailable
    );
  }

  return (
    <main className="space-y-7">
      <header className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center">
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-[#9b8358]">
            <Archive size={15} />
            Data governance
          </div>

          <h1 className="text-2xl font-semibold tracking-tight text-[#25241f]">
            Data Export Governance
          </h1>

          <p className="mt-1 max-w-2xl text-sm text-[#77736c]">
            Review export requests, data sensitivity, approval status,
            and controlled download availability.
          </p>
        </div>

        <button
          type="button"
          onClick={onRefresh}
          disabled={!onRefresh || loading}
          className="rounded-lg border border-[#ded9cf] bg-white px-4 py-2.5 text-sm font-medium text-[#34322c] hover:bg-[#f8f6f1] disabled:opacity-50"
        >
          Refresh
        </button>
      </header>

      {error && (
        <div
          role="alert"
          className="flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
        >
          <AlertCircle size={18} className="mt-0.5 shrink-0" />
          {error}
        </div>
      )}

      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">
        <MetricCard
          label="Total requests"
          value={metrics.total}
          description="All supplied export records"
          icon={<FileText size={19} />}
        />
        <MetricCard
          label="Awaiting review"
          value={metrics.pending}
          description="Pending or under review"
          icon={<Clock3 size={19} />}
        />
        <MetricCard
          label="Processing"
          value={metrics.processing}
          description="Export jobs in progress"
          icon={<FileSpreadsheet size={19} />}
        />
        <MetricCard
          label="Ready"
          value={metrics.ready}
          description="Marked ready for download"
          icon={<Download size={19} />}
        />
        <MetricCard
          label="Sensitive datasets"
          value={metrics.sensitive}
          description="Requests flagged as sensitive"
          icon={<LockKeyhole size={19} />}
        />
      </section>

      <section className="overflow-hidden rounded-xl border border-[#e9e5dd] bg-white">
        <div className="space-y-4 border-b border-[#eeeae3] p-5">
          <div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-center">
            <div>
              <h2 className="font-semibold text-[#292821]">
                Export request register
              </h2>
              <p className="mt-1 text-xs text-[#918c83]">
                {filteredRequests.length} matching requests
              </p>
            </div>

            <div className="relative w-full lg:max-w-sm">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#918c83]"
              />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search requester or dataset..."
                className="w-full rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[#a58c5d]"
              />
            </div>
          </div>

          <div className="grid gap-3 md:grid-cols-2">
            <select
              value={statusFilter}
              onChange={(event) =>
                setStatusFilter(event.target.value as ExportFilter)
              }
              className="rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] px-3 py-2.5 text-sm outline-none focus:border-[#a58c5d]"
            >
              {filters.map((filter) => (
                <option key={filter} value={filter}>
                  {filter === "ALL"
                    ? "All statuses"
                    : statusConfig[filter].label}
                </option>
              ))}
            </select>

            <select
              value={categoryFilter}
              onChange={(event) =>
                setCategoryFilter(
                  event.target.value as DataExportCategory | "ALL"
                )
              }
              className="rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] px-3 py-2.5 text-sm outline-none focus:border-[#a58c5d]"
            >
              <option value="ALL">All datasets</option>
              {Object.entries(categoryLabels).map(([key, label]) => (
                <option key={key} value={key}>
                  {label}
                </option>
              ))}
            </select>
          </div>
        </div>

        {loading ? (
          <div className="p-12 text-center text-sm text-[#77736c]">
            Loading export requests...
          </div>
        ) : filteredRequests.length === 0 ? (
          <div className="p-12 text-center">
            <Archive size={30} className="mx-auto text-[#b3aa9b]" />
            <p className="mt-3 font-medium text-[#34322c]">
              No export requests found
            </p>
            <p className="mt-1 text-sm text-[#918c83]">
              Try changing the search or filters.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[1350px] text-left">
              <thead className="bg-[#faf9f6] text-xs uppercase tracking-wider text-[#918c83]">
                <tr>
                  <th className="px-5 py-3 font-medium">Requester</th>
                  <th className="px-5 py-3 font-medium">Dataset</th>
                  <th className="px-5 py-3 font-medium">Format</th>
                  <th className="px-5 py-3 font-medium">Records</th>
                  <th className="px-5 py-3 font-medium">Data sensitivity</th>
                  <th className="px-5 py-3 font-medium">Requested</th>
                  <th className="px-5 py-3 font-medium">Status</th>
                  <th className="px-5 py-3 text-right font-medium">
                    Actions
                  </th>
                </tr>
              </thead>

              <tbody className="divide-y divide-[#f0ede7]">
                {filteredRequests.map((request) => (
                  <tr
                    key={request.id}
                    className="hover:bg-[#fcfbf9]"
                  >
                    <td className="px-5 py-4">
                      <p className="text-sm font-medium text-[#34322c]">
                        {request.requesterName}
                      </p>
                      <p className="mt-1 text-xs text-[#918c83]">
                        {request.requesterRole}
                      </p>
                      <p className="mt-1 font-mono text-xs text-[#aaa397]">
                        {request.id}
                      </p>
                    </td>

                    <td className="max-w-[260px] px-5 py-4">
                      <p className="text-sm text-[#34322c]">
                        {categoryLabels[request.category]}
                      </p>
                      <p className="mt-1 line-clamp-2 text-xs text-[#918c83]">
                        {request.datasetDescription}
                      </p>
                    </td>

                    <td className="px-5 py-4">
                      <span className="rounded-md bg-[#f3f1ec] px-2 py-1 text-xs font-medium text-[#68645c]">
                        {request.format}
                      </span>
                    </td>

                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {request.recordCount === undefined
                        ? "—"
                        : request.recordCount.toLocaleString("en-IN")}
                    </td>

                    <td className="px-5 py-4">
                      {request.containsSensitiveData ? (
                        <div className="space-y-1">
                          <span className="inline-flex items-center gap-1 text-xs font-medium text-amber-700">
                            <LockKeyhole size={13} />
                            Sensitive
                          </span>
                          <p className="text-xs text-[#918c83]">
                            {request.maskingRequired
                              ? "Masking required"
                              : "Masking not flagged"}
                          </p>
                        </div>
                      ) : (
                        <span className="text-xs text-[#77736c]">
                          Not flagged
                        </span>
                      )}
                    </td>

                    <td className="px-5 py-4 text-xs text-[#77736c]">
                      {formatDate(request.requestedAt)}
                    </td>

                    <td className="px-5 py-4">
                      <StatusBadge status={request.status} />
                    </td>

                    <td className="px-5 py-4">
                      <div className="flex justify-end gap-2">
                        <button
                          type="button"
                          onClick={() => onViewDetails?.(request)}
                          disabled={!onViewDetails}
                          title="View export details"
                          className="rounded-lg border border-[#e8e3da] p-2 text-[#77736c] hover:bg-[#f7f5f0] disabled:opacity-40"
                        >
                          <Eye size={15} />
                        </button>

                        {canReview(request) && (
                          <button
                            type="button"
                            onClick={() =>
                              onReviewRequest?.(request, "APPROVE")
                            }
                            disabled={!onReviewRequest}
                            title="Open export approval review"
                            className="rounded-lg border border-[#e8e3da] p-2 text-[#9b8358] hover:bg-[#f7f5f0] disabled:opacity-40"
                          >
                            <ShieldCheck size={15} />
                          </button>
                        )}

                        {canDownload(request) && (
                          <button
                            type="button"
                            onClick={() => onDownload?.(request)}
                            disabled={!onDownload}
                            title="Request secure download"
                            className="rounded-lg border border-[#e8e3da] p-2 text-[#77736c] hover:bg-[#f7f5f0] disabled:opacity-40"
                          >
                            <Download size={15} />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>

      <section className="rounded-xl border border-[#e9e5dd] bg-[#faf9f6] p-5">
        <div className="flex items-start gap-3">
          <ShieldCheck
            size={19}
            className="mt-0.5 shrink-0 text-[#9b8358]"
          />

          <div>
            <h3 className="text-sm font-semibold text-[#34322c]">
              Export security requirements
            </h3>

            <ul className="mt-2 space-y-1.5 text-xs leading-5 text-[#77736c]">
              <li>
                • Enforce role-based export permissions and dataset-level
                access checks on the backend.
              </li>
              <li>
                • Require explicit approval for sensitive financial,
                client, and audit datasets.
              </li>
              <li>
                • Apply and verify masking before generating sensitive
                exports.
              </li>
              <li>
                • Use short-lived, authorized download links rather than
                permanent public file URLs.
              </li>
              <li>
                • Record export scope, requester, reviewer, generation
                time, and download activity.
              </li>
              <li>
                • Enforce expiry, retention, and secure deletion policies
                for generated export files.
              </li>
              <li>
                • Do not treat the frontend&apos;s downloadAvailable flag as
                proof of authorization.
              </li>
            </ul>
          </div>
        </div>
      </section>
    </main>
  );
}

"use client";

import { useMemo, useState } from "react";
import type { ReactNode } from "react";
import {
  AlertCircle,
  Archive,
  CalendarClock,
  CheckCircle2,
  Clock3,
  Eye,
  Filter,
  Lock,
  Search,
  ShieldCheck,
  Trash2,
  XCircle,
} from "lucide-react";

export type RetentionRecordStatus =
  | "ACTIVE"
  | "REVIEW_DUE"
  | "DISPOSAL_SCHEDULED"
  | "LEGAL_HOLD"
  | "DISPOSAL_PENDING"
  | "DISPOSED"
  | "EXCEPTION";

export type RetentionDataCategory =
  | "PROJECT_DOCUMENTS"
  | "FINANCIAL_RECORDS"
  | "CLIENT_RECORDS"
  | "VENDOR_RECORDS"
  | "AUDIT_LOGS"
  | "ENQUIRIES"
  | "SYSTEM_EXPORTS"
  | "OTHER";

export interface DataRetentionRecord {
  id: string;
  category: RetentionDataCategory;
  description: string;
  retentionPolicyName: string;
  retentionPeriodLabel: string;
  createdAt: string;
  retentionEndsAt?: string;
  status: RetentionRecordStatus;
  legalHoldReference?: string;
  disposalJobId?: string;
  lastReviewedAt?: string;
  ownerName: string;
}

export interface DisposalHistoryRecord {
  id: string;
  category: RetentionDataCategory;
  completedAt: string;
  recordCount: number;
  method: string;
  approvedBy: string;
  executionReference: string;
  outcome: "SUCCESS" | "PARTIAL" | "FAILED";
}

interface AdminDataRetentionCenterProps {
  records: DataRetentionRecord[];
  disposalHistory: DisposalHistoryRecord[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onViewRecord?: (record: DataRetentionRecord) => void;
  onRequestReview?: (recordId: string) => void;
  onViewDisposalDetails?: (record: DisposalHistoryRecord) => void;
}

const statusConfig: Record<
  RetentionRecordStatus,
  { label: string; className: string; icon: ReactNode }
> = {
  ACTIVE: {
    label: "Active retention",
    className: "bg-emerald-50 text-emerald-700",
    icon: <CheckCircle2 size={14} />,
  },
  REVIEW_DUE: {
    label: "Review due",
    className: "bg-amber-50 text-amber-700",
    icon: <CalendarClock size={14} />,
  },
  DISPOSAL_SCHEDULED: {
    label: "Disposal scheduled",
    className: "bg-blue-50 text-blue-700",
    icon: <Clock3 size={14} />,
  },
  LEGAL_HOLD: {
    label: "Legal hold",
    className: "bg-purple-50 text-purple-700",
    icon: <Lock size={14} />,
  },
  DISPOSAL_PENDING: {
    label: "Disposal pending",
