  "REVIEW_DUE",
  "DISPOSAL_SCHEDULED",
  "LEGAL_HOLD",
  "DISPOSAL_PENDING",
  "DISPOSED",
  "EXCEPTION",
] as const;

type StatusFilter = (typeof statusFilters)[number];

function formatDate(value?: string) {
  if (!value) return "—";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
