export default function AdminDataRetentionCenter({
  records,
  disposalHistory,
  loading = false,
  error,
  onRefresh,
  onViewRecord,
  onRequestReview,
  onViewDisposalDetails,
}: AdminDataRetentionCenterProps) {
  const [search, setSearch] = useState("");
  const [activeFilter, setActiveFilter] =
    useState<StatusFilter>("ALL");

  const metrics = useMemo(
    () => ({
      total: records.length,
      reviewDue: records.filter(
        (record) => record.status === "REVIEW_DUE"
      ).length,
      legalHolds: records.filter(
        (record) => record.status === "LEGAL_HOLD"
      ).length,
      pendingDisposal: records.filter(
        (record) =>
          record.status === "DISPOSAL_PENDING" ||
          record.status === "DISPOSAL_SCHEDULED"
      ).length,
      exceptions: records.filter(
        (record) => record.status === "EXCEPTION"
      ).length,
    }),
    [records]
  );

  const filteredRecords = useMemo(() => {
    const query = search.trim().toLowerCase();

    return records.filter((record) => {
      const matchesStatus =
        activeFilter === "ALL" ||
        record.status === activeFilter;

      const searchable = [
        record.id,
        record.description,
        record.category,
        record.retentionPolicyName,
        record.ownerName,
        record.legalHoldReference ?? "",
      ]
        .join(" ")
        .toLowerCase();

      return (
        matchesStatus &&
        (!query || searchable.includes(query))
      );
    });
  }, [records, search, activeFilter]);

  return (
    <main className="space-y-7">
      <header className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center">
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-[#9b8358]">
            <Archive size={15} />
            Governance operations
          </div>

          <h1 className="text-2xl font-semibold tracking-tight text-[#25241f]">
            Data Retention & Disposal
          </h1>

          <p className="mt-1 max-w-2xl text-sm text-[#77736c]">
            Monitor retention obligations, review deadlines, legal holds,
            and authorized disposal records.
          </p>
        </div>

        <button
          type="button"
          onClick={onRefresh}
          disabled={!onRefresh || loading}
          className="rounded-lg border border-[#ded9cf] bg-white px-4 py-2.5 text-sm font-medium text-[#34322c] hover:bg-[#f8f6f1] disabled:cursor-not-allowed disabled:opacity-50"
        >
          Refresh records
        </button>
      </header>

      {error && (
        <div
          role="alert"
          className="flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
        >
          <AlertCircle size={18} className="mt-0.5 shrink-0" />
          {error}
        </div>
      )}

      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">
        <MetricCard
          label="Tracked records"
          value={metrics.total}
          description="Records in supplied dataset"
          icon={<Archive size={19} />}
        />
        <MetricCard
          label="Review due"
          value={metrics.reviewDue}
          description="Require retention review"
          icon={<CalendarClock size={19} />}
        />
        <MetricCard
          label="Legal holds"
          value={metrics.legalHolds}
          description="Protected from ordinary disposal"
          icon={<Lock size={19} />}
        />
        <MetricCard
          label="Pending disposal"
          value={metrics.pendingDisposal}
          description="Scheduled or awaiting execution"
          icon={<Trash2 size={19} />}
        />
        <MetricCard
          label="Exceptions"
          value={metrics.exceptions}
          description="Require investigation"
          icon={<AlertCircle size={19} />}
        />
      </section>

      <section className="overflow-hidden rounded-xl border border-[#e9e5dd] bg-white">
        <div className="space-y-4 border-b border-[#eeeae3] p-5">
          <div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-center">
            <div>
              <h2 className="font-semibold text-[#292821]">
                Retention register
              </h2>
              <p className="mt-1 text-xs text-[#918c83]">
                {filteredRecords.length} matching records
              </p>
            </div>

            <div className="relative w-full lg:max-w-sm">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#918c83]"
              />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search category, policy, owner..."
                className="w-full rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[#a58c5d]"
              />
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <Filter size={15} className="mr-1 text-[#918c83]" />

            {statusFilters.map((filter) => (
              <button
                key={filter}
                type="button"
                onClick={() => setActiveFilter(filter)}
                className={`rounded-full px-3 py-1.5 text-xs font-medium transition ${
                  activeFilter === filter
                    ? "bg-[#292821] text-white"
                    : "border border-[#e8e3da] text-[#77736c] hover:bg-[#f7f5f0]"
                }`}
              >
                {filter === "ALL"
                  ? "All records"
                  : statusConfig[filter].label}
              </button>
            ))}
          </div>
        </div>

        {loading ? (
          <div className="p-12 text-center text-sm text-[#77736c]">
            Loading retention records...
          </div>
        ) : filteredRecords.length === 0 ? (
          <div className="p-12 text-center">
            <Archive
              size={30}
              className="mx-auto text-[#b3aa9b]"
            />
            <p className="mt-3 font-medium text-[#34322c]">
              No retention records found
            </p>
            <p className="mt-1 text-sm text-[#918c83]">
              Try changing the search or status filter.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[1200px] text-left">
              <thead className="bg-[#faf9f6] text-xs uppercase tracking-wider text-[#918c83]">
                <tr>
                  <th className="px-5 py-3 font-medium">Data category</th>
                  <th className="px-5 py-3 font-medium">Policy</th>
                  <th className="px-5 py-3 font-medium">Retention period</th>
                  <th className="px-5 py-3 font-medium">Retention end</th>
                  <th className="px-5 py-3 font-medium">Owner</th>
                  <th className="px-5 py-3 font-medium">Status</th>
                  <th className="px-5 py-3 text-right font-medium">
                    Actions
                  </th>
                </tr>
              </thead>

              <tbody className="divide-y divide-[#f0ede7]">
                {filteredRecords.map((record) => (
                  <tr
                    key={record.id}
                    className="hover:bg-[#fcfbf9]"
                  >
                    <td className="px-5 py-4">
                      <p className="text-sm font-medium text-[#34322c]">
                        {record.category.replaceAll("_", " ")}
                      </p>
                      <p className="mt-1 max-w-[230px] text-xs text-[#918c83]">
                        {record.description}
                      </p>
                      <p className="mt-1 font-mono text-xs text-[#aaa397]">
                        {record.id}
                      </p>
                    </td>

                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {record.retentionPolicyName}
                    </td>

                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {record.retentionPeriodLabel}
                    </td>

                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {formatDate(record.retentionEndsAt)}
                    </td>

                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {record.ownerName}
                    </td>

                    <td className="px-5 py-4">
                      <StatusBadge status={record.status} />
                      {record.status === "LEGAL_HOLD" &&
                        record.legalHoldReference && (
                          <p className="mt-1 text-xs text-purple-700">
                            Ref: {record.legalHoldReference}
                          </p>
                        )}
                    </td>

                    <td className="px-5 py-4">
                      <div className="flex justify-end gap-2">
                        <button
                          type="button"
                          onClick={() => onViewRecord?.(record)}
                          disabled={!onViewRecord}
                          title="View retention details"
                          className="rounded-lg border border-[#e8e3da] p-2 text-[#77736c] hover:bg-[#f7f5f0] disabled:opacity-40"
                        >
                          <Eye size={15} />
                        </button>

                        {(record.status === "REVIEW_DUE" ||
                          record.status === "EXCEPTION") && (
                          <button
                            type="button"
                            onClick={() => onRequestReview?.(record.id)}
                            disabled={!onRequestReview}
                            title="Request retention review"
                            className="rounded-lg border border-[#e8e3da] p-2 text-[#9b8358] hover:bg-[#f7f5f0] disabled:opacity-40"
                          >
                            <ShieldCheck size={15} />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>

      <section className="overflow-hidden rounded-xl border border-[#e9e5dd] bg-white">
        <div className="border-b border-[#eeeae3] p-5">
          <h2 className="font-semibold text-[#292821]">
            Disposal history
          </h2>
          <p className="mt-1 text-xs text-[#918c83]">
            Historical execution records supplied by the backend
          </p>
        </div>

        {disposalHistory.length === 0 ? (
          <div className="p-8 text-center text-sm text-[#918c83]">
            No disposal history records available.
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[850px] text-left">
              <thead className="bg-[#faf9f6] text-xs uppercase tracking-wider text-[#918c83]">
                <tr>
                  <th className="px-5 py-3 font-medium">Category</th>
                  <th className="px-5 py-3 font-medium">Records</th>
                  <th className="px-5 py-3 font-medium">Method</th>
                  <th className="px-5 py-3 font-medium">Approved by</th>
                  <th className="px-5 py-3 font-medium">Outcome</th>
                  <th className="px-5 py-3 font-medium">Completed</th>
                  <th className="px-5 py-3 text-right font-medium">
                    Details
                  </th>
                </tr>
              </thead>

              <tbody className="divide-y divide-[#f0ede7]">
                {disposalHistory.map((item) => (
                  <tr key={item.id}>
                    <td className="px-5 py-4 text-sm text-[#34322c]">
                      {item.category.replaceAll("_", " ")}
                    </td>
                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {item.recordCount.toLocaleString("en-IN")}
                    </td>
                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {item.method}
                    </td>
                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {item.approvedBy}
                    </td>
                    <td className="px-5 py-4">
                      <span
                        className={`rounded-full px-2.5 py-1 text-xs font-medium ${
                          item.outcome === "SUCCESS"
                            ? "bg-emerald-50 text-emerald-700"
                            : item.outcome === "PARTIAL"
                              ? "bg-amber-50 text-amber-700"
                              : "bg-red-50 text-red-700"
                        }`}
                      >
                        {item.outcome}
                      </span>
                    </td>
                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {formatDate(item.completedAt)}
                    </td>
                    <td className="px-5 py-4 text-right">
                      <button
                        type="button"
                        onClick={() => onViewDisposalDetails?.(item)}
                        disabled={!onViewDisposalDetails}
                        title="View disposal details"
                        className="rounded-lg border border-[#e8e3da] p-2 text-[#77736c] hover:bg-[#f7f5f0] disabled:opacity-40"
                      >
                        <Eye size={15} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>

      <section className="rounded-xl border border-[#e9e5dd] bg-[#faf9f6] p-5">
        <div className="flex items-start gap-3">
          <ShieldCheck
            size={19}
            className="mt-0.5 shrink-0 text-[#9b8358]"
          />

          <div>
            <h3 className="text-sm font-semibold text-[#34322c]">
              Retention and disposal safeguards
            </h3>

            <ul className="mt-2 space-y-1.5 text-xs leading-5 text-[#77736c]">
              <li>
                • Retention periods must come from approved legal and
                business policies, not frontend assumptions.
              </li>
              <li>
                • Legal holds must prevent ordinary disposal until formally
                released by an authorized process.
              </li>
              <li>
                • Disposal requires authorization, execution evidence, and
                an auditable record.
              </li>
              <li>
                • Consider backups, exports, replicas, and third-party
                processors when defining disposal completion.
              </li>
              <li>
                • Preserve financial, contractual, and audit records where
                applicable retention obligations require it.
              </li>
              <li>
                • A disposal history entry is not independent proof that
                every copy of the data was erased.
              </li>
            </ul>
          </div>
        </div>
      </section>
    </main>
  );
}

"use client";

import {
  AlertCircle,
  Archive,
  CheckCircle2,
  Clock3,
  Download,
  Eye,
  File,
  FileImage,
  FileText,
  FolderOpen,
  LockKeyhole,
  RefreshCw,
  Search,
  ShieldCheck,
  Upload,
} from "lucide-react";
import { useMemo, useState } from "react";

export type AdminDocumentStatus =
  | "draft"
  | "under_review"
  | "approved"
  | "rejected"
  | "archived";

export type AdminDocumentVisibility =
  | "internal"
  | "client"
  | "vendor"
  | "restricted";

export type AdminDocument = {
  id: string;
  name: string;
  projectName: string;
  projectId: string;
  category:
    | "drawing"
    | "render"
    | "contract"
    | "invoice"
    | "payment_proof"
    | "report"
    | "other";
  fileType: string;
  fileSizeBytes?: number;
  revision?: string;
  status: AdminDocumentStatus;
  visibility: AdminDocumentVisibility;
  uploadedBy: string;
  uploadedAt: string;
  reviewedBy?: string;
  reviewedAt?: string;
  description?: string;
};

type Props = {
  documents: AdminDocument[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onUpload?: () => void;
  onOpenDocument?: (document: AdminDocument) => void;
  onDownloadDocument?: (document: AdminDocument) => void;
  onReviewDocument?: (document: AdminDocument) => void;
  onChangeVisibility?: (document: AdminDocument) => void;
  onArchiveDocument?: (document: AdminDocument) => void;
};

const statusStyles: Record<AdminDocumentStatus, string> = {
  draft: "bg-[#F2F0EB] text-[#55534F]",
  under_review: "bg-amber-50 text-amber-800",
  approved: "bg-emerald-50 text-emerald-800",
  rejected: "bg-red-50 text-red-800",
  archived: "bg-[#EAE8E2] text-[#77736D]",
};

const visibilityStyles: Record<AdminDocumentVisibility, string> = {
  internal: "bg-blue-50 text-blue-800",
  client: "bg-emerald-50 text-emerald-800",
  vendor: "bg-amber-50 text-amber-800",
  restricted: "bg-red-50 text-red-800",
};

const categoryLabels: Record<AdminDocument["category"], string> = {
  drawing: "Drawing",
  render: "3D render",
  contract: "Contract",
  invoice: "Invoice",
  payment_proof: "Payment proof",
  report: "Report",
  other: "Other",
};

function formatDate(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function formatFileSize(bytes?: number) {
  if (bytes === undefined || bytes < 0) return "Size unavailable";
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function DocumentIcon({ category }: { category: AdminDocument["category"] }) {
  if (category === "drawing" || category === "render") {
    return <FileImage size={18} />;
  }

  if (category === "invoice" || category === "payment_proof") {
    return <FileText size={18} />;
  }

  return <File size={18} />;
}

function StatusPill({
  children,
  className,
}: {
  children: React.ReactNode;
  className: string;
}) {
  return (
    <span
      className={`inline-flex rounded-full px-2.5 py-1 text-[10px] font-medium ${className}`}
    >
      {children}
    </span>
  );
}

export default function AdminDocumentManagement({
  documents,
  loading = false,
  error = null,
  onRefresh,
  onUpload,
  onOpenDocument,
  onDownloadDocument,
  onReviewDocument,
  onChangeVisibility,
  onArchiveDocument,
}: Props) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [visibilityFilter, setVisibilityFilter] = useState("all");

  const filteredDocuments = useMemo(() => {
    const term = search.trim().toLowerCase();

    return documents.filter((document) => {
      const matchesSearch =
        !term ||
        [
          document.name,
          document.projectName,
          document.projectId,
          document.uploadedBy,
          document.description ?? "",
          document.revision ?? "",
        ].some((value) => value.toLowerCase().includes(term));

      const matchesStatus =
        statusFilter === "all" || document.status === statusFilter;

      const matchesCategory =
        categoryFilter === "all" || document.category === categoryFilter;

      const matchesVisibility =
        visibilityFilter === "all" ||
        document.visibility === visibilityFilter;

      return (
        matchesSearch &&
        matchesStatus &&
        matchesCategory &&
        matchesVisibility
      );
    });
  }, [documents, search, statusFilter, categoryFilter, visibilityFilter]);

  const pendingReviewCount = documents.filter(
    (document) => document.status === "under_review"
  ).length;

  const approvedCount = documents.filter(
    (document) => document.status === "approved"
  ).length;

  const restrictedCount = documents.filter(
    (document) => document.visibility === "restricted"
  ).length;

  return (
    <main className="min-h-screen bg-[#F7F6F2] px-4 py-6 sm:px-6 lg:px-8">
      <div className="mx-auto max-w-[1440px]">
        <header className="mb-8 flex flex-col justify-between gap-5 border-b border-[#D8D6D0] pb-6 sm:flex-row sm:items-end">
          <div>
            <p className="mb-2 font-mono text-[10px] uppercase tracking-[0.2em] text-[#9A7848]">
              Studio administration / Records
            </p>

            <h1 className="text-2xl font-medium tracking-tight text-[#171717] sm:text-3xl">
              Document management
            </h1>

            <p className="mt-2 max-w-2xl text-sm leading-6 text-[#77736D]">
              Review project records, control document classifications
              and monitor approval status.
            </p>
          </div>

          <div className="flex flex-wrap gap-3">
            {onRefresh && (
              <button
                type="button"
                onClick={onRefresh}
                disabled={loading}
                className="inline-flex items-center gap-2 rounded-lg border border-[#D8D6D0] bg-white px-4 py-2.5 text-xs font-medium text-[#33312E] hover:border-[#B68A4A] disabled:opacity-50"
              >
                <RefreshCw
                  size={14}
                  className={loading ? "animate-spin" : ""}
                />
                Refresh
              </button>
            )}

            {onUpload && (
              <button
                type="button"
                onClick={onUpload}
                className="inline-flex items-center gap-2 rounded-lg bg-[#171717] px-4 py-2.5 text-xs font-medium text-white transition hover:bg-[#33312E]"
              >
                <Upload size={14} />
                Upload document
              </button>
            )}
          </div>
        </header>

        {error && (
          <div
            role="alert"
            className="mb-6 flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
          >
            <AlertCircle size={18} className="mt-0.5 shrink-0" />
            <div>
              <p className="font-medium">Unable to load documents</p>
              <p className="mt-1 text-xs">{error}</p>
            </div>
          </div>
        )}

        {loading && (
          <div
            role="status"
            className="mb-6 rounded-lg border border-[#D8D6D0] bg-white px-4 py-3 text-xs text-[#77736D]"
          >
            Loading document records…
          </div>
        )}

        {/* Summary */}
        <section className="mb-8">
          <div className="mb-4">
            <p className="mb-1 font-mono text-[10px] uppercase tracking-[0.18em] text-[#9A7848]">
              01 / Overview
            </p>
            <h2 className="text-lg font-medium text-[#171717]">
              Document inventory
            </h2>
          </div>

          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
            <article className="rounded-xl border border-[#E2E0DA] bg-white p-5">
              <FolderOpen size={18} className="text-[#9A7848]" />
              <p className="mt-4 text-xs text-[#77736D]">
                Total documents
              </p>
              <p className="mt-1 text-3xl font-medium tabular-nums text-[#171717]">
                {documents.length}
              </p>
            </article>

            <article className="rounded-xl border border-[#E2E0DA] bg-white p-5">
              <Clock3 size={18} className="text-amber-700" />
              <p className="mt-4 text-xs text-[#77736D]">
                Awaiting review
              </p>
              <p className="mt-1 text-3xl font-medium tabular-nums text-[#171717]">
                {pendingReviewCount}
              </p>
            </article>

            <article className="rounded-xl border border-[#E2E0DA] bg-white p-5">
              <CheckCircle2 size={18} className="text-emerald-700" />
              <p className="mt-4 text-xs text-[#77736D]">
                Approved
              </p>
              <p className="mt-1 text-3xl font-medium tabular-nums text-[#171717]">
                {approvedCount}
              </p>
            </article>

            <article className="rounded-xl border border-[#E2E0DA] bg-white p-5">
              <LockKeyhole size={18} className="text-red-700" />
              <p className="mt-4 text-xs text-[#77736D]">
                Restricted records
              </p>
              <p className="mt-1 text-3xl font-medium tabular-nums text-[#171717]">
                {restrictedCount}
              </p>
            </article>
          </div>
        </section>

        {/* Filters */}
        <section className="mb-5 rounded-xl border border-[#E2E0DA] bg-white p-4">
          <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-[minmax(220px,1fr)_180px_180px_180px]">
            <div className="relative">
              <Search
                size={15}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#99958D]"
              />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search documents or projects"
                aria-label="Search documents or projects"
                className="w-full rounded-lg border border-[#D8D6D0] bg-[#FAF9F6] py-2.5 pl-9 pr-3 text-xs text-[#252421] outline-none focus:border-[#B68A4A]"
              />
            </div>

            <select
              value={statusFilter}
              onChange={(event) => setStatusFilter(event.target.value)}
              aria-label="Filter by document status"
              className="rounded-lg border border-[#D8D6D0] bg-[#FAF9F6] px-3 py-2.5 text-xs text-[#55534F] outline-none focus:border-[#B68A4A]"
            >
              <option value="all">All statuses</option>
              <option value="draft">Draft</option>
              <option value="under_review">Under review</option>
              <option value="approved">Approved</option>
              <option value="rejected">Rejected</option>
              <option value="archived">Archived</option>
            </select>

            <select
              value={categoryFilter}
              onChange={(event) => setCategoryFilter(event.target.value)}
              aria-label="Filter by document category"
              className="rounded-lg border border-[#D8D6D0] bg-[#FAF9F6] px-3 py-2.5 text-xs text-[#55534F] outline-none focus:border-[#B68A4A]"
            >
              <option value="all">All categories</option>
              {Object.entries(categoryLabels).map(([value, label]) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>

            <select
              value={visibilityFilter}
              onChange={(event) => setVisibilityFilter(event.target.value)}
              aria-label="Filter by document visibility"
              className="rounded-lg border border-[#D8D6D0] bg-[#FAF9F6] px-3 py-2.5 text-xs text-[#55534F] outline-none focus:border-[#B68A4A]"
            >
              <option value="all">All visibility levels</option>
              <option value="internal">Internal</option>
              <option value="client">Client</option>
              <option value="vendor">Vendor</option>
              <option value="restricted">Restricted</option>
            </select>
          </div>

          <p className="mt-3 text-[10px] text-[#99958D]">
            Showing {filteredDocuments.length} of {documents.length} records
          </p>
        </section>

        {/* Document table */}
        <section className="overflow-hidden rounded-xl border border-[#E2E0DA] bg-white">
          {filteredDocuments.length > 0 ? (
            <div className="overflow-x-auto">
              <table className="w-full min-w-[1050px] text-left">
                <thead className="border-b border-[#EEECE7] bg-[#FAF9F6]">
                  <tr className="text-[10px] uppercase tracking-wider text-[#77736D]">
                    <th className="px-5 py-3 font-medium">Document</th>
                    <th className="px-5 py-3 font-medium">Project</th>
                    <th className="px-5 py-3 font-medium">Category</th>
                    <th className="px-5 py-3 font-medium">Revision</th>
                    <th className="px-5 py-3 font-medium">Status</th>
                    <th className="px-5 py-3 font-medium">Visibility</th>
                    <th className="px-5 py-3 font-medium">Uploaded</th>
                    <th className="px-5 py-3 font-medium">Actions</th>
                  </tr>
                </thead>

                <tbody>
                  {filteredDocuments.map((document) => (
                    <tr
                      key={document.id}
                      className="border-b border-[#EEECE7] last:border-0 hover:bg-[#FAF9F6]"
                    >
                      <td className="px-5 py-4">
                        <div className="flex items-start gap-3">
                          <span className="rounded-lg bg-[#F2F0EB] p-2 text-[#77736D]">
                            <DocumentIcon category={document.category} />
                          </span>
                          <div className="max-w-[220px]">
                            <p className="truncate text-xs font-medium text-[#252421]">
                              {document.name}
                            </p>
                            <p className="mt-1 text-[10px] text-[#99958D]">
                              {document.fileType} ·{" "}
                              {formatFileSize(document.fileSizeBytes)}
                            </p>
                            {document.description && (
                              <p className="mt-1 line-clamp-2 text-[10px] text-[#77736D]">
                                {document.description}
                              </p>
                            )}
                          </div>
                        </div>
                      </td>

                      <td className="px-5 py-4">
                        <p className="text-xs text-[#252421]">
                          {document.projectName}
                        </p>
                        <p className="mt-1 text-[10px] text-[#99958D]">
                          {document.projectId}
                        </p>
                      </td>

                      <td className="px-5 py-4 text-xs text-[#77736D]">
                        {categoryLabels[document.category]}
                      </td>

                      <td className="px-5 py-4 text-xs text-[#77736D]">
                        {document.revision ?? "—"}
                      </td>

                      <td className="px-5 py-4">
                        <StatusPill className={statusStyles[document.status]}>
                          {document.status.replace("_", " ")}
                        </StatusPill>
                      </td>

                      <td className="px-5 py-4">
                        <StatusPill
                          className={visibilityStyles[document.visibility]}
                        >
                          {document.visibility}
                        </StatusPill>
                      </td>

                      <td className="px-5 py-4">
                        <p className="text-xs text-[#55534F]">
                          {formatDate(document.uploadedAt)}
                        </p>
                        <p className="mt-1 text-[10px] text-[#99958D]">
                          {document.uploadedBy}
                        </p>
                      </td>

                      <td className="px-5 py-4">
                        <div className="flex items-center gap-2">
                          {onOpenDocument && (
                            <button
                              type="button"
                              onClick={() => onOpenDocument(document)}
                              title="View document details"
                              aria-label={`View ${document.name}`}
                              className="rounded-md border border-[#E2E0DA] p-2 text-[#77736D] hover:border-[#B68A4A] hover:text-[#9A7848]"
                            >
                              <Eye size={14} />
                            </button>
                          )}

                          {onDownloadDocument && (
                            <button
                              type="button"
                              onClick={() => onDownloadDocument(document)}
                              title="Download document"
                              aria-label={`Download ${document.name}`}
                              className="rounded-md border border-[#E2E0DA] p-2 text-[#77736D] hover:border-[#B68A4A] hover:text-[#9A7848]"
                            >
                              <Download size={14} />
                            </button>
                          )}

                          {document.status === "under_review" &&
                            onReviewDocument && (
                              <button
                                type="button"
                                onClick={() => onReviewDocument(document)}
                                className="text-[10px] font-medium text-[#9A7848] hover:underline"
                              >
                                Review
                              </button>
                            )}

                          {onChangeVisibility && (
                            <button
                              type="button"
                              onClick={() => onChangeVisibility(document)}
                              title="Change visibility"
                              aria-label={`Change visibility for ${document.name}`}
                              className="rounded-md border border-[#E2E0DA] p-2 text-[#77736D] hover:border-[#B68A4A] hover:text-[#9A7848]"
                            >
                              <LockKeyhole size={14} />
                            </button>
                          )}

                          {document.status !== "archived" &&
                            onArchiveDocument && (
                              <button
                                type="button"
                                onClick={() => onArchiveDocument(document)}
                                title="Archive document"
                                aria-label={`Archive ${document.name}`}
                                className="rounded-md border border-[#E2E0DA] p-2 text-[#77736D] hover:border-red-300 hover:text-red-700"
                              >
                                <Archive size={14} />
                              </button>
                            )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="flex min-h-[240px] flex-col items-center justify-center px-5 py-10 text-center">
              <FolderOpen size={25} className="mb-3 text-[#99958D]" />
              <p className="text-sm font-medium text-[#33312E]">
                No matching documents
              </p>
              <p className="mt-1 text-xs text-[#77736D]">
                Try changing the search term or filters.
              </p>
            </div>
          )}
        </section>

        <footer className="mt-8 border-t border-[#D8D6D0] pt-5">
          <p className="text-[11px] leading-5 text-[#8B877F]">
            Document access must be enforced by the backend using
            authenticated identity, project ownership, role permissions
            and server-side file authorization. Never expose permanent
            private storage URLs. Payment proofs, contracts and restricted
            records require additional access controls and audit logging.
          </p>
        </footer>
      </div>
    </main>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  RefreshCw,
  TrendingUp,
  TrendingDown,
  Wallet,
  IndianRupee,
  Clock3,
  AlertCircle,
  ArrowUpRight,
  ArrowDownRight,
  FileText,
  CalendarDays,
  Building2,
  Download,
  BarChart3,
  ShieldCheck,
} from "lucide-react";

export interface FinanceAgeingBucket {
  label: string;
  amount: number;
  invoiceCount: number;
}

export interface FinanceMonthlyRecord {
  period: string;
  receivables: number;
  payables: number;
  collections: number;
  payments: number;
}

export interface FinanceRecentTransaction {
  id: string;
  reference: string;
  partyName: string;
  partyType: "Client" | "Vendor";
  description: string;
  amount: number;
  date: string;
  status:
    | "Recorded"
    | "Pending Verification"
    | "Under Review"
    | "Disputed"
    | "Rejected";
  direction: "Receivable" | "Payable";
}

export interface AdminFinanceData {
  currency: "INR";
  reportingPeriod: string;
  generatedAt: string;

  totalReceivables: number;
  totalPayables: number;

  overdueReceivables: number;
  overduePayables: number;

  collectionsThisPeriod: number;
  paymentsThisPeriod: number;

  pendingClientPayments: number;
  pendingVendorPayments: number;

  verifiedCashSettlements: number;
  disputedCashSettlements: number;

  receivablesAgeing: FinanceAgeingBucket[];
  payablesAgeing: FinanceAgeingBucket[];

  monthlyRecords: FinanceMonthlyRecord[];
  recentTransactions: FinanceRecentTransaction[];
}

interface AdminFinanceOverviewProps {
  data: AdminFinanceData | null;
  loading?: boolean;
  error?: string;

  onRefresh?: () => void;

  onOpenReceivables?: () => void;
  onOpenPayables?: () => void;
  onOpenInvoices?: () => void;
  onOpenCashSettlements?: () => void;
  onOpenTransaction?: (transactionId: string) => void;

  onExportReport?: () => void;
}

type TransactionFilter = "All" | "Receivable" | "Payable";

function formatCurrency(value: number) {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 0,
  }).format(value);
}

function formatDate(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  }).format(date);
}

function formatNumber(value: number) {
  return value.toLocaleString("en-IN");
}

function transactionStatusStyle(
  status: FinanceRecentTransaction["status"]
) {
  switch (status) {
    case "Recorded":
      return "bg-[#EAF1E8] text-[#547A51]";

    case "Pending Verification":
    case "Under Review":
      return "bg-[#F4EFE2] text-[#94743F]";

    case "Disputed":
    case "Rejected":
      return "bg-[#F8EAE7] text-[#9A5147]";

    default:
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

function validValue(value: number) {
  return Number.isFinite(value) && value >= 0;
}

export function AdminFinanceOverview({
  data,
  loading = false,
  error,
  onRefresh,
  onOpenReceivables,
  onOpenPayables,
  onOpenInvoices,
  onOpenCashSettlements,
  onOpenTransaction,
  onExportReport,
}: AdminFinanceOverviewProps) {
  const [transactionFilter, setTransactionFilter] =
    useState<TransactionFilter>("All");

  const filteredTransactions = useMemo(() => {
    if (!data) return [];

    if (transactionFilter === "All") {
      return data.recentTransactions;
    }

    return data.recentTransactions.filter(
      (transaction) =>
        transaction.direction === transactionFilter
    );
  }, [data, transactionFilter]);

  const invalidData = data
    ? [
        data.totalReceivables,
        data.totalPayables,
        data.overdueReceivables,
        data.overduePayables,
        data.collectionsThisPeriod,
        data.paymentsThisPeriod,
        data.pendingClientPayments,
        data.pendingVendorPayments,
        data.verifiedCashSettlements,
        data.disputedCashSettlements,
      ].some((value) => !validValue(value))
    : false;

  const monthlyMaximum = data
    ? Math.max(
        1,
        ...data.monthlyRecords.map((record) =>
          Math.max(
            record.receivables,
            record.payables,
            record.collections,
            record.payments
          )
        )
      )
    : 1;

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-9 md:px-10 md:py-12 lg:px-12">

      {/* Header */}
      <header className="flex flex-col justify-between gap-6 border-b border-[#D8D6D0] pb-8 md:flex-row md:items-end">
        <div>
          <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
            Administration / Finance
          </p>

          <h1 className="mt-4 font-serif text-4xl text-[#171717] md:text-5xl">
            Finance Overview
          </h1>

          <p className="mt-3 max-w-xl text-sm leading-7 text-[#77736C]">
            Monitor receivables, payables, overdue balances,
            collections and verified financial activity.
          </p>

          {data && (
            <p className="mt-4 font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
              Period: {data.reportingPeriod}
              {" · "}
              Generated: {formatDate(data.generatedAt)}
            </p>
          )}
        </div>

        <div className="flex flex-wrap gap-3">
          {onExportReport && (
            <button
              type="button"
              onClick={onExportReport}
              disabled={!data || loading || invalidData}
              className="inline-flex items-center gap-2 border border-[#D8D6D0] bg-white px-5 py-3 text-[10px] uppercase tracking-widest text-[#55514A] hover:border-[#A58A64] disabled:opacity-40"
            >
              <Download size={14} />
              Export Report
            </button>
          )}

          {onRefresh && (
            <button
              type="button"
              onClick={onRefresh}
              disabled={loading}
              className="inline-flex items-center gap-2 bg-[#171717] px-5 py-3 text-[10px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:opacity-40"
            >
              <RefreshCw size={14} />
              Refresh
            </button>
          )}
        </div>
      </header>

      {error && (
        <div
          role="alert"
          className="mt-6 flex items-start gap-3 border border-[#E3C9C5] bg-[#FAF3F1] p-5"
        >
          <AlertCircle
            size={18}
            className="mt-0.5 shrink-0 text-[#9A5147]"
          />
          <p className="text-xs leading-6 text-[#805B55]">
            {error}
          </p>
        </div>
      )}

      {loading && !data ? (
        <div className="flex min-h-80 items-center justify-center">
          <p className="font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
            Loading financial information...
          </p>
        </div>
      ) : !data ? (
        <div className="mt-10 border border-[#D8D6D0] bg-white px-6 py-16 text-center">
          <BarChart3
            size={30}
            className="mx-auto text-[#A58A64]"
          />

          <h2 className="mt-5 font-serif text-2xl text-[#171717]">
            Finance data unavailable
          </h2>

          <p className="mt-3 text-xs text-[#77736C]">
            Financial reports will appear when verified data is available.
          </p>
        </div>
      ) : (
        <>
          {invalidData && (
            <div
              role="alert"
              className="mt-6 flex items-start gap-3 border border-[#E3C9C5] bg-[#FAF3F1] p-5"
            >
              <AlertCircle
                size={18}
                className="mt-0.5 shrink-0 text-[#9A5147]"
              />

              <p className="text-xs leading-6 text-[#805B55]">
                Some financial values are invalid. Do not export or
                rely on this report until the source records are corrected.
              </p>
            </div>
          )}

          {/* Main Financial Position */}
          <section className="mt-9">
            <SectionHeading>Financial Position</SectionHeading>

            <div className="mt-5 grid grid-cols-1 gap-px border border-[#D8D6D0] bg-[#D8D6D0] md:grid-cols-2">
              <FinancialPositionCard
                title="Total Receivables"
                description="Amounts reported as due from clients"
                value={formatCurrency(data.totalReceivables)}
                icon={<TrendingUp size={19} />}
                overdue={data.overdueReceivables}
                onClick={onOpenReceivables}
              />

              <FinancialPositionCard
                title="Total Payables"
                description="Amounts reported as due to vendors"
                value={formatCurrency(data.totalPayables)}
                icon={<TrendingDown size={19} />}
                overdue={data.overduePayables}
                onClick={onOpenPayables}
              />
            </div>
          </section>

          {/* Collections and Payments */}
          <section className="mt-9">
            <SectionHeading>Period Activity</SectionHeading>

            <div className="mt-5 grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
              <MetricCard
                label="Collections This Period"
                value={formatCurrency(data.collectionsThisPeriod)}
                icon={<TrendingUp size={18} />}
              />

              <MetricCard
                label="Payments This Period"
                value={formatCurrency(data.paymentsThisPeriod)}
                icon={<TrendingDown size={18} />}
              />

              <MetricCard
                label="Pending Client Payments"
                value={formatCurrency(data.pendingClientPayments)}
                icon={<Clock3 size={18} />}
              />

              <MetricCard
                label="Pending Vendor Payments"
                value={formatCurrency(data.pendingVendorPayments)}
                icon={<Wallet size={18} />}
              />
            </div>
          </section>

          {/* Cash Settlement Monitoring */}
          <section className="mt-9">
            <SectionHeading>Cash Settlement Monitoring</SectionHeading>

            <div className="mt-5 grid grid-cols-1 gap-4 md:grid-cols-2">
              <SettlementMetric
                label="Verified Settlements"
                value={formatNumber(data.verifiedCashSettlements)}
                description="Finance-verified settlement records"
                icon={<ShieldCheck size={19} />}
                onClick={onOpenCashSettlements}
              />

              <SettlementMetric
                label="Disputed Settlements"
                value={formatNumber(data.disputedCashSettlements)}
                description="Records requiring dispute resolution"
                icon={<AlertCircle size={19} />}
                onClick={onOpenCashSettlements}
              />
            </div>
          </section>

          {/* Ageing Analysis */}
          <section className="mt-10">
            <div className="flex items-end justify-between border-b border-[#D8D6D0] pb-5">
              <div>
                <SectionHeading>Outstanding Analysis</SectionHeading>

                <h2 className="mt-3 font-serif text-2xl text-[#171717]">
                  Receivables Ageing
                </h2>
              </div>

              <p className="font-mono text-[9px] text-[#99958D]">
                CLIENT BALANCES
              </p>
            </div>

            <AgeingTable buckets={data.receivablesAgeing} />
          </section>

          <section className="mt-10">
            <div className="flex items-end justify-between border-b border-[#D8D6D0] pb-5">
              <div>
                <SectionHeading>Outstanding Analysis</SectionHeading>

                <h2 className="mt-3 font-serif text-2xl text-[#171717]">
                  Payables Ageing
                </h2>
              </div>

              <p className="font-mono text-[9px] text-[#99958D]">
                VENDOR BALANCES
              </p>
            </div>

            <AgeingTable buckets={data.payablesAgeing} />
          </section>

          {/* Monthly Financial Trend */}
          <section className="mt-10">
            <div className="border-b border-[#D8D6D0] pb-5">
              <SectionHeading>Financial Performance</SectionHeading>

              <h2 className="mt-3 font-serif text-2xl text-[#171717]">
                Monthly Financial Trend
              </h2>

              <p className="mt-2 text-xs text-[#77736C]">
                Compare receivables, payables, collections and payments.
              </p>
            </div>

            <div className="mt-5 border border-[#D8D6D0] bg-white p-5 md:p-7">
              <div className="flex flex-wrap gap-x-5 gap-y-3">
                <LegendItem label="Receivables" marker="bg-[#A58A64]" />
                <LegendItem label="Payables" marker="bg-[#343434]" />
                <LegendItem label="Collections" marker="bg-[#809B78]" />
                <LegendItem label="Payments" marker="bg-[#8C9EB0]" />
              </div>

              {data.monthlyRecords.length === 0 ? (
                <p className="py-16 text-center text-xs text-[#77736C]">
                  No monthly trend data is available.
                </p>
              ) : (
                <div className="mt-8 space-y-7">
                  {data.monthlyRecords.map((record) => (
                    <div key={record.period}>
                      <div className="mb-3 flex items-center justify-between gap-4">
                        <p className="font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                          {record.period}
                        </p>

                        <p className="text-[9px] text-[#99958D]">
                          Monthly comparison
                        </p>
                      </div>

                      <div className="space-y-2">
                        <TrendBar
                          label="Receivables"
                          value={record.receivables}
                          maximum={monthlyMaximum}
                          marker="bg-[#A58A64]"
                        />

                        <TrendBar
                          label="Payables"
                          value={record.payables}
                          maximum={monthlyMaximum}
                          marker="bg-[#343434]"
                        />

                        <TrendBar
                          label="Collections"
                          value={record.collections}
                          maximum={monthlyMaximum}
                          marker="bg-[#809B78]"
                        />

                        <TrendBar
                          label="Payments"
                          value={record.payments}
                          maximum={monthlyMaximum}
                          marker="bg-[#8C9EB0]"
                        />
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </section>

          {/* Recent Transactions */}
          <section className="mt-10">
            <div className="flex flex-col justify-between gap-4 border-b border-[#D8D6D0] pb-5 sm:flex-row sm:items-end">
              <div>
                <SectionHeading>Financial Activity</SectionHeading>

                <h2 className="mt-3 font-serif text-2xl text-[#171717]">
                  Recent Transactions
                </h2>
              </div>

              <div className="flex gap-2">
                {(
                  ["All", "Receivable", "Payable"] as TransactionFilter[]
                ).map((filter) => (
                  <button
                    key={filter}
                    type="button"
                    onClick={() => setTransactionFilter(filter)}
                    aria-pressed={transactionFilter === filter}
                    className={`border px-3 py-2 text-[8px] uppercase tracking-widest ${
                      transactionFilter === filter
                        ? "border-[#171717] bg-[#171717] text-white"
                        : "border-[#D8D6D0] bg-white text-[#77736C]"
                    }`}
                  >
                    {filter}
                  </button>
                ))}
              </div>
            </div>

            {filteredTransactions.length === 0 ? (
              <div className="mt-5 border border-[#D8D6D0] bg-white p-12 text-center">
                <FileText
                  size={25}
                  className="mx-auto text-[#A58A64]"
                />

                <p className="mt-4 text-xs text-[#77736C]">
                  No transactions are available for this selection.
                </p>
              </div>
            ) : (
              <div className="mt-5 space-y-3">
                {filteredTransactions.map((transaction) => (
                  <TransactionCard
                    key={transaction.id}
                    transaction={transaction}
                    onOpen={
                      onOpenTransaction
                        ? () => onOpenTransaction(transaction.id)
                        : undefined
                    }
                  />
                ))}
              </div>
            )}
          </section>

          {/* Reporting Note */}
          <section className="mt-10 flex items-start gap-4 border border-[#D8D6D0] bg-white p-5 md:p-6">
            <ShieldCheck
              size={19}
              className="mt-0.5 shrink-0 text-[#A58A64]"
            />

            <div>
              <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                Reporting Integrity
              </p>

              <p className="mt-2 text-xs leading-6 text-[#77736C]">
                This overview is only as accurate as its underlying
                reconciled financial records. Pending payment proofs,
                disputed settlements and unverified transactions must
                not be counted as completed payments.
              </p>
            </div>
          </section>
        </>
      )}
    </main>
  );
}

function SectionHeading({ children }: { children: ReactNode }) {
  return (
    <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
      {children}
    </p>
  );
}

function FinancialPositionCard({
  title,
  description,
  value,
  icon,
  overdue,
  onClick,
}: {
  title: string;
  description: string;
  value: string;
  icon: ReactNode;
  overdue: number;
  onClick?: () => void;
}) {
  return (
    <div className="bg-white p-6 md:p-8">
      <div className="flex items-center justify-between">
        <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
          {title}
        </p>

        <span className="text-[#A58A64]">{icon}</span>
      </div>

      <p className="mt-6 break-words font-serif text-3xl text-[#171717] md:text-4xl">
        {value}
      </p>

      <p className="mt-2 text-[10px] text-[#77736C]">
        {description}
      </p>

      <div className="mt-6 flex flex-wrap items-center justify-between gap-3 border-t border-[#E5E2DC] pt-5">
        <div>
          <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
            Overdue Balance
          </p>

          <p className="mt-2 text-sm text-[#9A5147]">
            {formatCurrency(overdue)}
          </p>
        </div>

        {onClick && (
          <button
            type="button"
            onClick={onClick}
            className="inline-flex items-center gap-1 text-[9px] uppercase tracking-widest text-[#987543]"
          >
            View Details
            <ArrowUpRight size={13} />
          </button>
        )}
      </div>
    </div>
  );
}

function MetricCard({
  label,
  value,
  icon,
}: {
  label: string;
  value: string;
  icon: ReactNode;
}) {
  return (
    <div className="border border-[#D8D6D0] bg-white p-5 md:p-6">
      <span className="text-[#A58A64]">{icon}</span>

      <p className="mt-5 font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
        {label}
      </p>

      <p className="mt-3 break-words font-serif text-2xl text-[#171717]">
        {value}
      </p>
    </div>
  );
}

function SettlementMetric({
  label,
  value,
  description,
  icon,
  onClick,
}: {
  label: string;
  value: string;
  description: string;
  icon: ReactNode;
  onClick?: () => void;
}) {
  return (
    <button
      type="button"
      disabled={!onClick}
      onClick={onClick}
      className="border border-[#D8D6D0] bg-white p-6 text-left transition-colors hover:border-[#A58A64] disabled:cursor-default"
    >
      <div className="flex items-center justify-between">
        <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
          {label}
        </p>

        <span className="text-[#A58A64]">{icon}</span>
      </div>

      <p className="mt-5 font-serif text-3xl text-[#171717]">
        {value}
      </p>

      <p className="mt-2 text-[10px] text-[#77736C]">
        {description}
      </p>
    </button>
  );
}

function AgeingTable({
  buckets,
}: {
  buckets: FinanceAgeingBucket[];
}) {
  const totalAmount = buckets.reduce(
    (total, bucket) => total + bucket.amount,
    0
  );

  const totalCount = buckets.reduce(
    (total, bucket) => total + bucket.invoiceCount,
    0
  );

  return (
    <div className="mt-5 overflow-x-auto border border-[#D8D6D0] bg-white">
      <table className="w-full min-w-[520px] text-left">
        <thead>
          <tr className="border-b border-[#E5E2DC] bg-[#FAF9F6]">
            <th className="px-5 py-4 font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
              Ageing Period
            </th>

            <th className="px-5 py-4 text-right font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
              Invoice Count
            </th>

            <th className="px-5 py-4 text-right font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
              Outstanding Amount
            </th>

            <th className="px-5 py-4 text-right font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
              Share
            </th>
          </tr>
        </thead>

        <tbody>
          {buckets.length === 0 ? (
            <tr>
              <td
                colSpan={4}
                className="px-5 py-12 text-center text-xs text-[#77736C]"
              >
                No ageing information available.
              </td>
            </tr>
          ) : (
            buckets.map((bucket) => (
              <tr
                key={bucket.label}
                className="border-b border-[#E5E2DC] last:border-0"
              >
                <td className="px-5 py-4 text-xs text-[#33312D]">
                  {bucket.label}
                </td>

                <td className="px-5 py-4 text-right text-xs tabular-nums text-[#55514A]">
                  {formatNumber(bucket.invoiceCount)}
                </td>

                <td className="px-5 py-4 text-right text-xs tabular-nums text-[#33312D]">
                  {formatCurrency(bucket.amount)}
                </td>

                <td className="px-5 py-4 text-right text-xs tabular-nums text-[#77736C]">
                  {totalAmount > 0
                    ? `${((bucket.amount / totalAmount) * 100).toFixed(1)}%`
                    : "0%"}
                </td>
              </tr>
            ))
          )}
        </tbody>

        {buckets.length > 0 && (
          <tfoot>
            <tr className="bg-[#FAF9F6]">
              <td className="px-5 py-4 text-xs font-semibold text-[#171717]">
                Total
              </td>

              <td className="px-5 py-4 text-right text-xs font-semibold text-[#171717]">
                {formatNumber(totalCount)}
              </td>

              <td className="px-5 py-4 text-right text-xs font-semibold text-[#171717]">
                {formatCurrency(totalAmount)}
              </td>

              <td className="px-5 py-4 text-right text-xs font-semibold text-[#171717]">
                100%
              </td>
            </tr>
          </tfoot>
        )}
      </table>
    </div>
  );
}

function TrendBar({
  label,
  value,
  maximum,
  marker,
}: {
  label: string;
  value: number;
  maximum: number;
  marker: string;
}) {
  const percentage =
    Number.isFinite(value) && value > 0
      ? Math.min(100, (value / maximum) * 100)
      : 0;

  return (
    <div className="grid grid-cols-[88px_minmax(0,1fr)_auto] items-center gap-3">
      <p className="text-[9px] text-[#77736C]">{label}</p>

      <div className="h-2 overflow-hidden bg-[#EAE7E0]">
        <div
          className={`h-full ${marker}`}
          style={{ width: `${percentage}%` }}
        />
      </div>

      <p className="text-right text-[9px] tabular-nums text-[#55514A]">
        {formatCurrency(value)}
      </p>
    </div>
  );
}

function LegendItem({
  label,
  marker,
}: {
  label: string;
  marker: string;
}) {
  return (
    <span className="inline-flex items-center gap-2 text-[9px] text-[#77736C]">
      <span className={`h-2 w-2 ${marker}`} />
      {label}
    </span>
  );
}

function TransactionCard({
  transaction,
  onOpen,
}: {
  transaction: FinanceRecentTransaction;
  onOpen?: () => void;
}) {
  const receivable = transaction.direction === "Receivable";

  return (
    <article className="flex flex-col justify-between gap-5 border border-[#D8D6D0] bg-white p-5 md:flex-row md:items-center md:p-6">
      <div className="flex min-w-0 items-start gap-4">
        <div className="flex h-10 w-10 shrink-0 items-center justify-center border border-[#E5E2DC] bg-[#FAF9F6] text-[#A58A64]">
          {receivable ? (
            <ArrowDownRight size={18} />
          ) : (
            <ArrowUpRight size={18} />
          )}
        </div>

        <div className="min-w-0">
          <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
            {transaction.reference}
          </p>

          <h3 className="mt-2 break-words font-serif text-xl text-[#171717]">
            {transaction.partyName}
          </h3>

          <p className="mt-1 text-[10px] text-[#77736C]">
            {transaction.description}
          </p>

          <p className="mt-2 text-[9px] text-[#99958D]">
            {transaction.partyType} · {formatDate(transaction.date)}
          </p>
        </div>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-4 md:justify-end">
        <div className="md:text-right">
          <p className="font-serif text-xl text-[#171717]">
            {formatCurrency(transaction.amount)}
          </p>

          <span
            className={`mt-2 inline-block px-3 py-2 text-[8px] uppercase tracking-widest ${transactionStatusStyle(transaction.status)}`}
          >
            {transaction.status}
          </span>
        </div>

        {onOpen && (
          <button
            type="button"
            onClick={onOpen}
            aria-label={`Open transaction ${transaction.reference}`}
            className="text-[#987543] hover:text-[#171717]"
          >
            <ArrowUpRight size={18} />
          </button>
        )}
      </div>
    </article>
  );
}

import { useMemo, useState } from "react";
import type { ReactNode } from "react";
import {
  AlertTriangle,
  CheckCircle2,
  Clock3,
  ExternalLink,
  Link2,
  RefreshCw,
  Search,
  ShieldCheck,
  Unplug,
  XCircle,
} from "lucide-react";

export type IntegrationStatus =
  | "CONNECTED"
  | "DISCONNECTED"
  | "DEGRADED"
  | "PENDING_CONFIGURATION"
  | "DISABLED"
  | "UNKNOWN";

export type IntegrationEnvironment = "PRODUCTION" | "STAGING" | "DEVELOPMENT";

export type IntegrationRecord = {
  id: string;
  name: string;
  description: string;
  provider: string;
  category: string;
  status: IntegrationStatus;
  environment: IntegrationEnvironment;
  enabled: boolean;
  lastCheckedAt?: string;
  lastSuccessfulSyncAt?: string;
  owner?: string;
  failureReason?: string;
  documentationUrl?: string;
};

export type IntegrationEvent = {
  id: string;
  integrationId: string;
  integrationName: string;
  eventType: "CONNECTION" | "AUTHENTICATION" | "SYNC" | "CONFIGURATION" | "ERROR";
  description: string;
  occurredAt: string;
  severity: "INFO" | "WARNING" | "ERROR";
};

type Props = {
  integrations: IntegrationRecord[];
  events: IntegrationEvent[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onOpenIntegration?: (integration: IntegrationRecord) => void;
  onOpenDocumentation?: (integration: IntegrationRecord) => void;
  onRequestConfiguration?: (integration: IntegrationRecord) => void;
  onRequestDisable?: (integration: IntegrationRecord) => void;
};

const statusStyles: Record<IntegrationStatus, string> = {
  CONNECTED: "bg-emerald-50 text-emerald-700",
  DISCONNECTED: "bg-red-50 text-red-700",
  DEGRADED: "bg-amber-50 text-amber-800",
  PENDING_CONFIGURATION: "bg-blue-50 text-blue-700",
  DISABLED: "bg-stone-100 text-stone-600",
  UNKNOWN: "bg-stone-100 text-stone-600",
};

const eventStyles: Record<IntegrationEvent["severity"], string> = {
  INFO: "bg-blue-50 text-blue-700",
  WARNING: "bg-amber-50 text-amber-800",
  ERROR: "bg-red-50 text-red-700",
};

function formatDate(value?: string) {
  if (!value) return "Not recorded";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function Badge({
  children,
  className,
}: {
  children: ReactNode;
  className: string;
}) {
  return (
    <span
      className={`inline-flex rounded-full px-2.5 py-1 text-[10px] font-semibold tracking-wide ${className}`}
    >
      {children}
    </span>
  );
}

function Metric({
  label,
  value,
  icon,
}: {
  label: string;
  value: number;
  icon: ReactNode;
}) {
  return (
    <div className="rounded-xl border border-stone-200 bg-white p-4">
      <div className="flex items-center justify-between">
        <p className="text-xs text-stone-500">{label}</p>
        <span className="text-stone-400">{icon}</span>
      </div>
      <p className="mt-3 text-2xl font-semibold">{value}</p>
    </div>
  );
}

export default function AdminIntegrationManagementCenter({
  integrations,
  events,
  loading = false,
  error,
  onRefresh,
  onOpenIntegration,
  onOpenDocumentation,
  onRequestConfiguration,
  onRequestDisable,
}: Props) {
  const [activeTab, setActiveTab] = useState<"integrations" | "events">(
    "integrations"
  );
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("ALL");
  const [environmentFilter, setEnvironmentFilter] = useState("ALL");

  const metrics = useMemo(
    () => ({
      total: integrations.length,
      connected: integrations.filter(
        (item) => item.status === "CONNECTED"
      ).length,
      attention: integrations.filter(
        (item) =>
          item.status === "DEGRADED" ||
          item.status === "DISCONNECTED" ||
          item.status === "UNKNOWN"
      ).length,
      disabled: integrations.filter(
        (item) =>
          !item.enabled || item.status === "DISABLED"
      ).length,
    }),
    [integrations]
  );

  const filteredIntegrations = useMemo(() => {
    const query = search.trim().toLowerCase();

    return integrations.filter((item) => {
      const searchable = [
        item.id,
        item.name,
        item.description,
        item.provider,
        item.category,
        item.owner ?? "",
      ]
        .join(" ")
        .toLowerCase();

      return (
        (!query || searchable.includes(query)) &&
        (statusFilter === "ALL" || item.status === statusFilter) &&
        (environmentFilter === "ALL" ||
          item.environment === environmentFilter)
      );
    });
  }, [integrations, search, statusFilter, environmentFilter]);

  const filteredEvents = useMemo(() => {
    const query = search.trim().toLowerCase();

    return events.filter((item) =>
      [
        item.id,
        item.integrationId,
        item.integrationName,
        item.eventType,
        item.description,
        item.severity,
      ]
        .join(" ")
        .toLowerCase()
        .includes(query)
    );
  }, [events, search]);

  return (
    <main className="min-h-screen bg-[#f7f6f3] px-4 py-6 text-stone-900 sm:px-6 lg:px-8">
      <div className="mx-auto max-w-7xl space-y-6">
        <header className="flex flex-col justify-between gap-4 md:flex-row md:items-center">
          <div>
            <p className="mb-2 flex items-center gap-2 text-xs text-stone-500">
              <Link2 size={14} />
              Administration / Integrations
            </p>
            <h1 className="text-2xl font-semibold tracking-tight">
              Integration Management
            </h1>
            <p className="mt-1 max-w-2xl text-sm text-stone-500">
              Monitor connected services, configuration status, and
              integration-related events.
            </p>
          </div>

          <button
            type="button"
            onClick={onRefresh}
            disabled={!onRefresh || loading}
            className="inline-flex items-center justify-center gap-2 rounded-lg border border-stone-300 bg-white px-4 py-2.5 text-sm font-medium hover:bg-stone-50 disabled:opacity-50"
          >
            <RefreshCw
              size={15}
              className={loading ? "animate-spin" : ""}
            />
            Refresh
          </button>
        </header>

        {error && (
          <div
            role="alert"
            className="flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
          >
            <AlertTriangle size={18} />
            {error}
          </div>
        )}

        <section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          <Metric
            label="Total integrations"
            value={metrics.total}
            icon={<Link2 size={18} />}
          />
          <Metric
            label="Connected"
            value={metrics.connected}
            icon={<CheckCircle2 size={18} />}
          />
          <Metric
            label="Needs attention"
            value={metrics.attention}
            icon={<AlertTriangle size={18} />}
          />
          <Metric
            label="Disabled"
            value={metrics.disabled}
            icon={<Unplug size={18} />}
          />
        </section>

        <section className="overflow-hidden rounded-xl border border-stone-200 bg-white">
          <div className="flex flex-col gap-3 border-b border-stone-200 p-4 lg:flex-row lg:items-center lg:justify-between">
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() => setActiveTab("integrations")}
                className={`rounded-lg px-4 py-2 text-sm font-medium ${
                  activeTab === "integrations"
                    ? "bg-stone-900 text-white"
                    : "text-stone-500 hover:bg-stone-100"
                }`}
              >
                Integrations
              </button>

              <button
                type="button"
                onClick={() => setActiveTab("events")}
                className={`rounded-lg px-4 py-2 text-sm font-medium ${
                  activeTab === "events"
                    ? "bg-stone-900 text-white"
                    : "text-stone-500 hover:bg-stone-100"
                }`}
              >
                Event history
              </button>
            </div>

            <div className="relative w-full lg:max-w-xs">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400"
              />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search integrations or events..."
                className="w-full rounded-lg border border-stone-200 py-2 pl-9 pr-3 text-sm outline-none focus:border-stone-500"
              />
            </div>
          </div>

          {activeTab === "integrations" ? (
            <>
              <div className="flex flex-wrap gap-3 border-b border-stone-100 bg-stone-50/60 p-4">
                <select
                  aria-label="Filter integration status"
                  value={statusFilter}
                  onChange={(event) => setStatusFilter(event.target.value)}
                  className="rounded-lg border border-stone-200 bg-white px-3 py-2 text-sm"
                >
                  <option value="ALL">All statuses</option>
                  {Object.keys(statusStyles).map((status) => (
                    <option key={status} value={status}>
                      {status.replaceAll("_", " ")}
                    </option>
                  ))}
                </select>

                <select
                  aria-label="Filter environment"
                  value={environmentFilter}
                  onChange={(event) =>
                    setEnvironmentFilter(event.target.value)
                  }
                  className="rounded-lg border border-stone-200 bg-white px-3 py-2 text-sm"
                >
                  <option value="ALL">All environments</option>
                  <option value="PRODUCTION">Production</option>
                  <option value="STAGING">Staging</option>
                  <option value="DEVELOPMENT">Development</option>
                </select>

                <p className="self-center text-xs text-stone-500 sm:ml-auto">
                  {filteredIntegrations.length} of {integrations.length} records
                </p>
              </div>

              {loading ? (
                <div className="p-12 text-center text-sm text-stone-500">
                  Loading integrations...
                </div>
              ) : filteredIntegrations.length === 0 ? (
                <div className="p-12 text-center">
                  <Link2 size={28} className="mx-auto text-stone-300" />
                  <p className="mt-3 text-sm font-medium">
                    No integrations found
                  </p>
                </div>
              ) : (
                <div className="divide-y divide-stone-100">
                  {filteredIntegrations.map((integration) => (
                    <article key={integration.id} className="p-4 sm:p-5">
                      <div className="flex flex-col justify-between gap-4 xl:flex-row xl:items-start">
                        <div className="min-w-0 flex-1">
                          <div className="flex flex-wrap items-center gap-2">
                            <span className="font-mono text-xs text-stone-400">
                              {integration.id}
                            </span>
                            <Badge className={statusStyles[integration.status]}>
                              {integration.status.replaceAll("_", " ")}
                            </Badge>
                            <Badge className="bg-stone-100 text-stone-600">
                              {integration.environment}
                            </Badge>
                            <Badge
                              className={
                                integration.enabled
                                  ? "bg-emerald-50 text-emerald-700"
                                  : "bg-stone-100 text-stone-600"
                              }
                            >
                              {integration.enabled ? "ENABLED" : "DISABLED"}
                            </Badge>
                          </div>

                          <h2 className="mt-2 text-sm font-semibold">
                            {integration.name}
                          </h2>
                          <p className="mt-1 text-sm leading-6 text-stone-500">
                            {integration.description}
                          </p>

                          <div className="mt-3 grid gap-2 text-xs text-stone-500 sm:grid-cols-2">
                            <p>Provider: {integration.provider}</p>
                            <p>Category: {integration.category}</p>
                            <p>Owner: {integration.owner || "Not assigned"}</p>
                            <p>
                              Last checked: {formatDate(integration.lastCheckedAt)}
                            </p>
                            <p>
                              Last successful sync:{" "}
                              {formatDate(integration.lastSuccessfulSyncAt)}
                            </p>
                          </div>

                          {integration.failureReason && (
                            <div className="mt-3 rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs leading-5 text-amber-900">
                              {integration.failureReason}
                            </div>
                          )}
                        </div>

                        <div className="flex flex-wrap items-center gap-2">
                          {onRequestConfiguration &&
                            integration.status === "PENDING_CONFIGURATION" && (
                              <button
                                type="button"
                                onClick={() =>
                                  onRequestConfiguration(integration)
                                }
                                className="rounded-lg border border-stone-200 px-3 py-2 text-xs font-medium hover:bg-stone-50"
                              >
                                Request configuration
                              </button>
                            )}

                          {onRequestDisable && integration.enabled && (
                            <button
                              type="button"
                              onClick={() => onRequestDisable(integration)}
                              className="rounded-lg border border-red-200 px-3 py-2 text-xs font-medium text-red-700 hover:bg-red-50"
                            >
                              Request disable
                            </button>
                          )}

                          {onOpenDocumentation &&
                            integration.documentationUrl && (
                              <button
                                type="button"
                                onClick={() =>
                                  onOpenDocumentation(integration)
                                }
                                className="inline-flex items-center gap-1.5 rounded-lg border border-stone-200 px-3 py-2 text-xs font-medium hover:bg-stone-50"
                              >
                                Documentation
                                <ExternalLink size={12} />
                              </button>
                            )}

                          <button
                            type="button"
                            onClick={() => onOpenIntegration?.(integration)}
                            disabled={!onOpenIntegration}
                            className="rounded-lg border border-stone-200 px-3 py-2 text-xs font-medium hover:bg-stone-100 disabled:opacity-50"
                          >
                            View details
                          </button>
                        </div>
                      </div>
                    </article>
                  ))}
                </div>
              )}
            </>
          ) : (
            <div>
              {loading ? (
                <div className="p-12 text-center text-sm text-stone-500">
                  Loading event history...
                </div>
              ) : filteredEvents.length === 0 ? (
                <div className="p-12 text-center text-sm text-stone-500">
                  No integration events found.
                </div>
              ) : (
                <div className="divide-y divide-stone-100">
                  {filteredEvents.map((event) => (
                    <article
                      key={event.id}
                      className="flex flex-col justify-between gap-3 p-4 sm:flex-row sm:items-start sm:p-5"
                    >
                      <div className="min-w-0">
                        <div className="flex flex-wrap items-center gap-2">
                          <span className="font-mono text-xs text-stone-400">
                            {event.id}
                          </span>
                          <Badge className={eventStyles[event.severity]}>
                            {event.severity}
                          </Badge>
                          <Badge className="bg-stone-100 text-stone-600">
                            {event.eventType}
                          </Badge>
                        </div>

                        <h3 className="mt-2 text-sm font-semibold">
                          {event.integrationName}
                        </h3>
                        <p className="mt-1 text-sm text-stone-500">
                          {event.description}
                        </p>
                        <p className="mt-2 text-xs text-stone-400">
                          Integration: {event.integrationId} ·{" "}
                          {formatDate(event.occurredAt)}
                        </p>
                      </div>
                    </article>
                  ))}
                </div>
              )}
            </div>
          )}
        </section>

        <section className="rounded-xl border border-amber-200 bg-amber-50/60 p-4">
          <div className="flex items-start gap-3">
            <ShieldCheck
              size={19}
              className="mt-0.5 shrink-0 text-amber-800"
            />
            <div>
              <h2 className="text-sm font-semibold">
                Integration security safeguards
              </h2>
              <p className="mt-1 text-xs leading-5 text-stone-600">
                Store credentials in an approved secrets manager, never in
                browser code or integration records. Validate webhook
                signatures, restrict permissions, audit configuration
                changes, and isolate integration access by environment and
                authorised user.
              </p>
            </div>
          </div>
        </section>

        <p className="flex items-center gap-2 text-xs text-stone-400">
          <Clock3 size={13} />
          Connection status and sync timestamps must reflect verified
          monitoring data, not assumed availability.
        </p>
      </div>
    </main>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  Search,
  RefreshCw,
  FileText,
  Clock3,
  ShieldCheck,
  AlertCircle,
  CheckCircle2,
  X,
  Eye,
  ArrowUpRight,
  UserRound,
  Building2,
  CalendarDays,
  IndianRupee,
  MessageSquare,
  LockKeyhole,
} from "lucide-react";

export type ApprovalInvoiceStatus =
  | "Submitted"
  | "Under Review"
  | "Partially Approved"
  | "Approved"
  | "Rejected"
  | "Disputed";

export type ApprovalDecision =
  | "Approve"
  | "Partially Approve"
  | "Reject"
  | "Request Clarification";

export interface ApprovalHistoryEntry {
  id: string;
  actorName: string;
  actorRole: string;
  action: string;
  remarks?: string;
  timestamp: string;
}

export interface ApprovalInvoice {
  id: string;
  reference: string;
  partyType: "Client" | "Vendor";
  partyName: string;
  projectName?: string;
  projectReference?: string;

  invoiceDate: string;
  submittedAt: string;

  currency: "INR";
  invoiceAmount: number;
  previouslyApprovedAmount: number;
  proposedApprovalAmount?: number;

  status: ApprovalInvoiceStatus;

  description: string;
  invoiceDocumentCount: number;
  hasRequiredDocuments: boolean;

  submittedBy: string;
  assignedReviewer?: string;

  requiresSecondApproval: boolean;
  approvalCount: number;
  requiredApprovalCount: number;

  currentUserCanApprove: boolean;
  currentUserAlreadyApproved: boolean;

  history: ApprovalHistoryEntry[];
}

export interface ApprovalWorkspaceSummary {
  pendingCount: number;
  underReviewCount: number;
  awaitingSecondApprovalCount: number;
  approvedTodayCount: number;
  rejectedCount: number;
}

export interface ApprovalSubmission {
  decision: ApprovalDecision;
  approvedAmount?: number;
  remarks: string;
}

interface AdminInvoiceApprovalWorkspaceProps {
  invoices: ApprovalInvoice[];
  summary?: ApprovalWorkspaceSummary;
  loading?: boolean;
  submittingInvoiceId?: string;
  error?: string;

  onRefresh?: () => void;

  onOpenInvoice?: (invoiceId: string) => void;

  onSubmitDecision: (
    invoiceId: string,
    decision: ApprovalSubmission
  ) => Promise<void>;

  onOpenHistory?: (invoiceId: string) => void;
}

type QueueFilter =
  | "All"
  | "Submitted"
  | "Under Review"
  | "Awaiting Second Approval";

function formatCurrency(value: number) {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 2,
  }).format(value);
}

function formatDate(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
}

function approvalStatusStyle(status: ApprovalInvoiceStatus) {
  switch (status) {
    case "Approved":
      return "bg-[#EAF1E8] text-[#547A51]";
    case "Submitted":
    case "Under Review":
      return "bg-[#F4EFE2] text-[#94743F]";
    case "Partially Approved":
      return "bg-[#EAEFF5] text-[#526C8A]";
    case "Rejected":
    case "Disputed":
      return "bg-[#F8EAE7] text-[#9A5147]";
    default:
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

function isPositiveMoney(value: number) {
  return Number.isFinite(value) && value > 0;
}

export function AdminInvoiceApprovalWorkspace({
  invoices,
  summary,
  loading = false,
  submittingInvoiceId,
  error,
  onRefresh,
  onOpenInvoice,
  onSubmitDecision,
  onOpenHistory,
}: AdminInvoiceApprovalWorkspaceProps) {
  const [search, setSearch] = useState("");
  const [queueFilter, setQueueFilter] =
    useState<QueueFilter>("All");

  const [selectedInvoice, setSelectedInvoice] =
    useState<ApprovalInvoice | null>(null);

  const [decision, setDecision] =
    useState<ApprovalDecision>("Approve");

  const [approvedAmount, setApprovedAmount] =
    useState("");

  const [remarks, setRemarks] = useState("");
  const [actionError, setActionError] = useState("");

  const [submitting, setSubmitting] = useState(false);

  const calculatedSummary = useMemo<ApprovalWorkspaceSummary>(() => ({
    pendingCount: invoices.filter(
      (invoice) => invoice.status === "Submitted"
    ).length,

    underReviewCount: invoices.filter(
      (invoice) => invoice.status === "Under Review"
    ).length,

    awaitingSecondApprovalCount: invoices.filter(
      (invoice) =>
        invoice.requiresSecondApproval &&
        invoice.approvalCount < invoice.requiredApprovalCount
    ).length,

    approvedTodayCount: 0,

    rejectedCount: invoices.filter(
      (invoice) => invoice.status === "Rejected"
    ).length,
  }), [invoices]);

  const totals = summary ?? calculatedSummary;

  const filteredInvoices = useMemo(() => {
    const query = search.trim().toLowerCase();

    return invoices.filter((invoice) => {
      const matchesSearch =
        !query ||
        invoice.reference.toLowerCase().includes(query) ||
        invoice.partyName.toLowerCase().includes(query) ||
        invoice.partyType.toLowerCase().includes(query) ||
        (invoice.projectName ?? "").toLowerCase().includes(query) ||
        (invoice.projectReference ?? "").toLowerCase().includes(query);

      const awaitingSecondApproval =
        invoice.requiresSecondApproval &&
        invoice.approvalCount < invoice.requiredApprovalCount;

      const matchesQueue =
        queueFilter === "All" ||
        (queueFilter === "Submitted" &&
          invoice.status === "Submitted") ||
        (queueFilter === "Under Review" &&
          invoice.status === "Under Review") ||
        (queueFilter === "Awaiting Second Approval" &&
          awaitingSecondApproval);

      return matchesSearch && matchesQueue;
    });
  }, [invoices, search, queueFilter]);

  function openReview(invoice: ApprovalInvoice) {
    setSelectedInvoice(invoice);
    setDecision("Approve");
    setApprovedAmount(
      String(
        invoice.proposedApprovalAmount ??
        invoice.invoiceAmount -
          invoice.previouslyApprovedAmount
      )
    );
    setRemarks("");
    setActionError("");
  }

  function closeReview() {
    if (submitting) return;

    setSelectedInvoice(null);
    setActionError("");
  }

  async function submitDecision() {
    if (!selectedInvoice || submitting) return;

    setActionError("");

    if (!selectedInvoice.currentUserCanApprove) {
      setActionError(
        "Your account is not authorised to approve this invoice."
      );
      return;
    }

    if (selectedInvoice.currentUserAlreadyApproved) {
      setActionError(
        "You have already approved this invoice. Another authorised reviewer is required."
      );
      return;
    }

    if (
      !selectedInvoice.hasRequiredDocuments &&
      decision !== "Request Clarification"
    ) {
      setActionError(
        "Required supporting documents are missing. Request clarification before approval."
      );
      return;
    }

    const remainingAmount =
      selectedInvoice.invoiceAmount -
      selectedInvoice.previouslyApprovedAmount;

    let amount: number | undefined;

    if (
      decision === "Approve" ||
      decision === "Partially Approve"
    ) {
      amount = Number(approvedAmount);

      if (!isPositiveMoney(amount)) {
        setActionError("Enter a valid approval amount.");
        return;
      }

      if (amount > remainingAmount) {
        setActionError(
          "The approval amount cannot exceed the remaining unapproved amount."
        );
        return;
      }

      if (
        decision === "Partially Approve" &&
        amount >= remainingAmount
      ) {
        setActionError(
          "For partial approval, enter an amount below the remaining invoice amount."
        );
        return;
      }
    }

    if (
      (decision === "Reject" ||
        decision === "Request Clarification") &&
      !remarks.trim()
    ) {
      setActionError(
        "A written reason is required for this decision."
      );
      return;
    }

    setSubmitting(true);

    try {
      await onSubmitDecision(selectedInvoice.id, {
        decision,
        approvedAmount: amount,
        remarks: remarks.trim(),
      });

      setSelectedInvoice(null);
      setRemarks("");
      setApprovedAmount("");
    } catch (err) {
      setActionError(
        err instanceof Error
          ? err.message
          : "The decision could not be submitted."
      );
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-9 md:px-10 md:py-12 lg:px-12">

      {/* Header */}
      <header className="flex flex-col justify-between gap-6 border-b border-[#D8D6D0] pb-8 md:flex-row md:items-end">
        <div>
          <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
            Administration / Finance / Approvals
          </p>

          <h1 className="mt-4 font-serif text-4xl text-[#171717] md:text-5xl">
            Invoice Approval
          </h1>

          <p className="mt-3 max-w-xl text-sm leading-7 text-[#77736C]">
            Verify submitted invoices, review supporting evidence
            and record authorised finance decisions.
          </p>
        </div>

        {onRefresh && (
          <button
            type="button"
            onClick={onRefresh}
            disabled={loading}
            className="inline-flex w-fit items-center gap-2 border border-[#D8D6D0] bg-white px-5 py-3 text-[10px] uppercase tracking-widest text-[#55514A] hover:border-[#A58A64] disabled:opacity-50"
          >
            <RefreshCw size={14} />
            Refresh Queue
          </button>
        )}
      </header>

      {error && (
        <div
          role="alert"
          className="mt-6 flex items-start gap-3 border border-[#E3C9C5] bg-[#FAF3F1] p-5"
        >
          <AlertCircle size={18} className="mt-0.5 shrink-0 text-[#9A5147]" />
          <p className="text-xs leading-6 text-[#805B55]">
            {error}
          </p>
        </div>
      )}

      {/* Approval Summary */}
      <section className="mt-9 grid grid-cols-2 gap-px border border-[#D8D6D0] bg-[#D8D6D0] lg:grid-cols-5">
        <SummaryCard
          label="Pending Submission"
          value={totals.pendingCount}
        />

        <SummaryCard
          label="Under Review"
          value={totals.underReviewCount}
        />

        <SummaryCard
          label="Awaiting Second Approval"
          value={totals.awaitingSecondApprovalCount}
        />

        <SummaryCard
          label="Approved Today"
          value={totals.approvedTodayCount}
        />

        <SummaryCard
          label="Rejected"
          value={totals.rejectedCount}
        />
      </section>

      {/* Governance Notice */}
      <section className="mt-6 flex items-start gap-4 border border-[#D8D6D0] bg-white p-5 md:p-6">
        <LockKeyhole
          size={20}
          className="mt-0.5 shrink-0 text-[#A58A64]"
        />

        <div>
          <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
            Approval Governance
          </p>

          <p className="mt-2 text-xs leading-6 text-[#666159]">
            Approval authority, maker-checker separation, approval
            thresholds and duplicate-payment prevention must be
            enforced by the backend. A successful browser action
            is not proof of a financial approval.
          </p>
        </div>
      </section>

      {/* Queue Filters */}
      <section className="mt-10">
        <div className="relative">
          <Search
            size={17}
            className="absolute left-4 top-1/2 -translate-y-1/2 text-[#99958D]"
          />

          <input
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            placeholder="Search invoice, party or project..."
            aria-label="Search approval queue"
            className="h-12 w-full border border-[#D8D6D0] bg-white pl-11 pr-4 text-sm outline-none focus:border-[#A58A64]"
          />
        </div>

        <div className="mt-4 flex flex-wrap gap-2">
          {(
            [
              "All",
              "Submitted",
              "Under Review",
              "Awaiting Second Approval",
            ] as QueueFilter[]
          ).map((filter) => (
            <button
              key={filter}
              type="button"
              onClick={() => setQueueFilter(filter)}
              aria-pressed={queueFilter === filter}
              className={`border px-4 py-3 text-[9px] uppercase tracking-widest transition-colors ${
                queueFilter === filter
                  ? "border-[#171717] bg-[#171717] text-white"
                  : "border-[#D8D6D0] bg-white text-[#77736C] hover:border-[#A58A64]"
              }`}
            >
              {filter}
            </button>
          ))}
        </div>
      </section>

      {/* Review Queue */}
      <section className="mt-9">
        <div className="flex items-end justify-between border-b border-[#D8D6D0] pb-5">
          <div>
            <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
              Finance Workflow
            </p>

            <h2 className="mt-3 font-serif text-2xl text-[#171717]">
              Review Queue
            </h2>
          </div>

          <p className="font-mono text-[9px] text-[#99958D]">
            {filteredInvoices.length} RECORDS
          </p>
        </div>

        {loading ? (
          <div className="flex min-h-64 items-center justify-center">
            <p className="font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
              Loading approval queue...
            </p>
          </div>
        ) : filteredInvoices.length === 0 ? (
          <div className="mt-5 border border-[#D8D6D0] bg-white px-6 py-16 text-center">
            <CheckCircle2
              size={28}
              strokeWidth={1.3}
              className="mx-auto text-[#A58A64]"
            />

            <h3 className="mt-5 font-serif text-2xl text-[#171717]">
              No matching invoices
            </h3>

            <p className="mt-3 text-xs text-[#77736C]">
              The selected queue has no matching records.
            </p>
          </div>
        ) : (
          <div className="mt-5 space-y-3">
            {filteredInvoices.map((invoice) => (
              <ApprovalQueueCard
                key={invoice.id}
                invoice={invoice}
                submitting={submittingInvoiceId === invoice.id}
                onReview={() => openReview(invoice)}
              />
            ))}
          </div>
        )}
      </section>

      {/* Review Workspace Drawer */}
      {selectedInvoice && (
        <div
          className="fixed inset-0 z-[70] flex justify-end bg-black/50"
          role="presentation"
          onMouseDown={(event) => {
            if (event.target === event.currentTarget) {
              closeReview();
            }
          }}
        >
          <aside
            role="dialog"
            aria-modal="true"
            aria-labelledby="approval-detail-title"
            className="flex h-full w-full max-w-3xl flex-col overflow-y-auto bg-[#F2F0EB] shadow-2xl"
          >
            {/* Drawer Header */}
            <div className="sticky top-0 z-10 flex items-center justify-between border-b border-[#D8D6D0] bg-[#F2F0EB] px-6 py-5 md:px-8">
              <div>
                <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                  Finance Review / {selectedInvoice.reference}
                </p>

                <h2
                  id="approval-detail-title"
                  className="mt-2 font-serif text-2xl text-[#171717]"
                >
                  Invoice Verification
                </h2>
              </div>

              <button
                type="button"
                onClick={closeReview}
                disabled={submitting}
                aria-label="Close review"
                className="text-[#77736C] disabled:opacity-40"
              >
                <X size={21} />
              </button>
            </div>

            <div className="flex-1 space-y-7 p-6 md:p-8">

              {/* Invoice Information */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                      {selectedInvoice.partyType} Invoice
                    </p>

                    <h3 className="mt-3 break-words font-serif text-3xl text-[#171717]">
                      {selectedInvoice.reference}
                    </h3>

                    <p className="mt-2 text-xs text-[#77736C]">
                      {selectedInvoice.partyName}
                    </p>
                  </div>

                  <span
                    className={`px-3 py-2 text-[8px] uppercase tracking-widest ${approvalStatusStyle(selectedInvoice.status)}`}
                  >
                    {selectedInvoice.status}
                  </span>
                </div>

                <div className="mt-6 grid grid-cols-1 gap-4 border-t border-[#E5E2DC] pt-5 sm:grid-cols-2">
                  <DetailLine
                    icon={<CalendarDays size={14} />}
                    label="Invoice Date"
                    value={formatDate(selectedInvoice.invoiceDate)}
                  />

                  <DetailLine
                    icon={<Clock3 size={14} />}
                    label="Submitted At"
                    value={formatDate(selectedInvoice.submittedAt)}
                  />

                  <DetailLine
                    icon={<UserRound size={14} />}
                    label="Submitted By"
                    value={selectedInvoice.submittedBy}
                  />

                  <DetailLine
                    icon={<Building2 size={14} />}
                    label="Project"
                    value={selectedInvoice.projectName || "Not linked"}
                  />
                </div>

                {selectedInvoice.description && (
                  <p className="mt-5 border-t border-[#E5E2DC] pt-5 text-xs leading-7 text-[#666159]">
                    {selectedInvoice.description}
                  </p>
                )}

                {onOpenInvoice && (
                  <button
                    type="button"
                    onClick={() => onOpenInvoice(selectedInvoice.id)}
                    className="mt-5 inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#987543]"
                  >
                    Open Full Invoice Record
                    <ArrowUpRight size={14} />
                  </button>
                )}
              </section>

              {/* Financial Verification */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <SectionHeading>Financial Verification</SectionHeading>

                <div className="mt-5 space-y-4">
                  <MoneyRow
                    label="Submitted Invoice Amount"
                    value={selectedInvoice.invoiceAmount}
                  />

                  <MoneyRow
                    label="Previously Approved"
                    value={selectedInvoice.previouslyApprovedAmount}
                  />

                  <div className="border-t border-[#E5E2DC] pt-4">
                    <MoneyRow
                      label="Remaining Unapproved"
                      value={
                        selectedInvoice.invoiceAmount -
                        selectedInvoice.previouslyApprovedAmount
                      }
                      strong
                    />
                  </div>
                </div>

                <div className="mt-5 flex items-start gap-3 border border-[#E5E2DC] bg-[#FAF9F6] p-4">
                  <FileText
                    size={17}
                    className="mt-0.5 shrink-0 text-[#A58A64]"
                  />

                  <div>
                    <p className="text-xs text-[#33312D]">
                      {selectedInvoice.invoiceDocumentCount} supporting documents
                    </p>

                    <p className="mt-1 text-[10px] leading-5 text-[#77736C]">
                      {selectedInvoice.hasRequiredDocuments
                        ? "Required document presence is reported by the server. Inspect the actual documents before making a decision."
                        : "Required documents are reported missing. Request clarification rather than approving without evidence."}
                    </p>
                  </div>
                </div>
              </section>

              {/* Approval Governance */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <div className="flex items-start gap-3">
                  <ShieldCheck
                    size={20}
                    className="mt-0.5 shrink-0 text-[#A58A64]"
                  />

                  <div className="flex-1">
                    <SectionHeading>Approval Governance</SectionHeading>

                    <p className="mt-3 text-xs leading-6 text-[#77736C]">
                      This invoice requires{" "}
                      {selectedInvoice.requiredApprovalCount} approval(s).
                      The server reports{" "}
                      {selectedInvoice.approvalCount} recorded approval(s).
                    </p>

                    <div className="mt-4 flex items-center gap-2">
                      {Array.from({
                        length: Math.min(
                          selectedInvoice.requiredApprovalCount,
                          5
                        ),
                      }).map((_, index) => (
                        <span
                          key={index}
                          className={`h-2 flex-1 ${
                            index < selectedInvoice.approvalCount
                              ? "bg-[#A58A64]"
                              : "bg-[#EAE7E0]"
                          }`}
                        />
                      ))}
                    </div>

                    <p className="mt-3 font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
                      {selectedInvoice.approvalCount} /{" "}
                      {selectedInvoice.requiredApprovalCount} approvals recorded
                    </p>
                  </div>
                </div>

                {selectedInvoice.currentUserAlreadyApproved && (
                  <div className="mt-5 border border-[#E3C9C5] bg-[#FAF3F1] p-4 text-xs leading-6 text-[#805B55]">
                    You have already approved this invoice. A different
                    authorised reviewer must complete the next approval.
                  </div>
                )}

                {!selectedInvoice.currentUserCanApprove && (
                  <div className="mt-5 border border-[#E3C9C5] bg-[#FAF3F1] p-4 text-xs leading-6 text-[#805B55]">
                    Your current account does not have approval authority
                    for this invoice.
                  </div>
                )}
              </section>

              {/* Approval History */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <div className="flex items-center justify-between">
                  <SectionHeading>Decision History</SectionHeading>

                  {onOpenHistory && (
                    <button
                      type="button"
                      onClick={() =>
                        onOpenHistory(selectedInvoice.id)
                      }
                      className="text-[9px] uppercase tracking-widest text-[#987543]"
                    >
                      Full History
                    </button>
                  )}
                </div>

                {selectedInvoice.history.length === 0 ? (
                  <p className="mt-5 text-xs text-[#77736C]">
                    No approval history is available.
                  </p>
                ) : (
                  <div className="mt-5 space-y-5">
                    {selectedInvoice.history.map((entry) => (
                      <div
                        key={entry.id}
                        className="border-l border-[#D8D6D0] pl-4"
                      >
                        <p className="text-xs text-[#33312D]">
                          {entry.action}
                        </p>

                        <p className="mt-1 text-[10px] text-[#77736C]">
                          {entry.actorName} · {entry.actorRole}
                        </p>

                        {entry.remarks && (
                          <p className="mt-2 text-xs leading-6 text-[#77736C]">
                            {entry.remarks}
                          </p>
                        )}

                        <p className="mt-2 font-mono text-[8px] text-[#99958D]">
                          {formatDate(entry.timestamp)}
                        </p>
                      </div>
                    ))}
                  </div>
                )}
              </section>

              {/* Decision Form */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <SectionHeading>Record Finance Decision</SectionHeading>

                <p className="mt-3 text-xs leading-6 text-[#77736C]">
                  Select a decision and provide the required supporting
                  remarks. The backend makes the final authorisation decision.
                </p>

                <label className="mt-6 block">
                  <span className="mb-2 block font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                    Decision
                  </span>

                  <select
                    value={decision}
                    onChange={(event) => {
                      setDecision(
                        event.target.value as ApprovalDecision
                      );
                      setActionError("");
                    }}
                    disabled={
                      submitting ||
                      !selectedInvoice.currentUserCanApprove ||
                      selectedInvoice.currentUserAlreadyApproved
                    }
                    className="h-12 w-full border border-[#D8D6D0] bg-white px-3 text-xs outline-none focus:border-[#A58A64] disabled:opacity-50"
                  >
                    <option value="Approve">Approve</option>
                    <option value="Partially Approve">
                      Partially Approve
                    </option>
                    <option value="Reject">Reject</option>
                    <option value="Request Clarification">
                      Request Clarification
                    </option>
                  </select>
                </label>

                {(decision === "Approve" ||
                  decision === "Partially Approve") && (
                  <label className="mt-5 block">
                    <span className="mb-2 block font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                      Approval Amount (INR)
                    </span>

                    <div className="relative">
                      <IndianRupee
                        size={15}
                        className="absolute left-4 top-1/2 -translate-y-1/2 text-[#99958D]"
                      />

                      <input
                        type="number"
                        min="0.01"
                        step="0.01"
                        value={approvedAmount}
                        onChange={(event) =>
                          setApprovedAmount(event.target.value)
                        }
                        disabled={submitting}
                        className="h-12 w-full border border-[#D8D6D0] bg-white pl-10 pr-4 text-sm outline-none focus:border-[#A58A64] disabled:opacity-50"
                      />
                    </div>
                  </label>
                )}

                <label className="mt-5 block">
                  <span className="mb-2 block font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                    Remarks
                    {(decision === "Reject" ||
                      decision === "Request Clarification") &&
                      " · Required"}
                  </span>

                  <textarea
                    value={remarks}
                    onChange={(event) => setRemarks(event.target.value)}
                    rows={4}
                    maxLength={2000}
                    disabled={submitting}
                    placeholder="Record the reason, verification observations or clarification required..."
                    className="w-full resize-y border border-[#D8D6D0] bg-white p-4 text-xs leading-6 outline-none focus:border-[#A58A64] disabled:opacity-50"
                  />

                  <span className="mt-2 block text-right font-mono text-[8px] text-[#99958D]">
                    {remarks.length}/2000
                  </span>
                </label>

                {actionError && (
                  <div
                    role="alert"
                    className="mt-5 flex items-start gap-3 border border-[#E3C9C5] bg-[#FAF3F1] p-4"
                  >
                    <AlertCircle
                      size={16}
                      className="mt-0.5 shrink-0 text-[#9A5147]"
                    />

                    <p className="text-xs leading-6 text-[#805B55]">
                      {actionError}
                    </p>
                  </div>
                )}

                <button
                  type="button"
                  onClick={submitDecision}
                  disabled={
                    submitting ||
                    !selectedInvoice.currentUserCanApprove ||
                    selectedInvoice.currentUserAlreadyApproved ||
                    submittingInvoiceId === selectedInvoice.id
                  }
                  className="mt-6 flex w-full items-center justify-center gap-2 bg-[#171717] px-5 py-4 text-[9px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:cursor-not-allowed disabled:opacity-40"
                >
                  {submitting ? (
                    <>
                      <RefreshCw size={14} className="animate-spin" />
                      Submitting Decision...
                    </>
                  ) : (
                    <>
                      <ShieldCheck size={15} />
                      Submit Finance Decision
                    </>
                  )}
                </button>

                <p className="mt-4 text-[9px] leading-5 text-[#99958D]">
                  Submitting a decision does not execute a bank payment.
                  All approval actions must be validated and recorded by
                  the server.
                </p>
              </section>
            </div>

            <div className="sticky bottom-0 border-t border-[#D8D6D0] bg-[#F2F0EB] p-5">
              <button
                type="button"
                onClick={closeReview}
                disabled={submitting}
                className="w-full border border-[#D8D6D0] px-5 py-4 text-[9px] uppercase tracking-widest text-[#77736C] disabled:opacity-40"
              >
                Close Review
              </button>
            </div>
          </aside>
        </div>
      )}
    </main>
  );
}

function SummaryCard({
  label,
  value,
}: {
  label: string;
  value: number;
}) {
  return (
    <div className="bg-white p-5 md:p-6">
      <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
        {label}
      </p>

      <p className="mt-5 font-serif text-3xl text-[#171717]">
        {value.toLocaleString("en-IN")}
      </p>
    </div>
  );
}

function ApprovalQueueCard({
  invoice,
  submitting,
  onReview,
}: {
  invoice: ApprovalInvoice;
  submitting: boolean;
  onReview: () => void;
}) {
  const awaitingSecond =
    invoice.requiresSecondApproval &&
    invoice.approvalCount < invoice.requiredApprovalCount;

  return (
    <article className="border border-[#D8D6D0] bg-white p-5 md:p-7">
      <div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-start">
        <div className="flex min-w-0 items-start gap-4">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center border border-[#E5E2DC] bg-[#FAF9F6] text-[#A58A64]">
            <FileText size={19} />
          </div>

          <div className="min-w-0">
            <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
              {invoice.reference}
            </p>

            <h3 className="mt-2 break-words font-serif text-2xl text-[#171717]">
              {invoice.partyName}
            </h3>

            <p className="mt-2 text-xs text-[#77736C]">
              {invoice.partyType} invoice
              {invoice.projectName
                ? ` · ${invoice.projectName}`
                : ""}
            </p>
          </div>
        </div>

        <div className="flex flex-wrap gap-2 lg:justify-end">
          <span
            className={`px-3 py-2 text-[8px] uppercase tracking-widest ${approvalStatusStyle(invoice.status)}`}
          >
            {invoice.status}
          </span>

          {awaitingSecond && (
            <span className="bg-[#EAEFF5] px-3 py-2 text-[8px] uppercase tracking-widest text-[#526C8A]">
              Second approval required
            </span>
          )}
        </div>
      </div>

      <div className="mt-6 grid grid-cols-2 gap-4 border-t border-[#E5E2DC] pt-5 md:grid-cols-3">
        <Metric
          label="Invoice Amount"
          value={formatCurrency(invoice.invoiceAmount)}
        />

        <Metric
          label="Previously Approved"
          value={formatCurrency(invoice.previouslyApprovedAmount)}
        />

        <Metric
          label="Submitted"
          value={formatDate(invoice.submittedAt)}
        />
      </div>

      <div className="mt-6 flex flex-col justify-between gap-4 border-t border-[#E5E2DC] pt-5 sm:flex-row sm:items-center">
        <p className="text-[10px] text-[#77736C]">
          {invoice.approvalCount} of {invoice.requiredApprovalCount} approvals recorded
        </p>

        <button
          type="button"
          onClick={onReview}
          disabled={submitting}
          className="inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#987543] hover:text-[#171717] disabled:opacity-40"
        >
          Review Invoice
          <ArrowUpRight size={14} />
        </button>
      </div>
    </article>
  );
}

function Metric({
  label,
  value,
}: {
  label: string;
  value: string;
}) {
  return (
    <div className="min-w-0">
      <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
        {label}
      </p>

      <p className="mt-2 break-words text-sm text-[#33312D]">
        {value}
      </p>
    </div>
  );
}

function MoneyRow({
  label,
  value,
  strong = false,
}: {
  label: string;
  value: number;
  strong?: boolean;
}) {
  return (
    <div className="flex items-center justify-between gap-4">
      <p
        className={`text-xs ${
          strong
            ? "font-semibold text-[#171717]"
            : "text-[#77736C]"
        }`}
      >
        {label}
      </p>

      <p
        className={`text-right text-sm tabular-nums ${
          strong
            ? "font-semibold text-[#171717]"
            : "text-[#55514A]"
        }`}
      >
        {formatCurrency(value)}
      </p>
    </div>
  );
}

function DetailLine({
  icon,
  label,
  value,
}: {
  icon: ReactNode;
  label: string;
  value: string;
}) {
  return (
    <div className="flex min-w-0 items-start gap-3">
      <span className="mt-0.5 shrink-0 text-[#A58A64]">
        {icon}
      </span>

      <div className="min-w-0">
        <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
          {label}
        </p>

        <p className="mt-1 break-words text-xs text-[#55514A]">
          {value}
        </p>
      </div>
    </div>
  );
}

function SectionHeading({ children }: { children: ReactNode }) {
  return (
    <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
      {children}
    </p>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  Search,
  FileText,
  RefreshCw,
  ArrowUpRight,
  X,
  AlertCircle,
  CalendarDays,
  Building2,
  UserRound,
  IndianRupee,
  Download,
  Eye,
  Filter,
  Clock3,
  CheckCircle2,
} from "lucide-react";

export type AdminInvoicePartyType = "Client" | "Vendor";

export type AdminInvoiceStatus =
  | "Draft"
  | "Submitted"
  | "Under Review"
  | "Partially Approved"
  | "Approved"
  | "Rejected"
  | "Payment Processing"
  | "Partially Paid"
  | "Paid"
  | "Disputed"
  | "Cancelled";

export interface AdminInvoiceRecord {
  id: string;
  reference: string;
  partyType: AdminInvoicePartyType;
  partyId: string;
  partyName: string;
  projectId?: string;
  projectReference?: string;
  projectName?: string;
  invoiceDate: string;
  dueDate?: string;
  submittedAt?: string;
  currency: "INR";
  subtotal: number;
  taxAmount: number;
  totalAmount: number;
  approvedAmount?: number;
  paidAmount: number;
  outstandingAmount: number;
  status: AdminInvoiceStatus;
  description?: string;
  financeRemarks?: string;
  attachmentCount: number;
  lastUpdated: string;
}

export interface AdminInvoiceSummary {
  totalInvoices: number;
  submittedAmount: number;
  approvedAmount: number;
  paidAmount: number;
  outstandingAmount: number;
  pendingReviewCount: number;
}

interface AdminInvoiceManagementProps {
  invoices: AdminInvoiceRecord[];
  summary?: AdminInvoiceSummary;
  loading?: boolean;
  error?: string;
  updatingInvoiceId?: string;

  onRefresh?: () => void;
  onOpenInvoice?: (invoiceId: string) => void;
  onReviewInvoice?: (invoiceId: string) => void;
  onOpenParty?: (
    partyType: AdminInvoicePartyType,
    partyId: string
  ) => void;
  onOpenProject?: (projectId: string) => void;
  onDownloadAttachment?: (invoiceId: string) => void;
}

type StatusFilter = "All" | AdminInvoiceStatus;
type PartyFilter = "All" | AdminInvoicePartyType;

const INVOICE_STATUSES: AdminInvoiceStatus[] = [
  "Draft",
  "Submitted",
  "Under Review",
  "Partially Approved",
  "Approved",
  "Rejected",
  "Payment Processing",
  "Partially Paid",
  "Paid",
  "Disputed",
  "Cancelled",
];

function formatCurrency(value: number) {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 2,
  }).format(value);
}

function formatDate(value?: string) {
  if (!value) return "Not available";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  }).format(date);
}

function statusStyle(status: AdminInvoiceStatus) {
  switch (status) {
    case "Approved":
    case "Paid":
      return "bg-[#EAF1E8] text-[#547A51]";

    case "Submitted":
    case "Under Review":
    case "Payment Processing":
      return "bg-[#F4EFE2] text-[#94743F]";

    case "Partially Approved":
    case "Partially Paid":
      return "bg-[#EAEFF5] text-[#526C8A]";

    case "Rejected":
    case "Disputed":
      return "bg-[#F8EAE7] text-[#9A5147]";

    default:
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

function getBalancePercentage(invoice: AdminInvoiceRecord) {
  if (invoice.totalAmount <= 0) return 0;

  const paid = Math.max(
    0,
    Math.min(invoice.paidAmount, invoice.totalAmount)
  );

  return Math.round((paid / invoice.totalAmount) * 100);
}

function isValidMoney(value: number) {
  return Number.isFinite(value) && value >= 0;
}

export function AdminInvoiceManagement({
  invoices,
  summary,
  loading = false,
  error,
  updatingInvoiceId,
  onRefresh,
  onOpenInvoice,
  onReviewInvoice,
  onOpenParty,
  onOpenProject,
  onDownloadAttachment,
}: AdminInvoiceManagementProps) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] =
    useState<StatusFilter>("All");
  const [partyFilter, setPartyFilter] =
    useState<PartyFilter>("All");
  const [selectedInvoice, setSelectedInvoice] =
    useState<AdminInvoiceRecord | null>(null);

  const calculatedSummary = useMemo<AdminInvoiceSummary>(() => ({
    totalInvoices: invoices.length,

    submittedAmount: invoices.reduce(
      (total, invoice) => total + invoice.totalAmount,
      0
    ),

    approvedAmount: invoices.reduce(
      (total, invoice) =>
        total + (invoice.approvedAmount ?? 0),
      0
    ),

    paidAmount: invoices.reduce(
      (total, invoice) => total + invoice.paidAmount,
      0
    ),

    outstandingAmount: invoices.reduce(
      (total, invoice) =>
        total + invoice.outstandingAmount,
      0
    ),

    pendingReviewCount: invoices.filter(
      (invoice) =>
        invoice.status === "Submitted" ||
        invoice.status === "Under Review"
    ).length,
  }), [invoices]);

  const totals = summary ?? calculatedSummary;

  const filteredInvoices = useMemo(() => {
    const query = search.trim().toLowerCase();

    return invoices.filter((invoice) => {
      const matchesSearch =
        !query ||
        invoice.reference.toLowerCase().includes(query) ||
        invoice.partyName.toLowerCase().includes(query) ||
        invoice.partyId.toLowerCase().includes(query) ||
        (invoice.projectReference ?? "").toLowerCase().includes(query) ||
        (invoice.projectName ?? "").toLowerCase().includes(query) ||
        (invoice.description ?? "").toLowerCase().includes(query);

      const matchesStatus =
        statusFilter === "All" ||
        invoice.status === statusFilter;

      const matchesParty =
        partyFilter === "All" ||
        invoice.partyType === partyFilter;

      return matchesSearch && matchesStatus && matchesParty;
    });
  }, [invoices, search, statusFilter, partyFilter]);

  function clearFilters() {
    setSearch("");
    setStatusFilter("All");
    setPartyFilter("All");
  }

  function openInvoice(invoice: AdminInvoiceRecord) {
    setSelectedInvoice(invoice);
  }

  const hasFilters =
    Boolean(search) ||
    statusFilter !== "All" ||
    partyFilter !== "All";

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-9 md:px-10 md:py-12 lg:px-12">

      {/* Header */}
      <header className="flex flex-col justify-between gap-6 border-b border-[#D8D6D0] pb-8 md:flex-row md:items-end">
        <div>
          <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
            Administration / Finance
          </p>

          <h1 className="mt-4 font-serif text-4xl text-[#171717] md:text-5xl">
            Invoice Management
          </h1>

          <p className="mt-3 max-w-xl text-sm leading-7 text-[#77736C]">
            Review client and vendor invoices, monitor approval
            progress and track outstanding balances.
          </p>
        </div>

        {onRefresh && (
          <button
            type="button"
            onClick={onRefresh}
            disabled={loading}
            className="inline-flex w-fit items-center gap-2 border border-[#D8D6D0] bg-white px-5 py-3 text-[10px] uppercase tracking-widest text-[#55514A] hover:border-[#A58A64] disabled:opacity-50"
          >
            <RefreshCw size={14} />
            Refresh Invoices
          </button>
        )}
      </header>

      {error && (
        <div
          role="alert"
          className="mt-6 flex items-start gap-3 border border-[#E3C9C5] bg-[#FAF3F1] p-5"
        >
          <AlertCircle
            size={18}
            className="mt-0.5 shrink-0 text-[#9A5147]"
          />
          <p className="text-xs leading-6 text-[#805B55]">
            {error}
          </p>
        </div>
      )}

      {/* Financial Summary */}
      <section className="mt-9 grid grid-cols-1 gap-px border border-[#D8D6D0] bg-[#D8D6D0] sm:grid-cols-2 xl:grid-cols-5">
        <SummaryCard
          label="Invoice Records"
          value={totals.totalInvoices.toLocaleString("en-IN")}
          description="Total records"
        />

        <SummaryCard
          label="Invoice Value"
          value={formatCurrency(totals.submittedAmount)}
          description="Submitted invoice value"
        />

        <SummaryCard
          label="Approved Value"
          value={formatCurrency(totals.approvedAmount)}
          description="Approved invoice value"
        />

        <SummaryCard
          label="Payments Recorded"
          value={formatCurrency(totals.paidAmount)}
          description="Verified payment records"
        />

        <SummaryCard
          label="Outstanding Balance"
          value={formatCurrency(totals.outstandingAmount)}
          description="Reported outstanding value"
        />
      </section>

      {/* Review Queue */}
      <section className="mt-6 flex flex-col justify-between gap-4 border border-[#D8D6D0] bg-white p-5 md:flex-row md:items-center md:p-6">
        <div className="flex items-start gap-4">
          <div className="flex h-10 w-10 shrink-0 items-center justify-center bg-[#F4EFE2] text-[#94743F]">
            <Clock3 size={19} />
          </div>

          <div>
            <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
              Finance Review Queue
            </p>

            <p className="mt-2 font-serif text-2xl text-[#171717]">
              {totals.pendingReviewCount} invoices awaiting review
            </p>

            <p className="mt-1 text-[10px] leading-5 text-[#77736C]">
              Review eligibility and approval authority must be
              checked by the finance workflow.
            </p>
          </div>
        </div>

        <span className="inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#94743F]">
          <AlertCircle size={14} />
          Review required
        </span>
      </section>

      {/* Filters */}
      <section className="mt-10">
        <div className="relative">
          <Search
            size={17}
            className="absolute left-4 top-1/2 -translate-y-1/2 text-[#99958D]"
          />

          <input
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            placeholder="Search invoice, party, project or reference..."
            aria-label="Search invoices"
            className="h-12 w-full border border-[#D8D6D0] bg-white pl-11 pr-4 text-sm outline-none focus:border-[#A58A64]"
          />
        </div>

        <div className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-2">
          <FilterSelect
            label="Invoice Status"
            value={statusFilter}
            options={["All", ...INVOICE_STATUSES]}
            onChange={(value) =>
              setStatusFilter(value as StatusFilter)
            }
          />

          <FilterSelect
            label="Party Type"
            value={partyFilter}
            options={["All", "Client", "Vendor"]}
            onChange={(value) =>
              setPartyFilter(value as PartyFilter)
            }
          />
        </div>

        <div className="mt-4 flex flex-wrap items-center justify-between gap-3">
          <p className="text-xs text-[#77736C]">
            Showing {filteredInvoices.length} of {invoices.length} invoices
          </p>

          {hasFilters && (
            <button
              type="button"
              onClick={clearFilters}
              className="text-[9px] uppercase tracking-widest text-[#987543]"
            >
              Clear Filters
            </button>
          )}
        </div>
      </section>

      {/* Invoice Register */}
      <section className="mt-9">
        <div className="flex items-end justify-between border-b border-[#D8D6D0] pb-5">
          <div>
            <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
              Financial Records
            </p>

            <h2 className="mt-3 font-serif text-2xl text-[#171717]">
              Invoice Register
            </h2>
          </div>

          <p className="font-mono text-[9px] text-[#99958D]">
            {filteredInvoices.length} RECORDS
          </p>
        </div>

        {loading ? (
          <div className="flex min-h-64 items-center justify-center">
            <p className="font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
              Loading invoice records...
            </p>
          </div>
        ) : filteredInvoices.length === 0 ? (
          <div className="mt-5 border border-[#D8D6D0] bg-white px-6 py-16 text-center">
            <FileText
              size={28}
              strokeWidth={1.3}
              className="mx-auto text-[#A58A64]"
            />

            <h3 className="mt-5 font-serif text-2xl text-[#171717]">
              No invoices found
            </h3>

            <p className="mt-3 text-xs text-[#77736C]">
              No invoice records match your current search and filters.
            </p>
          </div>
        ) : (
          <div className="mt-5 space-y-3">
            {filteredInvoices.map((invoice) => (
              <InvoiceCard
                key={invoice.id}
                invoice={invoice}
                updating={updatingInvoiceId === invoice.id}
                onOpen={() => openInvoice(invoice)}
              />
            ))}
          </div>
        )}
      </section>

      {/* Invoice Details */}
      {selectedInvoice && (
        <div
          className="fixed inset-0 z-[60] flex justify-end bg-black/50"
          role="presentation"
          onMouseDown={(event) => {
            if (event.target === event.currentTarget) {
              setSelectedInvoice(null);
            }
          }}
        >
          <aside
            role="dialog"
            aria-modal="true"
            aria-labelledby="invoice-detail-title"
            className="flex h-full w-full max-w-2xl flex-col overflow-y-auto bg-[#F2F0EB] shadow-2xl"
          >
            <div className="sticky top-0 z-10 flex items-center justify-between border-b border-[#D8D6D0] bg-[#F2F0EB] px-6 py-5 md:px-8">
              <div>
                <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                  Invoice / {selectedInvoice.reference}
                </p>

                <h2
                  id="invoice-detail-title"
                  className="mt-2 font-serif text-2xl text-[#171717]"
                >
                  Invoice Details
                </h2>
              </div>

              <button
                type="button"
                onClick={() => setSelectedInvoice(null)}
                aria-label="Close invoice details"
                className="text-[#77736C]"
              >
                <X size={21} />
              </button>
            </div>

            <div className="flex-1 space-y-7 p-6 md:p-8">

              {/* Invoice Identity */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex h-12 w-12 shrink-0 items-center justify-center border border-[#E5E2DC] bg-[#FAF9F6] text-[#A58A64]">
                    <FileText size={20} />
                  </div>

                  <span
                    className={`px-3 py-2 text-[8px] uppercase tracking-widest ${statusStyle(selectedInvoice.status)}`}
                  >
                    {selectedInvoice.status}
                  </span>
                </div>

                <h3 className="mt-5 break-words font-serif text-3xl text-[#171717]">
                  {selectedInvoice.reference}
                </h3>

                <p className="mt-2 text-xs text-[#77736C]">
                  {selectedInvoice.partyType} invoice
                </p>

                <div className="mt-6 space-y-4 border-t border-[#E5E2DC] pt-5">
                  <DetailLine
                    icon={<Building2 size={15} />}
                    label="Invoice Party"
                    value={selectedInvoice.partyName}
                  />

                  <DetailLine
                    icon={<CalendarDays size={15} />}
                    label="Invoice Date"
                    value={formatDate(selectedInvoice.invoiceDate)}
                  />

                  <DetailLine
                    icon={<Clock3 size={15} />}
                    label="Due Date"
                    value={formatDate(selectedInvoice.dueDate)}
                  />

                  <DetailLine
                    icon={<CalendarDays size={15} />}
                    label="Last Updated"
                    value={formatDate(selectedInvoice.lastUpdated)}
                  />
                </div>

                {onOpenParty && (
                  <button
                    type="button"
                    onClick={() =>
                      onOpenParty(
                        selectedInvoice.partyType,
                        selectedInvoice.partyId
                      )
                    }
                    className="mt-6 inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#987543]"
                  >
                    Open {selectedInvoice.partyType} Record
                    <ArrowUpRight size={14} />
                  </button>
                )}
              </section>

              {/* Project */}
              {(selectedInvoice.projectId ||
                selectedInvoice.projectName) && (
                <section className="border border-[#D8D6D0] bg-white p-6">
                  <SectionHeading>Project Association</SectionHeading>

                  <h3 className="mt-3 font-serif text-xl text-[#171717]">
                    {selectedInvoice.projectName || "Project"}
                  </h3>

                  {selectedInvoice.projectReference && (
                    <p className="mt-2 font-mono text-[9px] text-[#A58A64]">
                      {selectedInvoice.projectReference}
                    </p>
                  )}

                  {selectedInvoice.projectId && onOpenProject && (
                    <button
                      type="button"
                      onClick={() =>
                        onOpenProject(selectedInvoice.projectId!)
                      }
                      className="mt-5 inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#987543]"
                    >
                      Open Project
                      <ArrowUpRight size={14} />
                    </button>
                  )}
                </section>
              )}

              {/* Financial Breakdown */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <SectionHeading>Financial Breakdown</SectionHeading>

                <div className="mt-5 space-y-4">
                  <MoneyRow
                    label="Subtotal"
                    value={selectedInvoice.subtotal}
                  />

                  <MoneyRow
                    label="Tax Amount"
                    value={selectedInvoice.taxAmount}
                  />

                  <div className="border-t border-[#E5E2DC] pt-4">
                    <MoneyRow
                      label="Invoice Total"
                      value={selectedInvoice.totalAmount}
                      strong
                    />
                  </div>

                  <MoneyRow
                    label="Approved Amount"
                    value={selectedInvoice.approvedAmount ?? 0}
                  />

                  <MoneyRow
                    label="Paid Amount"
                    value={selectedInvoice.paidAmount}
                  />

                  <div className="border-t border-[#E5E2DC] pt-4">
                    <MoneyRow
                      label="Outstanding Amount"
                      value={selectedInvoice.outstandingAmount}
                      strong
                    />
                  </div>
                </div>

                <div className="mt-6">
                  <div className="mb-2 flex items-center justify-between">
                    <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
                      Payment Progress
                    </p>

                    <p className="font-mono text-[9px] text-[#77736C]">
                      {getBalancePercentage(selectedInvoice)}%
                    </p>
                  </div>

                  <div
                    className="h-2 overflow-hidden bg-[#EAE7E0]"
                    role="progressbar"
                    aria-valuenow={getBalancePercentage(selectedInvoice)}
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-label="Invoice payment progress"
                  >
                    <div
                      className="h-full bg-[#A58A64]"
                      style={{
                        width: `${getBalancePercentage(selectedInvoice)}%`,
                      }}
                    />
                  </div>
                </div>
              </section>

              {/* Description and Finance Remarks */}
              {(selectedInvoice.description ||
                selectedInvoice.financeRemarks) && (
                <section className="border border-[#D8D6D0] bg-white p-6">
                  {selectedInvoice.description && (
                    <>
                      <SectionHeading>Invoice Description</SectionHeading>

                      <p className="mt-3 whitespace-pre-wrap text-xs leading-7 text-[#55514A]">
                        {selectedInvoice.description}
                      </p>
                    </>
                  )}

                  {selectedInvoice.financeRemarks && (
                    <div className="mt-6 border-t border-[#E5E2DC] pt-5">
                      <SectionHeading>Finance Remarks</SectionHeading>

                      <p className="mt-3 whitespace-pre-wrap text-xs leading-7 text-[#55514A]">
                        {selectedInvoice.financeRemarks}
                      </p>
                    </div>
                  )}
                </section>
              )}

              {/* Attachments */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <div className="flex items-center justify-between">
                  <SectionHeading>Invoice Attachments</SectionHeading>

                  <span className="font-mono text-[9px] text-[#99958D]">
                    {selectedInvoice.attachmentCount} FILES
                  </span>
                </div>

                <p className="mt-3 text-xs leading-6 text-[#77736C]">
                  Attachments are available only through the
                  authorised document service.
                </p>

                {selectedInvoice.attachmentCount > 0 &&
                  onDownloadAttachment && (
                    <button
                      type="button"
                      onClick={() =>
                        onDownloadAttachment(selectedInvoice.id)
                      }
                      className="mt-5 inline-flex items-center gap-2 border border-[#D8D6D0] px-5 py-3 text-[9px] uppercase tracking-widest text-[#55514A] hover:border-[#A58A64]"
                    >
                      <Download size={14} />
                      Access Attachments
                    </button>
                  )}
              </section>

              {/* Validation Warnings */}
              {!isValidMoney(selectedInvoice.totalAmount) ||
              !isValidMoney(selectedInvoice.paidAmount) ||
              !isValidMoney(selectedInvoice.outstandingAmount) ? (
                <div
                  role="alert"
                  className="border border-[#E3C9C5] bg-[#FAF3F1] p-4 text-xs leading-6 text-[#805B55]"
                >
                  The supplied invoice contains an invalid financial
                  value. Do not use these figures for financial
                  approval or payment decisions.
                </div>
              ) : null}
            </div>

            {/* Actions */}
            <div className="sticky bottom-0 border-t border-[#D8D6D0] bg-[#F2F0EB] p-5">
              <div className="flex flex-col-reverse gap-3 sm:flex-row">
                <button
                  type="button"
                  onClick={() => setSelectedInvoice(null)}
                  className="flex-1 border border-[#D8D6D0] px-5 py-4 text-[9px] uppercase tracking-widest text-[#77736C]"
                >
                  Close
                </button>

                {onOpenInvoice && (
                  <button
                    type="button"
                    onClick={() => onOpenInvoice(selectedInvoice.id)}
                    className="flex-1 border border-[#D8D6D0] bg-white px-5 py-4 text-[9px] uppercase tracking-widest text-[#55514A] hover:border-[#A58A64]"
                  >
                    Open Full Invoice
                  </button>
                )}

                {onReviewInvoice &&
                  (selectedInvoice.status === "Submitted" ||
                    selectedInvoice.status === "Under Review") && (
                    <button
                      type="button"
                      disabled={
                        updatingInvoiceId === selectedInvoice.id
                      }
                      onClick={() =>
                        onReviewInvoice(selectedInvoice.id)
                      }
                      className="flex-1 bg-[#171717] px-5 py-4 text-[9px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:opacity-40"
                    >
                      Review Invoice
                    </button>
                  )}
              </div>
            </div>
          </aside>
        </div>
      )}
    </main>
  );
}

function SummaryCard({
  label,
  value,
  description,
}: {
  label: string;
  value: string;
  description: string;
}) {
  return (
    <div className="bg-white p-5 md:p-6">
      <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
        {label}
      </p>

      <p className="mt-5 break-words font-serif text-2xl text-[#171717] md:text-3xl">
        {value}
      </p>

      <p className="mt-2 text-[9px] text-[#99958D]">
        {description}
      </p>
    </div>
  );
}

function InvoiceCard({
  invoice,
  updating,
  onOpen,
}: {
  invoice: AdminInvoiceRecord;
  updating: boolean;
  onOpen: () => void;
}) {
  return (
    <article className="border border-[#D8D6D0] bg-white p-5 md:p-7">
      <div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-start">
        <div className="flex min-w-0 items-start gap-4">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center border border-[#E5E2DC] bg-[#FAF9F6] text-[#A58A64]">
            <FileText size={19} />
          </div>

          <div className="min-w-0">
            <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
              {invoice.reference}
            </p>

            <h3 className="mt-2 break-words font-serif text-2xl text-[#171717]">
              {invoice.partyName}
            </h3>

            <p className="mt-2 text-xs text-[#77736C]">
              {invoice.partyType} invoice
              {invoice.projectName
                ? ` · ${invoice.projectName}`
                : ""}
            </p>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2 lg:justify-end">
          <span
            className={`px-3 py-2 text-[8px] uppercase tracking-widest ${statusStyle(invoice.status)}`}
          >
            {invoice.status}
          </span>

          {updating && (
            <span className="text-[8px] uppercase tracking-widest text-[#94743F]">
              Updating...
            </span>
          )}
        </div>
      </div>

      <div className="mt-6 grid grid-cols-2 gap-4 border-t border-[#E5E2DC] pt-5 md:grid-cols-4">
        <InvoiceMetric
          label="Invoice Total"
          value={formatCurrency(invoice.totalAmount)}
        />

        <InvoiceMetric
          label="Approved"
          value={formatCurrency(invoice.approvedAmount ?? 0)}
        />

        <InvoiceMetric
          label="Paid"
          value={formatCurrency(invoice.paidAmount)}
        />

        <InvoiceMetric
          label="Outstanding"
          value={formatCurrency(invoice.outstandingAmount)}
        />
      </div>

      <div className="mt-6 flex flex-col justify-between gap-4 border-t border-[#E5E2DC] pt-5 sm:flex-row sm:items-center">
        <div className="flex flex-wrap gap-x-6 gap-y-2 text-[10px] text-[#77736C]">
          <span>
            Invoice date: {formatDate(invoice.invoiceDate)}
          </span>

          <span>
            Due: {formatDate(invoice.dueDate)}
          </span>

          <span>
            {invoice.attachmentCount} attachments
          </span>
        </div>

        <button
          type="button"
          onClick={onOpen}
          className="inline-flex items-center gap-2 text-[9px] uppercase tracking-widest text-[#987543] hover:text-[#171717]"
        >
          Review Details
          <ArrowUpRight size={14} />
        </button>
      </div>
    </article>
  );
}

function InvoiceMetric({
  label,
  value,
}: {
  label: string;
  value: string;
}) {
  return (
    <div className="min-w-0">
      <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
        {label}
      </p>

      <p className="mt-2 break-words text-sm text-[#33312D]">
        {value}
      </p>
    </div>
  );
}

function MoneyRow({
  label,
  value,
  strong = false,
}: {
  label: string;
  value: number;
  strong?: boolean;
}) {
  return (
    <div className="flex items-center justify-between gap-4">
      <p
        className={`text-xs ${
          strong
            ? "font-semibold text-[#171717]"
            : "text-[#77736C]"
        }`}
      >
        {label}
      </p>

      <p
        className={`text-right text-sm tabular-nums ${
          strong
            ? "font-semibold text-[#171717]"
            : "text-[#55514A]"
        }`}
      >
        {formatCurrency(value)}
      </p>
    </div>
  );
}

function DetailLine({
  icon,
  label,
  value,
}: {
  icon: ReactNode;
  label: string;
  value: string;
}) {
  return (
    <div className="flex items-start gap-3">
      <span className="mt-0.5 shrink-0 text-[#A58A64]">
        {icon}
      </span>

      <div className="min-w-0">
        <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
          {label}
        </p>

        <p className="mt-1 break-all text-xs text-[#55514A]">
          {value}
        </p>
      </div>
    </div>
  );
}

function SectionHeading({ children }: { children: ReactNode }) {
  return (
    <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
      {children}
    </p>
  );
}

function FilterSelect({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: string;
  options: string[];
  onChange: (value: string) => void;
}) {
  return (
    <label className="block">
      <span className="mb-2 block font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
        {label}
      </span>

      <select
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="h-11 w-full border border-[#D8D6D0] bg-white px-3 text-xs outline-none focus:border-[#A58A64]"
      >
        {options.map((option) => (
          <option key={option} value={option}>
            {option === "All" ? `All ${label}` : option}
          </option>
        ))}
      </select>
    </label>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  Search,
  Users,
  Mail,
  Phone,
  CalendarDays,
  MapPin,
  ArrowUpRight,
  RefreshCw,
  X,
  AlertCircle,
  MessageSquare,
  UserRound,
  BriefcaseBusiness,
  Filter,
} from "lucide-react";

export type LeadStatus =
  | "New"
  | "Contacted"
  | "Qualified"
  | "Consultation Scheduled"
  | "Proposal Sent"
  | "Converted"
  | "Lost";

export type LeadPriority = "Low" | "Normal" | "High" | "Urgent";

export type LeadSource =
  | "Website"
  | "WhatsApp"
  | "Phone"
  | "Referral"
  | "Social Media"
  | "Other";

export interface AdminLeadRecord {
  id: string;
  reference: string;
  fullName: string;
  email: string;
  phone: string;
  serviceInterest: string;
  projectLocation?: string;
  projectDescription?: string;
  source: LeadSource;
  status: LeadStatus;
  priority: LeadPriority;
  assignedTo?: string;
  createdAt: string;
  lastContactedAt?: string;
  nextFollowUpAt?: string;
  consultationDate?: string;
  conversionProjectReference?: string;
}

export interface LeadAssignee {
  id: string;
  name: string;
  active: boolean;
}

interface AdminLeadManagementProps {
  leads: AdminLeadRecord[];
  assignees: LeadAssignee[];

  loading?: boolean;
  updatingLeadId?: string;
  error?: string;

  onRefresh?: () => void;

  onUpdateStatus: (
    leadId: string,
    status: LeadStatus
  ) => Promise<void>;

  onAssignLead: (
    leadId: string,
    assigneeId: string
  ) => Promise<void>;

  onUpdateFollowUp: (
    leadId: string,
    date: string | null
  ) => Promise<void>;

  onConvertLead: (
    leadId: string
  ) => Promise<void>;

  onOpenLead?: (leadId: string) => void;
}

type LeadStatusFilter = "All" | LeadStatus;

const STATUS_OPTIONS: LeadStatus[] = [
  "New",
  "Contacted",
  "Qualified",
  "Consultation Scheduled",
  "Proposal Sent",
  "Converted",
  "Lost",
];

const STATUS_FILTERS: LeadStatusFilter[] = [
  "All",
  ...STATUS_OPTIONS,
];

function formatDate(value?: string) {
  if (!value) return "Not scheduled";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  }).format(date);
}

function getStatusStyle(status: LeadStatus) {
  switch (status) {
    case "New":
      return "bg-[#EAF0F5] text-[#58738C]";
    case "Contacted":
      return "bg-[#F4EFE2] text-[#94743F]";
    case "Qualified":
      return "bg-[#EAF1E8] text-[#547A51]";
    case "Consultation Scheduled":
      return "bg-[#F0EAF5] text-[#765A91]";
    case "Proposal Sent":
      return "bg-[#E8EEF0] text-[#54737C]";
    case "Converted":
      return "bg-[#EAF1E8] text-[#547A51]";
    case "Lost":
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

function getPriorityStyle(priority: LeadPriority) {
  switch (priority) {
    case "Urgent":
      return "bg-[#F8EAE7] text-[#9A5147]";
    case "High":
      return "bg-[#F4EFE2] text-[#94743F]";
    default:
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

export function AdminLeadManagement({
  leads,
  assignees,
  loading = false,
  updatingLeadId,
  error,
  onRefresh,
  onUpdateStatus,
  onAssignLead,
  onUpdateFollowUp,
  onConvertLead,
  onOpenLead,
}: AdminLeadManagementProps) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] =
    useState<LeadStatusFilter>("All");
  const [priorityFilter, setPriorityFilter] =
    useState<"All" | LeadPriority>("All");
  const [sourceFilter, setSourceFilter] =
    useState<"All" | LeadSource>("All");

  const [selectedLead, setSelectedLead] =
    useState<AdminLeadRecord | null>(null);

  const [followUpDate, setFollowUpDate] = useState("");
  const [actionError, setActionError] = useState("");
  const [actionLoading, setActionLoading] = useState(false);

  const counts = useMemo(() => ({
    total: leads.length,
    new: leads.filter((lead) => lead.status === "New").length,
    qualified: leads.filter(
      (lead) => lead.status === "Qualified"
    ).length,
    scheduled: leads.filter(
      (lead) => lead.status === "Consultation Scheduled"
    ).length,
    converted: leads.filter(
      (lead) => lead.status === "Converted"
    ).length,
  }), [leads]);

  const filteredLeads = useMemo(() => {
    const query = search.trim().toLowerCase();

    return leads.filter((lead) => {
      const matchesSearch =
        !query ||
        lead.fullName.toLowerCase().includes(query) ||
        lead.reference.toLowerCase().includes(query) ||
        lead.email.toLowerCase().includes(query) ||
        lead.phone.toLowerCase().includes(query) ||
        lead.serviceInterest.toLowerCase().includes(query) ||
        (lead.projectLocation ?? "").toLowerCase().includes(query);

      const matchesStatus =
        statusFilter === "All" ||
        lead.status === statusFilter;

      const matchesPriority =
        priorityFilter === "All" ||
        lead.priority === priorityFilter;

      const matchesSource =
        sourceFilter === "All" ||
        lead.source === sourceFilter;

      return (
        matchesSearch &&
        matchesStatus &&
        matchesPriority &&
        matchesSource
      );
    });
  }, [leads, search, statusFilter, priorityFilter, sourceFilter]);

  const hasFilters =
    search.trim().length > 0 ||
    statusFilter !== "All" ||
    priorityFilter !== "All" ||
    sourceFilter !== "All";

  function clearFilters() {
    setSearch("");
    setStatusFilter("All");
    setPriorityFilter("All");
    setSourceFilter("All");
  }

  function openLead(lead: AdminLeadRecord) {
    setSelectedLead(lead);
    setFollowUpDate(
      lead.nextFollowUpAt
        ? lead.nextFollowUpAt.slice(0, 10)
        : ""
    );
    setActionError("");
  }

  async function runAction(action: () => Promise<void>) {
    if (actionLoading) return;

    setActionLoading(true);
    setActionError("");

    try {
      await action();
    } catch (err) {
      setActionError(
        err instanceof Error
          ? err.message
          : "The operation could not be completed."
      );
    } finally {
      setActionLoading(false);
    }
  }

  async function handleFollowUpSave() {
    if (!selectedLead) return;

    await runAction(async () => {
      await onUpdateFollowUp(
        selectedLead.id,
        followUpDate || null
      );
    });
  }

  async function handleConversion() {
    if (!selectedLead) return;

    if (
      !window.confirm(
        "Submit this lead for conversion? The backend must validate the conversion."
      )
    ) {
      return;
    }

    await runAction(async () => {
      await onConvertLead(selectedLead.id);
    });
  }

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-9 md:px-10 md:py-12 lg:px-12">

      {/* Header */}
      <header className="flex flex-col justify-between gap-6 border-b border-[#D8D6D0] pb-8 md:flex-row md:items-end">
        <div>
          <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
            Administration / CRM
          </p>

          <h1 className="mt-4 font-serif text-4xl text-[#171717] md:text-5xl">
            Enquiries & Leads
          </h1>

          <p className="mt-3 max-w-xl text-sm leading-7 text-[#77736C]">
            Manage incoming enquiries, consultation requests,
            follow-ups and potential client conversions.
          </p>
        </div>

        {onRefresh && (
          <button
            type="button"
            onClick={onRefresh}
            disabled={loading}
            className="inline-flex w-fit items-center gap-2 border border-[#D8D6D0] bg-white px-5 py-3 text-[10px] uppercase tracking-widest text-[#55514A] hover:border-[#A58A64] disabled:opacity-50"
          >
            <RefreshCw size={14} />
            Refresh Leads
          </button>
        )}
      </header>

      {/* Error */}
      {error && (
        <div
          role="alert"
          className="mt-6 flex items-start gap-3 border border-[#E3C9C5] bg-[#FAF3F1] p-5"
        >
          <AlertCircle
            size={18}
            className="mt-0.5 shrink-0 text-[#9A5147]"
          />
          <p className="text-xs leading-6 text-[#805B55]">
            {error}
          </p>
        </div>
      )}

      {/* Summary */}
      <section className="mt-9">
        <div className="grid grid-cols-2 gap-px border border-[#D8D6D0] bg-[#D8D6D0] lg:grid-cols-5">
          <SummaryCard label="Total Enquiries" value={counts.total} />
          <SummaryCard label="New" value={counts.new} />
          <SummaryCard label="Qualified" value={counts.qualified} />
          <SummaryCard label="Consultations" value={counts.scheduled} />
          <SummaryCard label="Converted" value={counts.converted} />
        </div>
      </section>

      {/* Search */}
      <section className="mt-10">
        <div className="relative">
          <Search
            size={17}
            className="absolute left-4 top-1/2 -translate-y-1/2 text-[#99958D]"
          />

          <input
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            placeholder="Search name, reference, email, phone or service..."
            aria-label="Search leads"
            className="h-12 w-full border border-[#D8D6D0] bg-white pl-11 pr-4 text-sm outline-none focus:border-[#A58A64]"
          />
        </div>

        <div className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-3">
          <FilterSelect
            label="Lead Status"
            value={statusFilter}
            onChange={(value) =>
              setStatusFilter(value as LeadStatusFilter)
            }
            options={STATUS_FILTERS.map((value) => ({
              value,
              label: value === "All" ? "All Statuses" : value,
            }))}
          />

          <FilterSelect
            label="Priority"
            value={priorityFilter}
            onChange={(value) =>
              setPriorityFilter(value as "All" | LeadPriority)
            }
            options={["All", "Low", "Normal", "High", "Urgent"].map(
              (value) => ({
                value,
                label: value === "All" ? "All Priorities" : value,
              })
            )}
          />

          <FilterSelect
            label="Source"
            value={sourceFilter}
            onChange={(value) =>
              setSourceFilter(value as "All" | LeadSource)
            }
            options={[
              "All",
              "Website",
              "WhatsApp",
              "Phone",
              "Referral",
              "Social Media",
              "Other",
            ].map((value) => ({
              value,
              label: value === "All" ? "All Sources" : value,
            }))}
          />
        </div>

        {hasFilters && (
          <div className="mt-4 flex items-center justify-between gap-3">
            <p className="text-xs text-[#77736C]">
              Showing {filteredLeads.length} of {leads.length} leads
            </p>

            <button
              type="button"
              onClick={clearFilters}
              className="text-[9px] uppercase tracking-widest text-[#987543]"
            >
              Clear Filters
            </button>
          </div>
        )}
      </section>

      {/* Lead Register */}
      <section className="mt-9">
        <div className="flex items-end justify-between border-b border-[#D8D6D0] pb-5">
          <div>
            <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
              CRM Records
            </p>

            <h2 className="mt-3 font-serif text-2xl text-[#171717]">
              Enquiry Register
            </h2>
          </div>

          <p className="font-mono text-[9px] text-[#99958D]">
            {filteredLeads.length} RECORDS
          </p>
        </div>

        {loading ? (
          <div className="flex min-h-64 items-center justify-center">
            <p className="font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
              Loading enquiries...
            </p>
          </div>
        ) : filteredLeads.length === 0 ? (
          <div className="mt-5 border border-[#D8D6D0] bg-white px-6 py-16 text-center">
            <Users
              size={28}
              strokeWidth={1.3}
              className="mx-auto text-[#A58A64]"
            />

            <h3 className="mt-5 font-serif text-2xl text-[#171717]">
              No enquiries found
            </h3>

            <p className="mt-3 text-xs text-[#77736C]">
              No records match the selected search and filters.
            </p>
          </div>
        ) : (
          <div className="mt-5 space-y-3">
            {filteredLeads.map((lead) => (
              <LeadCard
                key={lead.id}
                lead={lead}
                onOpen={() => openLead(lead)}
              />
            ))}
          </div>
        )}
      </section>

      {/* Lead Detail Drawer */}
      {selectedLead && (
        <div
          className="fixed inset-0 z-[60] flex justify-end bg-black/50"
          role="presentation"
          onMouseDown={(event) => {
            if (
              event.target === event.currentTarget &&
              !actionLoading
            ) {
              setSelectedLead(null);
            }
          }}
        >
          <aside
            role="dialog"
            aria-modal="true"
            aria-labelledby="lead-detail-title"
            className="flex h-full w-full max-w-2xl flex-col overflow-y-auto bg-[#F2F0EB] shadow-2xl"
          >
            <div className="sticky top-0 z-10 flex items-center justify-between border-b border-[#D8D6D0] bg-[#F2F0EB] px-6 py-5 md:px-8">
              <div>
                <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                  Lead Record / {selectedLead.reference}
                </p>

                <h2
                  id="lead-detail-title"
                  className="mt-2 font-serif text-2xl text-[#171717]"
                >
                  Enquiry Details
                </h2>
              </div>

              <button
                type="button"
                onClick={() => setSelectedLead(null)}
                disabled={actionLoading}
                aria-label="Close lead details"
                className="text-[#77736C] disabled:opacity-40"
              >
                <X size={21} />
              </button>
            </div>

            <div className="flex-1 space-y-7 p-6 md:p-8">

              {/* Contact Details */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                      Prospective Client
                    </p>

                    <h3 className="mt-3 font-serif text-2xl text-[#171717]">
                      {selectedLead.fullName}
                    </h3>
                  </div>

                  <span
                    className={`px-3 py-2 text-[8px] uppercase tracking-widest ${getStatusStyle(selectedLead.status)}`}
                  >
                    {selectedLead.status}
                  </span>
                </div>

                <div className="mt-6 space-y-4 border-t border-[#E5E2DC] pt-5">
                  <DetailLine
                    icon={<Mail size={15} />}
                    value={selectedLead.email}
                  />

                  <DetailLine
                    icon={<Phone size={15} />}
                    value={selectedLead.phone}
                  />

                  <DetailLine
                    icon={<BriefcaseBusiness size={15} />}
                    value={selectedLead.serviceInterest}
                  />

                  {selectedLead.projectLocation && (
                    <DetailLine
                      icon={<MapPin size={15} />}
                      value={selectedLead.projectLocation}
                    />
                  )}
                </div>

                {selectedLead.projectDescription && (
                  <div className="mt-6 border-t border-[#E5E2DC] pt-5">
                    <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
                      Project Description
                    </p>

                    <p className="mt-3 text-xs leading-7 text-[#55514A]">
                      {selectedLead.projectDescription}
                    </p>
                  </div>
                )}
              </section>

              {/* Lead Metadata */}
              <section>
                <SectionHeading>Enquiry Information</SectionHeading>

                <div className="mt-4 grid grid-cols-2 gap-3">
                  <MetadataCard
                    label="Source"
                    value={selectedLead.source}
                  />

                  <MetadataCard
                    label="Priority"
                    value={selectedLead.priority}
                  />

                  <MetadataCard
                    label="Received"
                    value={formatDate(selectedLead.createdAt)}
                  />

                  <MetadataCard
                    label="Last Contact"
                    value={formatDate(selectedLead.lastContactedAt)}
                  />
                </div>
              </section>

              {/* Assignment */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <SectionHeading>Lead Assignment</SectionHeading>

                <p className="mt-3 text-xs text-[#77736C]">
                  Current assignee: {selectedLead.assignedTo || "Unassigned"}
                </p>

                <label className="mt-5 block">
                  <span className="mb-2 block font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                    Assign To
                  </span>

                  <select
                    value={
                      assignees.find(
                        (person) => person.name === selectedLead.assignedTo
                      )?.id ?? ""
                    }
                    disabled={actionLoading}
                    onChange={(event) => {
                      const assigneeId = event.target.value;

                      if (!assigneeId) return;

                      void runAction(async () => {
                        await onAssignLead(
                          selectedLead.id,
                          assigneeId
                        );
                      });
                    }}
                    className="h-11 w-full border border-[#D8D6D0] bg-white px-3 text-xs outline-none focus:border-[#A58A64]"
                  >
                    <option value="">Select an assignee</option>

                    {assignees
                      .filter((person) => person.active)
                      .map((person) => (
                        <option key={person.id} value={person.id}>
                          {person.name}
                        </option>
                      ))}
                  </select>
                </label>
              </section>

              {/* Status */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <SectionHeading>Lead Progress</SectionHeading>

                <label className="mt-5 block">
                  <span className="mb-2 block font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                    Update Status
                  </span>

                  <select
                    value={selectedLead.status}
                    disabled={actionLoading}
                    onChange={(event) => {
                      const nextStatus = event.target.value as LeadStatus;

                      void runAction(async () => {
                        await onUpdateStatus(
                          selectedLead.id,
                          nextStatus
                        );
                      });
                    }}
                    className="h-11 w-full border border-[#D8D6D0] bg-white px-3 text-xs outline-none focus:border-[#A58A64]"
                  >
                    {STATUS_OPTIONS.map((status) => (
                      <option key={status} value={status}>
                        {status}
                      </option>
                    ))}
                  </select>
                </label>

                {selectedLead.status === "Converted" &&
                  selectedLead.conversionProjectReference && (
                    <p className="mt-4 text-xs text-[#547A51]">
                      Converted project:{" "}
                      {selectedLead.conversionProjectReference}
                    </p>
                  )}
              </section>

              {/* Follow-up */}
              <section className="border border-[#D8D6D0] bg-white p-6">
                <SectionHeading>Follow-up Schedule</SectionHeading>

                <p className="mt-3 text-xs text-[#77736C]">
                  Current follow-up:{" "}
                  {formatDate(selectedLead.nextFollowUpAt)}
                </p>

                <label className="mt-5 block">
                  <span className="mb-2 block font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                    Next Follow-up Date
                  </span>

                  <input
                    type="date"
                    value={followUpDate}
                    onChange={(event) =>
                      setFollowUpDate(event.target.value)
                    }
                    disabled={actionLoading}
                    className="h-11 w-full border border-[#D8D6D0] bg-white px-3 text-xs outline-none focus:border-[#A58A64]"
                  />
                </label>

                <button
                  type="button"
                  onClick={handleFollowUpSave}
                  disabled={actionLoading}
                  className="mt-4 bg-[#171717] px-6 py-3 text-[9px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:opacity-50"
                >
                  Save Follow-up
                </button>
              </section>

              {/* Consultation */}
              {selectedLead.consultationDate && (
                <section className="border border-[#D8D6D0] bg-white p-6">
                  <SectionHeading>Consultation</SectionHeading>

                  <p className="mt-4 flex items-center gap-3 text-xs text-[#55514A]">
                    <CalendarDays size={16} className="text-[#A58A64]" />
                    {formatDate(selectedLead.consultationDate)}
                  </p>
                </section>
              )}

              {/* Convert */}
              {selectedLead.status !== "Converted" &&
                selectedLead.status !== "Lost" && (
                  <section className="border border-[#D8D6D0] bg-white p-6">
                    <SectionHeading>Conversion</SectionHeading>

                    <p className="mt-3 text-xs leading-6 text-[#77736C]">
                      Convert this qualified enquiry into a client or
                      project through the authorised conversion workflow.
                    </p>

                    <button
                      type="button"
                      onClick={handleConversion}
                      disabled={actionLoading}
                      className="mt-5 bg-[#171717] px-6 py-3 text-[9px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:opacity-50"
                    >
                      {actionLoading
                        ? "Processing..."
                        : "Start Conversion"}
                    </button>
                  </section>
                )}

              {actionError && (
                <div
                  role="alert"
                  className="border border-[#E3C9C5] bg-[#FAF3F1] p-4 text-xs leading-6 text-[#805B55]"
                >
                  {actionError}
                </div>
              )}
            </div>

            <div className="sticky bottom-0 border-t border-[#D8D6D0] bg-[#F2F0EB] p-5">
              <div className="flex flex-col-reverse gap-3 sm:flex-row">
                <button
                  type="button"
                  onClick={() => setSelectedLead(null)}
                  className="flex-1 border border-[#D8D6D0] px-5 py-4 text-[9px] uppercase tracking-widest text-[#77736C]"
                >
                  Close
                </button>

                {onOpenLead && (
                  <button
                    type="button"
                    onClick={() => onOpenLead(selectedLead.id)}
                    className="flex-1 bg-[#171717] px-5 py-4 text-[9px] uppercase tracking-widest text-white hover:bg-[#A58A64]"
                  >
                    Open Full Record
                  </button>
                )}
              </div>
            </div>
          </aside>
        </div>
      )}
    </main>
  );
}

function SummaryCard({
  label,
  value,
}: {
  label: string;
  value: number;
}) {
  return (
    <div className="bg-white p-5 md:p-6">
      <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
        {label}
      </p>

      <p className="mt-5 font-serif text-3xl text-[#171717]">
        {value.toLocaleString("en-IN")}
      </p>
    </div>
  );
}

function LeadCard({
  lead,
  onOpen,
}: {
  lead: AdminLeadRecord;
  onOpen: () => void;
}) {
  return (
    <article className="border border-[#D8D6D0] bg-white p-5 md:p-7">
      <div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-start">
