import { useMemo, useState } from "react";
import type { ReactNode } from "react";
import {
  AlertTriangle,
  CalendarClock,
  CheckCircle2,
  Clock3,
  Plus,
  RefreshCw,
  Search,
  Server,
  X,
} from "lucide-react";

export type MaintenanceStatus =
  | "DRAFT"
  | "PENDING_APPROVAL"
  | "APPROVED"
  | "SCHEDULED"
  | "IN_PROGRESS"
  | "COMPLETED"
  | "CANCELLED"
  | "FAILED";

export type MaintenanceImpact =
  | "NO_EXPECTED_DOWNTIME"
  | "DEGRADED_SERVICE"
  | "PARTIAL_OUTAGE"
  | "FULL_OUTAGE"
  | "UNKNOWN";

export type MaintenanceRecord = {
  id: string;
  title: string;
  description: string;
  affectedServices: string[];
  impact: MaintenanceImpact;
  status: MaintenanceStatus;
  requestedBy: string;
  approvedBy?: string;
  scheduledStart: string;
  scheduledEnd: string;
  actualStart?: string;
  actualEnd?: string;
  notificationRequired: boolean;
  notificationStatus?: "NOT_SENT" | "SENT" | "FAILED" | "NOT_REQUIRED";
  updatedAt: string;
};

export type MaintenanceDraft = {
  title: string;
  description: string;
  affectedServices: string;
  impact: MaintenanceImpact;
  scheduledStart: string;
  scheduledEnd: string;
  notificationRequired: boolean;
};

type Props = {
  records: MaintenanceRecord[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onOpenRecord?: (record: MaintenanceRecord) => void;
  onCreateRecord?: (draft: MaintenanceDraft) => void;
  onReviewRecord?: (
    record: MaintenanceRecord,
    decision: "APPROVE" | "REJECT"
  ) => void;
  onUpdateStatus?: (
    record: MaintenanceRecord,
    status: MaintenanceStatus
  ) => void;
};

const statusStyles: Record<MaintenanceStatus, string> = {
  DRAFT: "bg-stone-100 text-stone-600",
  PENDING_APPROVAL: "bg-amber-50 text-amber-800",
  APPROVED: "bg-blue-50 text-blue-700",
  SCHEDULED: "bg-indigo-50 text-indigo-700",
  IN_PROGRESS: "bg-orange-50 text-orange-800",
  COMPLETED: "bg-emerald-50 text-emerald-700",
  CANCELLED: "bg-stone-100 text-stone-600",
  FAILED: "bg-red-50 text-red-700",
};

const impactStyles: Record<MaintenanceImpact, string> = {
  NO_EXPECTED_DOWNTIME: "bg-emerald-50 text-emerald-700",
  DEGRADED_SERVICE: "bg-amber-50 text-amber-800",
  PARTIAL_OUTAGE: "bg-orange-50 text-orange-800",
  FULL_OUTAGE: "bg-red-50 text-red-700",
  UNKNOWN: "bg-stone-100 text-stone-600",
};

const statusOptions: MaintenanceStatus[] = [
  "DRAFT",
  "PENDING_APPROVAL",
  "APPROVED",
  "SCHEDULED",
  "IN_PROGRESS",
  "COMPLETED",
  "CANCELLED",
  "FAILED",
];

function formatDate(value?: string) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function Badge({
  children,
  className,
}: {
  children: ReactNode;
  className: string;
}) {
  return (
    <span
      className={`inline-flex rounded-full px-2.5 py-1 text-[10px] font-semibold tracking-wide ${className}`}
    >
      {children}
    </span>
  );
}

function Metric({
  label,
  value,
  icon,
}: {
  label: string;
  value: number;
  icon: ReactNode;
}) {
  return (
    <div className="rounded-xl border border-stone-200 bg-white p-4">
      <div className="flex items-center justify-between">
        <span className="text-xs text-stone-500">{label}</span>
        <span className="text-stone-400">{icon}</span>
      </div>
      <p className="mt-3 text-2xl font-semibold">{value}</p>
    </div>
  );
}

const emptyDraft: MaintenanceDraft = {
  title: "",
  description: "",
  affectedServices: "",
  impact: "UNKNOWN",
  scheduledStart: "",
  scheduledEnd: "",
  notificationRequired: true,
};

export default function AdminMaintenanceManagementCenter({
  records,
  loading = false,
  error,
  onRefresh,
  onOpenRecord,
  onCreateRecord,
  onReviewRecord,
  onUpdateStatus,
}: Props) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("ALL");
  const [impactFilter, setImpactFilter] = useState("ALL");
  const [showForm, setShowForm] = useState(false);
  const [draft, setDraft] = useState<MaintenanceDraft>(emptyDraft);
  const [formError, setFormError] = useState("");

  const metrics = useMemo(
    () => ({
      total: records.length,
      awaitingApproval: records.filter(
        (item) => item.status === "PENDING_APPROVAL"
      ).length,
      upcoming: records.filter((item) => item.status === "SCHEDULED").length,
      inProgress: records.filter(
        (item) => item.status === "IN_PROGRESS"
      ).length,
    }),
    [records]
  );

  const filteredRecords = useMemo(() => {
    const query = search.trim().toLowerCase();

    return records.filter((record) => {
      const searchable = [
        record.id,
        record.title,
        record.description,
        record.requestedBy,
        record.approvedBy ?? "",
        ...record.affectedServices,
      ]
        .join(" ")
        .toLowerCase();

      return (
        (!query || searchable.includes(query)) &&
        (statusFilter === "ALL" || record.status === statusFilter) &&
        (impactFilter === "ALL" || record.impact === impactFilter)
      );
    });
  }, [records, search, statusFilter, impactFilter]);

  function updateDraft<K extends keyof MaintenanceDraft>(
    key: K,
    value: MaintenanceDraft[K]
  ) {
    setDraft((current) => ({ ...current, [key]: value }));
  }

  function submitDraft(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setFormError("");

    if (!draft.title.trim() || !draft.description.trim()) {
      setFormError("Title and description are required.");
      return;
    }

    if (!draft.scheduledStart || !draft.scheduledEnd) {
      setFormError("Both scheduled dates are required.");
      return;
    }

    const start = new Date(draft.scheduledStart).getTime();
    const end = new Date(draft.scheduledEnd).getTime();

    if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) {
      setFormError("The end time must be later than the start time.");
      return;
    }

    if (!onCreateRecord) {
      setFormError("Maintenance creation is not configured.");
      return;
    }

    onCreateRecord(draft);
    setDraft(emptyDraft);
    setShowForm(false);
  }

  return (
    <main className="min-h-screen bg-[#f7f6f3] px-4 py-6 text-stone-900 sm:px-6 lg:px-8">
      <div className="mx-auto max-w-7xl space-y-6">
        <header className="flex flex-col justify-between gap-4 md:flex-row md:items-center">
          <div>
            <p className="mb-2 flex items-center gap-2 text-xs text-stone-500">
              <Server size={14} />
              Administration / Maintenance
            </p>
            <h1 className="text-2xl font-semibold tracking-tight">
              Maintenance Management
            </h1>
            <p className="mt-1 text-sm text-stone-500">
              Coordinate planned maintenance, review service impact, and
              monitor execution records.
            </p>
          </div>

          <div className="flex flex-wrap gap-2">
            <button
              type="button"
              onClick={onRefresh}
              disabled={!onRefresh || loading}
              className="inline-flex items-center gap-2 rounded-lg border border-stone-300 bg-white px-4 py-2.5 text-sm font-medium hover:bg-stone-50 disabled:opacity-50"
            >
              <RefreshCw
                size={15}
                className={loading ? "animate-spin" : ""}
              />
              Refresh
            </button>

            <button
              type="button"
              onClick={() => {
                setFormError("");
                setShowForm(true);
              }}
              disabled={!onCreateRecord}
              className="inline-flex items-center gap-2 rounded-lg bg-stone-900 px-4 py-2.5 text-sm font-medium text-white hover:bg-stone-700 disabled:opacity-50"
            >
              <Plus size={15} />
              Plan maintenance
            </button>
          </div>
        </header>

        {error && (
          <div
            role="alert"
            className="flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
          >
            <AlertTriangle size={18} />
            {error}
          </div>
        )}

        <section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          <Metric
            label="Total records"
            value={metrics.total}
            icon={<CalendarClock size={18} />}
          />
          <Metric
            label="Awaiting approval"
            value={metrics.awaitingApproval}
            icon={<Clock3 size={18} />}
          />
          <Metric
            label="Scheduled"
            value={metrics.upcoming}
            icon={<CalendarClock size={18} />}
          />
          <Metric
            label="In progress"
            value={metrics.inProgress}
            icon={<RefreshCw size={18} />}
          />
        </section>

        <section className="rounded-xl border border-stone-200 bg-white">
          <div className="flex flex-col gap-3 border-b border-stone-200 p-4 lg:flex-row lg:items-center">
            <div className="relative flex-1">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400"
              />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search maintenance records..."
                className="w-full rounded-lg border border-stone-200 py-2.5 pl-9 pr-3 text-sm outline-none focus:border-stone-500"
              />
            </div>

            <select
              aria-label="Filter by status"
              value={statusFilter}
              onChange={(event) => setStatusFilter(event.target.value)}
              className="rounded-lg border border-stone-200 bg-white px-3 py-2.5 text-sm"
            >
              <option value="ALL">All statuses</option>
              {statusOptions.map((status) => (
                <option key={status} value={status}>
                  {status.replaceAll("_", " ")}
                </option>
              ))}
            </select>

            <select
              aria-label="Filter by service impact"
              value={impactFilter}
              onChange={(event) => setImpactFilter(event.target.value)}
              className="rounded-lg border border-stone-200 bg-white px-3 py-2.5 text-sm"
            >
              <option value="ALL">All impact levels</option>
              {Object.keys(impactStyles).map((impact) => (
                <option key={impact} value={impact}>
                  {impact.replaceAll("_", " ")}
                </option>
              ))}
            </select>
          </div>

          {loading ? (
            <div className="p-12 text-center text-sm text-stone-500">
              Loading maintenance records...
            </div>
          ) : filteredRecords.length === 0 ? (
            <div className="p-12 text-center">
              <CalendarClock
                size={28}
                className="mx-auto text-stone-300"
              />
              <p className="mt-3 text-sm font-medium">
                No maintenance records found
              </p>
              <p className="mt-1 text-xs text-stone-500">
                Try changing the filters or search terms.
              </p>
            </div>
          ) : (
            <div className="divide-y divide-stone-100">
              {filteredRecords.map((record) => (
                <article key={record.id} className="p-4 sm:p-5">
                  <div className="flex flex-col justify-between gap-4 xl:flex-row xl:items-start">
                    <div className="min-w-0 flex-1">
                      <div className="flex flex-wrap items-center gap-2">
                        <span className="font-mono text-xs text-stone-400">
                          {record.id}
                        </span>
                        <Badge className={statusStyles[record.status]}>
                          {record.status.replaceAll("_", " ")}
                        </Badge>
                        <Badge className={impactStyles[record.impact]}>
                          {record.impact.replaceAll("_", " ")}
                        </Badge>
                      </div>

                      <h2 className="mt-2 text-sm font-semibold">
                        {record.title}
                      </h2>
                      <p className="mt-1 max-w-3xl text-sm leading-6 text-stone-500">
                        {record.description}
                      </p>

                      <div className="mt-3 grid gap-2 text-xs text-stone-500 sm:grid-cols-2">
                        <p>
                          <span className="font-medium text-stone-700">
                            Scheduled start:
                          </span>{" "}
                          {formatDate(record.scheduledStart)}
                        </p>
                        <p>
                          <span className="font-medium text-stone-700">
                            Scheduled end:
                          </span>{" "}
                          {formatDate(record.scheduledEnd)}
                        </p>
                        <p>Requested by: {record.requestedBy}</p>
                        <p>Approved by: {record.approvedBy || "Not recorded"}</p>
                        <p>
                          Notification:{" "}
                          {record.notificationStatus || "Not recorded"}
                        </p>
                      </div>

                      {record.affectedServices.length > 0 && (
                        <div className="mt-3 flex flex-wrap gap-1.5">
                          {record.affectedServices.map((service) => (
                            <span
                              key={service}
                              className="rounded-md border border-stone-200 bg-white px-2 py-1 text-[10px] text-stone-600"
                            >
                              {service}
                            </span>
                          ))}
                        </div>
                      )}

                      {record.actualStart && (
                        <p className="mt-3 text-xs text-stone-500">
                          Actual start: {formatDate(record.actualStart)}
                        </p>
                      )}
                      {record.actualEnd && (
                        <p className="mt-1 text-xs text-stone-500">
                          Actual end: {formatDate(record.actualEnd)}
                        </p>
                      )}
                    </div>

                    <div className="flex flex-wrap items-center gap-2 xl:justify-end">
                      {record.status === "PENDING_APPROVAL" &&
                        onReviewRecord && (
                          <>
                            <button
                              type="button"
                              onClick={() =>
                                onReviewRecord(record, "REJECT")
                              }
                              className="rounded-lg border border-red-200 px-3 py-2 text-xs font-medium text-red-700 hover:bg-red-50"
                            >
                              Reject
                            </button>
                            <button
                              type="button"
                              onClick={() =>
                                onReviewRecord(record, "APPROVE")
                              }
                              className="rounded-lg bg-stone-900 px-3 py-2 text-xs font-medium text-white hover:bg-stone-700"
                            >
                              Approve
                            </button>
                          </>
                        )}

                      {onUpdateStatus && (
                        <select
                          aria-label={`Update status for ${record.id}`}
                          value={record.status}
                          onChange={(event) =>
                            onUpdateStatus(
                              record,
                              event.target.value as MaintenanceStatus
                            )
                          }
                          className="max-w-44 rounded-lg border border-stone-200 bg-white px-2 py-2 text-xs"
                        >
                          {statusOptions.map((status) => (
                            <option key={status} value={status}>
                              {status.replaceAll("_", " ")}
                            </option>
                          ))}
                        </select>
                      )}

                      <button
                        type="button"
                        onClick={() => onOpenRecord?.(record)}
                        disabled={!onOpenRecord}
                        className="rounded-lg border border-stone-200 px-3 py-2 text-xs font-medium hover:bg-stone-100 disabled:opacity-50"
                      >
                        View details
                      </button>
                    </div>
                  </div>
                </article>
              ))}
            </div>
          )}
        </section>

        <section className="rounded-xl border border-amber-200 bg-amber-50/60 p-4">
          <div className="flex items-start gap-3">
            <AlertTriangle
              size={19}
              className="mt-0.5 shrink-0 text-amber-800"
            />
            <div>
              <h2 className="text-sm font-semibold">
                Maintenance execution safeguards
              </h2>
              <p className="mt-1 text-xs leading-5 text-stone-600">
                Approval and scheduling do not execute maintenance. Confirm
                service ownership, impact, recovery arrangements, and
                communication requirements before any infrastructure action.
                Record actual start and end times from verified execution
                results.
              </p>
            </div>
          </div>
        </section>
      </div>

      {showForm && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4"
          onMouseDown={(event) => {
            if (event.target === event.currentTarget) {
              setShowForm(false);
            }
          }}
        >
          <section
            role="dialog"
            aria-modal="true"
            aria-labelledby="maintenance-dialog-title"
            className="max-h-[90vh] w-full max-w-xl overflow-y-auto rounded-2xl bg-white p-5 shadow-xl"
          >
            <div className="flex items-center justify-between">
              <div>
                <h2
                  id="maintenance-dialog-title"
                  className="text-lg font-semibold"
                >
                  Plan maintenance
                </h2>
                <p className="mt-1 text-xs text-stone-500">
                  Create a maintenance request for review.
                </p>
              </div>
              <button
                type="button"
                onClick={() => setShowForm(false)}
                aria-label="Close dialog"
                className="rounded-lg p-2 text-stone-500 hover:bg-stone-100"
              >
                <X size={18} />
              </button>
            </div>

            <form onSubmit={submitDraft} className="mt-5 space-y-4">
              <div>
                <label
                  htmlFor="maintenance-title"
                  className="mb-1.5 block text-xs font-medium"
                >
                  Maintenance title
                </label>
                <input
                  id="maintenance-title"
                  required
                  maxLength={160}
                  value={draft.title}
                  onChange={(event) =>
                    updateDraft("title", event.target.value)
                  }
                  className="w-full rounded-lg border border-stone-200 px-3 py-2.5 text-sm"
                />
              </div>

              <div>
                <label
                  htmlFor="maintenance-description"
                  className="mb-1.5 block text-xs font-medium"
                >
                  Description
                </label>
                <textarea
                  id="maintenance-description"
                  required
                  rows={3}
                  maxLength={4000}
                  value={draft.description}
                  onChange={(event) =>
                    updateDraft("description", event.target.value)
                  }
                  className="w-full rounded-lg border border-stone-200 px-3 py-2.5 text-sm"
                />
              </div>

              <div>
                <label
                  htmlFor="maintenance-services"
                  className="mb-1.5 block text-xs font-medium"
                >
                  Affected services
                </label>
                <input
                  id="maintenance-services"
                  value={draft.affectedServices}
                  onChange={(event) =>
                    updateDraft("affectedServices", event.target.value)
                  }
                  placeholder="Comma-separated service names"
                  className="w-full rounded-lg border border-stone-200 px-3 py-2.5 text-sm"
                />
              </div>

              <div>
                <label
                  htmlFor="maintenance-impact"
                  className="mb-1.5 block text-xs font-medium"
                >
                  Expected impact
                </label>
                <select
                  id="maintenance-impact"
                  value={draft.impact}
                  onChange={(event) =>
                    updateDraft(
                      "impact",
                      event.target.value as MaintenanceImpact
                    )
                  }
                  className="w-full rounded-lg border border-stone-200 bg-white px-3 py-2.5 text-sm"
                >
                  {Object.keys(impactStyles).map((impact) => (
                    <option key={impact} value={impact}>
                      {impact.replaceAll("_", " ")}
                    </option>
                  ))}
                </select>
              </div>

              <div className="grid gap-3 sm:grid-cols-2">
                <div>
                  <label
                    htmlFor="maintenance-start"
                    className="mb-1.5 block text-xs font-medium"
                  >
                    Scheduled start
                  </label>
                  <input
                    id="maintenance-start"
                    type="datetime-local"
                    required
                    value={draft.scheduledStart}
                    onChange={(event) =>
                      updateDraft("scheduledStart", event.target.value)
                    }
                    className="w-full rounded-lg border border-stone-200 px-3 py-2.5 text-sm"
                  />
                </div>

                <div>
                  <label
                    htmlFor="maintenance-end"
                    className="mb-1.5 block text-xs font-medium"
                  >
                    Scheduled end
                  </label>
                  <input
                    id="maintenance-end"
                    type="datetime-local"
                    required
                    value={draft.scheduledEnd}
                    onChange={(event) =>
                      updateDraft("scheduledEnd", event.target.value)
                    }
                    className="w-full rounded-lg border border-stone-200 px-3 py-2.5 text-sm"
                  />
                </div>
              </div>

              <label className="flex items-start gap-2 text-xs text-stone-600">
                <input
                  type="checkbox"
                  checked={draft.notificationRequired}
                  onChange={(event) =>
                    updateDraft("notificationRequired", event.target.checked)
                  }
                  className="mt-0.5"
                />
                A notification is required for this maintenance request.
              </label>

              {formError && (
                <p role="alert" className="text-xs text-red-700">
                  {formError}
                </p>
              )}

              <div className="flex justify-end gap-2 border-t border-stone-100 pt-4">
                <button
                  type="button"
                  onClick={() => setShowForm(false)}
                  className="rounded-lg border border-stone-200 px-4 py-2.5 text-sm font-medium"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={!onCreateRecord}
                  className="rounded-lg bg-stone-900 px-4 py-2.5 text-sm font-medium text-white hover:bg-stone-700 disabled:opacity-50"
                >
                  Submit request
                </button>
              </div>
            </form>
          </section>
        </div>
      )}
    </main>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  ArchiveX,
  Search,
  RefreshCw,
  AlertTriangle,
  Clock,
  ShieldAlert,
  FileSearch,
} from "lucide-react";

export type DeadLetterStatus =
  | "UNREVIEWED"
  | "UNDER_INVESTIGATION"
  | "RESOLVED"
  | "DISCARDED";

export type DeadLetterFailureCategory =
  | "PROVIDER_REJECTION"
  | "INVALID_RECIPIENT"
  | "AUTHENTICATION"
  | "TEMPLATE_ERROR"
  | "RETRY_EXHAUSTED"
  | "POLICY_BLOCK"
  | "UNKNOWN";

export interface DeadLetterRecord {
  id: string;
  notificationId: string;
  recipientId: string;
  recipientName: string;
  channel: "EMAIL" | "SMS" | "WHATSAPP" | "IN_APP";
  purpose: string;
  failureCategory: DeadLetterFailureCategory;
  failureCode?: string;
  failureReason: string;
  status: DeadLetterStatus;
  attemptCount: number;
  maximumAttempts: number;
  firstFailedAt: string;
  lastFailedAt: string;
  provider?: string;
  correlationId?: string;
  reviewedBy?: string;
  reviewedAt?: string;
  resolutionNote?: string;
}

interface AdminNotificationDeadLetterQueueCenterProps {
  records: DeadLetterRecord[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onViewNotification?: (notificationId: string) => void;
  onViewRecipient?: (recipientId: string) => void;
  onReview?: (record: DeadLetterRecord) => void;
  onResolve?: (record: DeadLetterRecord) => void;
  onDiscard?: (record: DeadLetterRecord) => void;
}

const statusStyles: Record<DeadLetterStatus, string> = {
  UNREVIEWED: "bg-red-50 text-red-700",
  UNDER_INVESTIGATION: "bg-amber-50 text-amber-800",
  RESOLVED: "bg-emerald-50 text-emerald-700",
  DISCARDED: "bg-slate-100 text-slate-600",
};

const categoryLabels: Record<DeadLetterFailureCategory, string> = {
  PROVIDER_REJECTION: "Provider rejection",
  INVALID_RECIPIENT: "Invalid recipient",
  AUTHENTICATION: "Authentication failure",
  TEMPLATE_ERROR: "Template error",
  RETRY_EXHAUSTED: "Retry limit reached",
  POLICY_BLOCK: "Policy block",
  UNKNOWN: "Unknown failure",
};

function formatDate(value?: string) {
  if (!value) return "Not available";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return "Invalid date";

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

export default function AdminNotificationDeadLetterQueueCenter({
  records,
  loading = false,
  error,
  onRefresh,
  onViewNotification,
  onViewRecipient,
  onReview,
  onResolve,
  onDiscard,
}: AdminNotificationDeadLetterQueueCenterProps) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<
    DeadLetterStatus | "ALL"
  >("ALL");
  const [categoryFilter, setCategoryFilter] = useState<
    DeadLetterFailureCategory | "ALL"
  >("ALL");

  const filteredRecords = useMemo(() => {
    const query = search.trim().toLowerCase();

    return records
      .filter((record) => {
        const searchable = [
          record.id,
          record.notificationId,
          record.recipientId,
          record.recipientName,
          record.channel,
          record.purpose,
          record.failureCode ?? "",
          record.failureReason,
          record.provider ?? "",
          record.correlationId ?? "",
          record.resolutionNote ?? "",
        ]
          .join(" ")
          .toLowerCase();

        return (
          (!query || searchable.includes(query)) &&
          (statusFilter === "ALL" ||
            record.status === statusFilter) &&
          (categoryFilter === "ALL" ||
            record.failureCategory === categoryFilter)
        );
      })
      .sort(
        (a, b) =>
          new Date(b.lastFailedAt).getTime() -
          new Date(a.lastFailedAt).getTime()
      );
  }, [records, search, statusFilter, categoryFilter]);

  const counts = useMemo(
    () => ({
      total: records.length,
      unreviewed: records.filter(
        (item) => item.status === "UNREVIEWED"
      ).length,
      investigating: records.filter(
        (item) => item.status === "UNDER_INVESTIGATION"
      ).length,
      resolved: records.filter(
        (item) => item.status === "RESOLVED"
      ).length,
      discarded: records.filter(
        (item) => item.status === "DISCARDED"
      ).length,
    }),
    [records]
  );

  return (
    <main className="space-y-7">
      <header className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center">
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-[#9b8358]">
            <ArchiveX size={15} />
            Communication reliability
          </div>

          <h1 className="text-2xl font-semibold tracking-tight text-[#25241f]">
            Dead-Letter Queue
          </h1>

          <p className="mt-1 max-w-2xl text-sm text-[#77736c]">
            Investigate notifications that could not be delivered
            after their permitted processing attempts.
          </p>
        </div>

        <button
          type="button"
          onClick={onRefresh}
          disabled={!onRefresh || loading}
          className="flex items-center gap-2 self-start rounded-lg border border-[#ded9cf] px-4 py-2.5 text-sm font-medium text-[#34322c] hover:bg-[#f8f6f1] disabled:opacity-50"
        >
          <RefreshCw size={15} />
          Refresh records
        </button>
      </header>

      {error && (
        <div
          role="alert"
          className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
        >
          {error}
        </div>
      )}

      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">
        {[
          {
            label: "Total records",
            value: counts.total,
            color: "text-[#292821]",
          },
          {
            label: "Unreviewed",
            value: counts.unreviewed,
            color: "text-red-700",
          },
          {
            label: "Under investigation",
            value: counts.investigating,
            color: "text-amber-700",
          },
          {
            label: "Resolved",
            value: counts.resolved,
            color: "text-emerald-700",
          },
          {
            label: "Discarded",
            value: counts.discarded,
            color: "text-slate-600",
          },
        ].map((item) => (
          <div
            key={item.label}
            className="rounded-xl border border-[#e9e5dd] bg-white p-5"
          >
            <p className="text-sm text-[#77736c]">{item.label}</p>
            <p className={`mt-3 text-3xl font-semibold ${item.color}`}>
              {item.value.toLocaleString("en-IN")}
            </p>
          </div>
        ))}
      </section>

      <section className="overflow-hidden rounded-xl border border-[#e9e5dd] bg-white">
        <div className="space-y-4 border-b border-[#eeeae3] p-5">
          <div>
            <h2 className="font-semibold text-[#292821]">
              Failed notification records
            </h2>
            <p className="mt-1 text-xs text-[#918c83]">
              Historical failures returned by the notification backend.
            </p>
          </div>

          <div className="grid gap-3 lg:grid-cols-3">
            <div className="relative">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#918c83]"
              />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search notification, recipient, error..."
                className="w-full rounded-lg border border-[#e5e0d7] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[#a58c5d]"
              />
            </div>

            <select
              value={statusFilter}
              onChange={(event) =>
                setStatusFilter(
                  event.target.value as DeadLetterStatus | "ALL"
                )
              }
              className="rounded-lg border border-[#e5e0d7] bg-white px-3 py-2.5 text-sm"
            >
              <option value="ALL">All review statuses</option>
              <option value="UNREVIEWED">Unreviewed</option>
              <option value="UNDER_INVESTIGATION">
                Under investigation
              </option>
              <option value="RESOLVED">Resolved</option>
              <option value="DISCARDED">Discarded</option>
            </select>

            <select
              value={categoryFilter}
              onChange={(event) =>
                setCategoryFilter(
                  event.target.value as
                    | DeadLetterFailureCategory
                    | "ALL"
                )
              }
              className="rounded-lg border border-[#e5e0d7] bg-white px-3 py-2.5 text-sm"
            >
              <option value="ALL">All failure categories</option>
              {Object.entries(categoryLabels).map(([value, label]) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>
          </div>
        </div>

        {loading ? (
          <div className="p-12 text-center text-sm text-[#77736c]">
            Loading dead-letter records...
          </div>
        ) : filteredRecords.length === 0 ? (
          <div className="p-12 text-center">
            <ArchiveX
              size={30}
              className="mx-auto text-[#b3aa9b]"
            />
            <p className="mt-3 font-medium text-[#34322c]">
              No matching failure records
            </p>
            <p className="mt-1 text-sm text-[#918c83]">
              Adjust the filters or refresh the records.
            </p>
          </div>
        ) : (
          <div className="divide-y divide-[#f0ede7]">
            {filteredRecords.map((record) => (
              <article key={record.id} className="space-y-4 p-5">
                <div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-start">
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2">
                      <h3 className="font-semibold text-[#34322c]">
                        {record.notificationId}
                      </h3>

                      <span
                        className={`rounded-full px-2.5 py-1 text-xs font-medium ${statusStyles[record.status]}`}
                      >
                        {record.status.replaceAll("_", " ")}
                      </span>

                      <span className="rounded-full bg-red-50 px-2.5 py-1 text-xs text-red-700">
                        {categoryLabels[record.failureCategory]}
                      </span>
                    </div>

                    <p className="mt-2 text-sm text-[#77736c]">
                      {record.failureReason}
                    </p>

                    <p className="mt-2 text-xs text-[#918c83]">
                      Dead-letter ID: {record.id}
                      {" · "}
                      Channel: {record.channel}
                    </p>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    <button
                      type="button"
                      onClick={() =>
                        onViewNotification?.(record.notificationId)
                      }
                      disabled={!onViewNotification}
                      className="rounded-lg border border-[#ded9cf] px-3 py-2 text-xs font-medium text-[#555148] hover:bg-[#f8f6f1] disabled:opacity-40"
                    >
                      View notification
                    </button>

                    {record.status === "UNREVIEWED" && (
                      <button
                        type="button"
                        onClick={() => onReview?.(record)}
                        disabled={!onReview}
                        className="rounded-lg bg-[#292821] px-3 py-2 text-xs font-medium text-white disabled:opacity-40"
                      >
                        Start review
                      </button>
                    )}

                    {record.status === "UNDER_INVESTIGATION" && (
                      <button
                        type="button"
                        onClick={() => onResolve?.(record)}
                        disabled={!onResolve}
                        className="rounded-lg border border-emerald-200 px-3 py-2 text-xs font-medium text-emerald-700 hover:bg-emerald-50 disabled:opacity-40"
                      >
                        Record resolution
                      </button>
                    )}

                    {record.status === "UNREVIEWED" && (
                      <button
                        type="button"
                        onClick={() => onDiscard?.(record)}
                        disabled={!onDiscard}
                        className="rounded-lg border border-red-200 px-3 py-2 text-xs font-medium text-red-700 hover:bg-red-50 disabled:opacity-40"
                      >
                        Discard
                      </button>
                    )}
                  </div>
                </div>

                <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Recipient
                    </p>
                    <button
                      type="button"
                      onClick={() =>
                        onViewRecipient?.(record.recipientId)
                      }
                      disabled={!onViewRecipient}
                      className="mt-1 text-left text-sm font-medium text-[#34322c] disabled:cursor-default"
                    >
                      {record.recipientName}
                    </button>
                    <p className="mt-1 text-xs text-[#918c83]">
                      {record.recipientId}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Attempts
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {record.attemptCount} / {record.maximumAttempts}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      First failure
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {formatDate(record.firstFailedAt)}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Latest failure
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {formatDate(record.lastFailedAt)}
                    </p>
                  </div>
                </div>

                <div className="flex flex-wrap items-center justify-between gap-3 border-t border-[#f0ede7] pt-3">
                  <div className="text-xs text-[#918c83]">
                    <p>
                      Provider: {record.provider || "Not available"}
                    </p>
                    {record.failureCode && (
                      <p className="mt-1">
                        Error code: {record.failureCode}
                      </p>
                    )}
                    {record.correlationId && (
                      <p className="mt-1 break-all font-mono text-[10px]">
                        Correlation ID: {record.correlationId}
                      </p>
                    )}
                  </div>

                  {record.reviewedAt && (
                    <div className="text-right text-xs text-[#918c83]">
                      <p>Reviewed by {record.reviewedBy || "Unknown"}</p>
                      <p className="mt-1">
                        {formatDate(record.reviewedAt)}
                      </p>
                    </div>
                  )}
                </div>

                {record.resolutionNote && (
                  <div className="rounded-lg border border-emerald-100 bg-emerald-50 p-3">
                    <p className="text-xs font-semibold text-emerald-800">
                      Resolution note
                    </p>
                    <p className="mt-1 text-xs leading-5 text-emerald-800">
                      {record.resolutionNote}
                    </p>
                  </div>
                )}
              </article>
            ))}
          </div>
        )}

        <footer className="border-t border-[#eeeae3] bg-[#faf9f6] px-5 py-3 text-xs text-[#918c83]">
          Showing {filteredRecords.length.toLocaleString("en-IN")} of{" "}
          {records.length.toLocaleString("en-IN")} supplied records.
        </footer>
      </section>

      <section className="grid gap-4 md:grid-cols-2">
        <div className="flex gap-3 rounded-xl border border-[#e9e5dd] bg-white p-4">
          <FileSearch
            size={19}
            className="mt-0.5 shrink-0 text-[#9b8358]"
          />
          <div>
            <h3 className="text-sm font-semibold text-[#34322c]">
              Investigate before retrying
            </h3>
            <p className="mt-1 text-xs leading-5 text-[#77736c]">
              Resolve invalid recipients, provider configuration,
              and template errors before considering a controlled
              resend operation.
            </p>
          </div>
        </div>

        <div className="flex gap-3 rounded-xl border border-[#e9e5dd] bg-white p-4">
          <Clock
            size={19}
            className="mt-0.5 shrink-0 text-[#9b8358]"
          />
          <div>
            <h3 className="text-sm font-semibold text-[#34322c]">
              Preserve failure history
            </h3>
            <p className="mt-1 text-xs leading-5 text-[#77736c]">
              Keep original attempts, provider responses, timestamps,
              and investigation decisions available for audit.
            </p>
          </div>
        </div>
      </section>

      <section className="flex gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4">
        <ShieldAlert
          size={19}
          className="mt-0.5 shrink-0 text-amber-700"
        />
        <div>
          <h3 className="text-sm font-semibold text-amber-900">
            A failed notification must not be blindly resent
          </h3>
          <p className="mt-1 text-xs leading-5 text-amber-800">
            Before any resend, the backend must recheck consent,
            opt-out status, recipient validity, invoice and dispute
            state, template approval, and idempotency. A resolved
            investigation does not automatically authorize delivery.
          </p>
        </div>
      </section>
    </main>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  Activity,
  AlertTriangle,
  CheckCircle2,
  Clock,
  Search,
  RefreshCw,
  ShieldAlert,
  Webhook,
} from "lucide-react";

export type ProviderWebhookStatus =
  | "RECEIVED"
  | "PROCESSED"
  | "DUPLICATE"
  | "FAILED"
  | "REJECTED"
  | "PENDING";

export type ProviderWebhookEventType =
  | "MESSAGE_ACCEPTED"
  | "MESSAGE_SENT"
  | "MESSAGE_DELIVERED"
  | "MESSAGE_READ"
  | "MESSAGE_FAILED"
  | "UNKNOWN";

export interface ProviderWebhookEvent {
  id: string;
  provider: string;
  providerEventId: string;
  eventType: ProviderWebhookEventType;
  status: ProviderWebhookStatus;
  notificationId?: string;
  receivedAt: string;
  processedAt?: string;
  signatureValid: boolean;
  duplicate: boolean;
  failureReason?: string;
  correlationId?: string;
  processingDurationMs?: number;
}

interface AdminNotificationProviderWebhookMonitorProps {
  events: ProviderWebhookEvent[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onViewNotification?: (notificationId: string) => void;
  onInspectEvent?: (event: ProviderWebhookEvent) => void;
  onRetryProcessing?: (event: ProviderWebhookEvent) => void;
}

const statusStyles: Record<ProviderWebhookStatus, string> = {
  RECEIVED: "bg-blue-50 text-blue-700",
  PROCESSED: "bg-emerald-50 text-emerald-700",
  DUPLICATE: "bg-slate-100 text-slate-600",
  FAILED: "bg-red-50 text-red-700",
  REJECTED: "bg-red-50 text-red-700",
  PENDING: "bg-amber-50 text-amber-800",
};

const eventLabels: Record<ProviderWebhookEventType, string> = {
  MESSAGE_ACCEPTED: "Message accepted",
  MESSAGE_SENT: "Message sent",
  MESSAGE_DELIVERED: "Message delivered",
  MESSAGE_READ: "Message read",
  MESSAGE_FAILED: "Message failed",
  UNKNOWN: "Unknown event",
};

function formatDate(value?: string) {
  if (!value) return "Not available";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return "Invalid date";

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

export default function AdminNotificationProviderWebhookMonitor({
  events,
  loading = false,
  error,
  onRefresh,
  onViewNotification,
  onInspectEvent,
  onRetryProcessing,
}: AdminNotificationProviderWebhookMonitorProps) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<
    ProviderWebhookStatus | "ALL"
  >("ALL");
  const [providerFilter, setProviderFilter] = useState("ALL");

  const providers = useMemo(
    () =>
      Array.from(
        new Set(events.map((event) => event.provider))
      ).sort(),
    [events]
  );

  const filteredEvents = useMemo(() => {
    const query = search.trim().toLowerCase();

    return events
      .filter((event) => {
        const searchable = [
          event.id,
          event.provider,
          event.providerEventId,
          event.notificationId ?? "",
          event.eventType,
          event.status,
          event.failureReason ?? "",
          event.correlationId ?? "",
        ]
          .join(" ")
          .toLowerCase();

        return (
          (!query || searchable.includes(query)) &&
          (statusFilter === "ALL" ||
            event.status === statusFilter) &&
          (providerFilter === "ALL" ||
            event.provider === providerFilter)
        );
      })
      .sort(
        (a, b) =>
          new Date(b.receivedAt).getTime() -
          new Date(a.receivedAt).getTime()
      );
  }, [events, search, statusFilter, providerFilter]);

  const summary = useMemo(
    () => ({
      total: events.length,
      processed: events.filter(
        (event) => event.status === "PROCESSED"
      ).length,
      failed: events.filter(
        (event) => event.status === "FAILED"
      ).length,
      rejected: events.filter(
        (event) => event.status === "REJECTED"
      ).length,
      duplicates: events.filter(
        (event) =>
          event.duplicate || event.status === "DUPLICATE"
      ).length,
      invalidSignatures: events.filter(
        (event) => !event.signatureValid
      ).length,
      pending: events.filter(
        (event) => event.status === "PENDING"
      ).length,
    }),
    [events]
  );

  return (
    <main className="space-y-7">
      <header className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center">
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-[#9b8358]">
            <Webhook size={15} />
            Notification infrastructure
          </div>

          <h1 className="text-2xl font-semibold tracking-tight text-[#25241f]">
            Provider Webhook Monitor
          </h1>

          <p className="mt-1 max-w-2xl text-sm text-[#77736c]">
            Monitor external delivery events and identify
            processing, verification, and reconciliation failures.
          </p>
        </div>

        <button
          type="button"
          onClick={onRefresh}
          disabled={!onRefresh || loading}
          className="flex items-center gap-2 self-start rounded-lg border border-[#ded9cf] px-4 py-2.5 text-sm font-medium text-[#34322c] hover:bg-[#f8f6f1] disabled:opacity-50"
        >
          <RefreshCw size={15} />
          Refresh events
        </button>
      </header>

      {error && (
        <div
          role="alert"
          className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
        >
          {error}
        </div>
      )}

      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {[
          {
            label: "Total events",
            value: summary.total,
            icon: Activity,
            color: "text-[#292821]",
          },
          {
            label: "Processed",
            value: summary.processed,
            icon: CheckCircle2,
            color: "text-emerald-700",
          },
          {
            label: "Processing failures",
            value: summary.failed,
            icon: AlertTriangle,
            color: "text-red-700",
          },
          {
            label: "Invalid signatures",
            value: summary.invalidSignatures,
            icon: ShieldAlert,
            color: "text-amber-700",
          },
        ].map((item) => {
          const Icon = item.icon;

          return (
            <div
              key={item.label}
              className="rounded-xl border border-[#e9e5dd] bg-white p-5"
            >
                <div className="flex items-center justify-between">
                  <p className="text-sm text-[#77736c]">
                    {item.label}
                  </p>
                  <Icon size={18} className={item.color} />
                </div>

                <p className={`mt-3 text-3xl font-semibold ${item.color}`}>
                  {item.value.toLocaleString("en-IN")}
                </p>
            </div>
          );
        })}
      </section>

      <section className="grid gap-4 sm:grid-cols-3">
        {[
          { label: "Pending", value: summary.pending },
          { label: "Rejected", value: summary.rejected },
          { label: "Duplicate events", value: summary.duplicates },
        ].map((item) => (
          <div
            key={item.label}
            className="rounded-xl border border-[#e9e5dd] bg-[#faf9f6] p-4"
          >
            <p className="text-xs text-[#918c83]">{item.label}</p>
            <p className="mt-2 text-xl font-semibold text-[#34322c]">
              {item.value.toLocaleString("en-IN")}
            </p>
          </div>
        ))}
      </section>

      <section className="overflow-hidden rounded-xl border border-[#e9e5dd] bg-white">
        <div className="space-y-4 border-b border-[#eeeae3] p-5">
          <div>
            <h2 className="font-semibold text-[#292821]">
              Incoming provider events
            </h2>
            <p className="mt-1 text-xs text-[#918c83]">
              Events supplied by the backend webhook-processing service.
            </p>
          </div>

          <div className="grid gap-3 lg:grid-cols-3">
            <div className="relative">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#918c83]"
              />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search event or notification ID..."
                className="w-full rounded-lg border border-[#e5e0d7] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[#a58c5d]"
              />
            </div>

            <select
              value={statusFilter}
              onChange={(event) =>
                setStatusFilter(
                  event.target.value as ProviderWebhookStatus | "ALL"
                )
              }
              className="rounded-lg border border-[#e5e0d7] bg-white px-3 py-2.5 text-sm"
            >
              <option value="ALL">All processing statuses</option>
              <option value="RECEIVED">Received</option>
              <option value="PROCESSED">Processed</option>
              <option value="PENDING">Pending</option>
              <option value="FAILED">Failed</option>
              <option value="REJECTED">Rejected</option>
              <option value="DUPLICATE">Duplicate</option>
            </select>

            <select
              value={providerFilter}
              onChange={(event) => setProviderFilter(event.target.value)}
              className="rounded-lg border border-[#e5e0d7] bg-white px-3 py-2.5 text-sm"
            >
              <option value="ALL">All providers</option>
              {providers.map((provider) => (
                <option key={provider} value={provider}>
                  {provider}
                </option>
              ))}
            </select>
          </div>
        </div>

        {loading ? (
          <div className="p-12 text-center text-sm text-[#77736c]">
            Loading provider events...
          </div>
        ) : filteredEvents.length === 0 ? (
          <div className="p-12 text-center">
            <Webhook
              size={30}
              className="mx-auto text-[#b3aa9b]"
            />
            <p className="mt-3 font-medium text-[#34322c]">
              No matching webhook events
            </p>
            <p className="mt-1 text-sm text-[#918c83]">
              Try changing the filters or refreshing the event list.
            </p>
          </div>
        ) : (
          <div className="divide-y divide-[#f0ede7]">
            {filteredEvents.map((event) => (
              <article key={event.id} className="space-y-4 p-5">
                <div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-start">
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2">
                      <h3 className="font-semibold text-[#34322c]">
                        {event.provider}
                      </h3>

                      <span
                        className={`rounded-full px-2.5 py-1 text-xs font-medium ${statusStyles[event.status]}`}
                      >
                        {event.status.replaceAll("_", " ")}
                      </span>

                      {event.duplicate && (
                        <span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs text-slate-600">
                          Duplicate detected
                        </span>
                      )}
                    </div>

                    <p className="mt-2 text-sm text-[#77736c]">
                      {eventLabels[event.eventType]}
                    </p>

                    <p className="mt-1 break-all font-mono text-xs text-[#918c83]">
                      Provider event: {event.providerEventId}
                    </p>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    {event.notificationId && (
                      <button
                        type="button"
                        onClick={() =>
                          onViewNotification?.(event.notificationId!)
                        }
                        disabled={!onViewNotification}
                        className="rounded-lg border border-[#ded9cf] px-3 py-2 text-xs font-medium text-[#555148] hover:bg-[#f8f6f1] disabled:opacity-40"
                      >
                        View notification
                      </button>
                    )}

                    <button
                      type="button"
                      onClick={() => onInspectEvent?.(event)}
                      disabled={!onInspectEvent}
                      className="rounded-lg bg-[#292821] px-3 py-2 text-xs font-medium text-white disabled:opacity-40"
                    >
                      Inspect event
                    </button>

                    {event.status === "FAILED" &&
                      event.signatureValid &&
                      !event.duplicate && (
                        <button
                          type="button"
                          onClick={() => onRetryProcessing?.(event)}
                          disabled={!onRetryProcessing}
                          className="rounded-lg border border-amber-200 px-3 py-2 text-xs font-medium text-amber-800 hover:bg-amber-50 disabled:opacity-40"
                        >
                          Retry processing
                        </button>
                      )}
                  </div>
                </div>

                <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Signature verification
                    </p>
                    <p
                      className={`mt-1 text-sm font-medium ${
                        event.signatureValid
                          ? "text-emerald-700"
                          : "text-red-700"
                      }`}
                    >
                      {event.signatureValid ? "Valid" : "Invalid"}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Received at
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {formatDate(event.receivedAt)}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Processed at
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {formatDate(event.processedAt)}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Processing duration
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {event.processingDurationMs == null
                        ? "Not available"
                        : `${event.processingDurationMs.toLocaleString("en-IN")} ms`}
                    </p>
                  </div>
                </div>

                {event.failureReason && (
                  <div className="flex gap-3 rounded-lg border border-red-100 bg-red-50 p-3">
                    <AlertTriangle
                      size={17}
                      className="mt-0.5 shrink-0 text-red-700"
                    />
                    <div>
                      <p className="text-xs font-semibold text-red-800">
                        Processing failure
                      </p>
                      <p className="mt-1 text-xs leading-5 text-red-800">
                        {event.failureReason}
                      </p>
                    </div>
                  </div>
                )}

                <div className="flex flex-wrap items-center justify-between gap-2 border-t border-[#f0ede7] pt-3 text-xs text-[#918c83]">
                  <span>Internal event ID: {event.id}</span>
                  {event.correlationId && (
                    <span className="break-all font-mono">
                      Correlation: {event.correlationId}
                    </span>
                  )}
                </div>
              </article>
            ))}
          </div>
        )}

        <footer className="border-t border-[#eeeae3] bg-[#faf9f6] px-5 py-3 text-xs text-[#918c83]">
          Showing {filteredEvents.length.toLocaleString("en-IN")} of{" "}
          {events.length.toLocaleString("en-IN")} supplied events.
        </footer>
      </section>

      <section className="flex gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4">
        <ShieldAlert
          size={19}
          className="mt-0.5 shrink-0 text-amber-700"
        />
        <div>
          <h3 className="text-sm font-semibold text-amber-900">
            Webhook security requirements
          </h3>
          <p className="mt-1 text-xs leading-5 text-amber-800">
            Verify provider signatures against the raw request body,
            enforce timestamp and replay protection, deduplicate using
            provider event IDs, and validate event-to-notification
            ownership. Never treat an unverified webhook as proof that
            an invoice has been paid.
          </p>
        </div>
      </section>
    </main>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  CalendarClock,
  Search,
  RefreshCw,
  Clock,
  CalendarDays,
  AlertTriangle,
  CheckCircle2,
  PauseCircle,
} from "lucide-react";

export type NotificationScheduleStatus =
  | "SCHEDULED"
  | "ACTIVE"
  | "PAUSED"
  | "COMPLETED"
  | "CANCELLED"
  | "FAILED";

export type NotificationRecurrence =
  | "ONCE"
  | "DAILY"
  | "WEEKLY"
  | "MONTHLY"
  | "CUSTOM";

export interface NotificationScheduleRecord {
  id: string;
  name: string;
  description: string;
  notificationPurpose: string;
  channel: "EMAIL" | "SMS" | "WHATSAPP" | "IN_APP";
  status: NotificationScheduleStatus;
  recurrence: NotificationRecurrence;
  timezone: string;
  nextRunAt?: string;
  lastRunAt?: string;
  createdAt: string;
  updatedAt: string;
  createdBy: string;
  templateId?: string;
  targetAudience: string;
  executionCount: number;
  failureCount: number;
}

interface AdminNotificationScheduleManagementCenterProps {
  schedules: NotificationScheduleRecord[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onView?: (schedule: NotificationScheduleRecord) => void;
  onEdit?: (schedule: NotificationScheduleRecord) => void;
  onChangeStatus?: (
    schedule: NotificationScheduleRecord,
    nextStatus: NotificationScheduleStatus
  ) => void;
}

const statusStyles: Record<NotificationScheduleStatus, string> = {
  SCHEDULED: "bg-blue-50 text-blue-700",
  ACTIVE: "bg-emerald-50 text-emerald-700",
  PAUSED: "bg-amber-50 text-amber-800",
  COMPLETED: "bg-slate-100 text-slate-700",
  CANCELLED: "bg-zinc-100 text-zinc-600",
  FAILED: "bg-red-50 text-red-700",
};

const recurrenceLabels: Record<NotificationRecurrence, string> = {
  ONCE: "One time",
  DAILY: "Daily",
  WEEKLY: "Weekly",
  MONTHLY: "Monthly",
  CUSTOM: "Custom recurrence",
};

function formatDate(value?: string) {
  if (!value) return "Not available";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return "Invalid date";

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

export default function AdminNotificationScheduleManagementCenter({
  schedules,
  loading = false,
  error,
  onRefresh,
  onView,
  onEdit,
  onChangeStatus,
}: AdminNotificationScheduleManagementCenterProps) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<
    NotificationScheduleStatus | "ALL"
  >("ALL");
  const [recurrenceFilter, setRecurrenceFilter] = useState<
    NotificationRecurrence | "ALL"
  >("ALL");

  const filteredSchedules = useMemo(() => {
    const query = search.trim().toLowerCase();

    return schedules
      .filter((schedule) => {
        const searchable = [
          schedule.id,
          schedule.name,
          schedule.description,
          schedule.notificationPurpose,
          schedule.channel,
          schedule.createdBy,
          schedule.targetAudience,
          schedule.timezone,
          schedule.templateId ?? "",
        ]
          .join(" ")
          .toLowerCase();

        return (
          (!query || searchable.includes(query)) &&
          (statusFilter === "ALL" ||
            schedule.status === statusFilter) &&
          (recurrenceFilter === "ALL" ||
            schedule.recurrence === recurrenceFilter)
        );
      })
      .sort((a, b) => {
        const aTime = a.nextRunAt
          ? new Date(a.nextRunAt).getTime()
          : Number.MAX_SAFE_INTEGER;

        const bTime = b.nextRunAt
          ? new Date(b.nextRunAt).getTime()
          : Number.MAX_SAFE_INTEGER;

        return aTime - bTime;
      });
  }, [schedules, search, statusFilter, recurrenceFilter]);

  const counts = useMemo(
    () => ({
      scheduled: schedules.filter(
        (item) => item.status === "SCHEDULED"
      ).length,
      active: schedules.filter(
        (item) => item.status === "ACTIVE"
      ).length,
      paused: schedules.filter(
        (item) => item.status === "PAUSED"
      ).length,
      failed: schedules.filter(
        (item) => item.status === "FAILED"
      ).length,
    }),
    [schedules]
  );

  return (
    <main className="space-y-7">
      <header className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center">
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-[#9b8358]">
            <CalendarClock size={15} />
            Communication operations
          </div>

          <h1 className="text-2xl font-semibold tracking-tight text-[#25241f]">
            Notification Schedule Management
          </h1>

          <p className="mt-1 max-w-2xl text-sm text-[#77736c]">
            Review scheduled communication jobs, recurring reminders,
            execution history, and scheduling ownership.
          </p>
        </div>

        <button
          type="button"
          onClick={onRefresh}
          disabled={!onRefresh || loading}
          className="flex items-center gap-2 self-start rounded-lg border border-[#ded9cf] px-4 py-2.5 text-sm font-medium text-[#34322c] hover:bg-[#f8f6f1] disabled:opacity-50"
        >
          <RefreshCw size={15} />
          Refresh schedules
        </button>
      </header>

      {error && (
        <div
          role="alert"
          className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
        >
          {error}
        </div>
      )}

      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {[
          {
            label: "Scheduled",
            value: counts.scheduled,
            color: "text-blue-700",
            icon: CalendarDays,
          },
          {
            label: "Active",
            value: counts.active,
            color: "text-emerald-700",
            icon: CheckCircle2,
          },
          {
            label: "Paused",
            value: counts.paused,
            color: "text-amber-700",
            icon: PauseCircle,
          },
          {
            label: "Failed",
            value: counts.failed,
            color: "text-red-700",
            icon: AlertTriangle,
          },
        ].map((item) => {
          const Icon = item.icon;

          return (
            <div
              key={item.label}
              className="rounded-xl border border-[#e9e5dd] bg-white p-5"
            >
              <div className="flex items-center justify-between">
                <p className="text-sm text-[#77736c]">{item.label}</p>
                <Icon size={17} className={item.color} />
              </div>

              <p className={`mt-3 text-3xl font-semibold ${item.color}`}>
                {item.value.toLocaleString("en-IN")}
              </p>
            </div>
          );
        })}
      </section>

      <section className="overflow-hidden rounded-xl border border-[#e9e5dd] bg-white">
        <div className="space-y-4 border-b border-[#eeeae3] p-5">
          <div>
            <h2 className="font-semibold text-[#292821]">
              Scheduled jobs
            </h2>

            <p className="mt-1 text-xs text-[#918c83]">
              Times are displayed using the supplied timezone
              information from each schedule.
            </p>
          </div>

          <div className="grid gap-3 lg:grid-cols-3">
            <div className="relative">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#918c83]"
              />

              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search schedules..."
                className="w-full rounded-lg border border-[#e5e0d7] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[#a58c5d]"
              />
            </div>

            <select
              value={statusFilter}
              onChange={(event) =>
                setStatusFilter(
                  event.target.value as
                    | NotificationScheduleStatus
                    | "ALL"
                )
              }
              className="rounded-lg border border-[#e5e0d7] bg-white px-3 py-2.5 text-sm"
            >
              <option value="ALL">All statuses</option>
              <option value="SCHEDULED">Scheduled</option>
              <option value="ACTIVE">Active</option>
              <option value="PAUSED">Paused</option>
              <option value="COMPLETED">Completed</option>
              <option value="CANCELLED">Cancelled</option>
              <option value="FAILED">Failed</option>
            </select>

            <select
              value={recurrenceFilter}
              onChange={(event) =>
                setRecurrenceFilter(
                  event.target.value as
                    | NotificationRecurrence
                    | "ALL"
                )
              }
              className="rounded-lg border border-[#e5e0d7] bg-white px-3 py-2.5 text-sm"
            >
              <option value="ALL">All recurrence types</option>
              <option value="ONCE">One time</option>
              <option value="DAILY">Daily</option>
              <option value="WEEKLY">Weekly</option>
              <option value="MONTHLY">Monthly</option>
              <option value="CUSTOM">Custom</option>
            </select>
          </div>
        </div>

        {loading ? (
          <div className="p-12 text-center text-sm text-[#77736c]">
            Loading notification schedules...
          </div>
        ) : filteredSchedules.length === 0 ? (
          <div className="p-12 text-center">
            <CalendarClock
              size={30}
              className="mx-auto text-[#b3aa9b]"
            />

            <p className="mt-3 font-medium text-[#34322c]">
              No matching schedules
            </p>

            <p className="mt-1 text-sm text-[#918c83]">
              Adjust your filters or refresh the schedule list.
            </p>
          </div>
        ) : (
          <div className="divide-y divide-[#f0ede7]">
            {filteredSchedules.map((schedule) => (
              <article
                key={schedule.id}
                className="space-y-4 p-5"
              >
                <div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-start">
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2">
                      <h3 className="font-semibold text-[#34322c]">
                        {schedule.name}
                      </h3>

                      <span
                        className={`rounded-full px-2.5 py-1 text-xs font-medium ${statusStyles[schedule.status]}`}
                      >
                        {schedule.status}
                      </span>

                      <span className="rounded-full bg-[#f3f1ec] px-2.5 py-1 text-xs text-[#666157]">
                        {recurrenceLabels[schedule.recurrence]}
                      </span>
                    </div>

                    <p className="mt-2 text-sm leading-6 text-[#77736c]">
                      {schedule.description}
                    </p>

                    <p className="mt-2 text-xs text-[#918c83]">
                      Schedule ID: {schedule.id}
                    </p>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    <button
                      type="button"
                      onClick={() => onView?.(schedule)}
                      disabled={!onView}
                      className="rounded-lg border border-[#ded9cf] px-3 py-2 text-xs font-medium text-[#555148] hover:bg-[#f8f6f1] disabled:opacity-40"
                    >
                      View details
                    </button>

                    <button
                      type="button"
                      onClick={() => onEdit?.(schedule)}
                      disabled={
                        !onEdit ||
                        schedule.status === "COMPLETED" ||
                        schedule.status === "CANCELLED"
                      }
                      className="rounded-lg border border-[#ded9cf] px-3 py-2 text-xs font-medium text-[#555148] hover:bg-[#f8f6f1] disabled:opacity-40"
                    >
                      Edit schedule
                    </button>

                    {schedule.status === "ACTIVE" ||
                    schedule.status === "SCHEDULED" ? (
                      <button
                        type="button"
                        onClick={() =>
                          onChangeStatus?.(schedule, "PAUSED")
                        }
                        disabled={!onChangeStatus}
                        className="rounded-lg border border-amber-200 px-3 py-2 text-xs font-medium text-amber-800 hover:bg-amber-50 disabled:opacity-40"
                      >
                        Pause
                      </button>
                    ) : schedule.status === "PAUSED" ? (
                      <button
                        type="button"
                        onClick={() =>
                          onChangeStatus?.(schedule, "ACTIVE")
                        }
                        disabled={!onChangeStatus}
                        className="rounded-lg bg-[#292821] px-3 py-2 text-xs font-medium text-white disabled:opacity-40"
                      >
                        Resume
                      </button>
                    ) : null}
                  </div>
                </div>

                <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Next execution
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {formatDate(schedule.nextRunAt)}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Last execution
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {formatDate(schedule.lastRunAt)}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Execution count
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {schedule.executionCount.toLocaleString("en-IN")}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Failure count
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {schedule.failureCount.toLocaleString("en-IN")}
                    </p>
                  </div>
                </div>

                <div className="grid gap-3 md:grid-cols-3">
                  <div>
                    <p className="text-xs font-semibold uppercase tracking-wider text-[#918c83]">
                      Channel
                    </p>
                    <p className="mt-1 text-sm text-[#555148]">
                      {schedule.channel}
                    </p>
                  </div>

                  <div>
                    <p className="text-xs font-semibold uppercase tracking-wider text-[#918c83]">
                      Target audience
                    </p>
                    <p className="mt-1 text-sm text-[#555148]">
                      {schedule.targetAudience}
                    </p>
                  </div>

                  <div>
                    <p className="text-xs font-semibold uppercase tracking-wider text-[#918c83]">
                      Timezone
                    </p>
                    <p className="mt-1 text-sm text-[#555148]">
                      {schedule.timezone}
                    </p>
                  </div>
                </div>

                <div className="flex flex-wrap items-center justify-between gap-2 border-t border-[#f0ede7] pt-3 text-xs text-[#918c83]">
                  <span>
                    Created by {schedule.createdBy}
                  </span>

                  <span>
                    Updated {formatDate(schedule.updatedAt)}
                  </span>

                  {schedule.templateId && (
                    <span>
                      Template: {schedule.templateId}
                    </span>
                  )}
                </div>
              </article>
            ))}
          </div>
        )}

        <footer className="border-t border-[#eeeae3] bg-[#faf9f6] px-5 py-3 text-xs text-[#918c83]">
          Showing {filteredSchedules.length.toLocaleString("en-IN")} of{" "}
          {schedules.length.toLocaleString("en-IN")} supplied schedules.
        </footer>
      </section>

      <section className="flex gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4">
        <AlertTriangle
          size={19}
          className="mt-0.5 shrink-0 text-amber-700"
        />

        <div>
          <h3 className="text-sm font-semibold text-amber-900">
            Scheduling requires server-side safeguards
          </h3>

          <p className="mt-1 text-xs leading-5 text-amber-800">
            The backend must handle timezone-aware execution,
            duplicate prevention, schedule versioning, retry
            behavior, consent checks, and payment-state validation.
            A paused schedule must not leave already queued messages
            eligible for delivery without revalidation.
          </p>
        </div>
      </section>
    </main>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  ShieldAlert,
  Search,
  Plus,
  RefreshCw,
  Clock,
  Ban,
  CheckCircle2,
  AlertTriangle,
  Settings2,
} from "lucide-react";

export type SuppressionRuleStatus = "ACTIVE" | "INACTIVE" | "DRAFT";

export type SuppressionRuleCategory =
  | "CONSENT"
  | "QUIET_HOURS"
  | "PAYMENT"
  | "DISPUTE"
  | "FREQUENCY"
  | "ACCOUNT"
  | "CUSTOM";

export interface NotificationSuppressionRule {
  id: string;
  name: string;
  description: string;
  category: SuppressionRuleCategory;
  status: SuppressionRuleStatus;
  applicableChannels: string[];
  applicablePurposes: string[];
  priority: number;
  createdAt: string;
  updatedAt: string;
  updatedBy: string;
  lastTriggeredAt?: string;
  triggerCount?: number;
}

interface AdminNotificationSuppressionRulesCenterProps {
  rules: NotificationSuppressionRule[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onCreate?: () => void;
  onView?: (rule: NotificationSuppressionRule) => void;
  onEdit?: (rule: NotificationSuppressionRule) => void;
  onChangeStatus?: (
    rule: NotificationSuppressionRule,
    nextStatus: SuppressionRuleStatus
  ) => void;
}

const categoryLabels: Record<SuppressionRuleCategory, string> = {
  CONSENT: "Consent and opt-out",
  QUIET_HOURS: "Quiet hours",
  PAYMENT: "Payment state",
  DISPUTE: "Dispute state",
  FREQUENCY: "Frequency limit",
  ACCOUNT: "Account restrictions",
  CUSTOM: "Custom rule",
};

const categoryStyles: Record<SuppressionRuleCategory, string> = {
  CONSENT: "bg-red-50 text-red-700",
  QUIET_HOURS: "bg-blue-50 text-blue-700",
  PAYMENT: "bg-emerald-50 text-emerald-700",
  DISPUTE: "bg-orange-50 text-orange-700",
  FREQUENCY: "bg-violet-50 text-violet-700",
  ACCOUNT: "bg-slate-100 text-slate-700",
  CUSTOM: "bg-amber-50 text-amber-800",
};

const statusStyles: Record<SuppressionRuleStatus, string> = {
  ACTIVE: "bg-emerald-50 text-emerald-700",
  INACTIVE: "bg-slate-100 text-slate-600",
  DRAFT: "bg-amber-50 text-amber-800",
};

function formatDate(value?: string) {
  if (!value) return "Not available";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return "Invalid date";

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

export default function AdminNotificationSuppressionRulesCenter({
  rules,
  loading = false,
  error,
  onRefresh,
  onCreate,
  onView,
  onEdit,
  onChangeStatus,
}: AdminNotificationSuppressionRulesCenterProps) {
  const [search, setSearch] = useState("");
  const [categoryFilter, setCategoryFilter] = useState<
    SuppressionRuleCategory | "ALL"
  >("ALL");
  const [statusFilter, setStatusFilter] = useState<
    SuppressionRuleStatus | "ALL"
  >("ALL");

  const filteredRules = useMemo(() => {
    const query = search.trim().toLowerCase();

    return rules
      .filter((rule) => {
        const searchable = [
          rule.id,
          rule.name,
          rule.description,
          rule.updatedBy,
          categoryLabels[rule.category],
          ...rule.applicableChannels,
          ...rule.applicablePurposes,
        ]
          .join(" ")
          .toLowerCase();

        return (
          (!query || searchable.includes(query)) &&
          (categoryFilter === "ALL" ||
            rule.category === categoryFilter) &&
          (statusFilter === "ALL" ||
            rule.status === statusFilter)
        );
      })
      .sort((a, b) => a.priority - b.priority);
  }, [rules, search, categoryFilter, statusFilter]);

  const counts = useMemo(
    () => ({
      active: rules.filter((rule) => rule.status === "ACTIVE").length,
      inactive: rules.filter((rule) => rule.status === "INACTIVE").length,
      draft: rules.filter((rule) => rule.status === "DRAFT").length,
      triggered: rules.reduce(
        (total, rule) => total + (rule.triggerCount ?? 0),
        0
      ),
    }),
    [rules]
  );

  return (
    <main className="space-y-7">
      <header className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center">
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-[#9b8358]">
            <ShieldAlert size={15} />
            Notification governance
          </div>

          <h1 className="text-2xl font-semibold tracking-tight text-[#25241f]">
            Notification Suppression Rules
          </h1>

          <p className="mt-1 max-w-2xl text-sm text-[#77736c]">
            Review rules that prevent inappropriate, unauthorized,
            or unnecessary customer and vendor notifications.
          </p>
        </div>

        <div className="flex flex-wrap gap-2">
          <button
            type="button"
            onClick={onRefresh}
            disabled={!onRefresh || loading}
            className="flex items-center gap-2 rounded-lg border border-[#ded9cf] px-4 py-2.5 text-sm font-medium text-[#34322c] hover:bg-[#f8f6f1] disabled:opacity-50"
          >
            <RefreshCw size={15} />
            Refresh
          </button>

          <button
            type="button"
            onClick={onCreate}
            disabled={!onCreate}
            className="flex items-center gap-2 rounded-lg bg-[#292821] px-4 py-2.5 text-sm font-medium text-white disabled:opacity-40"
          >
            <Plus size={16} />
            New rule
          </button>
        </div>
      </header>

      {error && (
        <div
          role="alert"
          className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
        >
          {error}
        </div>
      )}

      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {[
          {
            label: "Active rules",
            value: counts.active,
            color: "text-emerald-700",
          },
          {
            label: "Inactive rules",
            value: counts.inactive,
            color: "text-slate-700",
          },
          {
            label: "Draft rules",
            value: counts.draft,
            color: "text-amber-700",
          },
          {
            label: "Recorded triggers",
            value: counts.triggered,
            color: "text-[#292821]",
          },
        ].map((item) => (
          <div
            key={item.label}
            className="rounded-xl border border-[#e9e5dd] bg-white p-5"
          >
            <p className="text-sm text-[#77736c]">{item.label}</p>
            <p className={`mt-3 text-3xl font-semibold ${item.color}`}>
              {item.value.toLocaleString("en-IN")}
            </p>
          </div>
        ))}
      </section>

      <section className="overflow-hidden rounded-xl border border-[#e9e5dd] bg-white">
        <div className="space-y-4 border-b border-[#eeeae3] p-5">
          <div>
            <h2 className="font-semibold text-[#292821]">
              Suppression rule registry
            </h2>
            <p className="mt-1 text-xs text-[#918c83]">
              Lower priority numbers are evaluated first, subject
              to backend-defined rule precedence.
            </p>
          </div>

          <div className="grid gap-3 lg:grid-cols-3">
            <div className="relative">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#918c83]"
              />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search rules..."
                className="w-full rounded-lg border border-[#e5e0d7] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[#a58c5d]"
              />
            </div>

            <select
              value={categoryFilter}
              onChange={(event) =>
                setCategoryFilter(
                  event.target.value as SuppressionRuleCategory | "ALL"
                )
              }
              className="rounded-lg border border-[#e5e0d7] bg-white px-3 py-2.5 text-sm"
            >
              <option value="ALL">All categories</option>
              {Object.entries(categoryLabels).map(([value, label]) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>

            <select
              value={statusFilter}
              onChange={(event) =>
                setStatusFilter(
                  event.target.value as SuppressionRuleStatus | "ALL"
                )
              }
              className="rounded-lg border border-[#e5e0d7] bg-white px-3 py-2.5 text-sm"
            >
              <option value="ALL">All statuses</option>
              <option value="ACTIVE">Active</option>
              <option value="INACTIVE">Inactive</option>
              <option value="DRAFT">Draft</option>
            </select>
          </div>
        </div>

        {loading ? (
          <div className="p-12 text-center text-sm text-[#77736c]">
            Loading suppression rules...
          </div>
        ) : filteredRules.length === 0 ? (
          <div className="p-12 text-center">
            <ShieldAlert
              size={30}
              className="mx-auto text-[#b3aa9b]"
            />
            <p className="mt-3 font-medium text-[#34322c]">
              No matching suppression rules
            </p>
            <p className="mt-1 text-sm text-[#918c83]">
              Change the filters or create a rule.
            </p>
          </div>
        ) : (
          <div className="divide-y divide-[#f0ede7]">
            {filteredRules.map((rule) => (
              <article key={rule.id} className="space-y-4 p-5">
                <div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-start">
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2">
                      <h3 className="font-semibold text-[#34322c]">
                        {rule.name}
                      </h3>

                      <span
                        className={`rounded-full px-2.5 py-1 text-xs font-medium ${categoryStyles[rule.category]}`}
                      >
                        {categoryLabels[rule.category]}
                      </span>

                      <span
                        className={`rounded-full px-2.5 py-1 text-xs font-medium ${statusStyles[rule.status]}`}
                      >
                        {rule.status}
                      </span>
                    </div>

                    <p className="mt-2 text-sm leading-6 text-[#77736c]">
                      {rule.description}
                    </p>

                    <p className="mt-2 text-xs text-[#918c83]">
                      Rule ID: {rule.id} · Priority: {rule.priority}
                    </p>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    <button
                      type="button"
                      onClick={() => onView?.(rule)}
                      disabled={!onView}
                      className="rounded-lg border border-[#ded9cf] px-3 py-2 text-xs font-medium text-[#555148] hover:bg-[#f8f6f1] disabled:opacity-40"
                    >
                      View
                    </button>

                    <button
                      type="button"
                      onClick={() => onEdit?.(rule)}
                      disabled={!onEdit || rule.status === "INACTIVE"}
                      className="rounded-lg border border-[#ded9cf] px-3 py-2 text-xs font-medium text-[#555148] hover:bg-[#f8f6f1] disabled:opacity-40"
                    >
                      Edit
                    </button>

                    {rule.status !== "DRAFT" && (
                      <button
                        type="button"
                        onClick={() =>
                          onChangeStatus?.(
                            rule,
                            rule.status === "ACTIVE"
                              ? "INACTIVE"
                              : "ACTIVE"
                          )
                        }
                        disabled={!onChangeStatus}
                        className="rounded-lg border border-[#ded9cf] px-3 py-2 text-xs font-medium text-[#555148] hover:bg-[#f8f6f1] disabled:opacity-40"
                      >
                        {rule.status === "ACTIVE" ? "Deactivate" : "Activate"}
                      </button>
                    )}
                  </div>
                </div>

                <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Trigger count
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {(rule.triggerCount ?? 0).toLocaleString("en-IN")}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Last triggered
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {formatDate(rule.lastTriggeredAt)}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Last updated
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {formatDate(rule.updatedAt)}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Updated by
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {rule.updatedBy}
                    </p>
                  </div>
                </div>

                <div className="grid gap-4 md:grid-cols-2">
                  <div>
                    <p className="mb-2 text-xs font-semibold uppercase tracking-wider text-[#918c83]">
                      Applicable channels
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {rule.applicableChannels.length === 0 ? (
                        <span className="text-xs text-[#918c83]">
                          No channels specified
                        </span>
                      ) : (
                        rule.applicableChannels.map((channel) => (
                          <span
                            key={channel}
                            className="rounded-md border border-[#eeeae3] px-2.5 py-1.5 text-xs text-[#666157]"
                          >
                            {channel}
                          </span>
                        ))
                      )}
                    </div>
                  </div>

                  <div>
                    <p className="mb-2 text-xs font-semibold uppercase tracking-wider text-[#918c83]">
                      Applicable purposes
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {rule.applicablePurposes.length === 0 ? (
                        <span className="text-xs text-[#918c83]">
                          All purposes or not specified
                        </span>
                      ) : (
                        rule.applicablePurposes.map((purpose) => (
                          <span
                            key={purpose}
                            className="rounded-md border border-[#eeeae3] px-2.5 py-1.5 text-xs text-[#666157]"
                          >
                            {purpose}
                          </span>
                        ))
                      )}
                    </div>
                  </div>
                </div>
              </article>
            ))}
          </div>
        )}

        <footer className="border-t border-[#eeeae3] bg-[#faf9f6] px-5 py-3 text-xs text-[#918c83]">
          Showing {filteredRules.length.toLocaleString("en-IN")} of{" "}
          {rules.length.toLocaleString("en-IN")} supplied rules.
        </footer>
      </section>

      <section className="grid gap-4 md:grid-cols-2">
        <div className="flex gap-3 rounded-xl border border-[#e9e5dd] bg-white p-4">
          <Clock size={19} className="mt-0.5 shrink-0 text-[#9b8358]" />
          <div>
            <h3 className="text-sm font-semibold text-[#34322c]">
              Quiet-hour enforcement
            </h3>
            <p className="mt-1 text-xs leading-5 text-[#77736c]">
              Evaluate quiet hours using the recipient&apos;s configured
              timezone and the applicable communication purpose.
            </p>
          </div>
        </div>

        <div className="flex gap-3 rounded-xl border border-[#e9e5dd] bg-white p-4">
          <CheckCircle2
            size={19}
            className="mt-0.5 shrink-0 text-[#9b8358]"
          />
          <div>
            <h3 className="text-sm font-semibold text-[#34322c]">
              Payment and dispute suppression
            </h3>
            <p className="mt-1 text-xs leading-5 text-[#77736c]">
              Recheck authoritative invoice and dispute states before
              dispatching reminders. Do not rely on stale frontend data.
            </p>
          </div>
        </div>
      </section>

      <section className="flex gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4">
        <AlertTriangle
          size={19}
          className="mt-0.5 shrink-0 text-amber-700"
        />
        <div>
          <h3 className="text-sm font-semibold text-amber-900">
            Critical suppression rules must not be bypassable
          </h3>
          <p className="mt-1 text-xs leading-5 text-amber-800">
            Opt-out, consent, legal restrictions, and account-level
            blocks must be enforced by the backend. An administrator
            must not be able to bypass these restrictions merely by
            changing a UI rule. Changes need authorization, audit
            records, and effective-time handling.
          </p>
        </div>
      </section>
    </main>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  Bell,
  Search,
  Plus,
  RefreshCw,
  FileText,
  MessageSquare,
  Mail,
  ShieldCheck,
  AlertTriangle,
} from "lucide-react";

export type NotificationTemplateChannel =
  | "EMAIL"
  | "SMS"
  | "WHATSAPP"
  | "IN_APP";

export type NotificationTemplateStatus =
  | "DRAFT"
  | "PENDING_APPROVAL"
  | "APPROVED"
  | "REJECTED"
  | "ARCHIVED";

export interface NotificationTemplateRecord {
  id: string;
  name: string;
  description: string;
  channel: NotificationTemplateChannel;
  purpose: string;
  language: string;
  version: number;
  status: NotificationTemplateStatus;
  providerTemplateId?: string;
  approvalReference?: string;
  variables: string[];
  createdAt: string;
  updatedAt: string;
  updatedBy: string;
}

interface AdminNotificationTemplateManagementCenterProps {
  templates: NotificationTemplateRecord[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onCreate?: () => void;
  onView?: (template: NotificationTemplateRecord) => void;
  onEdit?: (template: NotificationTemplateRecord) => void;
  onSubmitForApproval?: (template: NotificationTemplateRecord) => void;
  onArchive?: (template: NotificationTemplateRecord) => void;
}

const statusStyles: Record<
  NotificationTemplateStatus,
  string
> = {
  DRAFT: "bg-slate-100 text-slate-700",
  PENDING_APPROVAL: "bg-amber-50 text-amber-800",
  APPROVED: "bg-emerald-50 text-emerald-700",
  REJECTED: "bg-red-50 text-red-700",
  ARCHIVED: "bg-zinc-100 text-zinc-600",
};

const channelStyles: Record<
  NotificationTemplateChannel,
  string
> = {
  EMAIL: "bg-blue-50 text-blue-700",
  SMS: "bg-violet-50 text-violet-700",
  WHATSAPP: "bg-emerald-50 text-emerald-700",
  IN_APP: "bg-slate-100 text-slate-700",
};

function formatDate(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return "Unknown";

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
  }).format(date);
}

export default function AdminNotificationTemplateManagementCenter({
  templates,
  loading = false,
  error,
  onRefresh,
  onCreate,
  onView,
  onEdit,
  onSubmitForApproval,
  onArchive,
}: AdminNotificationTemplateManagementCenterProps) {
  const [search, setSearch] = useState("");
  const [channelFilter, setChannelFilter] = useState<
    NotificationTemplateChannel | "ALL"
  >("ALL");
  const [statusFilter, setStatusFilter] = useState<
    NotificationTemplateStatus | "ALL"
  >("ALL");

  const filteredTemplates = useMemo(() => {
    const query = search.trim().toLowerCase();

    return templates
      .filter((template) => {
        const searchable = [
          template.id,
          template.name,
          template.description,
          template.purpose,
          template.language,
          template.providerTemplateId ?? "",
          template.updatedBy,
          ...template.variables,
        ]
          .join(" ")
          .toLowerCase();

        return (
          (!query || searchable.includes(query)) &&
          (channelFilter === "ALL" ||
            template.channel === channelFilter) &&
          (statusFilter === "ALL" ||
            template.status === statusFilter)
        );
      })
      .sort(
        (a, b) =>
          new Date(b.updatedAt).getTime() -
          new Date(a.updatedAt).getTime()
      );
  }, [templates, search, channelFilter, statusFilter]);

  const counts = useMemo(
    () => ({
      total: templates.length,
      approved: templates.filter(
        (item) => item.status === "APPROVED"
      ).length,
      pending: templates.filter(
        (item) => item.status === "PENDING_APPROVAL"
      ).length,
      drafts: templates.filter(
        (item) => item.status === "DRAFT"
      ).length,
      rejected: templates.filter(
        (item) => item.status === "REJECTED"
      ).length,
    }),
    [templates]
  );

  return (
    <main className="space-y-7">
      <header className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center">
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-[#9b8358]">
            <Bell size={15} />
            Communication governance
          </div>

          <h1 className="text-2xl font-semibold tracking-tight text-[#25241f]">
            Notification Template Management
          </h1>

          <p className="mt-1 max-w-2xl text-sm text-[#77736c]">
            Maintain approved communication templates and track
            their channel, purpose, language, and version status.
          </p>
        </div>

        <div className="flex flex-wrap gap-2">
          <button
            type="button"
            onClick={onRefresh}
            disabled={!onRefresh || loading}
            className="flex items-center gap-2 rounded-lg border border-[#ded9cf] px-4 py-2.5 text-sm font-medium text-[#34322c] hover:bg-[#f8f6f1] disabled:opacity-50"
          >
            <RefreshCw size={15} />
            Refresh
          </button>

          <button
            type="button"
            onClick={onCreate}
            disabled={!onCreate}
            className="flex items-center gap-2 rounded-lg bg-[#292821] px-4 py-2.5 text-sm font-medium text-white disabled:opacity-40"
          >
            <Plus size={16} />
            New template
          </button>
        </div>
      </header>

      {error && (
        <div
          role="alert"
          className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
        >
          {error}
        </div>
      )}

      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">
        {[
          {
            label: "Total templates",
            value: counts.total,
            color: "text-[#292821]",
          },
          {
            label: "Approved",
            value: counts.approved,
            color: "text-emerald-700",
          },
          {
            label: "Pending approval",
            value: counts.pending,
            color: "text-amber-700",
          },
          {
            label: "Drafts",
            value: counts.drafts,
            color: "text-slate-700",
          },
          {
            label: "Rejected",
            value: counts.rejected,
            color: "text-red-700",
          },
        ].map((item) => (
          <div
            key={item.label}
            className="rounded-xl border border-[#e9e5dd] bg-white p-5"
          >
            <p className="text-sm text-[#77736c]">{item.label}</p>
            <p className={`mt-3 text-3xl font-semibold ${item.color}`}>
              {item.value.toLocaleString("en-IN")}
            </p>
          </div>
        ))}
      </section>

      <section className="overflow-hidden rounded-xl border border-[#e9e5dd] bg-white">
        <div className="space-y-4 border-b border-[#eeeae3] p-5">
          <div>
            <h2 className="font-semibold text-[#292821]">
              Template registry
            </h2>
            <p className="mt-1 text-xs text-[#918c83]">
              Review template metadata and approval lifecycle.
            </p>
          </div>

          <div className="grid gap-3 lg:grid-cols-3">
            <div className="relative">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#918c83]"
              />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search templates..."
                className="w-full rounded-lg border border-[#e5e0d7] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[#a58c5d]"
              />
            </div>

            <select
              value={channelFilter}
              onChange={(event) =>
                setChannelFilter(
                  event.target.value as
                    | NotificationTemplateChannel
                    | "ALL"
                )
              }
              className="rounded-lg border border-[#e5e0d7] bg-white px-3 py-2.5 text-sm"
            >
              <option value="ALL">All channels</option>
              <option value="EMAIL">Email</option>
              <option value="SMS">SMS</option>
              <option value="WHATSAPP">WhatsApp</option>
              <option value="IN_APP">In-app</option>
            </select>

            <select
              value={statusFilter}
              onChange={(event) =>
                setStatusFilter(
                  event.target.value as
                    | NotificationTemplateStatus
                    | "ALL"
                )
              }
              className="rounded-lg border border-[#e5e0d7] bg-white px-3 py-2.5 text-sm"
            >
              <option value="ALL">All statuses</option>
              <option value="DRAFT">Draft</option>
              <option value="PENDING_APPROVAL">
                Pending approval
              </option>
              <option value="APPROVED">Approved</option>
              <option value="REJECTED">Rejected</option>
              <option value="ARCHIVED">Archived</option>
            </select>
          </div>
        </div>

        {loading ? (
          <div className="p-12 text-center text-sm text-[#77736c]">
            Loading notification templates...
          </div>
        ) : filteredTemplates.length === 0 ? (
          <div className="p-12 text-center">
            <FileText
              size={30}
              className="mx-auto text-[#b3aa9b]"
            />
            <p className="mt-3 font-medium text-[#34322c]">
              No matching templates
            </p>
            <p className="mt-1 text-sm text-[#918c83]">
              Adjust your filters or create a template.
            </p>
          </div>
        ) : (
          <div className="divide-y divide-[#f0ede7]">
            {filteredTemplates.map((template) => (
              <article key={template.id} className="space-y-4 p-5">
                <div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-start">
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2">
                      <h3 className="font-semibold text-[#34322c]">
                        {template.name}
                      </h3>

                      <span
                        className={`rounded-full px-2.5 py-1 text-xs font-medium ${channelStyles[template.channel]}`}
                      >
                        {template.channel}
                      </span>

                      <span
                        className={`rounded-full px-2.5 py-1 text-xs font-medium ${statusStyles[template.status]}`}
                      >
                        {template.status.replaceAll("_", " ")}
                      </span>
                    </div>

                    <p className="mt-2 text-sm leading-6 text-[#77736c]">
                      {template.description}
                    </p>

                    <p className="mt-2 text-xs text-[#918c83]">
                      ID: {template.id} · Version {template.version}
                      {" · "}
                      Language: {template.language}
                    </p>
                  </div>

                  <div className="flex shrink-0 flex-wrap gap-2">
                    <button
                      type="button"
                      onClick={() => onView?.(template)}
                      disabled={!onView}
                      className="rounded-lg border border-[#ded9cf] px-3 py-2 text-xs font-medium text-[#555148] hover:bg-[#f8f6f1] disabled:opacity-40"
                    >
                      View
                    </button>

                    <button
                      type="button"
                      onClick={() => onEdit?.(template)}
                      disabled={
                        !onEdit ||
                        template.status === "ARCHIVED" ||
                        template.status === "PENDING_APPROVAL"
                      }
                      className="rounded-lg border border-[#ded9cf] px-3 py-2 text-xs font-medium text-[#555148] hover:bg-[#f8f6f1] disabled:opacity-40"
                    >
                      Edit
                    </button>

                    {template.status === "DRAFT" && (
                      <button
                        type="button"
                        onClick={() =>
                          onSubmitForApproval?.(template)
                        }
                        disabled={!onSubmitForApproval}
                        className="rounded-lg bg-[#292821] px-3 py-2 text-xs font-medium text-white disabled:opacity-40"
                      >
                        Submit for approval
                      </button>
                    )}

                    {template.status !== "ARCHIVED" && (
                      <button
                        type="button"
                        onClick={() => onArchive?.(template)}
                        disabled={!onArchive}
                        className="rounded-lg border border-red-200 px-3 py-2 text-xs font-medium text-red-700 hover:bg-red-50 disabled:opacity-40"
                      >
                        Archive
                      </button>
                    )}
                  </div>
                </div>

                <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">Purpose</p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {template.purpose}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Provider template ID
                    </p>
                    <p className="mt-1 break-all text-sm font-medium text-[#34322c]">
                      {template.providerTemplateId || "Not configured"}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Approval reference
                    </p>
                    <p className="mt-1 break-all text-sm font-medium text-[#34322c]">
                      {template.approvalReference || "Not available"}
                    </p>
                  </div>

                  <div className="rounded-lg bg-[#faf9f6] p-3">
                    <p className="text-xs text-[#918c83]">
                      Last updated
                    </p>
                    <p className="mt-1 text-sm font-medium text-[#34322c]">
                      {formatDate(template.updatedAt)}
                    </p>
                    <p className="mt-1 text-xs text-[#918c83]">
                      By {template.updatedBy}
                    </p>
                  </div>
                </div>

                <div>
                  <p className="mb-2 text-xs font-semibold uppercase tracking-wider text-[#918c83]">
                    Template variables
                  </p>

                  {template.variables.length === 0 ? (
                    <p className="text-xs text-[#918c83]">
                      No variables supplied.
                    </p>
                  ) : (
                    <div className="flex flex-wrap gap-2">
                      {template.variables.map((variable) => (
                        <span
                          key={variable}
                          className="rounded-md border border-[#eeeae3] bg-white px-2.5 py-1.5 font-mono text-xs text-[#666157]"
                        >
                          {`{{${variable}}}`}
                        </span>
                      ))}
                    </div>
                  )}
                </div>
              </article>
            ))}
          </div>
        )}

        <footer className="border-t border-[#eeeae3] bg-[#faf9f6] px-5 py-3 text-xs text-[#918c83]">
          Showing {filteredTemplates.length.toLocaleString("en-IN")} of{" "}
          {templates.length.toLocaleString("en-IN")} supplied templates.
        </footer>
      </section>

      <section className="flex gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4">
        <AlertTriangle
          size={19}
          className="mt-0.5 shrink-0 text-amber-700"
        />
        <div>
          <h3 className="text-sm font-semibold text-amber-900">
            Approval is not provider activation
          </h3>
          <p className="mt-1 text-xs leading-5 text-amber-800">
            An internally approved template may still require
            provider-side approval or configuration. The backend
            must validate template versions, allowed variables,
            channel restrictions, and provider status before use.
          </p>
        </div>
      </section>
    </main>
  );
}

"use client";

import {
  Activity,
  AlertCircle,
  CheckCircle2,
  Clock3,
  Database,
  HardDrive,
  Layers3,
  RefreshCw,
  Server,
  ShieldAlert,
  Workflow,
  XCircle,
} from "lucide-react";

export type PlatformServiceStatus =
  | "healthy"
  | "degraded"
  | "unavailable"
  | "unknown";

export type PlatformService = {
  id: string;
  name: string;
  description: string;
  category: "application" | "database" | "storage" | "integration" | "infrastructure";
  status: PlatformServiceStatus;
  checkedAt?: string;
  responseTimeMs?: number;
  detail?: string;
};

export type PlatformJob = {
  id: string;
  name: string;
  status: "running" | "queued" | "completed" | "failed" | "paused";
  startedAt?: string;
  completedAt?: string;
  lastRunAt?: string;
  detail?: string;
};

export type PlatformHealthCheck = {
  id: string;
  name: string;
  result: "passed" | "failed" | "warning" | "not_run";
  checkedAt?: string;
  detail?: string;
};

type Props = {
  services: PlatformService[];
  jobs: PlatformJob[];
  checks: PlatformHealthCheck[];
  environmentLabel?: string;
  lastUpdatedAt?: string;
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onOpenService?: (service: PlatformService) => void;
  onOpenJob?: (job: PlatformJob) => void;
  onOpenHealthCheck?: (check: PlatformHealthCheck) => void;
};

const serviceStyles: Record<PlatformServiceStatus, string> = {
  healthy: "bg-emerald-50 text-emerald-800",
  degraded: "bg-amber-50 text-amber-800",
  unavailable: "bg-red-50 text-red-800",
  unknown: "bg-[#F2F0EB] text-[#77736D]",
};

const jobStyles: Record<PlatformJob["status"], string> = {
  running: "bg-blue-50 text-blue-800",
  queued: "bg-[#F2F0EB] text-[#55534F]",
  completed: "bg-emerald-50 text-emerald-800",
  failed: "bg-red-50 text-red-800",
  paused: "bg-amber-50 text-amber-800",
};

const checkStyles: Record<PlatformHealthCheck["result"], string> = {
  passed: "bg-emerald-50 text-emerald-800",
  failed: "bg-red-50 text-red-800",
  warning: "bg-amber-50 text-amber-800",
  not_run: "bg-[#F2F0EB] text-[#77736D]",
};

function formatDate(value?: string) {
  if (!value) return "Not available";

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function StatusPill({
  children,
  className,
}: {
  children: React.ReactNode;
  className: string;
}) {
  return (
    <span className={`inline-flex rounded-full px-2.5 py-1 text-[10px] font-medium ${className}`}>
      {children}
    </span>
  );
}

function SectionHeading({
  eyebrow,
  title,
}: {
  eyebrow: string;
  title: string;
}) {
  return (
    <div className="mb-4">
      <p className="mb-1 font-mono text-[10px] uppercase tracking-[0.18em] text-[#9A7848]">
        {eyebrow}
      </p>
      <h2 className="text-lg font-medium tracking-tight text-[#171717]">
        {title}
      </h2>
    </div>
  );
}

function ServiceIcon({ category }: { category: PlatformService["category"] }) {
  switch (category) {
    case "database":
      return <Database size={18} />;
    case "storage":
      return <HardDrive size={18} />;
    case "integration":
      return <Layers3 size={18} />;
    case "infrastructure":
      return <Server size={18} />;
    default:
      return <Activity size={18} />;
  }
}

export default function AdminPlatformHealthMonitor({
  services,
  jobs,
  checks,
  environmentLabel,
  lastUpdatedAt,
  loading = false,
  error = null,
  onRefresh,
  onOpenService,
  onOpenJob,
  onOpenHealthCheck,
}: Props) {
  const healthyServices = services.filter(
    (service) => service.status === "healthy"
  ).length;

  const degradedServices = services.filter(
    (service) => service.status === "degraded"
  ).length;

  const unavailableServices = services.filter(
    (service) => service.status === "unavailable"
  ).length;

  const failedJobs = jobs.filter(
    (job) => job.status === "failed"
  ).length;

  const failedChecks = checks.filter(
    (check) => check.result === "failed"
  ).length;

  const warningChecks = checks.filter(
    (check) => check.result === "warning"
  ).length;

  const hasIssues =
    degradedServices > 0 ||
    unavailableServices > 0 ||
    failedJobs > 0 ||
    failedChecks > 0;

  return (
    <main className="min-h-screen bg-[#F7F6F2] px-4 py-6 sm:px-6 lg:px-8">
      <div className="mx-auto max-w-[1440px]">
        <header className="mb-8 flex flex-col justify-between gap-5 border-b border-[#D8D6D0] pb-6 sm:flex-row sm:items-end">
          <div>
            <p className="mb-2 font-mono text-[10px] uppercase tracking-[0.2em] text-[#9A7848]">
              Studio administration / Infrastructure
            </p>

            <h1 className="text-2xl font-medium tracking-tight text-[#171717] sm:text-3xl">
              Platform health
            </h1>

            <p className="mt-2 max-w-2xl text-sm leading-6 text-[#77736D]">
              Monitor service availability, background processing and
              infrastructure health checks.
            </p>

            {environmentLabel && (
              <p className="mt-3 inline-flex rounded-md bg-[#EAE8E2] px-2.5 py-1 font-mono text-[10px] text-[#55534F]">
                Environment: {environmentLabel}
              </p>
            )}
          </div>

          <div className="flex flex-wrap items-center gap-3">
            {lastUpdatedAt && (
              <span className="text-xs text-[#77736D]">
                Updated {formatDate(lastUpdatedAt)}
              </span>
            )}

            {onRefresh && (
              <button
                type="button"
                onClick={onRefresh}
                disabled={loading}
                className="inline-flex items-center gap-2 rounded-lg border border-[#D8D6D0] bg-white px-4 py-2.5 text-xs font-medium text-[#33312E] hover:border-[#B68A4A] disabled:opacity-50"
              >
                <RefreshCw size={14} className={loading ? "animate-spin" : ""} />
                Refresh
              </button>
            )}
          </div>
        </header>

        {error && (
          <div
            role="alert"
            className="mb-6 flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
          >
            <AlertCircle size={18} className="mt-0.5 shrink-0" />
            <div>
              <p className="font-medium">Unable to retrieve platform health</p>
              <p className="mt-1 text-xs">{error}</p>
            </div>
          </div>
        )}

        {loading && (
          <div role="status" className="mb-6 rounded-lg border border-[#D8D6D0] bg-white px-4 py-3 text-xs text-[#77736D]">
            Refreshing platform health information…
          </div>
        )}

        {/* Overall status */}
        <section className="mb-9">
          <div className={`flex items-start gap-3 rounded-xl border p-5 ${
            hasIssues
              ? "border-amber-200 bg-amber-50"
              : "border-[#E2E0DA] bg-white"
          }`}>
            {hasIssues ? (
              <ShieldAlert size={21} className="mt-0.5 shrink-0 text-amber-800" />
            ) : (
              <CheckCircle2 size={21} className="mt-0.5 shrink-0 text-emerald-700" />
            )}

            <div>
              <h2 className="text-sm font-medium text-[#252421]">
                {hasIssues
                  ? "Attention required"
                  : "No reported service issues"}
              </h2>
              <p className="mt-1 text-xs leading-5 text-[#77736D]">
                {hasIssues
                  ? "One or more supplied service, job or health-check records indicate an issue."
                  : "The supplied monitoring records contain no degraded services, unavailable services or failed checks."}
              </p>
            </div>
          </div>
        </section>

        {/* Metrics */}
        <section className="mb-9">
          <SectionHeading eyebrow="01 / Services" title="Service indicators" />

          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
            <article className="rounded-xl border border-[#E2E0DA] bg-white p-5">
              <Server size={18} className="text-[#9A7848]" />
              <p className="mt-4 text-xs text-[#77736D]">Total services</p>
              <p className="mt-1 text-3xl font-medium tabular-nums text-[#171717]">
                {services.length}
              </p>
            </article>

            <article className="rounded-xl border border-[#E2E0DA] bg-white p-5">
              <CheckCircle2 size={18} className="text-emerald-700" />
              <p className="mt-4 text-xs text-[#77736D]">Healthy</p>
              <p className="mt-1 text-3xl font-medium tabular-nums text-[#171717]">
                {healthyServices}
              </p>
            </article>

            <article className="rounded-xl border border-[#E2E0DA] bg-white p-5">
              <AlertCircle size={18} className="text-amber-700" />
              <p className="mt-4 text-xs text-[#77736D]">Degraded</p>
              <p className="mt-1 text-3xl font-medium tabular-nums text-[#171717]">
                {degradedServices}
              </p>
            </article>

            <article className="rounded-xl border border-[#E2E0DA] bg-white p-5">
              <XCircle size={18} className="text-red-700" />
              <p className="mt-4 text-xs text-[#77736D]">Unavailable</p>
              <p className="mt-1 text-3xl font-medium tabular-nums text-[#171717]">
                {unavailableServices}
              </p>
            </article>
          </div>
        </section>

        {/* Service inventory */}
        <section className="mb-9">
          <SectionHeading eyebrow="02 / Inventory" title="Service status" />

          {services.length > 0 ? (
            <div className="overflow-hidden rounded-xl border border-[#E2E0DA] bg-white">
              {services.map((service, index) => (
                <button
                  key={service.id}
                  type="button"
                  onClick={() => onOpenService?.(service)}
                  disabled={!onOpenService}
                  className={`flex w-full flex-col justify-between gap-4 p-5 text-left transition hover:bg-[#FAF9F6] sm:flex-row sm:items-center ${
                    index !== services.length - 1
                      ? "border-b border-[#EEECE7]"
                      : ""
                  }`}
                >
                  <div className="flex items-start gap-3">
                    <span className="rounded-lg bg-[#F2F0EB] p-2 text-[#77736D]">
                      <ServiceIcon category={service.category} />
                    </span>

                    <div>
                      <h3 className="text-sm font-medium text-[#252421]">
                        {service.name}
                      </h3>
                      <p className="mt-1 text-xs text-[#77736D]">
                        {service.description}
                      </p>
                      {service.detail && (
                        <p className="mt-2 text-[10px] text-[#99958D]">
                          {service.detail}
                        </p>
                      )}
                    </div>
                  </div>

                  <div className="flex flex-wrap items-center gap-3 sm:justify-end">
                    {service.responseTimeMs !== undefined && (
                      <span className="text-xs text-[#77736D]">
                        {service.responseTimeMs} ms
                      </span>
                    )}

                    <StatusPill className={serviceStyles[service.status]}>
                      {service.status}
                    </StatusPill>

                    <span className="text-[10px] text-[#99958D]">
                      {formatDate(service.checkedAt)}
                    </span>
                  </div>
                </button>
              ))}
            </div>
          ) : (
            <div className="rounded-xl border border-dashed border-[#D8D6D0] bg-white p-8 text-center">
              <Server size={23} className="mx-auto mb-2 text-[#99958D]" />
              <p className="text-sm font-medium text-[#33312E]">No service records</p>
              <p className="mt-1 text-xs text-[#77736D]">
                Service status will appear when monitoring data is connected.
              </p>
            </div>
          )}
        </section>

        {/* Background jobs */}
        <section className="mb-9">
          <SectionHeading eyebrow="03 / Processing" title="Background jobs" />

          <div className="mb-4 grid grid-cols-1 gap-3 sm:grid-cols-3">
            <div className="rounded-lg border border-[#E2E0DA] bg-white p-4">
              <p className="text-xs text-[#77736D]">Running</p>
              <p className="mt-1 text-xl font-medium text-[#171717]">
                {jobs.filter((job) => job.status === "running").length}
              </p>
            </div>
            <div className="rounded-lg border border-[#E2E0DA] bg-white p-4">
              <p className="text-xs text-[#77736D]">Queued</p>
              <p className="mt-1 text-xl font-medium text-[#171717]">
                {jobs.filter((job) => job.status === "queued").length}
              </p>
            </div>
            <div className="rounded-lg border border-[#E2E0DA] bg-white p-4">
              <p className="text-xs text-[#77736D]">Failed</p>
              <p className="mt-1 text-xl font-medium text-[#171717]">
                {failedJobs}
              </p>
            </div>
          </div>

          {jobs.length > 0 ? (
            <div className="overflow-x-auto rounded-xl border border-[#E2E0DA] bg-white">
              <table className="w-full min-w-[760px] text-left">
                <thead className="border-b border-[#EEECE7] bg-[#FAF9F6]">
                  <tr className="text-[10px] uppercase tracking-wider text-[#77736D]">
                    <th className="px-5 py-3 font-medium">Job</th>
                    <th className="px-5 py-3 font-medium">Status</th>
                    <th className="px-5 py-3 font-medium">Started</th>
                    <th className="px-5 py-3 font-medium">Last run</th>
                    <th className="px-5 py-3 font-medium">Details</th>
                  </tr>
                </thead>
                <tbody>
                  {jobs.map((job) => (
                    <tr key={job.id} className="border-b border-[#EEECE7] last:border-0">
                      <td className="px-5 py-4 text-xs font-medium text-[#252421]">
                        {job.name}
                      </td>
                      <td className="px-5 py-4">
                        <StatusPill className={jobStyles[job.status]}>
                          {job.status}
                        </StatusPill>
                      </td>
                      <td className="px-5 py-4 text-xs text-[#77736D]">
                        {formatDate(job.startedAt)}
                      </td>
                      <td className="px-5 py-4 text-xs text-[#77736D]">
                        {formatDate(job.lastRunAt)}
                      </td>
                      <td className="px-5 py-4">
                        <button
                          type="button"
                          disabled={!onOpenJob}
                          onClick={() => onOpenJob?.(job)}
                          className="text-xs font-medium text-[#9A7848] hover:underline disabled:cursor-default"
                        >
                          {job.detail || onOpenJob ? "View details" : "—"}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="rounded-xl border border-dashed border-[#D8D6D0] bg-white p-8 text-center">
              <Workflow size={23} className="mx-auto mb-2 text-[#99958D]" />
              <p className="text-sm font-medium text-[#33312E]">No job records</p>
              <p className="mt-1 text-xs text-[#77736D]">
                Background job information has not been supplied.
              </p>
            </div>
          )}
        </section>

        {/* Health checks */}
        <section>
          <SectionHeading eyebrow="04 / Diagnostics" title="Health checks" />

          <div className="mb-4 flex flex-wrap gap-3">
            <StatusPill className="bg-red-50 text-red-800">
              Failed: {failedChecks}
            </StatusPill>
            <StatusPill className="bg-amber-50 text-amber-800">
              Warnings: {warningChecks}
            </StatusPill>
            <StatusPill className="bg-[#F2F0EB] text-[#55534F]">
              Total: {checks.length}
            </StatusPill>
          </div>

          {checks.length > 0 ? (
            <div className="overflow-hidden rounded-xl border border-[#E2E0DA] bg-white">
              {checks.map((check, index) => (
                <button
                  key={check.id}
                  type="button"
                  onClick={() => onOpenHealthCheck?.(check)}
                  disabled={!onOpenHealthCheck}
                  className={`flex w-full flex-col justify-between gap-3 p-5 text-left transition hover:bg-[#FAF9F6] sm:flex-row sm:items-center ${
                    index !== checks.length - 1
                      ? "border-b border-[#EEECE7]"
                      : ""
                  }`}
                >
                  <div>
                    <h3 className="text-sm font-medium text-[#252421]">
                      {check.name}
                    </h3>
                    {check.detail && (
                      <p className="mt-1 text-xs text-[#77736D]">
                        {check.detail}
                      </p>
                    )}
                    <p className="mt-2 text-[10px] text-[#99958D]">
                      Checked: {formatDate(check.checkedAt)}
                    </p>
                  </div>

                  <StatusPill className={checkStyles[check.result]}>
                    {check.result.replace("_", " ")}
                  </StatusPill>
                </button>
              ))}
            </div>
          ) : (
            <div className="rounded-xl border border-dashed border-[#D8D6D0] bg-white p-8 text-center">
              <Activity size={23} className="mx-auto mb-2 text-[#99958D]" />
              <p className="text-sm font-medium text-[#33312E]">No health checks available</p>
              <p className="mt-1 text-xs text-[#77736D]">
                Diagnostic results will appear when the monitoring service provides them.
              </p>
            </div>
          )}
        </section>

        <footer className="mt-9 border-t border-[#D8D6D0] pt-5">
          <div className="flex items-start gap-2">
            <ShieldAlert size={15} className="mt-0.5 shrink-0 text-[#9A7848]" />
            <p className="text-[11px] leading-5 text-[#8B877F]">
              This interface displays monitoring data supplied by the
              backend. It does not perform infrastructure diagnostics,
              restart services, modify databases or execute background
              jobs. Do not expose internal hostnames, credentials,
              connection strings, stack traces or sensitive infrastructure
              metadata to unauthorised users.
            </p>
          </div>
        </footer>
      </div>
    </main>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import {
  LayoutDashboard,
  FolderKanban,
  Users,
  HardHat,
  UserRound,
  FileText,
  Wallet,
  ClipboardCheck,
  Banknote,
  ChartNoAxesCombined,
  ScrollText,
  Settings,
  LogOut,
  Menu,
  X,
  ChevronRight,
  ShieldCheck,
  Search,
  Bell,
} from "lucide-react";

export type AdminPortalSection =
  | "dashboard"
  | "projects"
  | "leads"
  | "clients"
  | "vendors"
  | "invoices"
  | "approvals"
  | "cash-settlements"
  | "finance-reports"
  | "audit-logs"
  | "settings";

interface AdminPortalLayoutProps {
  children: ReactNode;

  activeSection: AdminPortalSection;

  adminName: string;
  adminRole: string;
  adminReference: string;

  pendingApprovals?: number;
  unreadNotifications?: number;

  onNavigate: (section: AdminPortalSection) => void;
  onLogout: () => void;

  pageTitle?: string;
  pageDescription?: string;

  loading?: boolean;
}

interface NavigationItem {
  id: AdminPortalSection;
  label: string;
  description: string;
  icon: typeof LayoutDashboard;
  badge?: "approvals";
}

interface NavigationGroup {
  title: string;
  items: NavigationItem[];
}

const NAVIGATION_GROUPS: NavigationGroup[] = [
  {
    title: "Workspace",
    items: [
      {
        id: "dashboard",
        label: "Overview",
        description: "Studio operations summary",
        icon: LayoutDashboard,
      },
      {
        id: "projects",
        label: "Projects",
        description: "Project oversight",
        icon: FolderKanban,
      },
      {
        id: "leads",
        label: "Enquiries & Leads",
        description: "Incoming enquiries",
        icon: Users,
      },
    ],
  },
  {
    title: "People & Partners",
    items: [
      {
        id: "clients",
        label: "Clients",
        description: "Client accounts",
        icon: UserRound,
      },
      {
        id: "vendors",
        label: "Vendors",
        description: "Vendor accounts",
        icon: HardHat,
      },
    ],
  },
  {
    title: "Finance & Control",
    items: [
      {
        id: "invoices",
        label: "Invoices & Bills",
        description: "Financial records",
        icon: FileText,
      },
      {
        id: "approvals",
        label: "Approvals",
        description: "Pending decisions",
        icon: ClipboardCheck,
        badge: "approvals",
      },
      {
        id: "cash-settlements",
        label: "Cash Settlements",
        description: "Settlement verification",
        icon: Banknote,
      },
      {
        id: "finance-reports",
        label: "Finance Reports",
        description: "Receivables and reports",
        icon: ChartNoAxesCombined,
      },
    ],
  },
  {
    title: "Governance",
    items: [
      {
        id: "audit-logs",
        label: "Audit Records",
        description: "Recorded system actions",
        icon: ScrollText,
      },
      {
        id: "settings",
        label: "System Settings",
        description: "Configuration and policies",
        icon: Settings,
      },
    ],
  },
];

export function AdminPortalLayout({
  children,
  activeSection,
  adminName,
  adminRole,
  adminReference,
  pendingApprovals = 0,
  unreadNotifications = 0,
  onNavigate,
  onLogout,
  pageTitle,
  pageDescription,
  loading = false,
}: AdminPortalLayoutProps) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [logoutConfirmation, setLogoutConfirmation] = useState(false);

  const activeItem = NAVIGATION_GROUPS
    .flatMap((group) => group.items)
    .find((item) => item.id === activeSection);

  function handleNavigate(section: AdminPortalSection) {
    onNavigate(section);
    setMobileMenuOpen(false);
  }

  function handleLogout() {
    setLogoutConfirmation(false);
    setMobileMenuOpen(false);
    onLogout();
  }

  return (
    <div className="admin-portal-root min-h-screen bg-[#F2F0EB] text-[#171717]">

      {/* Mobile Header */}
      <header className="sticky top-0 z-40 flex h-[70px] items-center justify-between border-b border-[#343434] bg-[#111111] px-5 lg:hidden">
        <div>
          <p className="font-serif text-xl tracking-wide text-[#F2F0EB]">
            ARCHEON
          </p>

          <p className="font-mono text-[8px] uppercase tracking-[0.2em] text-[#A58A64]">
            Administration
          </p>
        </div>

        <button
          type="button"
          onClick={() => setMobileMenuOpen((value) => !value)}
          aria-label={
            mobileMenuOpen
              ? "Close navigation menu"
              : "Open navigation menu"
          }
          aria-expanded={mobileMenuOpen}
          className="flex h-10 w-10 items-center justify-center border border-[#343434] text-white"
        >
          {mobileMenuOpen ? <X size={19} /> : <Menu size={19} />}
        </button>
      </header>

      <div className="flex min-h-screen">

        {/* Desktop Sidebar */}
        <aside className="fixed inset-y-0 left-0 z-30 hidden w-[270px] flex-col bg-[#111111] text-white lg:flex">

          {/* Brand */}
          <div className="border-b border-[#343434] px-8 py-8">
            <p className="font-serif text-2xl tracking-wide text-[#F2F0EB]">
              ARCHEON
            </p>

            <p className="mt-1 font-mono text-[9px] uppercase tracking-[0.22em] text-[#A58A64]">
              Design Studio
            </p>

            <div className="mt-7 border-t border-[#343434] pt-5">
              <p className="font-mono text-[9px] uppercase tracking-[0.18em] text-[#777777]">
                Restricted Workspace
              </p>

              <p className="mt-2 text-xs text-[#D8D6D0]">
                Studio Administration
              </p>
            </div>
          </div>

          {/* Navigation */}
          <nav
            aria-label="Administration navigation"
            className="flex-1 space-y-7 overflow-y-auto px-4 py-6"
          >
            {NAVIGATION_GROUPS.map((group) => (
              <div key={group.title}>
                <p className="mb-3 px-4 font-mono text-[9px] uppercase tracking-[0.18em] text-[#777777]">
                  {group.title}
                </p>

                <div className="space-y-1">
                  {group.items.map((item) => (
                    <NavigationButton
                      key={item.id}
                      item={item}
                      active={activeSection === item.id}
                      badgeCount={
                        item.badge === "approvals"
                          ? pendingApprovals
                          : 0
                      }
                      onClick={() => handleNavigate(item.id)}
                    />
                  ))}
                </div>
              </div>
            ))}
          </nav>

          {/* Admin Identity */}
          <div className="border-t border-[#343434] p-5">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 shrink-0 items-center justify-center border border-[#A58A64]/40 bg-[#25221D] text-[#C5A36D]">
                <ShieldCheck size={18} />
              </div>

              <div className="min-w-0 flex-1">
                <p className="truncate text-xs font-medium text-white">
                  {adminName}
                </p>

                <p className="mt-1 truncate text-[10px] text-[#99958D]">
                  {adminRole}
                </p>
              </div>
            </div>

            <button
              type="button"
              onClick={() => setLogoutConfirmation(true)}
              className="mt-5 flex w-full items-center gap-3 border border-[#343434] px-4 py-3 text-left text-[10px] uppercase tracking-widest text-[#B7B3AC] transition-colors hover:border-[#A58A64] hover:text-white"
            >
              <LogOut size={15} />
              Sign Out
            </button>
          </div>
        </aside>

        {/* Mobile Navigation */}
        {mobileMenuOpen && (
          <div className="fixed inset-0 z-30 bg-[#111111] pt-[70px] lg:hidden">
            <div className="flex h-full flex-col overflow-y-auto px-5 py-7">

              <div className="mb-7 border-b border-[#343434] pb-6">
                <p className="text-sm font-medium text-white">
                  {adminName}
                </p>

                <p className="mt-2 text-xs text-[#99958D]">
                  {adminRole}
                </p>

                <p className="mt-3 font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                  {adminReference}
                </p>
              </div>

              <nav
                aria-label="Mobile administration navigation"
                className="space-y-7"
              >
                {NAVIGATION_GROUPS.map((group) => (
                  <div key={group.title}>
                    <p className="mb-3 font-mono text-[9px] uppercase tracking-widest text-[#777777]">
                      {group.title}
                    </p>

                    <div className="space-y-2">
                      {group.items.map((item) => (
                        <NavigationButton
                          key={item.id}
                          item={item}
                          active={activeSection === item.id}
                          badgeCount={
                            item.badge === "approvals"
                              ? pendingApprovals
                              : 0
                          }
                          onClick={() => handleNavigate(item.id)}
                          mobile
                        />
                      ))}
                    </div>
                  </div>
                ))}
              </nav>

              <button
                type="button"
                onClick={() => setLogoutConfirmation(true)}
                className="mt-auto flex items-center gap-3 border border-[#343434] px-5 py-4 text-xs uppercase tracking-widest text-[#D8D6D0]"
              >
                <LogOut size={16} />
                Sign Out
              </button>
            </div>
          </div>
        )}

        {/* Main Workspace */}
        <div className="min-w-0 flex-1 lg:ml-[270px]">

          {/* Desktop Topbar */}
          <header className="hidden h-[76px] items-center justify-between border-b border-[#D8D6D0] bg-[#F2F0EB] px-8 md:px-10 lg:flex">
            <div className="flex items-center gap-3 text-[10px] uppercase tracking-widest text-[#99958D]">
              <span>Administration</span>
              <ChevronRight size={13} />

              <span className="text-[#33312D]">
                {activeItem?.label ?? "Workspace"}
              </span>
            </div>

            <div className="flex items-center gap-6">
              <div className="flex items-center gap-2 text-[#77736C]">
                <Bell size={16} />
                {unreadNotifications > 0 && (
                  <span className="font-mono text-[9px] text-[#A58A64]">
                    {unreadNotifications > 99
                      ? "99+"
                      : unreadNotifications}
                  </span>
                )}
              </div>

              <div className="h-8 w-px bg-[#D8D6D0]" />

              <div className="text-right">
                <p className="text-xs font-medium text-[#33312D]">
                  {adminName}
                </p>

                <p className="mt-1 font-mono text-[9px] text-[#99958D]">
                  {adminReference}
                </p>
              </div>

              <div className="flex h-9 w-9 items-center justify-center border border-[#D8D6D0] bg-white text-[#A58A64]">
                <UserRound size={16} />
              </div>
            </div>
          </header>

          {/* Page Heading */}
          {(pageTitle || pageDescription) && (
            <div className="border-b border-[#D8D6D0] px-5 py-7 md:px-10 lg:px-12">
              {pageTitle && (
                <h1 className="font-serif text-2xl text-[#171717] md:text-3xl">
                  {pageTitle}
                </h1>
              )}

              {pageDescription && (
                <p className="mt-2 max-w-2xl text-xs leading-6 text-[#77736C]">
                  {pageDescription}
                </p>
              )}
            </div>
          )}

          {/* Page Content */}
          <main className="min-h-[calc(100vh-76px)]">
            {loading ? (
              <div className="flex min-h-80 items-center justify-center">
                <p className="font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
                  Loading administration workspace...
                </p>
              </div>
            ) : (
              children
            )}
          </main>

          {/* Footer */}
          <footer className="border-t border-[#D8D6D0] px-5 py-6 md:px-10 lg:px-12">
            <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center">
              <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
                ARCHEON DESIGN STUDIO
              </p>

              <p className="flex items-center gap-2 font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
                <ShieldCheck size={13} />
                Restricted Administrative Workspace
              </p>
            </div>
          </footer>
        </div>
      </div>

      {/* Logout Confirmation */}
      {logoutConfirmation && (
        <div
          className="fixed inset-0 z-[60] flex items-center justify-center bg-black/60 p-5"
          role="presentation"
          onMouseDown={(event) => {
            if (event.target === event.currentTarget) {
              setLogoutConfirmation(false);
            }
          }}
        >
          <section
            role="dialog"
            aria-modal="true"
            aria-labelledby="admin-logout-title"
            className="w-full max-w-md border border-[#D8D6D0] bg-[#F2F0EB] p-7 md:p-9"
          >
            <div className="flex h-12 w-12 items-center justify-center border border-[#D8D6D0] bg-white text-[#A58A64]">
              <LogOut size={20} />
            </div>

            <h2
              id="admin-logout-title"
              className="mt-6 font-serif text-3xl text-[#171717]"
            >
              Sign out?
            </h2>

            <p className="mt-3 text-sm leading-7 text-[#77736C]">
              You will leave the restricted administration workspace.
            </p>

            <div className="mt-8 flex flex-col-reverse gap-3 sm:flex-row">
              <button
                type="button"
                onClick={() => setLogoutConfirmation(false)}
                className="flex-1 border border-[#D8D6D0] px-5 py-4 text-[10px] uppercase tracking-widest text-[#77736C]"
              >
                Stay Signed In
              </button>

              <button
                type="button"
                onClick={handleLogout}
                className="flex-1 bg-[#171717] px-5 py-4 text-[10px] uppercase tracking-widest text-white hover:bg-[#A58A64]"
              >
                Confirm Sign Out
              </button>
            </div>
          </section>
        </div>
      )}
    </div>
  );
}

function NavigationButton({
  item,
  active,
  badgeCount = 0,
  onClick,
  mobile = false,
}: {
  item: NavigationItem;
  active: boolean;
  badgeCount?: number;
  onClick: () => void;
  mobile?: boolean;
}) {
  const Icon = item.icon;

  return (
    <button
      type="button"
      onClick={onClick}
      aria-current={active ? "page" : undefined}
      className={`group flex w-full items-center gap-4 px-4 py-3.5 text-left transition-colors ${
        mobile ? "min-h-[58px]" : "min-h-[52px]"
      } ${
        active
          ? "border-l-2 border-[#B68A4A] bg-[#24221E] text-white"
          : "border-l-2 border-transparent text-[#99958D] hover:bg-[#1D1D1D] hover:text-white"
      }`}
    >
      <Icon
        size={17}
        strokeWidth={1.6}
        className={
          active
            ? "shrink-0 text-[#C5A36D]"
            : "shrink-0 text-[#777777] group-hover:text-[#C5A36D]"
        }
      />

      <span className="min-w-0 flex-1">
        <span className="block text-[11px] tracking-wide">
          {item.label}
        </span>

        {!mobile && (
          <span className="mt-1 block text-[9px] text-[#777777]">
            {item.description}
          </span>
        )}
      </span>

      {badgeCount > 0 && (
        <span
          aria-label={`${badgeCount} pending approvals`}
          className="flex h-5 min-w-5 items-center justify-center rounded-full bg-[#A58A64] px-1.5 font-mono text-[9px] text-white"
        >
          {badgeCount > 99 ? "99+" : badgeCount}
        </span>
      )}

      {active && (
        <ChevronRight
          size={14}
          className="shrink-0 text-[#A58A64]"
        />
      )}
    </button>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  ShieldCheck,
  ShieldAlert,
  LockKeyhole,
  Search,
  RefreshCw,
  Save,
  X,
  Info,
  Check,
  Minus,
  Users,
  ChevronRight,
  AlertCircle,
  History,
} from "lucide-react";

export interface AdminPermission {
  key: string;
  label: string;
  description: string;
  category: string;
  protected?: boolean;
}

export interface AdminRoleDefinition {
  id: string;
  name: string;
  description: string;
  isSystemRole: boolean;
  isActive: boolean;
  assignedUserCount: number;
  permissions: string[];
  updatedAt: string;
  updatedBy: string;
}

export interface AdminRolePermissionMatrixProps {
  roles: AdminRoleDefinition[];
  permissions: AdminPermission[];

  loading?: boolean;
  saving?: boolean;
  error?: string;

  canManageRoles?: boolean;

  onRefresh?: () => void;

  onSavePermissions: (
    roleId: string,
    permissionKeys: string[],
    reason: string,
    expectedUpdatedAt: string
  ) => Promise<void>;

  onOpenRoleUsers?: (roleId: string) => void;
  onOpenRoleHistory?: (roleId: string) => void;
}

interface PermissionDraft {
  roleId: string;
  permissionKeys: Set<string>;
  reason: string;
}

function categoryPermissions(
  permissions: AdminPermission[]
) {
  const groups = new Map<string, AdminPermission[]>();

  permissions.forEach((permission) => {
    const existing = groups.get(permission.category) ?? [];
    existing.push(permission);
    groups.set(permission.category, existing);
  });

  return Array.from(groups.entries()).map(([category, items]) => ({
    category,
    items,
  }));
}

export function AdminRolePermissionMatrix({
  roles,
  permissions,
  loading = false,
  saving = false,
  error,
  canManageRoles = false,
  onRefresh,
  onSavePermissions,
  onOpenRoleUsers,
  onOpenRoleHistory,
}: AdminRolePermissionMatrixProps) {
  const [selectedRoleId, setSelectedRoleId] = useState(
    roles[0]?.id ?? ""
  );

  const [draft, setDraft] = useState<PermissionDraft | null>(null);
  const [search, setSearch] = useState("");
  const [expandedCategories, setExpandedCategories] =
    useState<Set<string>>(new Set());

  const [validationError, setValidationError] = useState("");
  const [actionError, setActionError] = useState("");
  const [confirmationOpen, setConfirmationOpen] = useState(false);

  const selectedRole = roles.find(
    (role) => role.id === selectedRoleId
  );

  const activePermissionKeys =
    draft?.roleId === selectedRoleId
      ? draft.permissionKeys
      : new Set(selectedRole?.permissions ?? []);

  const groupedPermissions = useMemo(
    () => categoryPermissions(permissions),
    [permissions]
  );

  const visibleGroups = useMemo(() => {
    const query = search.trim().toLowerCase();

    if (!query) return groupedPermissions;

    return groupedPermissions
      .map((group) => ({
        ...group,
        items: group.items.filter((permission) =>
          [
            permission.key,
            permission.label,
            permission.description,
            permission.category,
          ].some((value) =>
            value.toLowerCase().includes(query)
          )
        ),
      }))
      .filter((group) => group.items.length > 0);
  }, [groupedPermissions, search]);

  const hasChanges =
    Boolean(draft) &&
    draft?.roleId === selectedRoleId &&
    selectedRole !== undefined &&
    (
      draft.permissionKeys.size !== selectedRole.permissions.length ||
      selectedRole.permissions.some(
        (key) => !draft.permissionKeys.has(key)
      )
    );

  const editable =
    canManageRoles &&
    Boolean(selectedRole) &&
    Boolean(selectedRole?.isActive);

  function startEditing() {
    if (!selectedRole || !editable) return;

    setDraft({
      roleId: selectedRole.id,
      permissionKeys: new Set(selectedRole.permissions),
      reason: "",
    });

    setValidationError("");
    setActionError("");
  }

  function cancelEditing() {
    setDraft(null);
    setValidationError("");
    setActionError("");
    setConfirmationOpen(false);
  }

  function togglePermission(permission: AdminPermission) {
    if (!editable || !draft || draft.roleId !== selectedRoleId) {
      return;
    }

    if (permission.protected) return;

    setDraft((current) => {
      if (!current) return current;

      const next = new Set(current.permissionKeys);

      if (next.has(permission.key)) {
        next.delete(permission.key);
      } else {
        next.add(permission.key);
      }

      return {
        ...current,
        permissionKeys: next,
      };
    });

    setValidationError("");
  }

  function toggleCategory(category: string) {
    setExpandedCategories((current) => {
      const next = new Set(current);

      if (next.has(category)) {
        next.delete(category);
      } else {
        next.add(category);
      }

      return next;
    });
  }

  function validateChanges() {
    if (!selectedRole || !draft) {
      return "No role changes are available.";
    }

    if (!canManageRoles) {
      return "You do not have permission to manage roles.";
    }

    if (!selectedRole.isActive) {
      return "Inactive roles cannot be modified.";
    }

    if (draft.roleId !== selectedRole.id) {
      return "The selected role changed. Refresh and try again.";
    }

    if (draft.reason.trim().length < 10) {
      return "Provide a reason with at least 10 characters.";
    }

    const protectedPermissions = permissions.filter(
      (permission) => permission.protected
    );

    for (const permission of protectedPermissions) {
      if (
        selectedRole.permissions.includes(permission.key) &&
        !draft.permissionKeys.has(permission.key)
      ) {
        return `The protected permission "${permission.label}" cannot be removed here.`;
      }
    }

    const knownKeys = new Set(
      permissions.map((permission) => permission.key)
    );

    for (const key of draft.permissionKeys) {
      if (!knownKeys.has(key)) {
        return `Unknown permission detected: ${key}`;
      }
    }

    return "";
  }

  function requestSave() {
    const validation = validateChanges();

    if (validation) {
      setValidationError(validation);
      return;
    }

    if (!hasChanges) {
      setValidationError("No permission changes have been made.");
      return;
    }

    setConfirmationOpen(true);
  }

  async function confirmSave() {
    if (!selectedRole || !draft) return;

    const validation = validateChanges();

    if (validation) {
      setValidationError(validation);
      setConfirmationOpen(false);
      return;
    }

    setActionError("");
    setValidationError("");

    try {
      await onSavePermissions(
        selectedRole.id,
        Array.from(draft.permissionKeys).sort(),
        draft.reason.trim(),
        selectedRole.updatedAt
      );

      setDraft(null);
      setConfirmationOpen(false);
    } catch {
      setActionError(
        "Permission changes were not confirmed. Refresh the role before trying again."
      );
    }
  }

  if (loading && roles.length === 0) {
    return (
      <div className="flex min-h-80 items-center justify-center bg-[#F2F0EB]">
        <p className="font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
          Loading role definitions...
        </p>
      </div>
    );
  }

  if (roles.length === 0) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[#F2F0EB] p-6">
        <div className="max-w-lg border border-[#D8D6D0] bg-white p-10 text-center">
          <ShieldAlert
            size={30}
            className="mx-auto text-[#A58A64]"
          />
          <h1 className="mt-5 font-serif text-3xl text-[#171717]">
            No role definitions
          </h1>
          <p className="mt-3 text-xs leading-6 text-[#77736C]">
            Role definitions could not be loaded from the system.
          </p>
          {onRefresh && (
            <button
              type="button"
              onClick={onRefresh}
              className="mt-6 bg-[#171717] px-5 py-3 text-[9px] uppercase tracking-widest text-white"
            >
              Retry
            </button>
          )}
        </div>
      </div>
    );
  }

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-9 md:px-10 md:py-12 lg:px-12">

      {/* Header */}
      <header className="flex flex-col justify-between gap-6 border-b border-[#D8D6D0] pb-8 md:flex-row md:items-end">
        <div>
          <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
            Administration / Access Governance
          </p>

          <h1 className="mt-4 font-serif text-4xl text-[#171717] md:text-5xl">
            Roles & Permissions
          </h1>

          <p className="mt-3 max-w-xl text-sm leading-7 text-[#77736C]">
            Review role definitions and control which operations
            each role is authorised to perform.
          </p>
        </div>

        {onRefresh && (
          <button
            type="button"
            onClick={onRefresh}
            disabled={loading || saving}
            className="inline-flex items-center gap-2 border border-[#D8D6D0] bg-white px-5 py-3 text-[10px] uppercase tracking-widest text-[#55514A] disabled:opacity-40"
          >
            <RefreshCw size={14} />
            Refresh
          </button>
        )}
      </header>

      {error && <Feedback type="error">{error}</Feedback>}
      {actionError && <Feedback type="error">{actionError}</Feedback>}
      {validationError && (
        <Feedback type="error">{validationError}</Feedback>
      )}

      {/* Security Notice */}
      <div className="mt-7 flex items-start gap-3 border border-[#D8D6D0] bg-white p-5">
        <LockKeyhole
          size={19}
          className="mt-0.5 shrink-0 text-[#A58A64]"
        />

        <div>
          <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
            Permission Enforcement
          </p>

          <p className="mt-2 text-xs leading-6 text-[#77736C]">
            This matrix is an administrative interface only.
            Backend APIs must enforce role permissions on every
            protected request. Hiding a button or disabling a
            checkbox does not provide security.
          </p>
        </div>
      </div>

      <div className="mt-9 grid grid-cols-1 gap-7 xl:grid-cols-[300px_minmax(0,1fr)]">

        {/* Role List */}
        <aside>
          <div className="flex items-center justify-between border-b border-[#D8D6D0] pb-4">
            <div>
              <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                Role Directory
              </p>
              <h2 className="mt-2 font-serif text-2xl text-[#171717]">
                Roles
              </h2>
            </div>

            <span className="font-mono text-[9px] text-[#99958D]">
              {roles.length}
            </span>
          </div>

          <div className="mt-4 space-y-2">
            {roles.map((role) => {
              const selected = role.id === selectedRoleId;

              return (
                <button
                  key={role.id}
                  type="button"
                  onClick={() => {
                    if (draft && hasChanges) {
                      const confirmed = window.confirm(
                        "Discard unsaved permission changes?"
                      );
                      if (!confirmed) return;
                    }

                    setSelectedRoleId(role.id);
                    setDraft(null);
                    setValidationError("");
                    setActionError("");
                    setConfirmationOpen(false);
                  }}
                  className={`w-full border p-4 text-left transition-colors ${
                    selected
                      ? "border-[#A58A64] bg-white"
                      : "border-[#D8D6D0] bg-transparent hover:bg-white"
                  }`}
                >
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex min-w-0 items-start gap-3">
                      <span className="mt-1 text-[#A58A64]">
                        <ShieldCheck size={17} />
                      </span>

                      <div className="min-w-0">
                        <p className="text-xs text-[#171717]">
                          {role.name}
                        </p>

                        <p className="mt-1 text-[9px] leading-5 text-[#99958D]">
                          {role.description}
                        </p>
                      </div>
                    </div>

                    <ChevronRight
                      size={15}
                      className="shrink-0 text-[#A58A64]"
                    />
                  </div>

                  <div className="mt-4 flex flex-wrap gap-2">
                    {role.isSystemRole && (
                      <span className="bg-[#F4EFE2] px-2 py-1 text-[8px] uppercase tracking-widest text-[#94743F]">
                        System Role
                      </span>
                    )}

                    <span
                      className={`px-2 py-1 text-[8px] uppercase tracking-widest ${
                        role.isActive
                          ? "bg-[#EAF1E8] text-[#547A51]"
                          : "bg-[#ECEAE5] text-[#77736C]"
                      }`}
                    >
                      {role.isActive ? "Active" : "Inactive"}
                    </span>
                  </div>

                  <div className="mt-4 flex items-center justify-between border-t border-[#EAE7E0] pt-3">
                    <span className="text-[9px] text-[#99958D]">
                      {role.assignedUserCount} assigned users
                    </span>

                    <span className="text-[9px] text-[#77736C]">
                      {role.permissions.length} permissions
                    </span>
                  </div>
                </button>
              );
            })}
          </div>
        </aside>

        {/* Permission Matrix */}
        <section className="min-w-0 border border-[#D8D6D0] bg-white">
          {selectedRole && (
            <>
              <header className="flex flex-col justify-between gap-4 border-b border-[#E5E2DC] p-6 md:flex-row md:items-start">
                <div>
                  <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                    Selected Role
                  </p>

                  <h2 className="mt-2 font-serif text-2xl text-[#171717]">
                    {selectedRole.name}
                  </h2>

                  <p className="mt-2 max-w-xl text-xs leading-6 text-[#77736C]">
                    {selectedRole.description}
                  </p>

                  <p className="mt-3 font-mono text-[8px] text-[#99958D]">
                    Updated {selectedRole.updatedAt}
                    {" · "}
                    By {selectedRole.updatedBy}
                  </p>
                </div>

                <div className="flex flex-wrap gap-2">
                  {onOpenRoleUsers && (
                    <button
                      type="button"
                      onClick={() =>
                        onOpenRoleUsers(selectedRole.id)
                      }
                      className="inline-flex items-center gap-2 border border-[#D8D6D0] bg-white px-4 py-3 text-[9px] uppercase tracking-widest text-[#55514A]"
                    >
                      <Users size={13} />
                      Assigned Users
                    </button>
                  )}

                  {onOpenRoleHistory && (
                    <button
                      type="button"
                      onClick={() =>
                        onOpenRoleHistory(selectedRole.id)
                      }
                      className="inline-flex items-center gap-2 border border-[#D8D6D0] bg-white px-4 py-3 text-[9px] uppercase tracking-widest text-[#55514A]"
                    >
                      <History size={13} />
                      History
                    </button>
                  )}
                </div>
              </header>

              {/* Role Summary */}
              <div className="grid grid-cols-2 gap-px border-b border-[#E5E2DC] bg-[#E5E2DC] md:grid-cols-3">
                <SummaryItem
                  label="Assigned Users"
                  value={selectedRole.assignedUserCount.toLocaleString("en-IN")}
                />
                <SummaryItem
                  label="Assigned Permissions"
                  value={activePermissionKeys.size.toLocaleString("en-IN")}
                />
                <SummaryItem
                  label="Role Type"
                  value={selectedRole.isSystemRole ? "System" : "Custom"}
                />
              </div>

              {/* Permission Controls */}
              <div className="p-5 md:p-6">
                <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center">
                  <div>
                    <p className="font-serif text-xl text-[#171717]">
                      Permission Catalogue
                    </p>

                    <p className="mt-1 text-[10px] text-[#99958D]">
                      {activePermissionKeys.size} permissions assigned
                    </p>
                  </div>

                  {editable && !draft && (
                    <button
                      type="button"
                      onClick={startEditing}
                      className="bg-[#171717] px-5 py-3 text-[9px] uppercase tracking-widest text-white"
                    >
                      Edit Permissions
                    </button>
                  )}
                </div>

                <div className="relative mt-5">
                  <Search
                    size={15}
                    className="absolute left-4 top-1/2 -translate-y-1/2 text-[#99958D]"
                  />

                  <input
                    value={search}
                    onChange={(event) =>
                      setSearch(event.target.value)
                    }
                    placeholder="Search permissions..."
                    className="h-11 w-full border border-[#D8D6D0] bg-[#FAF9F6] pl-10 pr-4 text-xs outline-none focus:border-[#A58A64]"
                  />
                </div>

                <div className="mt-5 space-y-3">
                  {visibleGroups.map((group) => {
                    const expanded =
                      expandedCategories.has(group.category) ||
                      Boolean(search.trim());

                    const assignedCount = group.items.filter(
                      (permission) =>
                        activePermissionKeys.has(permission.key)
                    ).length;

                    return (
                      <div
                        key={group.category}
                        className="border border-[#D8D6D0]"
                      >
                        <button
                          type="button"
                          onClick={() =>
                            toggleCategory(group.category)
                          }
                          aria-expanded={expanded}
                          className="flex w-full items-center justify-between gap-4 bg-[#FAF9F6] px-4 py-4 text-left"
                        >
                          <div>
                            <p className="text-xs text-[#33312D]">
                              {group.category}
                            </p>

                            <p className="mt-1 text-[9px] text-[#99958D]">
                              {assignedCount} of {group.items.length} assigned
                            </p>
                          </div>

                          <ChevronRight
                            size={15}
                            className={`text-[#A58A64] transition-transform ${
                              expanded ? "rotate-90" : ""
                            }`}
                          />
                        </button>

                        {expanded && (
                          <div className="divide-y divide-[#EAE7E0] px-4">
                            {group.items.map((permission) => {
                              const checked =
                                activePermissionKeys.has(permission.key);

                              return (
                                <div
                                  key={permission.key}
                                  className="flex items-start justify-between gap-4 py-4"
                                >
                                  <div className="min-w-0">
                                    <div className="flex flex-wrap items-center gap-2">
                                      <p className="text-xs text-[#33312D]">
                                        {permission.label}
                                      </p>

                                      {permission.protected && (
                                        <span className="inline-flex items-center gap-1 bg-[#F4EFE2] px-2 py-1 text-[8px] uppercase tracking-widest text-[#94743F]">
                                          <LockKeyhole size={10} />
                                          Protected
                                        </span>
                                      )}
                                    </div>

                                    <p className="mt-1 text-[10px] leading-5 text-[#99958D]">
                                      {permission.description}
                                    </p>

                                    <p className="mt-2 font-mono text-[8px] text-[#AAA69E]">
                                      {permission.key}
                                    </p>
                                  </div>

                                  <button
                                    type="button"
                                    role="checkbox"
                                    aria-checked={checked}
                                    aria-label={`${checked ? "Remove" : "Assign"} ${permission.label}`}
                                    disabled={
                                      !draft ||
                                      !editable ||
                                      Boolean(permission.protected)
                                    }
                                    onClick={() =>
                                      togglePermission(permission)
                                    }
                                    className={`flex h-7 w-7 shrink-0 items-center justify-center border ${
                                      checked
                                        ? "border-[#A58A64] bg-[#A58A64] text-white"
                                        : "border-[#D8D6D0] bg-white text-[#77736C]"
                                    } disabled:cursor-not-allowed disabled:opacity-70`}
                                  >
                                    {checked ? (
                                      <Check size={14} />
                                    ) : (
                                      <Minus size={14} />
                                    )}
                                  </button>
                                </div>
                              );
                            })}
                          </div>
                        )}
                      </div>
                    );
                  })}

                  {visibleGroups.length === 0 && (
                    <p className="border border-[#D8D6D0] p-8 text-center text-xs text-[#77736C]">
                      No permissions match this search.
                    </p>
                  )}
                </div>

                {draft && (
                  <div className="mt-7 border-t border-[#E5E2DC] pt-6">
                    <label className="block">
                      <span className="font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                        Reason for Permission Changes
                      </span>

                      <textarea
                        value={draft.reason}
                        onChange={(event) =>
                          setDraft((current) =>
                            current
                              ? {
                                  ...current,
                                  reason: event.target.value,
                                }
                              : current
                          )
                        }
                        rows={3}
                        maxLength={1000}
                        placeholder="Explain why this role requires these permission changes..."
                        className="mt-3 w-full border border-[#D8D6D0] bg-white p-4 text-xs leading-6 text-[#33312D] outline-none focus:border-[#A58A64]"
                      />
                    </label>

                    <div className="mt-5 flex flex-wrap justify-between gap-3">
                      <button
                        type="button"
                        onClick={cancelEditing}
                        disabled={saving}
                        className="inline-flex items-center gap-2 border border-[#D8D6D0] bg-white px-5 py-3 text-[9px] uppercase tracking-widest text-[#55514A]"
                      >
                        <X size={13} />
                        Discard
                      </button>

                      <button
                        type="button"
                        onClick={requestSave}
                        disabled={saving || !hasChanges}
                        className="inline-flex items-center gap-2 bg-[#171717] px-5 py-3 text-[9px] uppercase tracking-widest text-white disabled:opacity-40"
                      >
                        <Save size={13} />
                        Review Changes
                      </button>
                    </div>
                  </div>
                )}

                {!canManageRoles && (
                  <div className="mt-6 flex items-start gap-3 border border-[#D8D6D0] bg-[#FAF9F6] p-4">
                    <LockKeyhole
                      size={16}
                      className="mt-0.5 shrink-0 text-[#A58A64]"
                    />

                    <p className="text-[10px] leading-6 text-[#77736C]">
                      You have read-only access to role definitions.
                      Contact an authorised administrator for permission changes.
                    </p>
                  </div>
                )}

                {selectedRole && !selectedRole.isActive && (
                  <div className="mt-6 flex items-start gap-3 border border-[#D8D6D0] bg-[#FAF9F6] p-4">
                    <AlertCircle
                      size={16}
                      className="mt-0.5 shrink-0 text-[#A58A64]"
                    />

                    <p className="text-[10px] leading-6 text-[#77736C]">
                      This role is inactive. Permission editing is disabled.
                    </p>
                  </div>
                )}
              </div>
            </>
          )}
        </section>
      </div>

      {/* Confirmation */}
      {confirmationOpen && selectedRole && draft && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black/50 p-5">
          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="permission-confirm-title"
            className="w-full max-w-lg border border-[#D8D6D0] bg-[#F7F5F0] p-6 shadow-2xl"
          >
            <div className="flex items-center gap-3">
              <ShieldAlert
                size={21}
                className="text-[#A58A64]"
              />

              <h2
                id="permission-confirm-title"
                className="font-serif text-2xl text-[#171717]"
              >
                Confirm Permission Changes
              </h2>
            </div>

            <p className="mt-4 text-xs leading-7 text-[#77736C]">
              You are changing permissions for the role{" "}
              <strong>{selectedRole.name}</strong>.
              These changes may affect every user assigned to this role.
            </p>

            <div className="mt-5 grid grid-cols-2 gap-3">
              <div className="border border-[#D8D6D0] bg-white p-4">
                <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
                  Current
                </p>

                <p className="mt-2 font-serif text-2xl text-[#171717]">
                  {selectedRole.permissions.length}
                </p>
              </div>

              <div className="border border-[#D8D6D0] bg-white p-4">
                <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
                  Proposed
                </p>

                <p className="mt-2 font-serif text-2xl text-[#171717]">
                  {draft.permissionKeys.size}
                </p>
              </div>
            </div>

            <div className="mt-5 border border-[#D8D6D0] bg-white p-4">
              <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
                Reason
              </p>

              <p className="mt-2 text-xs leading-6 text-[#33312D]">
                {draft.reason}
              </p>
            </div>

            <p className="mt-4 text-[10px] leading-6 text-[#77736C]">
              The server must recheck your authority, validate the
              role version and record this change in the audit log.
            </p>

            {validationError && (
              <p className="mt-3 text-xs text-[#9A5147]">
                {validationError}
              </p>
            )}

            <div className="mt-6 flex justify-end gap-3">
              <button
                type="button"
                onClick={() => setConfirmationOpen(false)}
                disabled={saving}
                className="border border-[#D8D6D0] bg-white px-5 py-3 text-[9px] uppercase tracking-widest text-[#55514A]"
              >
                Cancel
              </button>

              <button
                type="button"
                onClick={confirmSave}
                disabled={saving}
                className="bg-[#171717] px-5 py-3 text-[9px] uppercase tracking-widest text-white disabled:opacity-40"
              >
                {saving ? "Saving..." : "Confirm Changes"}
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}

function SummaryItem({
  label,
  value,
}: {
  label: string;
  value: string;
}) {
  return (
    <div className="bg-[#FAF9F6] p-4">
      <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
        {label}
      </p>

      <p className="mt-2 font-serif text-xl text-[#171717]">
        {value}
      </p>
    </div>
  );
}

function Feedback({
  children,
  type,
}: {
  children: ReactNode;
  type: "error" | "success";
}) {
  return (
    <div
      role={type === "error" ? "alert" : "status"}
      className={`mt-6 flex items-start gap-3 border p-4 ${
        type === "error"
          ? "border-[#E3C9C5] bg-[#FAF3F1] text-[#9A5147]"
          : "border-[#D2DFCE] bg-[#F0F5EE] text-[#547A51]"
      }`}
    >
      {type === "error" ? (
        <AlertCircle size={17} />
      ) : (
        <Check size={17} />
      )}

      <p className="text-xs leading-6">{children}</p>
    </div>
  );
}

"use client";

import {
  AlertCircle,
  CheckCircle2,
  Clock3,
  KeyRound,
  LockKeyhole,
  Monitor,
  RefreshCw,
  Search,
  Shield,
  ShieldAlert,
  ShieldCheck,
  Smartphone,
  UserCheck,
  UserX,
  XCircle,
} from "lucide-react";
import { useMemo, useState } from "react";

export type AdminAccessUser = {
  id: string;
  name: string;
  email: string;
  role: string;
  status: "active" | "invited" | "suspended" | "disabled";
  lastLoginAt?: string;
  mfaEnabled: boolean;
  createdAt: string;
};

export type AdminAccessSession = {
  id: string;
  userId: string;
  userName: string;
  device: string;
  deviceType: "desktop" | "mobile" | "tablet" | "unknown";
  ipAddress?: string;
  locationLabel?: string;
  startedAt: string;
  lastActivityAt: string;
  currentSession?: boolean;
};

export type AdminSecurityEvent = {
  id: string;
  title: string;
  description: string;
  severity: "critical" | "warning" | "information";
  occurredAt: string;
  actor?: string;
  resolved?: boolean;
};

export type AdminInvitation = {
  id: string;
  recipient: string;
  role: string;
  status: "pending" | "accepted" | "expired" | "revoked";
  invitedAt: string;
  expiresAt?: string;
};

type Props = {
  users: AdminAccessUser[];
  sessions: AdminAccessSession[];
  events: AdminSecurityEvent[];
  invitations: AdminInvitation[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onOpenUser?: (user: AdminAccessUser) => void;
  onSuspendUser?: (user: AdminAccessUser) => void;
  onOpenSession?: (session: AdminAccessSession) => void;
  onRevokeSession?: (session: AdminAccessSession) => void;
  onOpenSecurityEvent?: (event: AdminSecurityEvent) => void;
  onResolveSecurityEvent?: (event: AdminSecurityEvent) => void;
  onRevokeInvitation?: (invitation: AdminInvitation) => void;
  onCreateInvitation?: () => void;
};

const userStatusStyles: Record<AdminAccessUser["status"], string> = {
  active: "bg-emerald-50 text-emerald-800",
  invited: "bg-blue-50 text-blue-800",
  suspended: "bg-amber-50 text-amber-800",
  disabled: "bg-[#F2F0EB] text-[#77736D]",
};

const eventSeverityStyles: Record<
  AdminSecurityEvent["severity"],
  string
> = {
  critical: "border-red-200 bg-red-50 text-red-800",
  warning: "border-amber-200 bg-amber-50 text-amber-800",
  information: "border-[#D8D6D0] bg-[#F2F0EB] text-[#55534F]",
};

const invitationStatusStyles: Record<AdminInvitation["status"], string> = {
  pending: "bg-blue-50 text-blue-800",
  accepted: "bg-emerald-50 text-emerald-800",
  expired: "bg-[#F2F0EB] text-[#77736D]",
  revoked: "bg-red-50 text-red-800",
};

function formatDate(value?: string) {
  if (!value) return "Not available";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function StatusPill({
  children,
  className,
}: {
  children: React.ReactNode;
  className: string;
}) {
  return (
    <span
      className={`inline-flex rounded-full px-2.5 py-1 text-[10px] font-medium ${className}`}
    >
      {children}
    </span>
  );
}

function SectionHeading({
  eyebrow,
  title,
  action,
}: {
  eyebrow: string;
  title: string;
  action?: React.ReactNode;
}) {
  return (
    <div className="mb-4 flex items-end justify-between gap-4">
      <div>
        <p className="mb-1 font-mono text-[10px] uppercase tracking-[0.18em] text-[#9A7848]">
          {eyebrow}
        </p>
        <h2 className="text-lg font-medium tracking-tight text-[#171717]">
          {title}
        </h2>
      </div>
      {action}
    </div>
  );
}

export default function AdminSecurityAccessCenter({
  users,
  sessions,
  events,
  invitations,
  loading = false,
  error = null,
  onRefresh,
  onOpenUser,
  onSuspendUser,
  onOpenSession,
  onRevokeSession,
  onOpenSecurityEvent,
  onResolveSecurityEvent,
  onRevokeInvitation,
  onCreateInvitation,
}: Props) {
  const [userSearch, setUserSearch] = useState("");
  const [userStatusFilter, setUserStatusFilter] = useState("all");
  const [eventFilter, setEventFilter] = useState("all");

  const filteredUsers = useMemo(() => {
    const term = userSearch.trim().toLowerCase();

    return users.filter((user) => {
      const matchesSearch =
        !term ||
        user.name.toLowerCase().includes(term) ||
        user.email.toLowerCase().includes(term) ||
        user.role.toLowerCase().includes(term);

      const matchesStatus =
        userStatusFilter === "all" || user.status === userStatusFilter;

      return matchesSearch && matchesStatus;
    });
  }, [users, userSearch, userStatusFilter]);

  const filteredEvents = useMemo(() => {
    if (eventFilter === "all") return events;
    return events.filter((event) => event.severity === eventFilter);
  }, [events, eventFilter]);

  const activeUsers = users.filter((user) => user.status === "active").length;
  const mfaEnabledUsers = users.filter(
    (user) => user.status === "active" && user.mfaEnabled
  ).length;
  const pendingInvitations = invitations.filter(
    (invitation) => invitation.status === "pending"
  ).length;
  const unresolvedCriticalEvents = events.filter(
    (event) => event.severity === "critical" && !event.resolved
  ).length;

  return (
    <main className="min-h-screen bg-[#F7F6F2] px-4 py-6 sm:px-6 lg:px-8">
      <div className="mx-auto max-w-[1440px]">
        <header className="mb-8 flex flex-col justify-between gap-5 border-b border-[#D8D6D0] pb-6 sm:flex-row sm:items-end">
          <div>
            <p className="mb-2 font-mono text-[10px] uppercase tracking-[0.2em] text-[#9A7848]">
              Studio administration / Security
            </p>

            <h1 className="text-2xl font-medium tracking-tight text-[#171717] sm:text-3xl">
              Security & access
            </h1>

            <p className="mt-2 max-w-2xl text-sm leading-6 text-[#77736D]">
              Review account access, active sessions, invitations and
              security events across the studio platform.
            </p>
          </div>

          <div className="flex flex-wrap gap-3">
            {onRefresh && (
              <button
                type="button"
                onClick={onRefresh}
                disabled={loading}
                className="inline-flex items-center gap-2 rounded-lg border border-[#D8D6D0] bg-white px-4 py-2.5 text-xs font-medium text-[#33312E] hover:border-[#B68A4A] disabled:opacity-50"
              >
                <RefreshCw
                  size={14}
                  className={loading ? "animate-spin" : ""}
                />
                Refresh
              </button>
            )}

            {onCreateInvitation && (
              <button
                type="button"
                onClick={onCreateInvitation}
                className="rounded-lg bg-[#171717] px-4 py-2.5 text-xs font-medium text-white hover:bg-[#33312E]"
              >
                Create invitation
              </button>
            )}
          </div>
        </header>

        {error && (
          <div
            role="alert"
            className="mb-6 flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
          >
            <AlertCircle size={18} className="mt-0.5 shrink-0" />
            <div>
              <p className="font-medium">Unable to load security information</p>
              <p className="mt-1 text-xs">{error}</p>
            </div>
          </div>
        )}

        {loading && (
          <div
            role="status"
            className="mb-6 rounded-lg border border-[#D8D6D0] bg-white px-4 py-3 text-xs text-[#77736D]"
          >
            Updating security information…
          </div>
        )}

        {/* Overview */}
        <section className="mb-9">
          <SectionHeading
            eyebrow="01 / Overview"
            title="Access indicators"
          />

          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
            <article className="rounded-xl border border-[#E2E0DA] bg-white p-5">
              <UserCheck size={18} className="text-[#9A7848]" />
              <p className="mt-4 text-xs text-[#77736D]">Active accounts</p>
              <p className="mt-1 text-3xl font-medium tabular-nums text-[#171717]">
                {activeUsers}
              </p>
            </article>

            <article className="rounded-xl border border-[#E2E0DA] bg-white p-5">
              <ShieldCheck size={18} className="text-emerald-700" />
              <p className="mt-4 text-xs text-[#77736D]">MFA-enabled active accounts</p>
              <p className="mt-1 text-3xl font-medium tabular-nums text-[#171717]">
                {mfaEnabledUsers}
                <span className="ml-1 text-sm font-normal text-[#99958D]">
                  / {activeUsers}
                </span>
              </p>
            </article>

            <article className="rounded-xl border border-[#E2E0DA] bg-white p-5">
              <KeyRound size={18} className="text-[#9A7848]" />
              <p className="mt-4 text-xs text-[#77736D]">Pending invitations</p>
              <p className="mt-1 text-3xl font-medium tabular-nums text-[#171717]">
                {pendingInvitations}
              </p>
            </article>

            <article className="rounded-xl border border-[#E2E0DA] bg-white p-5">
              <ShieldAlert size={18} className="text-red-700" />
              <p className="mt-4 text-xs text-[#77736D]">
                Unresolved critical events
              </p>
              <p className="mt-1 text-3xl font-medium tabular-nums text-[#171717]">
                {unresolvedCriticalEvents}
              </p>
            </article>
          </div>
        </section>

        {/* User access */}
        <section className="mb-9">
          <SectionHeading
            eyebrow="02 / Identity"
            title="User access management"
          />

          <div className="mb-4 grid grid-cols-1 gap-3 rounded-xl border border-[#E2E0DA] bg-white p-4 md:grid-cols-[minmax(220px,1fr)_200px]">
            <div className="relative">
              <Search
                size={15}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#99958D]"
              />
              <input
                value={userSearch}
                onChange={(event) => setUserSearch(event.target.value)}
                placeholder="Search name, email or role"
                aria-label="Search user accounts"
                className="w-full rounded-lg border border-[#D8D6D0] bg-[#FAF9F6] py-2.5 pl-9 pr-3 text-xs outline-none focus:border-[#B68A4A]"
              />
            </div>

            <select
              value={userStatusFilter}
              onChange={(event) => setUserStatusFilter(event.target.value)}
              aria-label="Filter user status"
              className="rounded-lg border border-[#D8D6D0] bg-[#FAF9F6] px-3 py-2.5 text-xs outline-none focus:border-[#B68A4A]"
            >
              <option value="all">All account statuses</option>
              <option value="active">Active</option>
              <option value="invited">Invited</option>
              <option value="suspended">Suspended</option>
              <option value="disabled">Disabled</option>
            </select>
          </div>

          <div className="overflow-x-auto rounded-xl border border-[#E2E0DA] bg-white">
            {filteredUsers.length > 0 ? (
              <table className="w-full min-w-[900px] text-left">
                <thead className="border-b border-[#EEECE7] bg-[#FAF9F6]">
                  <tr className="text-[10px] uppercase tracking-wider text-[#77736D]">
                    <th className="px-5 py-3 font-medium">User</th>
                    <th className="px-5 py-3 font-medium">Role</th>
                    <th className="px-5 py-3 font-medium">Status</th>
                    <th className="px-5 py-3 font-medium">MFA</th>
                    <th className="px-5 py-3 font-medium">Last login</th>
                    <th className="px-5 py-3 font-medium">Created</th>
                    <th className="px-5 py-3 font-medium">Actions</th>
                  </tr>
                </thead>

                <tbody>
                  {filteredUsers.map((user) => (
                    <tr
                      key={user.id}
                      className="border-b border-[#EEECE7] last:border-0 hover:bg-[#FAF9F6]"
                    >
                      <td className="px-5 py-4">
                        <p className="text-xs font-medium text-[#252421]">
                          {user.name}
                        </p>
                        <p className="mt-1 text-[10px] text-[#99958D]">
                          {user.email}
                        </p>
                      </td>

                      <td className="px-5 py-4 text-xs text-[#55534F]">
                        {user.role}
                      </td>

                      <td className="px-5 py-4">
                        <StatusPill className={userStatusStyles[user.status]}>
                          {user.status}
                        </StatusPill>
                      </td>

                      <td className="px-5 py-4">
                        {user.mfaEnabled ? (
                          <span className="inline-flex items-center gap-1 text-xs text-emerald-800">
                            <CheckCircle2 size={13} />
                            Enabled
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1 text-xs text-amber-800">
                            <AlertCircle size={13} />
                            Not enabled
                          </span>
                        )}
                      </td>

                      <td className="px-5 py-4 text-xs text-[#77736D]">
                        {formatDate(user.lastLoginAt)}
                      </td>

                      <td className="px-5 py-4 text-xs text-[#77736D]">
                        {formatDate(user.createdAt)}
                      </td>

                      <td className="px-5 py-4">
                        <div className="flex items-center gap-3">
                          {onOpenUser && (
                            <button
                              type="button"
                              onClick={() => onOpenUser(user)}
                              className="text-xs font-medium text-[#9A7848] hover:underline"
                            >
                              Details
                            </button>
                          )}

                          {user.status === "active" && onSuspendUser && (
                            <button
                              type="button"
                              onClick={() => onSuspendUser(user)}
                              className="text-xs font-medium text-red-700 hover:underline"
                            >
                              Suspend
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <p className="p-8 text-center text-xs text-[#77736D]">
                No matching user accounts.
              </p>
            )}
          </div>
        </section>

        {/* Sessions */}
        <section className="mb-9">
          <SectionHeading
            eyebrow="03 / Sessions"
            title="Active sessions"
          />

          <div className="overflow-hidden rounded-xl border border-[#E2E0DA] bg-white">
            {sessions.length > 0 ? (
              sessions.map((session, index) => (
                <div
                  key={session.id}
                  className={`flex flex-col justify-between gap-4 p-5 sm:flex-row sm:items-center ${
                    index !== sessions.length - 1
                      ? "border-b border-[#EEECE7]"
                      : ""
                  }`}
                >
                  <div className="flex items-start gap-3">
                    <span className="rounded-lg bg-[#F2F0EB] p-2 text-[#77736D]">
                      {session.deviceType === "mobile" ? (
                        <Smartphone size={18} />
                      ) : (
                        <Monitor size={18} />
                      )}
                    </span>

                    <div>
                      <p className="text-sm font-medium text-[#252421]">
                        {session.userName}
                      </p>
                      <p className="mt-1 text-xs text-[#77736D]">
                        {session.device}
                      </p>
                      <div className="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-[10px] text-[#99958D]">
                        {session.ipAddress && (
                          <span>IP: {session.ipAddress}</span>
                        )}
                        {session.locationLabel && (
                          <span>{session.locationLabel}</span>
                        )}
                        <span>
                          Last active: {formatDate(session.lastActivityAt)}
                        </span>
                      </div>
                    </div>
                  </div>

                  <div className="flex flex-wrap items-center gap-3">
                    {session.currentSession && (
                      <StatusPill className="bg-emerald-50 text-emerald-800">
                        Current session
                      </StatusPill>
                    )}

                    {onOpenSession && (
                      <button
                        type="button"
                        onClick={() => onOpenSession(session)}
                        className="text-xs font-medium text-[#9A7848] hover:underline"
                      >
                        Details
                      </button>
                    )}

                    {onRevokeSession && !session.currentSession && (
                      <button
                        type="button"
                        onClick={() => onRevokeSession(session)}
                        className="text-xs font-medium text-red-700 hover:underline"
                      >
                        Revoke session
                      </button>
                    )}
                  </div>
                </div>
              ))
            ) : (
              <p className="p-8 text-center text-xs text-[#77736D]">
                No active sessions were supplied.
              </p>
            )}
          </div>
        </section>

        {/* Security events */}
        <section className="mb-9">
          <SectionHeading
            eyebrow="04 / Monitoring"
            title="Security events"
            action={
              <select
                value={eventFilter}
                onChange={(event) => setEventFilter(event.target.value)}
                aria-label="Filter security events"
                className="rounded-lg border border-[#D8D6D0] bg-white px-3 py-2 text-xs text-[#55534F] outline-none focus:border-[#B68A4A]"
              >
                <option value="all">All severity levels</option>
                <option value="critical">Critical</option>
                <option value="warning">Warning</option>
                <option value="information">Information</option>
              </select>
            }
          />

          {filteredEvents.length > 0 ? (
            <div className="space-y-3">
              {filteredEvents.map((event) => (
                <article
                  key={event.id}
                  className="rounded-xl border border-[#E2E0DA] bg-white p-4"
                >
                  <div className="flex flex-col justify-between gap-3 sm:flex-row">
                    <div className="flex items-start gap-3">
                      <span
                        className={`mt-0.5 rounded-lg border p-2 ${eventSeverityStyles[event.severity]}`}
                      >
                        {event.severity === "critical" ? (
                          <ShieldAlert size={16} />
                        ) : event.severity === "warning" ? (
                          <AlertCircle size={16} />
                        ) : (
                          <Shield size={16} />
                        )}
                      </span>

                      <div>
                        <div className="flex flex-wrap items-center gap-2">
                          <h3 className="text-sm font-medium text-[#252421]">
                            {event.title}
                          </h3>
                          <StatusPill
                            className={eventSeverityStyles[event.severity]}
                          >
                            {event.severity}
                          </StatusPill>
                          {event.resolved && (
                            <StatusPill className="bg-emerald-50 text-emerald-800">
                              Resolved
                            </StatusPill>
                          )}
                        </div>

                        <p className="mt-1 text-xs leading-5 text-[#77736D]">
                          {event.description}
                        </p>

                        <p className="mt-2 text-[10px] text-[#99958D]">
                          {formatDate(event.occurredAt)}
                          {event.actor ? ` · ${event.actor}` : ""}
                        </p>
                      </div>
                    </div>

                    <div className="flex shrink-0 items-center gap-3">
                      {onOpenSecurityEvent && (
                        <button
                          type="button"
                          onClick={() => onOpenSecurityEvent(event)}
                          className="text-xs font-medium text-[#9A7848] hover:underline"
                        >
                          Details
                        </button>
                      )}

                      {!event.resolved && onResolveSecurityEvent && (
                        <button
                          type="button"
                          onClick={() => onResolveSecurityEvent(event)}
                          className="text-xs font-medium text-[#55534F] hover:underline"
                        >
                          Mark reviewed
                        </button>
                      )}
                    </div>
                  </div>
                </article>
              ))}
            </div>
          ) : (
            <div className="rounded-xl border border-dashed border-[#D8D6D0] bg-white p-8 text-center">
              <ShieldCheck size={23} className="mx-auto mb-2 text-[#99958D]" />
              <p className="text-sm font-medium text-[#33312E]">
                No matching security events
              </p>
            </div>
          )}
        </section>

        {/* Invitations */}
        <section>
          <SectionHeading
            eyebrow="05 / Onboarding"
            title="Account invitations"
          />

          <div className="overflow-x-auto rounded-xl border border-[#E2E0DA] bg-white">
            {invitations.length > 0 ? (
              <table className="w-full min-w-[760px] text-left">
                <thead className="border-b border-[#EEECE7] bg-[#FAF9F6]">
                  <tr className="text-[10px] uppercase tracking-wider text-[#77736D]">
                    <th className="px-5 py-3 font-medium">Recipient</th>
                    <th className="px-5 py-3 font-medium">Assigned role</th>
                    <th className="px-5 py-3 font-medium">Status</th>
                    <th className="px-5 py-3 font-medium">Invited</th>
                    <th className="px-5 py-3 font-medium">Expires</th>
                    <th className="px-5 py-3 font-medium">Action</th>
                  </tr>
                </thead>

                <tbody>
                  {invitations.map((invitation) => (
                    <tr
                      key={invitation.id}
                      className="border-b border-[#EEECE7] last:border-0"
                    >
                      <td className="px-5 py-4 text-xs font-medium text-[#252421]">
                        {invitation.recipient}
                      </td>
                      <td className="px-5 py-4 text-xs text-[#77736D]">
                        {invitation.role}
                      </td>
                      <td className="px-5 py-4">
                        <StatusPill
                          className={invitationStatusStyles[invitation.status]}
                        >
                          {invitation.status}
                        </StatusPill>
                      </td>
                      <td className="px-5 py-4 text-xs text-[#77736D]">
                        {formatDate(invitation.invitedAt)}
                      </td>
                      <td className="px-5 py-4 text-xs text-[#77736D]">
                        {formatDate(invitation.expiresAt)}
                      </td>
                      <td className="px-5 py-4">
                        {invitation.status === "pending" &&
                          onRevokeInvitation && (
                            <button
                              type="button"
                              onClick={() => onRevokeInvitation(invitation)}
                              className="text-xs font-medium text-red-700 hover:underline"
                            >
                              Revoke
                            </button>
                          )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <p className="p-8 text-center text-xs text-[#77736D]">
                No invitation records are available.
              </p>
            )}
          </div>
        </section>

        <footer className="mt-9 border-t border-[#D8D6D0] pt-5">
          <div className="flex items-start gap-2">
            <LockKeyhole
              size={15}
              className="mt-0.5 shrink-0 text-[#9A7848]"
            />
            <p className="text-[11px] leading-5 text-[#8B877F]">
              The backend must enforce authentication, role-based
              authorisation, MFA policy, session expiry and revocation,
              invitation expiry, account suspension and immutable security
              audit records. This interface does not independently secure
              accounts or terminate sessions.
            </p>
          </div>
        </footer>
      </div>
    </main>
  );
}

"use client";

import { useMemo, useState } from "react";
import type { ReactNode } from "react";
import {
  AlertCircle,
  AlertTriangle,
  CheckCircle2,
  Clock3,
  Eye,
  Filter,
  LockKeyhole,
  Search,
  ShieldAlert,
  ShieldCheck,
  UserX,
} from "lucide-react";

export type SecurityEventSeverity =
  | "INFO"
  | "LOW"
  | "MEDIUM"
  | "HIGH"
  | "CRITICAL";

export type SecurityEventCategory =
  | "AUTHENTICATION"
  | "AUTHORIZATION"
  | "ACCOUNT_SECURITY"
  | "ADMIN_ACTION"
  | "API_SECURITY"
  | "SESSION_SECURITY"
  | "OTHER";

export type SecurityEventStatus =
  | "OPEN"
  | "UNDER_REVIEW"
  | "RESOLVED"
  | "FALSE_POSITIVE";

export interface SecurityEvent {
  id: string;
  eventType: string;
  category: SecurityEventCategory;
  severity: SecurityEventSeverity;
  status: SecurityEventStatus;
  summary: string;
  actorLabel?: string;
  affectedResource?: string;
  sourceLabel?: string;
  correlationId?: string;
  occurredAt: string;
  reviewedBy?: string;
  reviewedAt?: string;
  resolutionSummary?: string;
}

interface AdminSecurityEventCenterProps {
  events: SecurityEvent[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onViewDetails?: (event: SecurityEvent) => void;
  onRequestReview?: (eventId: string) => void;
}

const severityConfig: Record<
  SecurityEventSeverity,
  { label: string; className: string; icon: ReactNode }
> = {
  INFO: {
    label: "Informational",
    className: "bg-slate-100 text-slate-700",
    icon: <CheckCircle2 size={14} />,
  },
  LOW: {
    label: "Low",
    className: "bg-blue-50 text-blue-700",
    icon: <AlertCircle size={14} />,
  },
  MEDIUM: {
    label: "Medium",
    className: "bg-amber-50 text-amber-700",
    icon: <AlertTriangle size={14} />,
  },
  HIGH: {
    label: "High",
    className: "bg-orange-50 text-orange-700",
    icon: <ShieldAlert size={14} />,
  },
  CRITICAL: {
    label: "Critical",
    className: "bg-red-50 text-red-700",
    icon: <AlertTriangle size={14} />,
  },
};

const statusConfig: Record<
  SecurityEventStatus,
  { label: string; className: string }
> = {
  OPEN: {
    label: "Open",
    className: "bg-red-50 text-red-700",
  },
  UNDER_REVIEW: {
    label: "Under review",
    className: "bg-amber-50 text-amber-700",
  },
  RESOLVED: {
    label: "Resolved",
    className: "bg-emerald-50 text-emerald-700",
  },
  FALSE_POSITIVE: {
    label: "False positive",
    className: "bg-slate-100 text-slate-600",
  },
};

const severityFilters = [
  "ALL",
  "INFO",
  "LOW",
  "MEDIUM",
  "HIGH",
  "CRITICAL",
] as const;

type SeverityFilter = (typeof severityFilters)[number];

function formatDate(value?: string) {
  if (!value) return "—";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function SeverityBadge({
  severity,
}: {
  severity: SecurityEventSeverity;
}) {
  const config = severityConfig[severity];

  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium ${config.className}`}
    >
      {config.icon}
      {config.label}
    </span>
  );
}

function StatusBadge({ status }: { status: SecurityEventStatus }) {
  const config = statusConfig[status];

  return (
    <span
      className={`inline-flex rounded-full px-2.5 py-1 text-xs font-medium ${config.className}`}
    >
      {config.label}
    </span>
  );
}

function MetricCard({
  label,
  value,
  description,
  icon,
}: {
  label: string;
  value: number;
  description: string;
  icon: ReactNode;
}) {
  return (
    <div className="rounded-xl border border-[#e9e5dd] bg-white p-5">
      <div className="flex items-center justify-between">
        <p className="text-sm text-[#77736c]">{label}</p>
        <span className="text-[#9b8358]">{icon}</span>
      </div>

      <p className="mt-3 text-3xl font-semibold text-[#292821]">
        {value.toLocaleString("en-IN")}
      </p>

      <p className="mt-1 text-xs text-[#918c83]">{description}</p>
    </div>
  );
}

export default function AdminSecurityEventCenter({
  events,
  loading = false,
  error,
  onRefresh,
  onViewDetails,
  onRequestReview,
}: AdminSecurityEventCenterProps) {
  const [search, setSearch] = useState("");
  const [activeSeverity, setActiveSeverity] =
    useState<SeverityFilter>("ALL");
  const [activeStatus, setActiveStatus] =
    useState<"ALL" | SecurityEventStatus>("ALL");

  const metrics = useMemo(
    () => ({
      total: events.length,
      critical: events.filter(
        (event) => event.severity === "CRITICAL"
      ).length,
      high: events.filter(
        (event) => event.severity === "HIGH"
      ).length,
      open: events.filter(
        (event) => event.status === "OPEN"
      ).length,
      underReview: events.filter(
        (event) => event.status === "UNDER_REVIEW"
      ).length,
    }),
    [events]
  );

  const filteredEvents = useMemo(() => {
    const query = search.trim().toLowerCase();

    return events.filter((event) => {
      const matchesSeverity =
        activeSeverity === "ALL" ||
        event.severity === activeSeverity;

      const matchesStatus =
        activeStatus === "ALL" ||
        event.status === activeStatus;

      const searchable = [
        event.id,
        event.eventType,
        event.category,
        event.summary,
        event.actorLabel ?? "",
        event.affectedResource ?? "",
        event.correlationId ?? "",
      ]
        .join(" ")
        .toLowerCase();

      return (
        matchesSeverity &&
        matchesStatus &&
        (!query || searchable.includes(query))
      );
    });
  }, [events, search, activeSeverity, activeStatus]);

  return (
    <main className="space-y-7">
      <header className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center">
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-[#9b8358]">
            <ShieldAlert size={15} />
            Security operations
          </div>

          <h1 className="text-2xl font-semibold tracking-tight text-[#25241f]">
            Security Event Center
          </h1>

          <p className="mt-1 max-w-2xl text-sm text-[#77736c]">
            Monitor security events, review alerts, and track investigation
            outcomes across the platform.
          </p>
        </div>

        <button
          type="button"
          onClick={onRefresh}
          disabled={!onRefresh || loading}
          className="rounded-lg border border-[#ded9cf] bg-white px-4 py-2.5 text-sm font-medium text-[#34322c] hover:bg-[#f8f6f1] disabled:cursor-not-allowed disabled:opacity-50"
        >
          Refresh events
        </button>
      </header>

      {error && (
        <div
          role="alert"
          className="flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
        >
          <AlertCircle size={18} className="mt-0.5 shrink-0" />
          {error}
        </div>
      )}

      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">
        <MetricCard
          label="Total events"
          value={metrics.total}
          description="Events in supplied dataset"
          icon={<LockKeyhole size={19} />}
        />
        <MetricCard
          label="Critical"
          value={metrics.critical}
          description="Critical severity records"
          icon={<ShieldAlert size={19} />}
        />
        <MetricCard
          label="High severity"
          value={metrics.high}
          description="High severity records"
          icon={<AlertTriangle size={19} />}
        />
        <MetricCard
          label="Open events"
          value={metrics.open}
          description="Awaiting investigation"
          icon={<UserX size={19} />}
        />
        <MetricCard
          label="Under review"
          value={metrics.underReview}
          description="Currently being reviewed"
          icon={<Eye size={19} />}
        />
      </section>

      <section className="overflow-hidden rounded-xl border border-[#e9e5dd] bg-white">
        <div className="space-y-4 border-b border-[#eeeae3] p-5">
          <div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-center">
            <div>
              <h2 className="font-semibold text-[#292821]">
                Security event records
              </h2>
              <p className="mt-1 text-xs text-[#918c83]">
                {filteredEvents.length} matching events
              </p>
            </div>

            <div className="relative w-full lg:max-w-sm">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#918c83]"
              />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search event, actor, resource..."
                className="w-full rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[#a58c5d]"
              />
            </div>
          </div>

          <div className="space-y-3">
            <div className="flex flex-wrap items-center gap-2">
              <Filter size={15} className="mr-1 text-[#918c83]" />
              <span className="mr-1 text-xs text-[#918c83]">
                Severity:
              </span>

              {severityFilters.map((filter) => (
                <button
                  key={filter}
                  type="button"
                  onClick={() => setActiveSeverity(filter)}
                  className={`rounded-full px-3 py-1.5 text-xs font-medium transition ${
                    activeSeverity === filter
                      ? "bg-[#292821] text-white"
                      : "border border-[#e8e3da] text-[#77736c] hover:bg-[#f7f5f0]"
                  }`}
                >
                  {filter === "ALL"
                    ? "All"
                    : severityConfig[filter].label}
                </button>
              ))}
            </div>

            <div className="flex flex-wrap items-center gap-2">
              <span className="mr-1 text-xs text-[#918c83]">
                Status:
              </span>

              {(
                [
                  "ALL",
                  "OPEN",
                  "UNDER_REVIEW",
                  "RESOLVED",
                  "FALSE_POSITIVE",
                ] as const
              ).map((filter) => (
                <button
                  key={filter}
                  type="button"
                  onClick={() => setActiveStatus(filter)}
                  className={`rounded-full px-3 py-1.5 text-xs font-medium transition ${
                    activeStatus === filter
                      ? "bg-[#292821] text-white"
                      : "border border-[#e8e3da] text-[#77736c] hover:bg-[#f7f5f0]"
                  }`}
                >
                  {filter === "ALL"
                    ? "All statuses"
                    : statusConfig[filter].label}
                </button>
              ))}
            </div>
          </div>
        </div>

        {loading ? (
          <div className="p-12 text-center text-sm text-[#77736c]">
            Loading security events...
          </div>
        ) : filteredEvents.length === 0 ? (
          <div className="p-12 text-center">
            <ShieldCheck
              size={30}
              className="mx-auto text-[#b3aa9b]"
            />
            <p className="mt-3 font-medium text-[#34322c]">
              No security events found
            </p>
            <p className="mt-1 text-sm text-[#918c83]">
              Try changing your search or filters.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[1250px] text-left">
              <thead className="bg-[#faf9f6] text-xs uppercase tracking-wider text-[#918c83]">
                <tr>
                  <th className="px-5 py-3 font-medium">Event</th>
                  <th className="px-5 py-3 font-medium">Category</th>
                  <th className="px-5 py-3 font-medium">Actor</th>
                  <th className="px-5 py-3 font-medium">Severity</th>
                  <th className="px-5 py-3 font-medium">Status</th>
                  <th className="px-5 py-3 font-medium">Occurred</th>
                  <th className="px-5 py-3 text-right font-medium">
                    Actions
                  </th>
                </tr>
              </thead>

              <tbody className="divide-y divide-[#f0ede7]">
                {filteredEvents.map((event) => (
                  <tr
                    key={event.id}
                    className="hover:bg-[#fcfbf9]"
                  >
                    <td className="px-5 py-4">
                      <p className="text-sm font-medium text-[#34322c]">
                        {event.eventType}
                      </p>
                      <p className="mt-1 max-w-[260px] text-xs text-[#918c83]">
                        {event.summary}
                      </p>
                      <p className="mt-1 font-mono text-xs text-[#aaa397]">
                        {event.id}
                      </p>
                    </td>

                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {event.category.replaceAll("_", " ")}
                    </td>

                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {event.actorLabel || "System"}
                    </td>

                    <td className="px-5 py-4">
                      <SeverityBadge severity={event.severity} />
                    </td>

                    <td className="px-5 py-4">
                      <StatusBadge status={event.status} />
                    </td>

                    <td className="px-5 py-4 text-sm text-[#77736c]">
                      {formatDate(event.occurredAt)}
                    </td>

                    <td className="px-5 py-4">
                      <div className="flex justify-end gap-2">
                        <button
                          type="button"
                          onClick={() => onViewDetails?.(event)}
                          disabled={!onViewDetails}
                          title="View security event"
                          className="rounded-lg border border-[#e8e3da] p-2 text-[#77736c] hover:bg-[#f7f5f0] disabled:opacity-40"
                        >
                          <Eye size={15} />
                        </button>

                        {(event.status === "OPEN" ||
                          event.status === "UNDER_REVIEW") && (
                          <button
                            type="button"
                            onClick={() => onRequestReview?.(event.id)}
                            disabled={!onRequestReview}
                            title="Request event review"
                            className="rounded-lg border border-[#e8e3da] p-2 text-[#9b8358] hover:bg-[#f7f5f0] disabled:opacity-40"
                          >
                            <ShieldCheck size={15} />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>

      <section className="rounded-xl border border-[#e9e5dd] bg-[#faf9f6] p-5">
        <div className="flex items-start gap-3">
          <ShieldCheck
            size={19}
            className="mt-0.5 shrink-0 text-[#9b8358]"
          />

          <div>
            <h3 className="text-sm font-semibold text-[#34322c]">
              Security monitoring safeguards
            </h3>

            <ul className="mt-2 space-y-1.5 text-xs leading-5 text-[#77736c]">
              <li>
                • Severity classifications should be based on documented
                detection rules and incident policies.
              </li>
              <li>
                • Preserve original event timestamps and correlation IDs
                for investigation.
              </li>
              <li>
                • Restrict access to sensitive event details and personal
                information.
              </li>
              <li>
                • Do not expose passwords, tokens, session secrets, or
                unnecessary network identifiers in event summaries.
              </li>
              <li>
                • Reviewing an event does not automatically resolve the
                underlying security issue.
              </li>
              <li>
                • Maintain an auditable record of investigation decisions
                and subsequent remediation.
              </li>
            </ul>
          </div>
        </div>
      </section>
    </main>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import {
  Settings2,
  ShieldCheck,
  Bell,
  Wallet,
  Users,
  Clock3,
  LockKeyhole,
  RefreshCw,
  Save,
  AlertCircle,
  CheckCircle2,
  History,
  Info,
} from "lucide-react";

export interface AdminSystemSettingsData {
  version: string;
  updatedAt: string;
  updatedBy: string;

  financial: {
    highValueThreshold: number;
    currency: "INR";
    makerCheckerEnabled: boolean;
    requireSeparateApprovers: boolean;
    preventPaymentSplitting: boolean;
  };

  notifications: {
    whatsappEnabled: boolean;
    quietHoursEnabled: boolean;
    quietHoursStart: string;
    quietHoursEnd: string;
    reminderIntervalCalendarDays: number;
    requireWhatsAppOptIn: boolean;
    suppressPaidInvoices: boolean;
    suppressDisputedInvoices: boolean;
    suppressOptOutContacts: boolean;
  };

  portalAccess: {
    clientSelfRegistration: boolean;
    vendorSelfRegistration: boolean;
    invitationOnlyAccess: boolean;
    invitationExpiryHours: number;
    requireEmailVerification: boolean;
  };

  security: {
    sessionTimeoutMinutes: number;
    maxFailedLoginAttempts: number;
    accountLockoutMinutes: number;
    requireStrongPasswords: boolean;
    auditLoggingEnabled: boolean;
  };
}

export type SystemSettingsSection =
  | "financial"
  | "notifications"
  | "portal"
  | "security";

export interface SystemSettingsChangeRequest {
  section: SystemSettingsSection;
  reason: string;
  proposedValues: Record<string, string | number | boolean>;
  expectedVersion: string;
}

export interface SystemSettingsHistoryEntry {
  id: string;
  section: SystemSettingsSection;
  description: string;
  changedBy: string;
  changedAt: string;
  status: "Applied" | "Pending Approval" | "Rejected";
  reason?: string;
}

interface AdminSystemSettingsProps {
  settings: AdminSystemSettingsData | null;
  history: SystemSettingsHistoryEntry[];

  loading?: boolean;
  saving?: boolean;
  error?: string;
  successMessage?: string;

  canManageFinancialSettings?: boolean;
  canManageNotificationSettings?: boolean;
  canManagePortalSettings?: boolean;
  canManageSecuritySettings?: boolean;

  onRefresh?: () => void;
  onSubmitChange: (
    request: SystemSettingsChangeRequest
  ) => Promise<void>;
  onOpenHistory?: () => void;
}

type SettingsDraft = {
  financial: AdminSystemSettingsData["financial"];
  notifications: AdminSystemSettingsData["notifications"];
  portalAccess: AdminSystemSettingsData["portalAccess"];
  security: AdminSystemSettingsData["security"];
};

const SECTIONS: {
  id: SystemSettingsSection;
  label: string;
  description: string;
  icon: ReactNode;
}[] = [
  {
    id: "financial",
    label: "Financial Policies",
    description: "Approval thresholds and payment controls",
    icon: <Wallet size={17} />,
  },
  {
    id: "notifications",
    label: "Notification Policies",
    description: "WhatsApp reminders and communication rules",
    icon: <Bell size={17} />,
  },
  {
    id: "portal",
    label: "Portal Access",
    description: "Client and vendor account access",
    icon: <Users size={17} />,
  },
  {
    id: "security",
    label: "Security Policies",
    description: "Session, login and audit controls",
    icon: <LockKeyhole size={17} />,
  },
];

function canManageSection(
  section: SystemSettingsSection,
  permissions: {
    financial: boolean;
    notifications: boolean;
    portal: boolean;
    security: boolean;
  }
) {
  switch (section) {
    case "financial":
      return permissions.financial;
    case "notifications":
      return permissions.notifications;
    case "portal":
      return permissions.portal;
    case "security":
      return permissions.security;
  }
}

export function AdminSystemSettings({
  settings,
  history,
  loading = false,
  saving = false,
  error,
  successMessage,
  canManageFinancialSettings = false,
  canManageNotificationSettings = false,
  canManagePortalSettings = false,
  canManageSecuritySettings = false,
  onRefresh,
  onSubmitChange,
  onOpenHistory,
}: AdminSystemSettingsProps) {
  const [activeSection, setActiveSection] =
    useState<SystemSettingsSection>("financial");

  const [draft, setDraft] = useState<SettingsDraft | null>(null);
  const [reason, setReason] = useState("");
  const [validationError, setValidationError] = useState("");
  const [confirmationOpen, setConfirmationOpen] = useState(false);

  const permissions = {
    financial: canManageFinancialSettings,
    notifications: canManageNotificationSettings,
    portal: canManagePortalSettings,
    security: canManageSecuritySettings,
  };

  const activeDraft = draft ??
    (settings
      ? {
          financial: { ...settings.financial },
          notifications: { ...settings.notifications },
          portalAccess: { ...settings.portalAccess },
          security: { ...settings.security },
        }
      : null);

  const hasDraft = Boolean(draft);

  function updateSection<K extends keyof SettingsDraft>(
    section: K,
    field: keyof SettingsDraft[K],
    value: SettingsDraft[K][keyof SettingsDraft[K]]
  ) {
    if (!settings || !canManageSection(
      activeSection,
      permissions
    )) {
      return;
    }

    setDraft((current) => {
      const base = current ?? {
        financial: { ...settings.financial },
        notifications: { ...settings.notifications },
        portalAccess: { ...settings.portalAccess },
        security: { ...settings.security },
      };

      return {
        ...base,
        [section]: {
          ...base[section],
          [field]: value,
        },
      } as SettingsDraft;
    });

    setValidationError("");
  }

  function resetDraft() {
    setDraft(null);
    setReason("");
    setValidationError("");
    setConfirmationOpen(false);
  }

  function getProposedValues(): Record<
    string,
    string | number | boolean
  > {
    if (!activeDraft) return {};

    switch (activeSection) {
      case "financial":
        return { ...activeDraft.financial };

      case "notifications":
        return { ...activeDraft.notifications };

      case "portal":
        return { ...activeDraft.portalAccess };

      case "security":
        return { ...activeDraft.security };
    }
  }

  function validateDraft() {
    if (!activeDraft || !settings) {
      return "Settings are not available.";
    }

    if (!canManageSection(activeSection, permissions)) {
      return "You do not have permission to change this section.";
    }

    if (reason.trim().length < 10) {
      return "Please provide a reason with at least 10 characters.";
    }

    const financial = activeDraft.financial;
    const notifications = activeDraft.notifications;
    const portal = activeDraft.portalAccess;
    const security = activeDraft.security;

    if (
      !Number.isFinite(financial.highValueThreshold) ||
      financial.highValueThreshold <= 0
    ) {
      return "The financial approval threshold must be greater than zero.";
    }

    if (
      !Number.isInteger(notifications.reminderIntervalCalendarDays) ||
      notifications.reminderIntervalCalendarDays < 1
    ) {
      return "Reminder interval must be at least one calendar day.";
    }

    if (
      !Number.isInteger(portal.invitationExpiryHours) ||
      portal.invitationExpiryHours < 1
    ) {
      return "Invitation expiry must be at least one hour.";
    }

    if (
      !Number.isInteger(security.sessionTimeoutMinutes) ||
      security.sessionTimeoutMinutes < 5
    ) {
      return "Session timeout must be at least five minutes.";
    }

    if (
      !Number.isInteger(security.maxFailedLoginAttempts) ||
      security.maxFailedLoginAttempts < 1
    ) {
      return "Failed login attempts must be at least one.";
    }

    if (
      !Number.isInteger(security.accountLockoutMinutes) ||
      security.accountLockoutMinutes < 1
    ) {
      return "Account lockout duration must be at least one minute.";
    }

    if (
      notifications.quietHoursEnabled &&
      notifications.quietHoursStart ===
        notifications.quietHoursEnd
    ) {
      return "Quiet hours start and end cannot be identical.";
    }

    if (
      portal.clientSelfRegistration ||
      portal.vendorSelfRegistration
    ) {
      return "Public self-registration is not permitted by the current access policy.";
    }

    if (!portal.invitationOnlyAccess) {
      return "Invitation-only portal access must remain enabled.";
    }

    if (!financial.makerCheckerEnabled) {
      return "Maker-checker approval controls must remain enabled.";
    }

    if (!financial.requireSeparateApprovers) {
      return "Separate approver controls must remain enabled.";
    }

    if (!financial.preventPaymentSplitting) {
      return "Payment-splitting prevention must remain enabled.";
    }

    if (!notifications.requireWhatsAppOptIn) {
      return "WhatsApp consent must remain mandatory.";
    }

    if (
      !notifications.suppressPaidInvoices ||
      !notifications.suppressDisputedInvoices ||
      !notifications.suppressOptOutContacts
    ) {
      return "Paid, disputed and opted-out contacts must remain excluded from reminders.";
    }

    if (!security.auditLoggingEnabled) {
      return "Audit logging cannot be disabled through this interface.";
    }

    return "";
  }

  function requestConfirmation() {
    const validation = validateDraft();

    if (validation) {
      setValidationError(validation);
      return;
    }

    setConfirmationOpen(true);
  }

  async function submitChange() {
    if (!settings) return;

    const validation = validateDraft();

    if (validation) {
      setValidationError(validation);
      setConfirmationOpen(false);
      return;
    }

    setValidationError("");

    await onSubmitChange({
      section: activeSection,
      reason: reason.trim(),
      proposedValues: getProposedValues(),
      expectedVersion: settings.version,
    });

    setConfirmationOpen(false);
    setDraft(null);
    setReason("");
  }

  if (loading && !settings) {
    return (
      <div className="flex min-h-80 items-center justify-center bg-[#F2F0EB]">
        <p className="font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
          Loading system configuration...
        </p>
      </div>
    );
  }

  if (!settings) {
    return (
      <div className="min-h-screen bg-[#F2F0EB] p-8">
        <div className="mx-auto max-w-3xl border border-[#D8D6D0] bg-white p-10 text-center">
          <Settings2
            size={30}
            className="mx-auto text-[#A58A64]"
          />

          <h1 className="mt-5 font-serif text-3xl text-[#171717]">
            Settings unavailable
          </h1>

          <p className="mt-3 text-xs text-[#77736C]">
            The system configuration could not be loaded.
          </p>

          {onRefresh && (
            <button
              type="button"
              onClick={onRefresh}
              className="mt-6 inline-flex items-center gap-2 bg-[#171717] px-5 py-3 text-[10px] uppercase tracking-widest text-white"
            >
              <RefreshCw size={14} />
              Retry
            </button>
          )}
        </div>
      </div>
    );
  }

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-9 md:px-10 md:py-12 lg:px-12">

      {/* Header */}
      <header className="flex flex-col justify-between gap-6 border-b border-[#D8D6D0] pb-8 md:flex-row md:items-end">
        <div>
          <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
            Administration / Configuration
          </p>

          <h1 className="mt-4 font-serif text-4xl text-[#171717] md:text-5xl">
            System Settings
          </h1>

          <p className="mt-3 max-w-xl text-sm leading-7 text-[#77736C]">
            Review operational policies and submit controlled
            configuration changes.
          </p>

          <p className="mt-4 font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
            Version {settings.version}
            {" · "}
            Last updated {settings.updatedAt}
            {" · "}
            By {settings.updatedBy}
          </p>
        </div>

        <div className="flex flex-wrap gap-3">
          {onOpenHistory && (
            <button
              type="button"
              onClick={onOpenHistory}
              className="inline-flex items-center gap-2 border border-[#D8D6D0] bg-white px-5 py-3 text-[10px] uppercase tracking-widest text-[#55514A]"
            >
              <History size={14} />
              Change History
            </button>
          )}

          {onRefresh && (
            <button
              type="button"
              onClick={onRefresh}
              disabled={loading || saving}
              className="inline-flex items-center gap-2 bg-[#171717] px-5 py-3 text-[10px] uppercase tracking-widest text-white disabled:opacity-40"
            >
              <RefreshCw size={14} />
              Refresh
            </button>
          )}
        </div>
      </header>

      {error && <FeedbackMessage type="error">{error}</FeedbackMessage>}

      {successMessage && (
        <FeedbackMessage type="success">
          {successMessage}
        </FeedbackMessage>
      )}

      {validationError && (
        <FeedbackMessage type="error">
          {validationError}
        </FeedbackMessage>
      )}

      {/* Governance Notice */}
      <div className="mt-7 flex items-start gap-3 border border-[#D8D6D0] bg-white p-5">
        <ShieldCheck
          size={19}
          className="mt-0.5 shrink-0 text-[#A58A64]"
        />

        <div>
          <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
            Controlled Configuration
          </p>

          <p className="mt-2 text-xs leading-6 text-[#77736C]">
            Changes submitted here are requests, not immediate policy
            changes. The server must verify permissions, validate
            the current configuration version and apply any required
            approval workflow.
          </p>
        </div>
      </div>

      <div className="mt-9 grid grid-cols-1 gap-7 xl:grid-cols-[280px_minmax(0,1fr)]">

        {/* Navigation */}
        <aside className="space-y-2">
          {SECTIONS.map((section) => {
            const permitted = canManageSection(
              section.id,
              permissions
            );

            return (
              <button
                key={section.id}
                type="button"
                onClick={() => {
                  setActiveSection(section.id);
                  setConfirmationOpen(false);
                  setValidationError("");
                }}
                className={`flex w-full items-start gap-4 border p-4 text-left transition-colors ${
                  activeSection === section.id
                    ? "border-[#A58A64] bg-white"
                    : "border-[#D8D6D0] bg-transparent hover:bg-white"
                }`}
              >
                <span className="mt-1 text-[#A58A64]">
                  {section.icon}
                </span>

                <span className="min-w-0 flex-1">
                  <span className="block text-xs text-[#171717]">
                    {section.label}
                  </span>

                  <span className="mt-1 block text-[9px] leading-5 text-[#99958D]">
                    {section.description}
                  </span>

                  <span className={`mt-2 inline-block text-[8px] uppercase tracking-widest ${
                    permitted ? "text-[#547A51]" : "text-[#99958D]"
                  }`}>
                    {permitted ? "Can manage" : "View only"}
                  </span>
                </span>
              </button>
            );
          })}

          <div className="border border-[#D8D6D0] bg-white p-4">
            <div className="flex items-center gap-2 text-[#A58A64]">
              <Info size={15} />
              <p className="font-mono text-[8px] uppercase tracking-widest">
                Permission Notice
              </p>
            </div>

            <p className="mt-3 text-[10px] leading-6 text-[#77736C]">
              Access shown here is supplied by the application.
              Backend authorization must independently verify
              every submitted change.
            </p>
          </div>
        </aside>

        {/* Settings Panel */}
        <section className="min-w-0 border border-[#D8D6D0] bg-white">
          <div className="flex flex-col justify-between gap-3 border-b border-[#E5E2DC] p-6 sm:flex-row sm:items-center">
            <div>
              <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                Configuration Area
              </p>

              <h2 className="mt-2 font-serif text-2xl text-[#171717]">
                {SECTIONS.find(
                  (section) => section.id === activeSection
                )?.label}
              </h2>
            </div>

            <span className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
              {canManageSection(activeSection, permissions)
                ? "Editing permitted"
                : "Read-only access"}
            </span>
          </div>

          <div className="space-y-8 p-6">
            {activeSection === "financial" && activeDraft && (
              <FinancialSettings
                value={activeDraft.financial}
                editable={canManageFinancialSettings}
                onChange={(field, value) =>
                  updateSection("financial", field, value)
                }
              />
            )}

            {activeSection === "notifications" && activeDraft && (
              <NotificationSettings
                value={activeDraft.notifications}
                editable={canManageNotificationSettings}
                onChange={(field, value) =>
                  updateSection("notifications", field, value)
                }
              />
            )}

            {activeSection === "portal" && activeDraft && (
              <PortalSettings
                value={activeDraft.portalAccess}
                editable={canManagePortalSettings}
                onChange={(field, value) =>
                  updateSection("portalAccess", field, value)
                }
              />
            )}

            {activeSection === "security" && activeDraft && (
              <SecuritySettings
                value={activeDraft.security}
                editable={canManageSecuritySettings}
                onChange={(field, value) =>
                  updateSection("security", field, value)
                }
              />
            )}
          </div>

          {/* Change Request */}
          {canManageSection(activeSection, permissions) && (
            <div className="border-t border-[#E5E2DC] bg-[#FAF9F6] p-6">
              <label className="block">
                <span className="font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                  Reason for Configuration Change
                </span>

                <textarea
                  value={reason}
                  onChange={(event) => setReason(event.target.value)}
                  rows={3}
                  maxLength={1000}
                  placeholder="Explain why this configuration change is required..."
                  className="mt-3 w-full resize-y border border-[#D8D6D0] bg-white p-4 text-xs leading-6 text-[#33312D] outline-none focus:border-[#A58A64]"
                />
              </label>

              <div className="mt-4 flex flex-wrap justify-between gap-3">
                <button
                  type="button"
                  onClick={resetDraft}
                  disabled={!hasDraft || saving}
                  className="border border-[#D8D6D0] bg-white px-5 py-3 text-[9px] uppercase tracking-widest text-[#55514A] disabled:opacity-40"
                >
                  Reset Changes
                </button>

                <button
                  type="button"
                  onClick={requestConfirmation}
                  disabled={!hasDraft || saving}
                  className="inline-flex items-center gap-2 bg-[#171717] px-5 py-3 text-[9px] uppercase tracking-widest text-white disabled:opacity-40"
                >
                  <Save size={14} />
                  Review Change Request
                </button>
              </div>
            </div>
          )}
        </section>
      </div>

      {/* Recent History */}
      <section className="mt-10">
        <div className="flex items-center justify-between border-b border-[#D8D6D0] pb-4">
          <div>
            <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
              Governance Records
            </p>

            <h2 className="mt-2 font-serif text-2xl text-[#171717]">
              Recent Configuration Changes
            </h2>
          </div>

          <History size={19} className="text-[#A58A64]" />
        </div>

        {history.length === 0 ? (
          <div className="mt-5 border border-[#D8D6D0] bg-white p-8 text-center text-xs text-[#77736C]">
            No configuration history is available.
          </div>
        ) : (
          <div className="mt-5 space-y-3">
            {history.map((entry) => (
              <div
                key={entry.id}
                className="flex flex-col justify-between gap-3 border border-[#D8D6D0] bg-white p-5 sm:flex-row sm:items-center"
              >
                <div>
                  <p className="text-xs text-[#171717]">
                    {entry.description}
                  </p>

                  <p className="mt-2 text-[9px] text-[#99958D]">
                    {entry.section}
                    {" · "}
                    {entry.changedBy}
                    {" · "}
                    {entry.changedAt}
                  </p>

                  {entry.reason && (
                    <p className="mt-2 text-[10px] leading-5 text-[#77736C]">
                      Reason: {entry.reason}
                    </p>
                  )}
                </div>

                <HistoryStatus status={entry.status} />
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Confirmation Dialog */}
      {confirmationOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/50 p-5">
          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="settings-confirm-title"
            className="w-full max-w-lg border border-[#D8D6D0] bg-[#F7F5F0] p-6 shadow-2xl"
          >
            <div className="flex items-center gap-3">
              <AlertCircle
                size={21}
                className="text-[#A58A64]"
              />

              <h2
                id="settings-confirm-title"
                className="font-serif text-2xl text-[#171717]"
              >
                Submit Configuration Request?
              </h2>
            </div>

            <p className="mt-4 text-xs leading-7 text-[#77736C]">
              You are submitting a proposed change to{" "}
              <strong>
                {SECTIONS.find(
                  (section) => section.id === activeSection
                )?.label}
              </strong>
              . The current settings will not be changed by this
              submission alone.
            </p>

            <div className="mt-5 border border-[#D8D6D0] bg-white p-4">
              <p className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
                Change Reason
              </p>

              <p className="mt-2 text-xs leading-6 text-[#33312D]">
                {reason}
              </p>
            </div>

            <div className="mt-6 flex justify-end gap-3">
              <button
                type="button"
                onClick={() => setConfirmationOpen(false)}
                disabled={saving}
                className="border border-[#D8D6D0] bg-white px-5 py-3 text-[9px] uppercase tracking-widest text-[#55514A]"
              >
                Cancel
              </button>

              <button
                type="button"
                onClick={submitChange}
                disabled={saving}
                className="bg-[#171717] px-5 py-3 text-[9px] uppercase tracking-widest text-white disabled:opacity-40"
              >
                {saving ? "Submitting..." : "Confirm Request"}
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}

function SettingGroup({
  title,
  description,
  children,
}: {
  title: string;
  description?: string;
  children: ReactNode;
}) {
  return (
    <section>
      <h3 className="font-serif text-xl text-[#171717]">
        {title}
      </h3>

      {description && (
        <p className="mt-2 text-[10px] leading-6 text-[#77736C]">
          {description}
        </p>
      )}

      <div className="mt-5 space-y-4">{children}</div>
    </section>
  );
}

function SettingToggle({
  title,
  description,
  checked,
  disabled,
  onChange,
}: {
  title: string;
  description: string;
  checked: boolean;
  disabled?: boolean;
  onChange: (value: boolean) => void;
}) {
  return (
    <div className="flex items-start justify-between gap-4 border-b border-[#EAE7E0] pb-4 last:border-0">
      <div className="min-w-0">
        <p className="text-xs text-[#33312D]">{title}</p>

        <p className="mt-1 max-w-xl text-[10px] leading-5 text-[#99958D]">
          {description}
        </p>
      </div>

      <button
        type="button"
        role="switch"
        aria-checked={checked}
        disabled={disabled}
        onClick={() => onChange(!checked)}
        className={`relative mt-1 h-5 w-10 shrink-0 rounded-full transition-colors ${
          checked ? "bg-[#A58A64]" : "bg-[#C9C5BC]"
        } disabled:cursor-not-allowed disabled:opacity-60`}
      >
        <span
          className={`absolute top-0.5 h-4 w-4 rounded-full bg-white transition-transform ${
            checked ? "translate-x-5" : "translate-x-0.5"
          }`}
        />
      </button>
    </div>
  );
}

function SettingNumber({
  label,
  value,
  suffix,
  editable,
  onChange,
}: {
  label: string;
  value: number;
  suffix?: string;
