"use client";

import { useMemo, useState } from "react";
import {
  Activity,
  AlertCircle,
  CheckCircle2,
  Clock3,
  Download,
  Filter,
  KeyRound,
  LogIn,
  LogOut,
  Search,
  ShieldAlert,
  User,
} from "lucide-react";

export type UserActivityType =
  | "LOGIN"
  | "LOGOUT"
  | "PASSWORD_CHANGE"
  | "PROFILE_UPDATE"
  | "ROLE_CHANGE"
  | "PERMISSION_CHANGE"
  | "SESSION_REVOKED"
  | "FAILED_LOGIN"
  | "ACCOUNT_LOCKED"
  | "OTHER";

export type UserActivityOutcome =
  | "SUCCESS"
  | "FAILED"
  | "BLOCKED"
  | "PENDING";

export interface UserActivityRecord {
  id: string;
  userId: string;
  userName: string;
  userEmail?: string;
  role?: string;
  activityType: UserActivityType;
  outcome: UserActivityOutcome;
  description: string;
  occurredAt: string;
  source?: string;
  ipAddress?: string;
  correlationId?: string;
}

interface AdminUserActivityTimelineProps {
  activities: UserActivityRecord[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onViewUser?: (userId: string) => void;
  onExport?: (records: UserActivityRecord[]) => void;
}

const activityLabels: Record<UserActivityType, string> = {
  LOGIN: "Login",
  LOGOUT: "Logout",
  PASSWORD_CHANGE: "Password change",
  PROFILE_UPDATE: "Profile update",
  ROLE_CHANGE: "Role change",
  PERMISSION_CHANGE: "Permission change",
  SESSION_REVOKED: "Session revoked",
  FAILED_LOGIN: "Failed login",
  ACCOUNT_LOCKED: "Account locked",
  OTHER: "Other activity",
};

const outcomeStyles: Record<
  UserActivityOutcome,
  string
> = {
  SUCCESS: "bg-emerald-50 text-emerald-700",
  FAILED: "bg-red-50 text-red-700",
  BLOCKED: "bg-amber-50 text-amber-700",
  PENDING: "bg-blue-50 text-blue-700",
};

const activityIcons: Record<
  UserActivityType,
  typeof Activity
> = {
  LOGIN: LogIn,
  LOGOUT: LogOut,
  PASSWORD_CHANGE: KeyRound,
  PROFILE_UPDATE: User,
  ROLE_CHANGE: ShieldAlert,
  PERMISSION_CHANGE: ShieldAlert,
  SESSION_REVOKED: LogOut,
  FAILED_LOGIN: AlertCircle,
  ACCOUNT_LOCKED: ShieldAlert,
  OTHER: Activity,
};

function formatDate(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "medium",
  }).format(date);
}

function getDayKey(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return "Unknown date";

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "full",
  }).format(date);
}

function MetricCard({
  label,
  value,
  icon,
  description,
}: {
  label: string;
  value: number;
  icon: React.ReactNode;
  description: string;
}) {
  return (
    <div className="rounded-xl border border-[#e9e5dd] bg-white p-5">
      <div className="flex items-center justify-between">
        <p className="text-sm text-[#77736c]">{label}</p>
        <span className="text-[#9b8358]">{icon}</span>
      </div>

      <p className="mt-3 text-3xl font-semibold text-[#292821]">
        {value.toLocaleString("en-IN")}
      </p>

      <p className="mt-1 text-xs text-[#918c83]">{description}</p>
    </div>
  );
}

export default function AdminUserActivityTimeline({
  activities,
  loading = false,
  error,
  onRefresh,
  onViewUser,
  onExport,
}: AdminUserActivityTimelineProps) {
  const [search, setSearch] = useState("");
  const [activityFilter, setActivityFilter] =
    useState<UserActivityType | "ALL">("ALL");
  const [outcomeFilter, setOutcomeFilter] =
    useState<UserActivityOutcome | "ALL">("ALL");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");

  const sortedActivities = useMemo(
    () =>
      [...activities].sort(
        (a, b) =>
          new Date(b.occurredAt).getTime() -
          new Date(a.occurredAt).getTime()
      ),
    [activities]
  );

  const filteredActivities = useMemo(() => {
    const query = search.trim().toLowerCase();

    return sortedActivities.filter((record) => {
      const matchesActivity =
        activityFilter === "ALL" ||
        record.activityType === activityFilter;

      const matchesOutcome =
        outcomeFilter === "ALL" ||
        record.outcome === outcomeFilter;

      const searchable = [
        record.userName,
        record.userEmail ?? "",
        record.userId,
        record.description,
        record.source ?? "",
        record.correlationId ?? "",
      ]
        .join(" ")
        .toLowerCase();

      const date = new Date(record.occurredAt);

      const matchesSearch =
        !query || searchable.includes(query);

      const matchesFrom =
        !dateFrom ||
        (!Number.isNaN(date.getTime()) &&
          date >= new Date(`${dateFrom}T00:00:00`));

      const matchesTo =
        !dateTo ||
        (!Number.isNaN(date.getTime()) &&
          date < new Date(`${dateTo}T00:00:00` + "Z") &&
          date < new Date(`${dateTo}T00:00:00`));

      return (
        matchesActivity &&
        matchesOutcome &&
        matchesSearch &&
        matchesFrom &&
        matchesTo
      );
    });
  }, [
    sortedActivities,
    search,
    activityFilter,
    outcomeFilter,
    dateFrom,
    dateTo,
  ]);

  const metrics = useMemo(
    () => ({
      total: filteredActivities.length,
      successful: filteredActivities.filter(
        (record) => record.outcome === "SUCCESS"
      ).length,
      failed: filteredActivities.filter(
        (record) => record.outcome === "FAILED"
      ).length,
      blocked: filteredActivities.filter(
        (record) => record.outcome === "BLOCKED"
      ).length,
    }),
    [filteredActivities]
  );

  const groupedActivities = useMemo(() => {
    const groups = new Map<string, UserActivityRecord[]>();

    filteredActivities.forEach((record) => {
      const key = getDayKey(record.occurredAt);
      const existing = groups.get(key) ?? [];

      existing.push(record);
      groups.set(key, existing);
    });

    return Array.from(groups.entries());
  }, [filteredActivities]);

  function clearFilters() {
    setSearch("");
    setActivityFilter("ALL");
    setOutcomeFilter("ALL");
    setDateFrom("");
    setDateTo("");
  }

  return (
    <main className="space-y-7">
      <header className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center">
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-[#9b8358]">
            <Activity size={15} />
            Security and user governance
          </div>

          <h1 className="text-2xl font-semibold tracking-tight text-[#25241f]">
            User Activity Timeline
          </h1>

          <p className="mt-1 max-w-2xl text-sm text-[#77736c]">
            Review chronological account activity, authentication
            outcomes, and security-related changes.
          </p>
        </div>

        <div className="flex flex-wrap gap-2">
          <button
            type="button"
            onClick={onRefresh}
            disabled={!onRefresh || loading}
            className="rounded-lg border border-[#ded9cf] bg-white px-4 py-2.5 text-sm font-medium text-[#34322c] hover:bg-[#f8f6f1] disabled:opacity-50"
          >
            Refresh
          </button>

          <button
            type="button"
            onClick={() => onExport?.(filteredActivities)}
            disabled={!onExport || filteredActivities.length === 0}
            className="inline-flex items-center gap-2 rounded-lg bg-[#292821] px-4 py-2.5 text-sm font-medium text-white hover:bg-[#403e35] disabled:opacity-50"
          >
            <Download size={15} />
            Export filtered records
          </button>
        </div>
      </header>

      {error && (
        <div
          role="alert"
          className="flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
        >
          <AlertCircle size={18} className="mt-0.5 shrink-0" />
          {error}
        </div>
      )}

      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <MetricCard
          label="Total activities"
          value={metrics.total}
          description="Records matching current filters"
          icon={<Activity size={19} />}
        />
        <MetricCard
          label="Successful"
          value={metrics.successful}
          description="Successful recorded outcomes"
          icon={<CheckCircle2 size={19} />}
        />
        <MetricCard
          label="Failed"
          value={metrics.failed}
          description="Failed recorded outcomes"
          icon={<AlertCircle size={19} />}
        />
        <MetricCard
          label="Blocked"
          value={metrics.blocked}
          description="Blocked recorded outcomes"
          icon={<ShieldAlert size={19} />}
        />
      </section>

      <section className="rounded-xl border border-[#e9e5dd] bg-white p-5">
        <div className="mb-4 flex items-center gap-2">
          <Filter size={16} className="text-[#9b8358]" />
          <h2 className="font-semibold text-[#292821]">
            Filter activity
          </h2>
        </div>

        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5">
          <div className="relative">
            <Search
              size={15}
              className="absolute left-3 top-1/2 -translate-y-1/2 text-[#918c83]"
            />
            <input
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Search user or activity..."
              className="w-full rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[#a58c5d]"
            />
          </div>

          <select
            value={activityFilter}
            onChange={(event) =>
              setActivityFilter(
                event.target.value as UserActivityType | "ALL"
              )
            }
            className="rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] px-3 py-2.5 text-sm outline-none focus:border-[#a58c5d]"
          >
            <option value="ALL">All activity types</option>
            {Object.entries(activityLabels).map(([key, label]) => (
              <option key={key} value={key}>
                {label}
              </option>
            ))}
          </select>

          <select
            value={outcomeFilter}
            onChange={(event) =>
              setOutcomeFilter(
                event.target.value as UserActivityOutcome | "ALL"
              )
            }
            className="rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] px-3 py-2.5 text-sm outline-none focus:border-[#a58c5d]"
          >
            <option value="ALL">All outcomes</option>
            <option value="SUCCESS">Success</option>
            <option value="FAILED">Failed</option>
            <option value="BLOCKED">Blocked</option>
            <option value="PENDING">Pending</option>
          </select>

          <input
            type="date"
            aria-label="Activity from date"
            value={dateFrom}
            onChange={(event) => setDateFrom(event.target.value)}
            className="rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] px-3 py-2.5 text-sm outline-none focus:border-[#a58c5d]"
          />

          <input
            type="date"
            aria-label="Activity to date"
            value={dateTo}
            onChange={(event) => setDateTo(event.target.value)}
            min={dateFrom || undefined}
            className="rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] px-3 py-2.5 text-sm outline-none focus:border-[#a58c5d]"
          />
        </div>

        <div className="mt-3 flex justify-end">
          <button
            type="button"
            onClick={clearFilters}
            className="text-xs font-medium text-[#9b8358] hover:underline"
          >
            Clear all filters
          </button>
        </div>
      </section>

      <section className="rounded-xl border border-[#e9e5dd] bg-white p-5">
        <div className="mb-6 flex items-center justify-between">
          <div>
            <h2 className="font-semibold text-[#292821]">
              Activity history
            </h2>
            <p className="mt-1 text-xs text-[#918c83]">
              Newest recorded events appear first
            </p>
          </div>
          <span className="rounded-full bg-[#f3f1ec] px-3 py-1 text-xs text-[#68645c]">
            {filteredActivities.length} records
          </span>
        </div>

        {loading ? (
          <div className="py-12 text-center text-sm text-[#77736c]">
            Loading activity history...
          </div>
        ) : groupedActivities.length === 0 ? (
          <div className="py-12 text-center">
            <Activity size={30} className="mx-auto text-[#b3aa9b]" />
            <p className="mt-3 font-medium text-[#34322c]">
              No activity records found
            </p>
            <p className="mt-1 text-sm text-[#918c83]">
              Change the filters or check again later.
            </p>
          </div>
        ) : (
          <div className="space-y-8">
            {groupedActivities.map(([day, records]) => (
              <div key={day}>
                <div className="mb-4 flex items-center gap-3">
                  <h3 className="text-xs font-semibold uppercase tracking-wider text-[#918c83]">
                    {day}
                  </h3>
                  <div className="h-px flex-1 bg-[#eeeae3]" />
                  <span className="text-xs text-[#aaa397]">
                    {records.length} events
                  </span>
                </div>

                <div className="space-y-3">
                  {records.map((record) => {
                    const Icon =
                      activityIcons[record.activityType];

                    return (
                      <article
                        key={record.id}
                        className="rounded-xl border border-[#eeeae3] p-4 transition hover:bg-[#fcfbf9]"
                      >
                        <div className="flex flex-col gap-3 sm:flex-row sm:items-start">
                          <div className="flex size-10 shrink-0 items-center justify-center rounded-full bg-[#f3f1ec] text-[#9b8358]">
                            <Icon size={18} />
                          </div>

                          <div className="min-w-0 flex-1">
                            <div className="flex flex-wrap items-center gap-2">
                              <h4 className="text-sm font-semibold text-[#34322c]">
                                {activityLabels[record.activityType]}
                              </h4>

                              <span
                                className={`rounded-full px-2 py-0.5 text-xs font-medium ${outcomeStyles[record.outcome]}`}
                              >
                                {record.outcome}
                              </span>
                            </div>

                            <p className="mt-1 text-sm text-[#68645c]">
                              {record.description}
                            </p>

                            <div className="mt-3 flex flex-wrap gap-x-4 gap-y-2 text-xs text-[#918c83]">
                              <span>
                                User:{" "}
                                <button
                                  type="button"
                                  onClick={() =>
                                    onViewUser?.(record.userId)
                                  }
                                  disabled={!onViewUser}
                                  className="font-medium text-[#8a7148] hover:underline disabled:cursor-default disabled:no-underline"
                                >
                                  {record.userName}
                                </button>
                              </span>

                              {record.role && (
                                <span>Role: {record.role}</span>
                              )}

                              {record.source && (
                                <span>Source: {record.source}</span>
                              )}

                              {record.ipAddress && (
                                <span>
                                  IP: {record.ipAddress}
                                </span>
                              )}
                            </div>

                            {record.correlationId && (
                              <p className="mt-2 break-all font-mono text-[11px] text-[#aaa397]">
                                Correlation ID: {record.correlationId}
                              </p>
                            )}
                          </div>

                          <time
                            dateTime={record.occurredAt}
                            className="shrink-0 text-xs text-[#918c83]"
                          >
                            {formatDate(record.occurredAt)}
                          </time>
                        </div>
                      </article>
                    );
                  })}
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      <section className="rounded-xl border border-[#e9e5dd] bg-[#faf9f6] p-5">
        <div className="flex items-start gap-3">
          <ShieldAlert
            size={19}
            className="mt-0.5 shrink-0 text-[#9b8358]"
          />
          <div>
            <h3 className="text-sm font-semibold text-[#34322c]">
              Audit and privacy requirements
            </h3>
            <ul className="mt-2 space-y-1.5 text-xs leading-5 text-[#77736c]">
              <li>
                • Activity records should be generated by trusted
                backend services, not by browser events alone.
              </li>
              <li>
                • Keep audit records append-only and protect them from
                unauthorized modification.
              </li>
              <li>
                • Restrict access to IP addresses and other potentially
                sensitive metadata.
              </li>
              <li>
                • Apply server-side pagination, date filtering, and
                export authorization for large datasets.
              </li>
              <li>
                • Do not store passwords, access tokens, session cookies,
                or other secrets in activity descriptions.
              </li>
              <li>
                • Use server timestamps and stable event IDs to support
                reliable investigation and correlation.
              </li>
            </ul>
          </div>
        </div>
      </section>
    </main>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  Search,
  RefreshCw,
  UserPlus,
  Users,
  ShieldCheck,
  ShieldAlert,
  UserRound,
  LockKeyhole,
  MoreHorizontal,
  X,
  CheckCircle2,
  AlertCircle,
  Clock3,
  History,
  ChevronDown,
} from "lucide-react";

export type AdminUserRole =
  | "Studio Admin"
  | "Project Manager"
  | "Accounts / Finance"
  | "Architect"
  | "Designer"
  | "Operations";

export type AdminUserStatus =
  | "Active"
  | "Invited"
  | "Suspended"
  | "Deactivated";

export interface AdminManagedUser {
  id: string;
  userReference: string;
  fullName: string;
  email: string;
  phone?: string;

  role: AdminUserRole;
  status: AdminUserStatus;

  department?: string;
  assignedProjectsCount: number;

  invitedAt?: string;
  lastLoginAt?: string;
  createdAt: string;
  updatedAt: string;

  mfaEnabled: boolean;
  permissions: string[];
}

export interface AdminUserRoleManagementProps {
  users: AdminManagedUser[];

  loading?: boolean;
  error?: string;

  totalRecords: number;
  currentPage: number;
  totalPages: number;

  canCreateUsers?: boolean;
  canChangeRoles?: boolean;
  canManageAccounts?: boolean;

  onRefresh?: () => void;
  onPageChange: (page: number) => void;

  onCreateUser?: () => void;

  onUpdateRole?: (
    userId: string,
    role: AdminUserRole,
    reason: string
  ) => Promise<void>;

  onUpdateStatus?: (
    userId: string,
    status: AdminUserStatus,
    reason: string
  ) => Promise<void>;

  onResendInvitation?: (userId: string) => Promise<void>;

  onOpenUser?: (userId: string) => void;
  onOpenAccessHistory?: (userId: string) => void;
}

const ROLES: AdminUserRole[] = [
  "Studio Admin",
  "Project Manager",
  "Accounts / Finance",
  "Architect",
  "Designer",
  "Operations",
];

const STATUSES: AdminUserStatus[] = [
  "Active",
  "Invited",
  "Suspended",
  "Deactivated",
];

type UserFilters = {
  search: string;
  role: string;
  status: string;
  department: string;
};

const INITIAL_FILTERS: UserFilters = {
  search: "",
  role: "All",
  status: "All",
  department: "All",
};

function statusStyle(status: AdminUserStatus) {
  switch (status) {
    case "Active":
      return "bg-[#EAF1E8] text-[#547A51]";
    case "Invited":
      return "bg-[#F4EFE2] text-[#94743F]";
    case "Suspended":
      return "bg-[#F8EAE7] text-[#9A5147]";
    case "Deactivated":
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

function formatDate(value?: string) {
  if (!value) return "Not available";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  }).format(date);
}

export function AdminUserRoleManagement({
  users,
  loading = false,
  error,
  totalRecords,
  currentPage,
  totalPages,
  canCreateUsers = false,
  canChangeRoles = false,
  canManageAccounts = false,
  onRefresh,
  onPageChange,
  onCreateUser,
  onUpdateRole,
  onUpdateStatus,
  onResendInvitation,
  onOpenUser,
  onOpenAccessHistory,
}: AdminUserRoleManagementProps) {
  const [filters, setFilters] =
    useState<UserFilters>(INITIAL_FILTERS);

  const [selectedUser, setSelectedUser] =
    useState<AdminManagedUser | null>(null);

  const [actionMenuUserId, setActionMenuUserId] =
    useState<string | null>(null);

  const [roleDraft, setRoleDraft] =
    useState<AdminUserRole | "">("");

  const [actionReason, setActionReason] = useState("");
  const [pendingAction, setPendingAction] = useState<
    | { type: "role"; userId: string; role: AdminUserRole }
    | { type: "status"; userId: string; status: AdminUserStatus }
    | { type: "resend"; userId: string }
    | null
  >(null);

  const [busy, setBusy] = useState(false);
  const [actionError, setActionError] = useState("");

  const departments = useMemo(() => {
    return Array.from(
      new Set(
        users
          .map((user) => user.department)
          .filter((department): department is string =>
            Boolean(department)
          )
      )
    ).sort();
  }, [users]);

  const filteredUsers = useMemo(() => {
    const query = filters.search.trim().toLowerCase();

    return users.filter((user) => {
      const matchesSearch =
        !query ||
        [
          user.fullName,
          user.email,
          user.userReference,
          user.role,
          user.department ?? "",
        ].some((value) =>
          value.toLowerCase().includes(query)
        );

      const matchesRole =
        filters.role === "All" || user.role === filters.role;

      const matchesStatus =
        filters.status === "All" ||
        user.status === filters.status;

      const matchesDepartment =
        filters.department === "All" ||
        user.department === filters.department;

      return (
        matchesSearch &&
        matchesRole &&
        matchesStatus &&
        matchesDepartment
      );
    });
  }, [users, filters]);

  const activeCount = users.filter(
    (user) => user.status === "Active"
  ).length;

  const invitedCount = users.filter(
    (user) => user.status === "Invited"
  ).length;

  const suspendedCount = users.filter(
    (user) => user.status === "Suspended"
  ).length;

  function clearFilters() {
    setFilters(INITIAL_FILTERS);
  }

  function openUser(user: AdminManagedUser) {
    setSelectedUser(user);
    setRoleDraft(user.role);
    setActionReason("");
    setActionError("");
    setActionMenuUserId(null);
  }

  async function executeAction() {
    if (!pendingAction) return;

    if (
      pendingAction.type !== "resend" &&
      actionReason.trim().length < 10
    ) {
      setActionError(
        "Provide a reason with at least 10 characters."
      );
      return;
    }

    setBusy(true);
    setActionError("");

    try {
      if (pendingAction.type === "role") {
        if (!onUpdateRole) return;

        await onUpdateRole(
          pendingAction.userId,
          pendingAction.role,
          actionReason.trim()
        );
      }

      if (pendingAction.type === "status") {
        if (!onUpdateStatus) return;

        await onUpdateStatus(
          pendingAction.userId,
          pendingAction.status,
          actionReason.trim()
        );
      }

      if (pendingAction.type === "resend") {
        if (!onResendInvitation) return;

        await onResendInvitation(pendingAction.userId);
      }

      setPendingAction(null);
      setActionReason("");
      setSelectedUser(null);
    } catch {
      setActionError(
        "The action could not be completed. Refresh the user record and try again."
      );
    } finally {
      setBusy(false);
    }
  }

  function requestStatusChange(
    user: AdminManagedUser,
    status: AdminUserStatus
  ) {
    setPendingAction({
      type: "status",
      userId: user.id,
      status,
    });

    setActionReason("");
    setActionError("");
    setActionMenuUserId(null);
  }

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-9 md:px-10 md:py-12 lg:px-12">

      {/* Header */}
      <header className="flex flex-col justify-between gap-6 border-b border-[#D8D6D0] pb-8 md:flex-row md:items-end">
        <div>
          <p className="font-mono text-[9px] uppercase tracking-[0.2em] text-[#A58A64]">
            Administration / Access Control
          </p>

          <h1 className="mt-4 font-serif text-4xl text-[#171717] md:text-5xl">
            User & Role Management
          </h1>

          <p className="mt-3 max-w-xl text-sm leading-7 text-[#77736C]">
            Manage internal accounts, assigned roles, account
            status and administrative access.
          </p>
        </div>

        <div className="flex flex-wrap gap-3">
          {onRefresh && (
            <button
              type="button"
              onClick={onRefresh}
              disabled={loading}
              className="inline-flex items-center gap-2 border border-[#D8D6D0] bg-white px-5 py-3 text-[10px] uppercase tracking-widest text-[#55514A] disabled:opacity-40"
            >
              <RefreshCw size={14} />
              Refresh
            </button>
          )}

          {canCreateUsers && onCreateUser && (
            <button
              type="button"
              onClick={onCreateUser}
              className="inline-flex items-center gap-2 bg-[#171717] px-5 py-3 text-[10px] uppercase tracking-widest text-white hover:bg-[#A58A64]"
            >
              <UserPlus size={14} />
              Create User
            </button>
          )}
        </div>
      </header>

      {error && (
        <Feedback type="error">{error}</Feedback>
      )}

      {actionError && !pendingAction && (
        <Feedback type="error">{actionError}</Feedback>
      )}

      {/* Summary */}
      <section className="mt-9 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <SummaryCard
          label="Total Users"
          value={totalRecords}
          icon={<Users size={18} />}
        />

        <SummaryCard
          label="Active Accounts"
          value={activeCount}
          icon={<CheckCircle2 size={18} />}
        />

        <SummaryCard
          label="Invitations Pending"
          value={invitedCount}
          icon={<Clock3 size={18} />}
        />

        <SummaryCard
          label="Suspended Accounts"
          value={suspendedCount}
          icon={<ShieldAlert size={18} />}
        />
      </section>

      {/* Access Notice */}
      <div className="mt-7 flex items-start gap-3 border border-[#D8D6D0] bg-white p-5">
        <ShieldCheck
          size={18}
          className="mt-0.5 shrink-0 text-[#A58A64]"
        />

        <p className="text-xs leading-6 text-[#77736C]">
          Role assignment is not a substitute for permission
          enforcement. Every protected backend operation must
          verify the authenticated user&apos;s permissions independently.
        </p>
      </div>

      {/* Search and Filters */}
      <section className="mt-9">
        <div className="grid grid-cols-1 gap-3 lg:grid-cols-[minmax(0,1fr)_220px_190px_190px]">
          <div className="relative">
            <Search
              size={16}
              className="absolute left-4 top-1/2 -translate-y-1/2 text-[#99958D]"
            />

            <input
              value={filters.search}
              onChange={(event) =>
                setFilters((current) => ({
                  ...current,
                  search: event.target.value,
                }))
              }
              placeholder="Search name, email or user reference..."
              aria-label="Search users"
              className="h-12 w-full border border-[#D8D6D0] bg-white pl-11 pr-4 text-xs outline-none focus:border-[#A58A64]"
            />
          </div>

          <FilterSelect
            label="Role"
            value={filters.role}
            options={["All", ...ROLES]}
            onChange={(value) =>
              setFilters((current) => ({
                ...current,
                role: value,
              }))
            }
          />

          <FilterSelect
            label="Status"
            value={filters.status}
            options={["All", ...STATUSES]}
            onChange={(value) =>
              setFilters((current) => ({
                ...current,
                status: value,
              }))
            }
          />

          <FilterSelect
            label="Department"
            value={filters.department}
            options={["All", ...departments]}
            onChange={(value) =>
              setFilters((current) => ({
                ...current,
                department: value,
              }))
            }
          />
        </div>

        <div className="mt-4 flex items-center justify-between">
          <p className="text-[10px] text-[#77736C]">
            {filteredUsers.length.toLocaleString("en-IN")} users shown
            {" · "}
            {totalRecords.toLocaleString("en-IN")} total records
          </p>

          <button
            type="button"
            onClick={clearFilters}
            className="text-[9px] uppercase tracking-widest text-[#987543]"
          >
            Clear Filters
          </button>
        </div>
      </section>

      {/* User Directory */}
      <section className="mt-7">
        {loading ? (
          <div className="flex min-h-64 items-center justify-center border border-[#D8D6D0] bg-white">
            <p className="font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
              Loading user directory...
            </p>
          </div>
        ) : filteredUsers.length === 0 ? (
          <div className="border border-[#D8D6D0] bg-white p-12 text-center">
            <Users
              size={28}
              className="mx-auto text-[#A58A64]"
            />

            <h2 className="mt-4 font-serif text-xl text-[#171717]">
              No users found
            </h2>

            <p className="mt-2 text-xs text-[#77736C]">
              Try changing the search terms or filters.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto border border-[#D8D6D0] bg-white">
            <table className="w-full min-w-[950px] text-left">
              <thead>
                <tr className="border-b border-[#E5E2DC] bg-[#FAF9F6]">
                  {[
                    "User",
                    "Role",
                    "Department",
                    "Projects",
                    "MFA",
                    "Last Login",
                    "Status",
                    "",
                  ].map((heading) => (
                    <th
                      key={heading}
                      className="px-5 py-4 font-mono text-[8px] uppercase tracking-widest text-[#99958D]"
                    >
                      {heading}
                    </th>
                  ))}
                </tr>
              </thead>

              <tbody>
                {filteredUsers.map((user) => (
                  <tr
                    key={user.id}
                    className="border-b border-[#EAE7E0] last:border-0 hover:bg-[#FAF9F6]"
                  >
                    <td className="px-5 py-4">
                      <button
                        type="button"
                        onClick={() => openUser(user)}
                        className="text-left"
                      >
                        <p className="text-xs text-[#171717]">
                          {user.fullName}
                        </p>

                        <p className="mt-1 text-[9px] text-[#99958D]">
                          {user.email}
                        </p>

                        <p className="mt-1 font-mono text-[8px] text-[#A58A64]">
                          {user.userReference}
                        </p>
                      </button>
                    </td>

                    <td className="px-5 py-4 text-xs text-[#55514A]">
                      {user.role}
                    </td>

                    <td className="px-5 py-4 text-xs text-[#77736C]">
                      {user.department ?? "—"}
                    </td>

                    <td className="px-5 py-4 text-xs tabular-nums text-[#55514A]">
                      {user.assignedProjectsCount}
                    </td>

                    <td className="px-5 py-4">
                      {user.mfaEnabled ? (
                        <span className="inline-flex items-center gap-1 text-[9px] text-[#547A51]">
                          <ShieldCheck size={13} />
                          Enabled
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-1 text-[9px] text-[#9A5147]">
                          <ShieldAlert size={13} />
                          Disabled
                        </span>
                      )}
                    </td>

                    <td className="px-5 py-4 text-[10px] text-[#77736C]">
                      {formatDate(user.lastLoginAt)}
                    </td>

                    <td className="px-5 py-4">
                      <span
                        className={`inline-block px-3 py-2 text-[8px] uppercase tracking-widest ${statusStyle(user.status)}`}
                      >
                        {user.status}
                      </span>
                    </td>

                    <td className="relative px-5 py-4">
                      <button
                        type="button"
                        aria-label={`Actions for ${user.fullName}`}
                        aria-expanded={actionMenuUserId === user.id}
                        onClick={() =>
                          setActionMenuUserId((current) =>
                            current === user.id ? null : user.id
                          )
                        }
                        className="border border-[#E5E2DC] p-2 text-[#77736C]"
                      >
                        <MoreHorizontal size={16} />
                      </button>

                      {actionMenuUserId === user.id && (
                        <div className="absolute right-5 top-14 z-20 w-48 border border-[#D8D6D0] bg-white p-2 shadow-xl">
                          <MenuAction
                            label="View User"
                            onClick={() => openUser(user)}
                          />

                          {onOpenAccessHistory && (
                            <MenuAction
                              label="Access History"
                              onClick={() => {
                                onOpenAccessHistory(user.id);
                                setActionMenuUserId(null);
                              }}
                            />
                          )}

                          {user.status === "Invited" &&
                            onResendInvitation && (
                              <MenuAction
                                label="Resend Invitation"
                                onClick={() => {
                                  setPendingAction({
                                    type: "resend",
                                    userId: user.id,
                                  });
                                  setActionMenuUserId(null);
                                }}
                              />
                            )}

                          {canManageAccounts &&
                            user.status === "Active" && (
                              <MenuAction
                                label="Suspend Account"
                                danger
                                onClick={() =>
                                  requestStatusChange(
                                    user,
                                    "Suspended"
                                  )
                                }
                              />
                            )}

                          {canManageAccounts &&
                            user.status === "Suspended" && (
                              <MenuAction
                                label="Reactivate Account"
                                onClick={() =>
                                  requestStatusChange(
                                    user,
                                    "Active"
                                  )
                                }
                              />
                            )}

                          {canManageAccounts &&
                            user.status !== "Deactivated" && (
                              <MenuAction
                                label="Deactivate Account"
                                danger
                                onClick={() =>
                                  requestStatusChange(
                                    user,
                                    "Deactivated"
                                  )
                                }
                              />
                            )}
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>

      {/* Pagination */}
      {!loading && totalPages > 1 && (
        <div className="mt-6 flex flex-wrap items-center justify-between gap-4">
          <p className="text-[10px] text-[#77736C]">
            Page {currentPage} of {totalPages}
          </p>

          <div className="flex gap-2">
            <button
              type="button"
              disabled={currentPage <= 1}
              onClick={() => onPageChange(currentPage - 1)}
              className="border border-[#D8D6D0] bg-white px-4 py-2 text-[9px] uppercase tracking-widest disabled:opacity-40"
            >
              Previous
            </button>

            <button
              type="button"
              disabled={currentPage >= totalPages}
              onClick={() => onPageChange(currentPage + 1)}
              className="border border-[#171717] bg-[#171717] px-4 py-2 text-[9px] uppercase tracking-widest text-white disabled:opacity-40"
            >
              Next
            </button>
          </div>
        </div>
      )}

      {/* User Detail Drawer */}
      {selectedUser && (
        <UserDetailDrawer
          user={selectedUser}
          editableRole={canChangeRoles}
          editableStatus={canManageAccounts}
          roleDraft={roleDraft}
          setRoleDraft={setRoleDraft}
          actionReason={actionReason}
          setActionReason={setActionReason}
          onClose={() => setSelectedUser(null)}
          onSaveRole={() => {
            if (!roleDraft || roleDraft === selectedUser.role) return;

            setPendingAction({
              type: "role",
              userId: selectedUser.id,
              role: roleDraft,
            });
            setActionError("");
          }}
          onStatusChange={(status) =>
            requestStatusChange(selectedUser, status)
          }
          onOpenHistory={() =>
            onOpenAccessHistory?.(selectedUser.id)
          }
          onOpenUser={() => onOpenUser?.(selectedUser.id)}
        />
      )}

      {/* Action Confirmation */}
      {pendingAction && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black/50 p-5">
          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="user-action-title"
            className="w-full max-w-lg border border-[#D8D6D0] bg-[#F7F5F0] p-6 shadow-2xl"
          >
            <div className="flex items-center gap-3">
              <ShieldAlert
                size={20}
                className="text-[#A58A64]"
              />

              <h2
                id="user-action-title"
                className="font-serif text-2xl text-[#171717]"
              >
                Confirm User Action
              </h2>
            </div>

            <p className="mt-4 text-xs leading-7 text-[#77736C]">
              {pendingAction.type === "role" &&
                `Change this user's role to ${pendingAction.role}?`}

              {pendingAction.type === "status" &&
                `Change this account status to ${pendingAction.status}?`}

              {pendingAction.type === "resend" &&
                "Request a new invitation message for this user?"}
            </p>

            {pendingAction.type !== "resend" && (
              <label className="mt-5 block">
                <span className="font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
                  Reason for action
                </span>

                <textarea
                  value={actionReason}
                  onChange={(event) =>
                    setActionReason(event.target.value)
                  }
                  rows={3}
                  maxLength={1000}
                  className="mt-3 w-full border border-[#D8D6D0] bg-white p-4 text-xs outline-none focus:border-[#A58A64]"
                  placeholder="Explain why this change is required..."
                />
              </label>
            )}

            {actionError && (
              <p className="mt-4 text-xs text-[#9A5147]">
                {actionError}
              </p>
            )}

            <div className="mt-6 flex justify-end gap-3">
              <button
                type="button"
                disabled={busy}
                onClick={() => {
                  setPendingAction(null);
                  setActionError("");
                }}
                className="border border-[#D8D6D0] bg-white px-5 py-3 text-[9px] uppercase tracking-widest text-[#55514A]"
              >
                Cancel
              </button>

              <button
                type="button"
                disabled={busy}
                onClick={executeAction}
                className="bg-[#171717] px-5 py-3 text-[9px] uppercase tracking-widest text-white disabled:opacity-40"
              >
                {busy ? "Processing..." : "Confirm Action"}
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}

function SummaryCard({
  label,
  value,
  icon,
}: {
  label: string;
  value: number;
  icon: ReactNode;
}) {
  return (
    <div className="border border-[#D8D6D0] bg-white p-5">
      <div className="flex items-center justify-between">
        <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
          {label}
        </p>

        <span className="text-[#A58A64]">{icon}</span>
      </div>

      <p className="mt-5 font-serif text-3xl text-[#171717]">
        {value.toLocaleString("en-IN")}
      </p>
    </div>
  );
}

function FilterSelect({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: string;
  options: string[];
  onChange: (value: string) => void;
}) {
  return (
    <label className="relative block">
      <span className="mb-2 block font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
        {label}
      </span>

      <select
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="h-12 w-full appearance-none border border-[#D8D6D0] bg-white px-4 pr-9 text-xs text-[#55514A] outline-none focus:border-[#A58A64]"
      >
        {options.map((option) => (
          <option key={option} value={option}>
            {option}
          </option>
        ))}
      </select>

      <ChevronDown
        size={13}
        className="pointer-events-none absolute bottom-4 right-3 text-[#99958D]"
      />
    </label>
  );
}

function MenuAction({
  label,
  onClick,
  danger = false,
}: {
  label: string;
  onClick: () => void;
  danger?: boolean;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`w-full px-3 py-2.5 text-left text-[10px] hover:bg-[#F7F5F0] ${
        danger ? "text-[#9A5147]" : "text-[#55514A]"
      }`}
    >
      {label}
    </button>
  );
}

function UserDetailDrawer({
  user,
  editableRole,
  editableStatus,
  roleDraft,
  setRoleDraft,
  actionReason,
  setActionReason,
  onClose,
  onSaveRole,
  onStatusChange,
  onOpenHistory,
  onOpenUser,
}: {
  user: AdminManagedUser;
  editableRole: boolean;
  editableStatus: boolean;
  roleDraft: AdminUserRole | "";
  setRoleDraft: (role: AdminUserRole) => void;
  actionReason: string;
  setActionReason: (reason: string) => void;
  onClose: () => void;
  onSaveRole: () => void;
  onStatusChange: (status: AdminUserStatus) => void;
  onOpenHistory: () => void;
  onOpenUser: () => void;
}) {
  return (
    <div className="fixed inset-0 z-[100] flex justify-end bg-black/40">
      <aside
        role="dialog"
        aria-modal="true"
        aria-labelledby="user-detail-title"
        className="h-full w-full max-w-xl overflow-y-auto bg-[#F7F5F0] shadow-2xl"
      >
        <header className="sticky top-0 z-10 flex items-center justify-between border-b border-[#D8D6D0] bg-[#F7F5F0] px-6 py-5">
          <div>
            <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
              User Account
            </p>

            <h2
              id="user-detail-title"
              className="mt-2 font-serif text-2xl text-[#171717]"
            >
              User Details
            </h2>
          </div>

          <button
            type="button"
            onClick={onClose}
            aria-label="Close user details"
            className="border border-[#D8D6D0] bg-white p-2"
          >
            <X size={17} />
          </button>
        </header>

        <div className="space-y-7 p-6">
          <section className="border border-[#D8D6D0] bg-white p-5">
            <div className="flex items-center gap-4">
              <div className="flex h-12 w-12 items-center justify-center bg-[#EAE7E0] text-[#A58A64]">
                <UserRound size={21} />
              </div>

              <div className="min-w-0">
                <h3 className="break-words font-serif text-xl text-[#171717]">
                  {user.fullName}
                </h3>

                <p className="mt-1 break-all text-[10px] text-[#77736C]">
                  {user.email}
                </p>

                <p className="mt-2 font-mono text-[8px] uppercase tracking-widest text-[#A58A64]">
                  {user.userReference}
                </p>
              </div>
            </div>

            <span
              className={`mt-5 inline-block px-3 py-2 text-[8px] uppercase tracking-widest ${statusStyle(user.status)}`}
            >
              {user.status}
            </span>
          </section>

          <DetailGroup title="Account Information">
            <DetailRow label="User ID" value={user.id} />
            <DetailRow label="Role" value={user.role} />
            <DetailRow
              label="Department"
              value={user.department ?? "Not assigned"}
            />
            <DetailRow
              label="Phone"
              value={user.phone ?? "Not provided"}
            />
            <DetailRow
              label="Assigned Projects"
              value={String(user.assignedProjectsCount)}
            />
            <DetailRow
              label="Created"
              value={formatDate(user.createdAt)}
            />
            <DetailRow
              label="Last Updated"
              value={formatDate(user.updatedAt)}
            />
            <DetailRow
              label="Last Login"
              value={formatDate(user.lastLoginAt)}
            />
            <DetailRow
              label="Invitation Sent"
              value={formatDate(user.invitedAt)}
            />
            <DetailRow
              label="Multi-factor Authentication"
              value={user.mfaEnabled ? "Enabled" : "Not enabled"}
            />
          </DetailGroup>

          <DetailGroup title="Assigned Permissions">
            {user.permissions.length === 0 ? (
              <p className="text-xs text-[#77736C]">
                No permission details supplied.
              </p>
            ) : (
              <div className="flex flex-wrap gap-2">
                {user.permissions.map((permission) => (
                  <span
                    key={permission}
                    className="border border-[#D8D6D0] bg-[#FAF9F6] px-3 py-2 text-[9px] text-[#55514A]"
                  >
                    {permission}
                  </span>
                ))}
              </div>
            )}
          </DetailGroup>

          {editableRole && (
            <DetailGroup title="Role Assignment">
              <label className="block">
                <span className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
                  New Role
                </span>

                <select
                  value={roleDraft}
                  onChange={(event) =>
                    setRoleDraft(event.target.value as AdminUserRole)
                  }
                  className="mt-2 h-11 w-full border border-[#D8D6D0] bg-white px-3 text-xs text-[#33312D] outline-none focus:border-[#A58A64]"
                >
                  {ROLES.map((role) => (
                    <option key={role} value={role}>
                      {role}
                    </option>
                  ))}
                </select>
              </label>

              <label className="mt-4 block">
                <span className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
                  Reason
                </span>

                <textarea
                  value={actionReason}
                  onChange={(event) =>
                    setActionReason(event.target.value)
                  }
                  rows={2}
                  maxLength={1000}
                  className="mt-2 w-full border border-[#D8D6D0] bg-white p-3 text-xs outline-none focus:border-[#A58A64]"
                  placeholder="Reason for role change..."
                />
              </label>

              <button
                type="button"
                onClick={onSaveRole}
                disabled={
                  !roleDraft ||
                  roleDraft === user.role ||
                  actionReason.trim().length < 10
                }
                className="mt-4 bg-[#171717] px-5 py-3 text-[9px] uppercase tracking-widest text-white disabled:opacity-40"
              >
                Request Role Change
              </button>
            </DetailGroup>
          )}

          {editableStatus && (
            <DetailGroup title="Account Status">
              <div className="flex flex-wrap gap-2">
                {user.status === "Active" && (
                  <ActionButton
                    danger
                    onClick={() => onStatusChange("Suspended")}
                  >
                    Suspend Account
                  </ActionButton>
                )}

                {user.status === "Suspended" && (
                  <ActionButton
                    onClick={() => onStatusChange("Active")}
                  >
                    Reactivate Account
                  </ActionButton>
                )}

                {user.status !== "Deactivated" && (
                  <ActionButton
                    danger
                    onClick={() => onStatusChange("Deactivated")}
                  >
                    Deactivate Account
                  </ActionButton>
                )}
              </div>
            </DetailGroup>
          )}

          <div className="flex flex-wrap gap-3">
            <button
              type="button"
              onClick={onOpenHistory}
              className="inline-flex items-center gap-2 border border-[#D8D6D0] bg-white px-4 py-3 text-[9px] uppercase tracking-widest text-[#55514A]"
            >
              <History size={13} />
              Access History
            </button>

            <button
              type="button"
              onClick={onOpenUser}
              className="inline-flex items-center gap-2 border border-[#D8D6D0] bg-white px-4 py-3 text-[9px] uppercase tracking-widest text-[#55514A]"
            >
              Open Full Record
            </button>
          </div>
        </div>
      </aside>
    </div>
  );
}

function DetailGroup({
  title,
  children,
}: {
  title: string;
  children: ReactNode;
}) {
  return (
    <section>
      <h3 className="mb-3 font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
        {title}
      </h3>

      <div className="border border-[#D8D6D0] bg-white p-5">
        {children}
      </div>
    </section>
  );
}

function DetailRow({
  label,
  value,
}: {
  label: string;
  value: string;
}) {
  return (
    <div className="flex flex-col justify-between gap-2 border-b border-[#EAE7E0] py-3 last:border-0 sm:flex-row">
      <span className="font-mono text-[8px] uppercase tracking-widest text-[#99958D]">
        {label}
      </span>

      <span className="break-all text-xs text-[#33312D] sm:max-w-[65%] sm:text-right">
        {value}
      </span>
    </div>
  );
}

function ActionButton({
  children,
  onClick,
  danger = false,
}: {
  children: ReactNode;
  onClick: () => void;
  danger?: boolean;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`border px-4 py-3 text-[9px] uppercase tracking-widest ${
        danger
          ? "border-[#E3C9C5] bg-[#FAF3F1] text-[#9A5147]"
          : "border-[#D8D6D0] bg-white text-[#55514A]"
      }`}
    >
      {children}
    </button>
  );
}

function Feedback({
  children,
  type,
}: {
  children: ReactNode;
  type: "error" | "success";
}) {
  return (
    <div
      role={type === "error" ? "alert" : "status"}
      className={`mt-6 flex items-start gap-3 border p-4 ${
        type === "error"
          ? "border-[#E3C9C5] bg-[#FAF3F1] text-[#9A5147]"
          : "border-[#D2DFCE] bg-[#F0F5EE] text-[#547A51]"
      }`}
    >
      {type === "error" ? (
        <AlertCircle size={17} />
      ) : (
        <CheckCircle2 size={17} />
      )}

      <p className="text-xs leading-6">{children}</p>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import type { ReactNode } from "react";
import {
  Activity,
  AlertCircle,
  CheckCircle2,
  Clock3,
  Copy,
  Eye,
  Filter,
  RotateCcw,
  Search,
  Webhook,
  XCircle,
} from "lucide-react";

export type WebhookDeliveryStatus =
  | "DELIVERED"
  | "FAILED"
  | "PENDING"
  | "RETRYING"
  | "EXHAUSTED";

export interface WebhookAttempt {
  id: string;
  attemptedAt: string;
  responseCode?: number;
  durationMs?: number;
  outcome: "SUCCESS" | "FAILURE" | "TIMEOUT";
  responseSummary?: string;
}

export interface WebhookEvent {
  id: string;
  eventType: string;
  destinationName: string;
  destinationUrl: string;
  status: WebhookDeliveryStatus;
  createdAt: string;
  lastAttemptAt?: string;
  attemptCount: number;
  maxAttempts: number;
  nextRetryAt?: string;
  correlationId?: string;
  payloadSummary: string;
  attempts: WebhookAttempt[];
}

interface AdminWebhookEventCenterProps {
  events: WebhookEvent[];
  loading?: boolean;
  error?: string | null;
  onRefresh?: () => void;
  onRequestRetry?: (eventId: string) => void;
  onViewDetails?: (event: WebhookEvent) => void;
  onCopyEventId?: (eventId: string) => void;
  onCopyCorrelationId?: (correlationId: string) => void;
}

const statusConfig: Record<
  WebhookDeliveryStatus,
  { label: string; className: string; icon: ReactNode }
> = {
  DELIVERED: {
    label: "Delivered",
    className: "bg-emerald-50 text-emerald-700",
    icon: <CheckCircle2 size={14} />,
  },
  FAILED: {
    label: "Failed",
    className: "bg-red-50 text-red-700",
    icon: <XCircle size={14} />,
  },
  PENDING: {
    label: "Pending",
    className: "bg-amber-50 text-amber-700",
    icon: <Clock3 size={14} />,
  },
  RETRYING: {
    label: "Retrying",
    className: "bg-blue-50 text-blue-700",
    icon: <RotateCcw size={14} />,
  },
  EXHAUSTED: {
    label: "Retries exhausted",
    className: "bg-rose-50 text-rose-700",
    icon: <AlertCircle size={14} />,
  },
};

const filters = [
  "ALL",
  "DELIVERED",
  "FAILED",
  "PENDING",
  "RETRYING",
  "EXHAUSTED",
] as const;

type FilterValue = (typeof filters)[number];

function formatDate(value?: string) {
  if (!value) return "—";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function StatusBadge({ status }: { status: WebhookDeliveryStatus }) {
  const config = statusConfig[status];

  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium ${config.className}`}
    >
      {config.icon}
      {config.label}
    </span>
  );
}

function MetricCard({
  label,
  value,
  icon,
  description,
}: {
  label: string;
  value: number;
  icon: ReactNode;
  description: string;
}) {
  return (
    <div className="rounded-xl border border-[#e9e5dd] bg-white p-5">
      <div className="flex items-center justify-between">
        <p className="text-sm text-[#77736c]">{label}</p>
        <span className="text-[#9b8358]">{icon}</span>
      </div>

      <p className="mt-3 text-3xl font-semibold tracking-tight text-[#25241f]">
        {value}
      </p>

      <p className="mt-1 text-xs text-[#918c83]">{description}</p>
    </div>
  );
}

export default function AdminWebhookEventCenter({
  events,
  loading = false,
  error,
  onRefresh,
  onRequestRetry,
  onViewDetails,
  onCopyEventId,
  onCopyCorrelationId,
}: AdminWebhookEventCenterProps) {
  const [search, setSearch] = useState("");
  const [activeFilter, setActiveFilter] =
    useState<FilterValue>("ALL");

  const metrics = useMemo(
    () => ({
      total: events.length,
      delivered: events.filter((e) => e.status === "DELIVERED").length,
      failed: events.filter((e) => e.status === "FAILED").length,
      pending: events.filter(
        (e) => e.status === "PENDING" || e.status === "RETRYING"
      ).length,
      exhausted: events.filter((e) => e.status === "EXHAUSTED").length,
    }),
    [events]
  );

  const filteredEvents = useMemo(() => {
    const query = search.trim().toLowerCase();

    return events.filter((event) => {
      const matchesFilter =
        activeFilter === "ALL" || event.status === activeFilter;

      const searchable = [
        event.id,
        event.eventType,
        event.destinationName,
        event.destinationUrl,
        event.correlationId ?? "",
      ]
        .join(" ")
        .toLowerCase();

      return matchesFilter && (!query || searchable.includes(query));
    });
  }, [events, search, activeFilter]);

  const handleRetry = (event: WebhookEvent) => {
    if (!onRequestRetry) return;

    const retryAllowed =
      event.status === "FAILED" &&
      event.attemptCount < event.maxAttempts;

    if (!retryAllowed) return;

    onRequestRetry(event.id);
  };

  return (
    <main className="space-y-7">
      <header className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center">
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-medium uppercase tracking-[0.18em] text-[#9b8358]">
            <Webhook size={15} />
            Platform operations
          </div>

          <h1 className="text-2xl font-semibold tracking-tight text-[#25241f]">
            Webhook Event Center
          </h1>

          <p className="mt-1 max-w-2xl text-sm text-[#77736c]">
            Monitor outbound event delivery, inspect failures, and request
            controlled retries.
          </p>
        </div>

        <button
          type="button"
          onClick={onRefresh}
          disabled={!onRefresh || loading}
          className="inline-flex items-center justify-center gap-2 rounded-lg border border-[#ded9cf] bg-white px-4 py-2.5 text-sm font-medium text-[#34322c] transition hover:bg-[#f8f6f1] disabled:cursor-not-allowed disabled:opacity-50"
        >
          <RotateCcw size={15} className={loading ? "animate-spin" : ""} />
          Refresh events
        </button>
      </header>

      {error && (
        <div
          role="alert"
          className="flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"
        >
          <AlertCircle size={18} className="mt-0.5 shrink-0" />
          <span>{error}</span>
        </div>
      )}

      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">
        <MetricCard
          label="Total events"
          value={metrics.total}
          icon={<Activity size={19} />}
          description="Events in the supplied dataset"
        />
        <MetricCard
          label="Delivered"
          value={metrics.delivered}
          icon={<CheckCircle2 size={19} />}
          description="Marked as successfully delivered"
        />
        <MetricCard
          label="Failed"
          value={metrics.failed}
          icon={<XCircle size={19} />}
          description="Failed delivery records"
        />
        <MetricCard
          label="Pending / retrying"
          value={metrics.pending}
          icon={<Clock3 size={19} />}
          description="Awaiting delivery or another attempt"
        />
        <MetricCard
          label="Exhausted"
          value={metrics.exhausted}
          icon={<AlertCircle size={19} />}
          description="Maximum attempts recorded"
        />
      </section>

      <section className="overflow-hidden rounded-xl border border-[#e9e5dd] bg-white">
        <div className="space-y-4 border-b border-[#eeeae3] p-5">
          <div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-center">
            <div>
              <h2 className="font-semibold text-[#292821]">
                Delivery records
              </h2>
              <p className="mt-1 text-xs text-[#918c83]">
                {filteredEvents.length} matching records
              </p>
            </div>

            <div className="relative w-full lg:max-w-sm">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#918c83]"
              />
              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search event, destination, correlation ID..."
                className="w-full rounded-lg border border-[#e5e0d7] bg-[#fcfbf9] py-2.5 pl-9 pr-3 text-sm outline-none transition focus:border-[#a58c5d]"
              />
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <Filter size={15} className="mr-1 text-[#918c83]" />

            {filters.map((filter) => (
              <button
                key={filter}
                type="button"
                onClick={() => setActiveFilter(filter)}
                className={`rounded-full px-3 py-1.5 text-xs font-medium transition ${
                  activeFilter === filter
                    ? "bg-[#292821] text-white"
                    : "border border-[#e8e3da] text-[#77736c] hover:bg-[#f7f5f0]"
                }`}
              >
                {filter === "ALL"
                  ? "All events"
                  : statusConfig[filter].label}
              </button>
            ))}
          </div>
        </div>

        {loading ? (
          <div className="p-12 text-center text-sm text-[#77736c]">
            Loading webhook events...
          </div>
        ) : filteredEvents.length === 0 ? (
          <div className="p-12 text-center">
            <Webhook size={30} className="mx-auto text-[#b3aa9b]" />
            <p className="mt-3 font-medium text-[#34322c]">
              No webhook events found
            </p>
            <p className="mt-1 text-sm text-[#918c83]">
              Try another search term or status filter.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[1050px] text-left">
              <thead className="bg-[#faf9f6] text-xs uppercase tracking-wider text-[#918c83]">
                <tr>
                  <th className="px-5 py-3 font-medium">Event</th>
                  <th className="px-5 py-3 font-medium">Destination</th>
                  <th className="px-5 py-3 font-medium">Status</th>
                  <th className="px-5 py-3 font-medium">Attempts</th>
                  <th className="px-5 py-3 font-medium">Last attempt</th>
                  <th className="px-5 py-3 text-right font-medium">
                    Actions
                  </th>
                </tr>
              </thead>

              <tbody className="divide-y divide-[#f0ede7]">
                {filteredEvents.map((event) => {
                  const canRetry =
                    event.status === "FAILED" &&
                    event.attemptCount < event.maxAttempts;

                  return (
                    <tr key={event.id} className="hover:bg-[#fcfbf9]">
                      <td className="px-5 py-4">
                        <p className="font-medium text-[#34322c]">
                          {event.eventType}
                        </p>
                        <p className="mt-1 font-mono text-xs text-[#918c83]">
                          {event.id}
                        </p>
                        <p className="mt-1 text-xs text-[#aaa397]">
                          {formatDate(event.createdAt)}
                        </p>
                      </td>

                      <td className="max-w-[240px] px-5 py-4">
                        <p className="truncate text-sm font-medium text-[#34322c]">
                          {event.destinationName}
                        </p>
                        <p className="mt-1 truncate text-xs text-[#918c83]">
                          {event.destinationUrl}
                        </p>
                      </td>

                      <td className="px-5 py-4">
                        <StatusBadge status={event.status} />
                      </td>

                      <td className="px-5 py-4">
                        <span className="text-sm font-medium text-[#34322c]">
                          {event.attemptCount}
                        </span>
                        <span className="text-xs text-[#918c83]">
                          {" "}/ {event.maxAttempts}
                        </span>
                      </td>

                      <td className="px-5 py-4 text-sm text-[#77736c]">
                        {formatDate(event.lastAttemptAt)}
                      </td>

                      <td className="px-5 py-4">
                        <div className="flex justify-end gap-2">
                          <button
                            type="button"
                            onClick={() => onViewDetails?.(event)}
                            disabled={!onViewDetails}
                            title="View event details"
                            className="rounded-lg border border-[#e8e3da] p-2 text-[#77736c] hover:bg-[#f7f5f0] disabled:opacity-40"
                          >
                            <Eye size={15} />
                          </button>

                          <button
                            type="button"
                            onClick={() => handleRetry(event)}
                            disabled={!canRetry || !onRequestRetry}
                            title={
                              canRetry
                                ? "Request delivery retry"
                                : "Retry unavailable"
                            }
                            className="rounded-lg border border-[#e8e3da] p-2 text-[#9b8358] hover:bg-[#f7f5f0] disabled:cursor-not-allowed disabled:opacity-30"
                          >
                            <RotateCcw size={15} />
                          </button>

                          <button
                            type="button"
                            onClick={() => onCopyEventId?.(event.id)}
                            disabled={!onCopyEventId}
                            title="Copy event ID"
                            className="rounded-lg border border-[#e8e3da] p-2 text-[#77736c] hover:bg-[#f7f5f0] disabled:opacity-40"
                          >
                            <Copy size={15} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </section>

      <section className="rounded-xl border border-[#e9e5dd] bg-[#faf9f6] p-5">
        <div className="flex items-start gap-3">
          <AlertCircle size={18} className="mt-0.5 shrink-0 text-[#9b8358]" />
          <div>
            <h3 className="text-sm font-semibold text-[#34322c]">
              Delivery and retry safeguards
            </h3>
            <ul className="mt-2 space-y-1.5 text-xs leading-5 text-[#77736c]">
              <li>
                • Retry requests must be validated and executed by the backend.
              </li>
              <li>
                • Enforce retry limits, backoff, idempotency, and destination
                authorization server-side.
              </li>
              <li>
                • Never expose signing secrets, authentication headers, or
                complete sensitive payloads in this interface.
              </li>
              <li>
                • Record the requesting administrator and outcome in an
                immutable audit trail.
              </li>
              <li>
                • Treat delivery status as backend-authoritative, not as proof
                that a downstream business action was completed.
              </li>
            </ul>
          </div>
        </div>
      </section>
    </main>
  );
}

"use client";

import {
  ArrowUpRight,
  Building2,
  CalendarDays,
  CheckCircle2,
  Clock3,
  FileText,
  FolderOpen,
  Bell,
  IndianRupee,
  AlertCircle,
} from "lucide-react";

export interface DashboardProject {
  id: string;
  name: string;
  location: string;
  status: string;
  updatedAt: string;
}

export interface DashboardInvoice {
  id: string;
  invoiceNumber: string;
  projectName: string;
  outstandingAmount: number;
  dueDate: string;
  status: string;
}

export interface DashboardActivity {
  id: string;
  title: string;
  description: string;
  date: string;
  category: "Project" | "Invoice" | "Payment" | "Dispute" | "Document";
}

export interface ClientDashboardData {
  clientName: string;
  projects: DashboardProject[];
  invoices: DashboardInvoice[];
  activities: DashboardActivity[];
  unreadNotifications: number;
}

interface ClientPortalDashboardProps {
  data: ClientDashboardData;
  loading?: boolean;
  error?: string;
  onOpenProjects: () => void;
  onOpenProject: (project: DashboardProject) => void;
  onOpenInvoices: () => void;
  onOpenInvoice: (invoice: DashboardInvoice) => void;
  onOpenDocuments: () => void;
  onOpenNotifications: () => void;
  onRetry?: () => void;
}

function formatCurrency(amount: number) {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 2,
  }).format(amount);
}

function getActivityIcon(category: DashboardActivity["category"]) {
  switch (category) {
    case "Project":
      return <Building2 size={17} />;

    case "Invoice":
      return <FileText size={17} />;

    case "Payment":
      return <IndianRupee size={17} />;

    case "Dispute":
      return <AlertCircle size={17} />;

    case "Document":
      return <FolderOpen size={17} />;
  }
}

export function ClientPortalDashboard({
  data,
  loading = false,
  error,
  onOpenProjects,
  onOpenProject,
  onOpenInvoices,
  onOpenInvoice,
  onOpenDocuments,
  onOpenNotifications,
  onRetry,
}: ClientPortalDashboardProps) {
  const outstandingTotal = data.invoices.reduce(
    (total, invoice) =>
      total + Math.max(0, invoice.outstandingAmount),
    0
  );

  if (loading) {
    return (
      <div className="min-h-screen bg-[#F2F0EB] p-8">
        <p className="text-sm text-[#77736C]">
          Loading your client dashboard...
        </p>
      </div>
    );
  }

  if (error) {
    return (
      <section
        role="alert"
        className="border border-[#E3C9C5] bg-[#FAF3F1] p-7"
      >
        <AlertCircle size={22} className="text-[#9A5147]" />

        <h2 className="mt-4 font-serif text-2xl text-[#773B34]">
          Dashboard unavailable
        </h2>

        <p className="mt-3 text-sm leading-7 text-[#805B55]">
          {error}
        </p>

        {onRetry && (
          <button
            type="button"
            onClick={onRetry}
            className="mt-5 text-xs uppercase tracking-widest text-[#773B34] underline"
          >
            Try Again
          </button>
        )}
      </section>
    );
  }

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-9 md:px-10 md:py-12">
      <div className="mx-auto max-w-7xl">

        {/* Top Header */}
        <header className="flex flex-col justify-between gap-6 border-b border-[#D8D6D0] pb-9 sm:flex-row sm:items-end">
          <div>
            <p className="font-mono text-[10px] uppercase tracking-[0.2em] text-[#A58A64]">
              ARCHEON DESIGN STUDIO / CLIENT PORTAL
            </p>

            <h1 className="mt-5 font-serif text-4xl text-[#171717] md:text-5xl">
              Welcome, {data.clientName}
            </h1>

            <p className="mt-4 text-sm leading-7 text-[#77736C]">
              Your projects, shared documents and account activity
              in one place.
            </p>
          </div>

          <button
            type="button"
            onClick={onOpenNotifications}
            className="relative flex w-fit items-center gap-3 border border-[#D8D6D0] bg-white px-5 py-3 text-xs text-[#33312D] hover:border-[#A58A64]"
          >
            <Bell size={17} className="text-[#A58A64]" />
            Notifications

            {data.unreadNotifications > 0 && (
              <span className="flex h-5 min-w-5 items-center justify-center rounded-full bg-[#A58A64] px-1 text-[9px] text-white">
                {data.unreadNotifications > 99
                  ? "99+"
                  : data.unreadNotifications}
              </span>
            )}
          </button>
        </header>

        {/* Overview Cards */}
        <section
          aria-label="Account overview"
          className="mt-8 grid grid-cols-1 gap-px border border-[#D8D6D0] bg-[#D8D6D0] sm:grid-cols-2 lg:grid-cols-4"
        >
          <OverviewCard
            label="Assigned Projects"
            value={String(data.projects.length)}
            icon={<Building2 size={19} />}
          />

          <OverviewCard
            label="Outstanding Balance"
            value={formatCurrency(outstandingTotal)}
            icon={<IndianRupee size={19} />}
          />

          <OverviewCard
            label="Invoices"
            value={String(data.invoices.length)}
            icon={<FileText size={19} />}
          />

          <OverviewCard
            label="Unread Notifications"
            value={String(data.unreadNotifications)}
            icon={<Bell size={19} />}
          />
        </section>

        {/* Projects */}
        <section className="mt-14">
          <div className="flex items-end justify-between gap-4 border-b border-[#D8D6D0] pb-5">
            <div>
              <p className="font-mono text-[10px] uppercase tracking-widest text-[#A58A64]">
                Your Work
              </p>

              <h2 className="mt-3 font-serif text-3xl text-[#171717]">
                My Projects
              </h2>
            </div>

            <button
              type="button"
              onClick={onOpenProjects}
              className="inline-flex items-center gap-2 text-[10px] uppercase tracking-widest text-[#77736C] hover:text-[#A58A64]"
            >
              All Projects
              <ArrowUpRight size={15} />
            </button>
          </div>

          {data.projects.length === 0 ? (
            <EmptyState message="Projects assigned to your account will appear here." />
          ) : (
            <div className="grid grid-cols-1 gap-5 py-7 md:grid-cols-2">
              {data.projects.slice(0, 4).map((project) => (
                <button
                  key={project.id}
                  type="button"
                  onClick={() => onOpenProject(project)}
                  className="border border-[#D8D6D0] bg-white p-6 text-left transition-colors hover:border-[#A58A64] md:p-7"
                >
                  <div className="flex items-start justify-between gap-4">
                    <span className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                      Assigned Project
                    </span>

                    <ArrowUpRight
                      size={17}
                      className="text-[#99958D]"
                    />
                  </div>

                  <h3 className="mt-5 font-serif text-2xl text-[#171717]">
                    {project.name}
                  </h3>

                  <p className="mt-2 text-xs text-[#77736C]">
                    {project.location}
                  </p>

                  <div className="mt-7 flex flex-wrap items-center justify-between gap-3 border-t border-[#E5E2DC] pt-5">
                    <span className="bg-[#ECEAE5] px-3 py-2 text-[9px] uppercase tracking-widest text-[#66635D]">
                      {project.status}
                    </span>

                    <span className="font-mono text-[9px] text-[#99958D]">
                      Updated {project.updatedAt}
                    </span>
                  </div>
                </button>
              ))}
            </div>
          )}
        </section>

        {/* Invoices and Quick Access */}
        <section className="mt-10 grid grid-cols-1 gap-10 lg:grid-cols-12">

          {/* Invoices */}
          <div className="lg:col-span-7">
            <div className="flex items-end justify-between gap-4 border-b border-[#D8D6D0] pb-5">
              <div>
                <p className="font-mono text-[10px] uppercase tracking-widest text-[#A58A64]">
                  Financial Overview
                </p>

                <h2 className="mt-3 font-serif text-3xl text-[#171717]">
                  Recent Invoices
                </h2>
              </div>

              <button
                type="button"
                onClick={onOpenInvoices}
                className="inline-flex items-center gap-2 text-[10px] uppercase tracking-widest text-[#77736C] hover:text-[#A58A64]"
              >
                View All
                <ArrowUpRight size={15} />
              </button>
            </div>

            {data.invoices.length === 0 ? (
              <EmptyState message="Your invoices will appear here when shared by the studio." />
            ) : (
              <div className="mt-2">
                {data.invoices.slice(0, 5).map((invoice) => (
                  <button
                    key={invoice.id}
                    type="button"
                    onClick={() => onOpenInvoice(invoice)}
                    className="flex w-full flex-col justify-between gap-4 border-b border-[#D8D6D0] py-6 text-left transition-colors hover:bg-white/60 sm:flex-row sm:items-center"
                  >
                    <div>
                      <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                        {invoice.invoiceNumber}
                      </p>

                      <h3 className="mt-2 text-sm text-[#171717]">
                        {invoice.projectName}
                      </h3>

                      <p className="mt-2 text-[10px] text-[#99958D]">
                        Due: {invoice.dueDate}
                      </p>
                    </div>

                    <div className="sm:text-right">
                      <p className="font-serif text-xl text-[#171717]">
                        {formatCurrency(invoice.outstandingAmount)}
                      </p>

                      <span className="mt-2 inline-block text-[9px] uppercase tracking-widest text-[#77736C]">
                        {invoice.status}
                      </span>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Quick Access */}
          <aside className="lg:col-span-4 lg:col-start-9">
            <p className="font-mono text-[10px] uppercase tracking-widest text-[#A58A64]">
              Your Workspace
            </p>

            <h2 className="mt-3 font-serif text-3xl text-[#171717]">
              Quick Access
            </h2>

            <div className="mt-7 space-y-3">
              <QuickAccessItem
                icon={<FolderOpen size={19} />}
                title="Document Library"
                description="Approved drawings and shared files"
                onClick={onOpenDocuments}
              />

              <QuickAccessItem
                icon={<FileText size={19} />}
                title="Invoices & Payments"
                description="Review your financial records"
                onClick={onOpenInvoices}
              />

              <QuickAccessItem
                icon={<Bell size={19} />}
                title="Notifications"
                description="View recent account activity"
                onClick={onOpenNotifications}
              />
            </div>

            <div className="mt-7 border border-[#D8D6D0] bg-white p-6">
              <CheckCircle2
                size={21}
                className="text-[#A58A64]"
              />

              <h3 className="mt-4 font-serif text-xl text-[#171717]">
                Your Client Workspace
              </h3>

              <p className="mt-3 text-xs leading-6 text-[#77736C]">
                Access project information and documents that
                have been authorised for your account.
              </p>
            </div>
          </aside>
        </section>

        {/* Recent Activity */}
        <section className="mt-16">
          <div className="border-b border-[#D8D6D0] pb-5">
            <p className="font-mono text-[10px] uppercase tracking-widest text-[#A58A64]">
              Latest Activity
            </p>

            <h2 className="mt-3 font-serif text-3xl text-[#171717]">
              Recent Updates
            </h2>
          </div>

          {data.activities.length === 0 ? (
            <EmptyState message="New activity related to your account will appear here." />
          ) : (
            <div className="mt-3">
              {data.activities.slice(0, 6).map((activity) => (
                <article
                  key={activity.id}
                  className="flex items-start gap-4 border-b border-[#D8D6D0] py-6"
                >
                  <span className="mt-1 shrink-0 text-[#A58A64]">
                    {getActivityIcon(activity.category)}
                  </span>

                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-3">
                      <h3 className="text-sm text-[#171717]">
                        {activity.title}
                      </h3>

                      <span className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                        {activity.category}
                      </span>
                    </div>

                    <p className="mt-2 text-xs leading-6 text-[#77736C]">
                      {activity.description}
                    </p>
                  </div>

                  <span className="shrink-0 font-mono text-[9px] text-[#99958D]">
                    {activity.date}
                  </span>
                </article>
              ))}
            </div>
          )}
        </section>

        {/* Footer */}
        <footer className="mt-14 border-t border-[#D8D6D0] pt-6">
          <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
            ARCHEON DESIGN STUDIO / PRIVATE CLIENT WORKSPACE
          </p>
        </footer>
      </div>
    </main>
  );
}

function OverviewCard({
  label,
  value,
  icon,
}: {
  label: string;
  value: string;
  icon: React.ReactNode;
}) {
  return (
    <div className="bg-white p-6 md:p-7">
      <div className="flex items-center justify-between gap-3">
        <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
          {label}
        </p>

        <span className="text-[#A58A64]">{icon}</span>
      </div>

      <p className="mt-7 break-words font-serif text-2xl text-[#171717] md:text-3xl">
        {value}
      </p>
    </div>
  );
}

function QuickAccessItem({
  icon,
  title,
  description,
  onClick,
}: {
  icon: React.ReactNode;
  title: string;
  description: string;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="flex w-full items-center gap-4 border border-[#D8D6D0] bg-white p-5 text-left transition-colors hover:border-[#A58A64]"
    >
      <span className="shrink-0 text-[#A58A64]">{icon}</span>

      <span className="min-w-0 flex-1">
        <span className="block text-sm text-[#171717]">
          {title}
        </span>

        <span className="mt-1 block text-[10px] leading-5 text-[#99958D]">
          {description}
        </span>
      </span>

      <ArrowUpRight
        size={16}
        className="shrink-0 text-[#99958D]"
      />
    </button>
  );
}

function EmptyState({ message }: { message: string }) {
  return (
    <div className="border-b border-[#D8D6D0] px-5 py-12 text-center">
      <FolderOpen
        size={25}
        strokeWidth={1.3}
        className="mx-auto text-[#A58A64]"
      />

      <p className="mt-4 text-sm leading-7 text-[#77736C]">
        {message}
      </p>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  ArrowLeft,
  ArrowUpRight,
  FileText,
  Image as ImageIcon,
  CalendarDays,
  Download,
  FolderOpen,
} from "lucide-react";

export type ProjectDocumentCategory =
  | "Drawing"
  | "Render"
  | "Document";

export interface ClientProjectDocument {
  id: string;
  title: string;
  category: ProjectDocumentCategory;
  version: string;
  uploadedAt: string;
  approved: boolean;
  downloadUrl?: string;
}

export interface ClientProjectUpdate {
  id: string;
  title: string;
  description: string;
  date: string;
}

export interface ClientProjectWorkspaceData {
  id: string;
  name: string;
  location: string;
  status: string;
  description?: string;
  documents: ClientProjectDocument[];
  updates: ClientProjectUpdate[];
}

type WorkspaceTab = "overview" | "drawings" | "renders" | "documents";

interface ClientProjectWorkspaceProps {
  project: ClientProjectWorkspaceData;
  loading?: boolean;
  error?: string;
  onBack: () => void;
  onDownloadDocument: (
    document: ClientProjectDocument
  ) => void | Promise<void>;
}

const tabs: { id: WorkspaceTab; label: string }[] = [
  { id: "overview", label: "Overview" },
  { id: "drawings", label: "Drawings" },
  { id: "renders", label: "Renders" },
  { id: "documents", label: "Documents" },
];

export function ClientProjectWorkspace({
  project,
  loading = false,
  error,
  onBack,
  onDownloadDocument,
}: ClientProjectWorkspaceProps) {
  const [activeTab, setActiveTab] =
    useState<WorkspaceTab>("overview");

  const visibleDocuments =
    activeTab === "drawings"
      ? project.documents.filter(
          (document) =>
            document.category === "Drawing" && document.approved
        )
      : activeTab === "renders"
        ? project.documents.filter(
            (document) =>
              document.category === "Render" && document.approved
          )
        : activeTab === "documents"
          ? project.documents.filter(
              (document) =>
                document.category === "Document" && document.approved
            )
          : [];

  if (loading) {
    return (
      <div className="min-h-screen bg-[#F2F0EB] p-10">
        <p className="text-sm text-[#77736C]">
          Loading project workspace...
        </p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-[#F2F0EB] p-10">
        <div role="alert" className="max-w-xl border border-[#E3C9C5] bg-[#FAF3F1] p-7">
          <h2 className="font-serif text-2xl text-[#773B34]">
            Workspace unavailable
          </h2>
          <p className="mt-3 text-sm leading-7 text-[#805B55]">
            {error}
          </p>
          <button
            type="button"
            onClick={onBack}
            className="mt-6 text-xs uppercase tracking-widest text-[#773B34] underline"
          >
            Return to Projects
          </button>
        </div>
      </div>
    );
  }

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-8 md:px-10 md:py-12">
      <div className="mx-auto max-w-7xl">

        {/* Back Navigation */}
        <button
          type="button"
          onClick={onBack}
          className="inline-flex items-center gap-3 font-mono text-[10px] uppercase tracking-widest text-[#77736C] hover:text-[#A58A64]"
        >
          <ArrowLeft size={15} />
          All Projects
        </button>

        {/* Project Header */}
        <header className="mt-10 border-b border-[#D8D6D0] pb-10">
          <p className="font-mono text-[10px] uppercase tracking-widest text-[#A58A64]">
            Private Workspace / {project.id}
          </p>

          <div className="mt-5 flex flex-col justify-between gap-6 md:flex-row md:items-end">
            <div>
              <h1 className="font-serif text-4xl text-[#111111] md:text-6xl">
                {project.name}
              </h1>

              <p className="mt-4 text-sm text-[#77736C]">
                {project.location}
              </p>
            </div>

            <span className="w-fit border border-[#D8D6D0] bg-white px-4 py-2 font-mono text-[10px] uppercase tracking-widest text-[#66635D]">
              {project.status}
            </span>
          </div>

          {project.description && (
            <p className="mt-8 max-w-3xl text-sm leading-8 text-[#66635D]">
              {project.description}
            </p>
          )}
        </header>

        {/* Workspace Navigation */}
        <nav
          aria-label="Project workspace sections"
          className="mt-8 flex gap-7 overflow-x-auto border-b border-[#D8D6D0]"
        >
          {tabs.map((tab) => (
            <button
              key={tab.id}
              type="button"
              onClick={() => setActiveTab(tab.id)}
              aria-current={activeTab === tab.id ? "page" : undefined}
              className={`shrink-0 border-b-2 pb-4 text-xs transition-colors ${
                activeTab === tab.id
                  ? "border-[#A58A64] text-[#171717]"
                  : "border-transparent text-[#99958D] hover:text-[#33312D]"
              }`}
            >
              {tab.label}
            </button>
          ))}
        </nav>

        {/* Overview */}
        {activeTab === "overview" && (
          <div className="grid grid-cols-1 gap-12 py-12 lg:grid-cols-12">
            <section className="lg:col-span-7">
              <p className="font-mono text-[10px] uppercase tracking-widest text-[#A58A64]">
                Project Activity
              </p>

              <h2 className="mt-5 font-serif text-3xl text-[#171717]">
                Recent Updates
              </h2>

              {project.updates.length === 0 ? (
                <EmptyState message="Project updates will appear here when shared by the studio." />
              ) : (
                <div className="mt-8 border-t border-[#D8D6D0]">
                  {project.updates.map((update) => (
                    <article
                      key={update.id}
                      className="border-b border-[#D8D6D0] py-7"
                    >
                      <div className="flex items-center gap-3 text-[#A58A64]">
                        <CalendarDays size={15} />
                        <span className="font-mono text-[10px] uppercase tracking-widest">
                          {update.date}
                        </span>
                      </div>

                      <h3 className="mt-4 font-serif text-2xl text-[#171717]">
                        {update.title}
                      </h3>

                      <p className="mt-3 text-sm leading-7 text-[#77736C]">
                        {update.description}
                      </p>
                    </article>
                  ))}
                </div>
              )}
            </section>

            <aside className="lg:col-span-4 lg:col-start-9">
              <div className="border border-[#D8D6D0] bg-white p-7">
                <FolderOpen size={23} className="text-[#A58A64]" />

                <h3 className="mt-5 font-serif text-2xl text-[#171717]">
                  Shared Files
                </h3>

                <p className="mt-3 text-sm leading-7 text-[#77736C]">
                  Access drawings, visualisations and documents that
                  the studio has approved for your project.
                </p>

                <p className="mt-7 border-t border-[#E5E2DC] pt-5 font-mono text-[10px] uppercase tracking-widest text-[#99958D]">
                  {project.documents.filter((item) => item.approved).length} Approved Files
                </p>
              </div>
            </aside>
          </div>
        )}

        {/* Document Collections */}
        {activeTab !== "overview" && (
          <section className="py-12">
            <div className="flex items-end justify-between gap-5">
              <div>
                <p className="font-mono text-[10px] uppercase tracking-widest text-[#A58A64]">
                  Project Library
                </p>

                <h2 className="mt-4 font-serif text-3xl text-[#171717]">
                  {tabs.find((tab) => tab.id === activeTab)?.label}
                </h2>
              </div>

              <span className="font-mono text-[10px] text-[#99958D]">
                {visibleDocuments.length} FILES
              </span>
            </div>

            {visibleDocuments.length === 0 ? (
              <EmptyState message="No approved files are currently available in this section." />
            ) : (
              <div className="mt-8 border-t border-[#D8D6D0]">
                {visibleDocuments.map((document) => (
                  <article
                    key={document.id}
                    className="flex flex-col justify-between gap-5 border-b border-[#D8D6D0] py-6 sm:flex-row sm:items-center"
                  >
                    <div className="flex items-start gap-4">
                      <span className="mt-1 text-[#A58A64]">
                        {document.category === "Render" ? (
                          <ImageIcon size={20} />
                        ) : (
                          <FileText size={20} />
                        )}
                      </span>

                      <div>
                        <h3 className="text-sm text-[#171717]">
                          {document.title}
                        </h3>

                        <p className="mt-2 font-mono text-[10px] text-[#99958D]">
                          {document.version} · {document.uploadedAt}
                        </p>

                        <span className="mt-3 inline-block text-[9px] uppercase tracking-widest text-[#547A51]">
                          Approved for client access
                        </span>
                      </div>
                    </div>

                    <button
                      type="button"
                      onClick={() => onDownloadDocument(document)}
                      disabled={!document.downloadUrl}
                      className="inline-flex items-center gap-3 text-xs uppercase tracking-widest text-[#33312D] hover:text-[#A58A64] disabled:cursor-not-allowed disabled:opacity-40"
                    >
                      Download
                      <Download size={16} />
                    </button>
                  </article>
                ))}
              </div>
            )}
          </section>
        )}

        {/* Footer */}
        <footer className="mt-12 border-t border-[#D8D6D0] pt-6">
          <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
            ARCHEON DESIGN STUDIO / CONFIDENTIAL CLIENT WORKSPACE
          </p>
        </footer>
      </div>
    </main>
  );
}

function EmptyState({ message }: { message: string }) {
  return (
    <div className="mt-8 border border-[#D8D6D0] bg-white px-6 py-14 text-center">
      <FolderOpen
        size={27}
        strokeWidth={1.3}
        className="mx-auto text-[#A58A64]"
      />
      <p className="mx-auto mt-5 max-w-md text-sm leading-7 text-[#77736C]">
        {message}
      </p>
    </div>
  );
}

"use client";

import { useState, type FormEvent } from "react";
import {
  CheckCircle2,
  AlertCircle,
  Clock3,
  ShieldCheck,
  IndianRupee,
  CalendarDays,
  FileText,
  MessageSquare,
  ArrowUpRight,
} from "lucide-react";

export type VendorSettlementStatus =
  | "Pending Acknowledgement"
  | "Vendor Acknowledged"
  | "Disputed"
  | "Finance Verification Pending"
  | "Finance Verified"
  | "Rejected";

export interface VendorCashSettlementRecord {
  id: string;
  referenceCode: string;
  projectName: string;
  settlementAmount: number;
  settlementDate: string;
  recordedBy: string;
  description?: string;
  status: VendorSettlementStatus;
  vendorAcknowledgedAt?: string;
  financeVerifiedAt?: string;
  financeRemark?: string;
  disputeReason?: string;
}

export interface VendorSettlementAcknowledgement {
  settlementId: string;
  decision: "ACKNOWLEDGE" | "DISPUTE";
  disputeReason?: string;
}

interface VendorCashSettlementProps {
  settlements: VendorCashSettlementRecord[];
  loading?: boolean;
  submittingId?: string;
  error?: string;
  onSubmitDecision: (
    decision: VendorSettlementAcknowledgement
  ) => void | Promise<void>;
  onOpenDetails?: (settlement: VendorCashSettlementRecord) => void;
  onRefresh?: () => void;
}

function formatCurrency(amount: number) {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 2,
  }).format(amount);
}

function formatDate(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  }).format(date);
}

function getStatusStyle(status: VendorSettlementStatus) {
  switch (status) {
    case "Finance Verified":
      return "bg-[#EAF1E8] text-[#547A51]";

    case "Vendor Acknowledged":
    case "Finance Verification Pending":
      return "bg-[#EAF0F5] text-[#58738C]";

    case "Disputed":
    case "Rejected":
      return "bg-[#F8EAE7] text-[#9A5147]";

    default:
      return "bg-[#F4EFE2] text-[#94743F]";
  }
}

export function VendorCashSettlement({
  settlements,
  loading = false,
  submittingId,
  error,
  onSubmitDecision,
  onOpenDetails,
  onRefresh,
}: VendorCashSettlementProps) {
  const [selectedSettlement, setSelectedSettlement] =
    useState<VendorCashSettlementRecord | null>(null);

  const [decision, setDecision] = useState<
    "ACKNOWLEDGE" | "DISPUTE"
  >("ACKNOWLEDGE");

  const [disputeReason, setDisputeReason] = useState("");
  const [validationError, setValidationError] = useState("");

  function openDecision(
    settlement: VendorCashSettlementRecord,
    selectedDecision: "ACKNOWLEDGE" | "DISPUTE"
  ) {
    setSelectedSettlement(settlement);
    setDecision(selectedDecision);
    setDisputeReason("");
    setValidationError("");
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!selectedSettlement || submittingId) return;

    if (
      decision === "DISPUTE" &&
      disputeReason.trim().length < 10
    ) {
      setValidationError(
        "Please explain the issue in at least 10 characters."
      );
      return;
    }

    setValidationError("");

    await onSubmitDecision({
      settlementId: selectedSettlement.id,
      decision,
      ...(decision === "DISPUTE"
        ? { disputeReason: disputeReason.trim() }
        : {}),
    });

    // Do not change the settlement status here.
    // The parent must refresh authoritative server data
    // after the backend confirms the decision.
    setSelectedSettlement(null);
  }

  if (loading) {
    return (
      <div className="min-h-80 bg-[#F2F0EB] p-8">
        <p className="text-sm text-[#77736C]">
          Loading cash settlement records...
        </p>
      </div>
    );
  }

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-10 md:px-10 md:py-14">
      <div className="mx-auto max-w-7xl">

        {/* Header */}
        <header className="border-b border-[#D8D6D0] pb-9">
          <p className="font-mono text-[10px] uppercase tracking-[0.2em] text-[#A58A64]">
            Vendor Portal / Finance
          </p>

          <h1 className="mt-5 font-serif text-4xl text-[#171717] md:text-5xl">
            Cash Settlements
          </h1>

          <p className="mt-4 max-w-2xl text-sm leading-7 text-[#77736C]">
            Review cash settlements recorded against your work.
            Confirm the amount only when you have actually received it.
          </p>

          {onRefresh && (
            <button
              type="button"
              onClick={onRefresh}
              className="mt-6 text-[10px] uppercase tracking-widest text-[#987543] hover:text-[#171717]"
            >
              Refresh Records
            </button>
          )}
        </header>

        {/* Important Notice */}
        <section className="mt-8 flex items-start gap-4 border border-[#E8DFCE] bg-[#F8F4EB] p-6">
          <ShieldCheck
            size={22}
            className="mt-1 shrink-0 text-[#94743F]"
          />

          <div>
            <h2 className="text-sm font-medium text-[#6F5C39]">
              Two-party settlement verification
            </h2>

            <p className="mt-2 text-xs leading-7 text-[#806D4A]">
              Your acknowledgement confirms your response to the
              recorded settlement. Final financial verification
              requires separate authorised finance verification.
            </p>
          </div>
        </section>

        {/* Error */}
        {error && (
          <div
            role="alert"
            className="mt-6 flex items-start gap-3 border border-[#E3C9C5] bg-[#FAF3F1] p-5"
          >
            <AlertCircle
              size={19}
              className="shrink-0 text-[#9A5147]"
            />

            <p className="text-xs leading-6 text-[#805B55]">
              {error}
            </p>
          </div>
        )}

        {/* Settlement List */}
        <section className="mt-12">
          <div className="border-b border-[#D8D6D0] pb-5">
            <p className="font-mono text-[10px] uppercase tracking-widest text-[#A58A64]">
              Settlement Records
            </p>

            <h2 className="mt-3 font-serif text-3xl text-[#171717]">
              Your Settlements
            </h2>
          </div>

          {settlements.length === 0 ? (
            <div className="mt-7 border border-[#D8D6D0] bg-white px-6 py-16 text-center">
              <IndianRupee
                size={28}
                strokeWidth={1.3}
                className="mx-auto text-[#A58A64]"
              />

              <h3 className="mt-5 font-serif text-2xl text-[#171717]">
                No settlement records
              </h3>

              <p className="mt-3 text-sm text-[#77736C]">
                No cash settlements are currently recorded for your account.
              </p>
            </div>
          ) : (
            <div className="mt-7 space-y-5">
              {settlements.map((settlement) => {
                const canRespond =
                  settlement.status === "Pending Acknowledgement";

                return (
                  <article
                    key={settlement.id}
                    className="border border-[#D8D6D0] bg-white p-6 md:p-8"
                  >
                    <div className="flex flex-col justify-between gap-5 md:flex-row md:items-start">
                      <div>
                        <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                          {settlement.referenceCode}
                        </p>

                        <h3 className="mt-3 font-serif text-2xl text-[#171717]">
                          {settlement.projectName}
                        </h3>

                        {settlement.description && (
                          <p className="mt-2 text-xs leading-6 text-[#77736C]">
                            {settlement.description}
                          </p>
                        )}
                      </div>

                      <span
                        className={`w-fit px-3 py-2 text-[9px] uppercase tracking-widest ${getStatusStyle(settlement.status)}`}
                      >
                        {settlement.status}
                      </span>
                    </div>

                    {/* Amount */}
                    <div className="mt-7 border-y border-[#E5E2DC] py-6">
                      <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
                        Recorded Settlement Amount
                      </p>

                      <p className="mt-3 font-serif text-3xl text-[#171717]">
                        {formatCurrency(settlement.settlementAmount)}
                      </p>
                    </div>

                    {/* Details */}
                    <div className="mt-6 grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">
                      <Detail
                        icon={<CalendarDays size={15} />}
                        label="Settlement Date"
                        value={formatDate(settlement.settlementDate)}
                      />

                      <Detail
                        icon={<FileText size={15} />}
                        label="Recorded By"
                        value={settlement.recordedBy}
                      />

                      <Detail
                        icon={<Clock3 size={15} />}
                        label="Vendor Response"
                        value={
                          settlement.vendorAcknowledgedAt
                            ? formatDate(settlement.vendorAcknowledgedAt)
                            : "Awaiting response"
                        }
                      />
                    </div>

                    {/* Dispute Information */}
                    {settlement.disputeReason && (
                      <div className="mt-6 border border-[#E3C9C5] bg-[#FAF3F1] p-5">
                        <p className="font-mono text-[9px] uppercase tracking-widest text-[#9A5147]">
                          Dispute Submitted
                        </p>

                        <p className="mt-3 text-xs leading-7 text-[#805B55]">
                          {settlement.disputeReason}
                        </p>
                      </div>
                    )}

                    {/* Finance Remark */}
                    {settlement.financeRemark && (
                      <div className="mt-6 border border-[#E8DFCE] bg-[#F8F4EB] p-5">
                        <p className="font-mono text-[9px] uppercase tracking-widest text-[#94743F]">
                          Finance Response
                        </p>

                        <p className="mt-3 text-xs leading-7 text-[#6F5C39]">
                          {settlement.financeRemark}
                        </p>
                      </div>
                    )}

                    {/* Finance Verification */}
                    {settlement.status === "Finance Verified" && (
                      <div className="mt-6 flex items-center gap-3 border border-[#D7E2D2] bg-[#F0F5EE] p-4">
                        <CheckCircle2
                          size={18}
                          className="text-[#547A51]"
                        />

                        <div>
                          <p className="text-xs font-medium text-[#547A51]">
                            Finance verification completed
                          </p>

                          {settlement.financeVerifiedAt && (
                            <p className="mt-1 text-[10px] text-[#6F826A]">
                              {formatDate(settlement.financeVerifiedAt)}
                            </p>
                          )}
                        </div>
                      </div>
                    )}

                    {/* Actions */}
                    <div className="mt-7 flex flex-wrap items-center gap-4 border-t border-[#E5E2DC] pt-6">
                      {canRespond && (
                        <>
                          <button
                            type="button"
                            onClick={() =>
                              openDecision(settlement, "ACKNOWLEDGE")
                            }
                            disabled={Boolean(submittingId)}
                            className="inline-flex items-center gap-2 bg-[#171717] px-6 py-3 text-[10px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:opacity-50"
                          >
                            <CheckCircle2 size={15} />
                            Acknowledge Receipt
                          </button>

                          <button
                            type="button"
                            onClick={() =>
                              openDecision(settlement, "DISPUTE")
                            }
                            disabled={Boolean(submittingId)}
                            className="inline-flex items-center gap-2 border border-[#D8D6D0] px-6 py-3 text-[10px] uppercase tracking-widest text-[#9A5147] hover:border-[#9A5147] disabled:opacity-50"
                          >
                            <AlertCircle size={15} />
                            Dispute Settlement
                          </button>
                        </>
                      )}

                      {onOpenDetails && (
                        <button
                          type="button"
                          onClick={() => onOpenDetails(settlement)}
                          className="ml-auto inline-flex items-center gap-2 text-[10px] uppercase tracking-widest text-[#987543] hover:text-[#171717]"
                        >
                          View Details
                          <ArrowUpRight size={15} />
                        </button>
                      )}
                    </div>
                  </article>
                );
              })}
            </div>
          )}
        </section>

        {/* Decision Dialog */}
        {selectedSettlement && (
          <div
            className="fixed inset-0 z-50 flex items-center justify-center overflow-y-auto bg-black/50 p-4"
            role="presentation"
          >
            <section
              role="dialog"
              aria-modal="true"
              aria-labelledby="settlement-dialog-title"
              className="my-auto w-full max-w-xl border border-[#D8D6D0] bg-[#F2F0EB] p-6 shadow-2xl md:p-9"
            >
              <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                Settlement Response
              </p>

              <h2
                id="settlement-dialog-title"
                className="mt-4 font-serif text-3xl text-[#171717]"
              >
                {decision === "ACKNOWLEDGE"
                  ? "Confirm Receipt"
                  : "Raise a Dispute"}
              </h2>

              <div className="mt-6 border border-[#D8D6D0] bg-white p-5">
                <p className="text-xs text-[#77736C]">
                  {selectedSettlement.projectName}
                </p>

                <p className="mt-3 font-serif text-2xl text-[#171717]">
                  {formatCurrency(selectedSettlement.settlementAmount)}
                </p>

                <p className="mt-2 font-mono text-[9px] text-[#99958D]">
                  {selectedSettlement.referenceCode}
                </p>
              </div>

              {decision === "ACKNOWLEDGE" ? (
                <div className="mt-6 border border-[#E8DFCE] bg-[#F8F4EB] p-5">
                  <p className="text-xs leading-7 text-[#6F5C39]">
                    By continuing, you confirm that you have received
                    the cash amount shown above. Do not acknowledge
                    a settlement that you have not actually received
                    or that has an incorrect amount.
                  </p>
                </div>
              ) : (
                <div className="mt-6">
                  <label
                    htmlFor="settlement-dispute-reason"
                    className="mb-3 block font-mono text-[9px] uppercase tracking-widest text-[#77736C]"
                  >
                    Explain the discrepancy
                  </label>

                  <textarea
                    id="settlement-dispute-reason"
                    value={disputeReason}
                    onChange={(event) =>
                      setDisputeReason(event.target.value)
                    }
                    rows={5}
                    maxLength={2000}
                    placeholder="Explain why the amount or settlement record is incorrect..."
                    className="w-full border border-[#D8D6D0] bg-white p-4 text-sm text-[#33312D] outline-none focus:border-[#A58A64]"
                  />

                  <p className="mt-2 text-right font-mono text-[9px] text-[#99958D]">
                    {disputeReason.length}/2000
                  </p>
                </div>
              )}

              {validationError && (
                <p role="alert" className="mt-4 text-xs text-[#9A5147]">
                  {validationError}
                </p>
              )}

              <div className="mt-8 flex flex-col-reverse gap-3 sm:flex-row sm:justify-end">
                <button
                  type="button"
                  disabled={Boolean(submittingId)}
                  onClick={() => setSelectedSettlement(null)}
                  className="border border-[#D8D6D0] px-6 py-3 text-[10px] uppercase tracking-widest text-[#77736C] disabled:opacity-50"
                >
                  Cancel
                </button>

                <button
                  type="button"
                  disabled={Boolean(submittingId)}
                  onClick={(event) => {
                    const form = event.currentTarget.form;
                    if (form) form.requestSubmit();
                  }}
                  className="bg-[#171717] px-6 py-3 text-[10px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:opacity-50"
                >
                  {submittingId === selectedSettlement.id
                    ? "Processing..."
                    : decision === "ACKNOWLEDGE"
                      ? "Confirm Receipt"
                      : "Submit Dispute"}
                </button>
              </div>

              {/* Hidden form handles the actual submission */}
              <form onSubmit={handleSubmit} className="hidden">
                <button type="submit">Submit</button>
              </form>
            </section>
          </div>
        )}

        <footer className="mt-12 border-t border-[#D8D6D0] pt-6">
          <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
            ARCHEON DESIGN STUDIO / CONFIDENTIAL VENDOR WORKSPACE
          </p>
        </footer>
      </div>
    </main>
  );
}

function Detail({
  icon,
  label,
  value,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
}) {
  return (
    <div>
      <p className="flex items-center gap-2 font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
        <span className="text-[#A58A64]">{icon}</span>
        {label}
      </p>

      <p className="mt-2 text-xs text-[#33312D]">{value}</p>
    </div>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  Bell,
  CheckCheck,
  CheckCircle2,
  Clock3,
  FileText,
  FolderOpen,
  IndianRupee,
  MessageSquare,
  Megaphone,
  Search,
  ShieldCheck,
  AlertCircle,
  ArrowUpRight,
  RefreshCw,
} from "lucide-react";

export type VendorNotificationCategory =
  | "Project"
  | "Invoice"
  | "Payment"
  | "Dispute"
  | "Announcement"
  | "System";

export type VendorNotificationPriority =
  | "Normal"
  | "Important"
  | "Urgent";

export interface VendorNotificationRecord {
  id: string;
  title: string;
  message: string;
  category: VendorNotificationCategory;
  priority: VendorNotificationPriority;
  createdAt: string;
  isRead: boolean;
  actionLabel?: string;
  relatedReference?: string;
  actionTarget?: string;
}

interface VendorNotificationsCentreProps {
  notifications: VendorNotificationRecord[];
  loading?: boolean;
  error?: string;
  onOpenNotification: (
    notification: VendorNotificationRecord
  ) => void;
  onMarkAsRead: (notificationId: string) => void | Promise<void>;
  onMarkAllAsRead: () => void | Promise<void>;
  onRefresh?: () => void;
}

type NotificationFilter =
  | "All"
  | "Unread"
  | VendorNotificationCategory;

const FILTERS: NotificationFilter[] = [
  "All",
  "Unread",
  "Project",
  "Invoice",
  "Payment",
  "Dispute",
  "Announcement",
  "System",
];

function formatDate(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
}

function renderCategoryIcon(category: VendorNotificationCategory, size: number) {
  switch (category) {
    case "Project":
      return <FolderOpen size={size} />;

    case "Invoice":
      return <FileText size={size} />;

    case "Payment":
      return <IndianRupee size={size} />;

    case "Dispute":
      return <MessageSquare size={size} />;

    case "Announcement":
      return <Megaphone size={size} />;

    default:
      return <Bell size={size} />;
  }
}

function getPriorityStyle(priority: VendorNotificationPriority) {
  switch (priority) {
    case "Urgent":
      return "bg-[#F8EAE7] text-[#9A5147]";

    case "Important":
      return "bg-[#F4EFE2] text-[#94743F]";

    default:
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

export function VendorNotificationsCentre({
  notifications,
  loading = false,
  error,
  onOpenNotification,
  onMarkAsRead,
  onMarkAllAsRead,
  onRefresh,
}: VendorNotificationsCentreProps) {
  const [filter, setFilter] =
    useState<NotificationFilter>("All");

  const [search, setSearch] = useState("");

  const unreadCount = notifications.filter(
    (notification) => !notification.isRead
  ).length;

  const filteredNotifications = useMemo(() => {
    const query = search.trim().toLowerCase();

    return notifications.filter((notification) => {
      const matchesSearch =
        !query ||
        notification.title.toLowerCase().includes(query) ||
        notification.message.toLowerCase().includes(query) ||
        (notification.relatedReference ?? "")
          .toLowerCase()
          .includes(query);

      const matchesFilter =
        filter === "All" ||
        (filter === "Unread" && !notification.isRead) ||
        notification.category === filter;

      return matchesSearch && matchesFilter;
    });
  }, [notifications, search, filter]);

  async function handleOpen(
    notification: VendorNotificationRecord
  ) {
    if (!notification.isRead) {
      await onMarkAsRead(notification.id);
    }

    onOpenNotification(notification);
  }

  if (loading) {
    return (
      <div className="min-h-80 bg-[#F2F0EB] p-8">
        <p className="text-sm text-[#77736C]">
          Loading notifications...
        </p>
      </div>
    );
  }

  if (error) {
    return (
      <section
        role="alert"
        className="border border-[#E3C9C5] bg-[#FAF3F1] p-7"
      >
        <AlertCircle size={22} className="text-[#9A5147]" />

        <h2 className="mt-4 font-serif text-2xl text-[#773B34]">
          Notifications unavailable
        </h2>

        <p className="mt-3 text-sm leading-7 text-[#805B55]">
          {error}
        </p>

        {onRefresh && (
          <button
            type="button"
            onClick={onRefresh}
            className="mt-5 text-xs uppercase tracking-widest text-[#773B34] underline"
          >
            Try Again
          </button>
        )}
      </section>
    );
  }

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-10 md:px-10 md:py-14">
      <div className="mx-auto max-w-6xl">

        {/* Header */}
        <header className="border-b border-[#D8D6D0] pb-9">
          <p className="font-mono text-[10px] uppercase tracking-[0.2em] text-[#A58A64]">
            Vendor Portal / Communication
          </p>

          <div className="mt-5 flex flex-col justify-between gap-5 md:flex-row md:items-end">
            <div>
              <h1 className="font-serif text-4xl text-[#171717] md:text-5xl">
                Notifications
              </h1>

              <p className="mt-4 max-w-2xl text-sm leading-7 text-[#77736C]">
                Stay informed about your assignments, invoices,
                payments, disputes and studio updates.
              </p>
            </div>

            <div className="flex items-center gap-3 border border-[#D8D6D0] bg-white px-5 py-3">
              <Bell size={17} className="text-[#A58A64]" />

              <span className="font-serif text-2xl text-[#171717]">
                {unreadCount}
              </span>

              <span className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
                Unread
              </span>
            </div>
          </div>

          <div className="mt-7 flex flex-wrap gap-4">
            {onRefresh && (
              <button
                type="button"
                onClick={onRefresh}
                className="inline-flex items-center gap-2 font-mono text-[10px] uppercase tracking-widest text-[#77736C] hover:text-[#A58A64]"
              >
                <RefreshCw size={14} />
                Refresh
              </button>
            )}

            {unreadCount > 0 && (
              <button
                type="button"
                onClick={() => void onMarkAllAsRead()}
                className="inline-flex items-center gap-2 font-mono text-[10px] uppercase tracking-widest text-[#987543] hover:text-[#171717]"
              >
                <CheckCheck size={15} />
                Mark All as Read
              </button>
            )}
          </div>
        </header>

        {/* Summary */}
        <section className="mt-9 grid grid-cols-1 gap-px border border-[#D8D6D0] bg-[#D8D6D0] sm:grid-cols-3">
          <SummaryCard
            label="Total Notifications"
            value={String(notifications.length)}
            icon={<Bell size={19} />}
          />

          <SummaryCard
            label="Unread"
            value={String(unreadCount)}
            icon={<AlertCircle size={19} />}
          />

          <SummaryCard
            label="Read"
            value={String(notifications.length - unreadCount)}
            icon={<CheckCircle2 size={19} />}
          />
        </section>

        {/* Notification List */}
        <section className="mt-12">
          <div className="border-b border-[#D8D6D0] pb-5">
            <p className="font-mono text-[10px] uppercase tracking-widest text-[#A58A64]">
              Updates & Activity
            </p>

            <h2 className="mt-3 font-serif text-3xl text-[#171717]">
              Your Activity
            </h2>
          </div>

          {/* Search */}
          <div className="relative mt-6">
            <Search
              size={17}
              className="absolute left-4 top-1/2 -translate-y-1/2 text-[#99958D]"
            />

            <input
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Search notifications..."
              aria-label="Search notifications"
              className="h-12 w-full border border-[#D8D6D0] bg-white pl-11 pr-4 text-sm text-[#33312D] outline-none focus:border-[#A58A64]"
            />
          </div>

          {/* Filters */}
          <div className="mt-5 flex gap-2 overflow-x-auto pb-3">
            {FILTERS.map((item) => {
              const active = filter === item;

              return (
                <button
                  key={item}
                  type="button"
                  onClick={() => setFilter(item)}
                  aria-pressed={active}
                  className={`shrink-0 border px-4 py-3 text-[9px] uppercase tracking-widest transition-colors ${
                    active
                      ? "border-[#171717] bg-[#171717] text-white"
                      : "border-[#D8D6D0] bg-white text-[#77736C] hover:border-[#A58A64]"
                  }`}
                >
                  {item === "All" ? "All Updates" : item}
                </button>
              );
            })}
          </div>

          {/* Results */}
          <div className="mt-5 space-y-3">
            {filteredNotifications.length === 0 ? (
              <div className="border border-[#D8D6D0] bg-white px-6 py-16 text-center">
                <Bell
                  size={28}
                  strokeWidth={1.3}
                  className="mx-auto text-[#A58A64]"
                />

                <h3 className="mt-5 font-serif text-2xl text-[#171717]">
                  No notifications found
                </h3>

                <p className="mt-3 text-sm text-[#77736C]">
                  There are no notifications matching your current filter.
                </p>
              </div>
            ) : (
              filteredNotifications.map((notification) => (
                <NotificationCard
                  key={notification.id}
                  notification={notification}
                  onOpen={() => void handleOpen(notification)}
                />
              ))
            )}
          </div>
        </section>

        {/* Security Notice */}
        <div className="mt-12 flex items-start gap-4 border border-[#D8D6D0] bg-white p-5">
          <ShieldCheck
            size={20}
            className="mt-1 shrink-0 text-[#A58A64]"
          />

          <p className="text-xs leading-6 text-[#77736C]">
            Notifications are account-specific. Project and financial
            information must only be shown to authorised vendor accounts.
            Important financial actions should always be completed in
            their respective secure workflows.
          </p>
        </div>

        <footer className="mt-12 border-t border-[#D8D6D0] pt-6">
          <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
            ARCHEON DESIGN STUDIO / CONFIDENTIAL VENDOR WORKSPACE
          </p>
        </footer>
      </div>
    </main>
  );
}

function SummaryCard({
  label,
  value,
  icon,
}: {
  label: string;
  value: string;
  icon: ReactNode;
}) {
  return (
    <div className="bg-white p-7">
      <div className="flex items-center justify-between gap-3">
        <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
          {label}
        </p>

        <span className="text-[#A58A64]">{icon}</span>
      </div>

      <p className="mt-7 font-serif text-3xl text-[#171717]">
        {value}
      </p>
    </div>
  );
}

function NotificationCard({
  notification,
  onOpen,
}: {
  notification: VendorNotificationRecord;
  onOpen: () => void;
}) {
  return (
    <article
      className={`border bg-white transition-colors ${
        notification.isRead
          ? "border-[#D8D6D0]"
          : "border-[#C8B28F]"
      }`}
    >
      <button
        type="button"
        onClick={onOpen}
        className="flex w-full items-start gap-4 p-5 text-left md:p-6"
      >
        <span className="mt-1 flex h-10 w-10 shrink-0 items-center justify-center border border-[#E5E2DC] bg-[#FAF9F6] text-[#A58A64]">
          {renderCategoryIcon(notification.category, 18)}
        </span>

        <span className="min-w-0 flex-1">
          <span className="flex flex-wrap items-center gap-2">
            <span className="text-sm font-medium text-[#33312D]">
              {notification.title}
            </span>

            {!notification.isRead && (
              <span className="h-2 w-2 rounded-full bg-[#A58A64]" />
            )}
          </span>

          <span className="mt-2 block text-xs leading-7 text-[#77736C]">
            {notification.message}
          </span>

          <span className="mt-4 flex flex-wrap items-center gap-3">
            <span className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
              {notification.category}
            </span>

            <span
              className={`px-2 py-1 font-mono text-[8px] uppercase tracking-widest ${getPriorityStyle(notification.priority)}`}
            >
              {notification.priority}
            </span>

            {notification.relatedReference && (
              <span className="font-mono text-[9px] text-[#99958D]">
                {notification.relatedReference}
              </span>
            )}
          </span>

          <span className="mt-3 block text-[10px] text-[#99958D]">
            {formatDate(notification.createdAt)}
          </span>
        </span>

        <ArrowUpRight
          size={16}
          className="mt-2 shrink-0 text-[#99958D]"
        />
      </button>

      {notification.actionLabel && (
        <div className="border-t border-[#E5E2DC] px-5 py-3 md:px-6">
          <span className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
            {notification.actionLabel}
          </span>
        </div>
      )}
    </article>
  );
}

"use client";

import { useState, type FormEvent, type ReactNode } from "react";
import {
  Building2,
  User,
  Mail,
  Phone,
  MapPin,
  ShieldCheck,
  Bell,
  LockKeyhole,
  Save,
  AlertCircle,
  CheckCircle2,
  KeyRound,
} from "lucide-react";

export interface VendorProfileData {
  businessName: string;
  vendorCode: string;
  contactPerson: string;
  email: string;
  phone: string;
  alternatePhone?: string;
  businessAddress: string;
  gstin?: string;
  businessType?: string;
}

export interface VendorNotificationPreferences {
  projectUpdates: boolean;
  invoiceUpdates: boolean;
  paymentUpdates: boolean;
  disputeUpdates: boolean;
  studioAnnouncements: boolean;
  emailNotifications: boolean;
  whatsappNotifications: boolean;
}

interface VendorProfileSettingsProps {
  profile: VendorProfileData;
  preferences: VendorNotificationPreferences;
  loading?: boolean;
  saving?: boolean;
  error?: string;
  successMessage?: string;
  onSaveProfile: (
    profile: Pick<
      VendorProfileData,
      | "contactPerson"
      | "email"
      | "phone"
      | "alternatePhone"
      | "businessAddress"
    >
  ) => void | Promise<void>;
  onSavePreferences: (
    preferences: VendorNotificationPreferences
  ) => void | Promise<void>;
  onChangePassword: () => void;
  onRequestEmailChange: (newEmail: string) => void | Promise<void>;
}

type SettingsTab = "profile" | "notifications" | "security";

export function VendorProfileSettings({
  profile,
  preferences,
  loading = false,
  saving = false,
  error,
  successMessage,
  onSaveProfile,
  onSavePreferences,
  onChangePassword,
  onRequestEmailChange,
}: VendorProfileSettingsProps) {
  const [activeTab, setActiveTab] =
    useState<SettingsTab>("profile");

  const [contactPerson, setContactPerson] =
    useState(profile.contactPerson);

  const [email, setEmail] = useState(profile.email);
  const [phone, setPhone] = useState(profile.phone);

  const [alternatePhone, setAlternatePhone] =
    useState(profile.alternatePhone ?? "");

  const [businessAddress, setBusinessAddress] =
    useState(profile.businessAddress);

  const [notificationPreferences, setNotificationPreferences] =
    useState(preferences);

  const [validationError, setValidationError] = useState("");

  function updatePreference(
    key: keyof VendorNotificationPreferences,
    value: boolean
  ) {
    setNotificationPreferences((current) => ({
      ...current,
      [key]: value,
    }));
  }

  async function handleProfileSubmit(
    event: FormEvent<HTMLFormElement>
  ) {
    event.preventDefault();

    if (saving) return;

    if (contactPerson.trim().length < 2) {
      setValidationError("Enter a valid contact person name.");
      return;
    }

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) {
      setValidationError("Enter a valid email address.");
      return;
    }

    if (!/^[0-9+\-\s()]{7,20}$/.test(phone.trim())) {
      setValidationError("Enter a valid phone number.");
      return;
    }

    if (
      alternatePhone.trim() &&
      !/^[0-9+\-\s()]{7,20}$/.test(alternatePhone.trim())
    ) {
      setValidationError("Enter a valid alternate phone number.");
      return;
    }

    if (businessAddress.trim().length < 5) {
      setValidationError("Enter a valid business address.");
      return;
    }

    setValidationError("");

    await onSaveProfile({
      contactPerson: contactPerson.trim(),
      email: email.trim(),
      phone: phone.trim(),
      alternatePhone: alternatePhone.trim(),
      businessAddress: businessAddress.trim(),
    });
  }

  async function handlePreferencesSubmit(
    event: FormEvent<HTMLFormElement>
  ) {
    event.preventDefault();

    if (saving) return;

    setValidationError("");
    await onSavePreferences(notificationPreferences);
  }

  async function handleEmailChange() {
    if (saving) return;

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) {
      setValidationError("Enter a valid email address.");
      return;
    }

    if (email.trim().toLowerCase() === profile.email.toLowerCase()) {
      setValidationError("Enter a different email address.");
      return;
    }

    setValidationError("");
    await onRequestEmailChange(email.trim());
  }

  if (loading) {
    return (
      <div className="min-h-80 bg-[#F2F0EB] p-8">
        <p className="text-sm text-[#77736C]">
          Loading vendor account settings...
        </p>
      </div>
    );
  }

  const tabs: {
    id: SettingsTab;
    label: string;
    icon: ReactNode;
  }[] = [
    {
      id: "profile",
      label: "Business Profile",
      icon: <Building2 size={16} />,
    },
    {
      id: "notifications",
      label: "Notifications",
      icon: <Bell size={16} />,
    },
    {
      id: "security",
      label: "Account Security",
      icon: <ShieldCheck size={16} />,
    },
  ];

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-10 md:px-10 md:py-14">
      <div className="mx-auto max-w-6xl">

        {/* Header */}
        <header className="border-b border-[#D8D6D0] pb-9">
          <p className="font-mono text-[10px] uppercase tracking-[0.2em] text-[#A58A64]">
            Vendor Portal / Account
          </p>

          <h1 className="mt-5 font-serif text-4xl text-[#171717] md:text-5xl">
            Account Settings
          </h1>

          <p className="mt-4 max-w-2xl text-sm leading-7 text-[#77736C]">
            Manage your business information, authorised contact
            details, communication preferences and account security.
          </p>
        </header>

        {/* Account Identity */}
        <section className="mt-8 flex flex-col justify-between gap-5 border border-[#D8D6D0] bg-white p-6 md:flex-row md:items-center md:p-8">
          <div className="flex items-center gap-5">
            <div className="flex h-14 w-14 shrink-0 items-center justify-center bg-[#F2F0EB] text-[#A58A64]">
              <Building2 size={25} />
            </div>

            <div>
              <h2 className="font-serif text-2xl text-[#171717]">
                {profile.businessName}
              </h2>

              <p className="mt-2 font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
                Vendor Reference: {profile.vendorCode}
              </p>
            </div>
          </div>

          <span className="inline-flex w-fit items-center gap-2 border border-[#D7E2D2] bg-[#F0F5EE] px-4 py-2 text-[9px] uppercase tracking-widest text-[#547A51]">
            <ShieldCheck size={14} />
            Account Workspace
          </span>
        </section>

        {/* Tabs */}
        <nav
          aria-label="Account settings sections"
          className="mt-8 flex gap-2 overflow-x-auto border-b border-[#D8D6D0] pb-3"
        >
          {tabs.map((tab) => (
            <button
              key={tab.id}
              type="button"
              onClick={() => {
                setActiveTab(tab.id);
                setValidationError("");
              }}
              aria-current={activeTab === tab.id ? "page" : undefined}
              className={`inline-flex shrink-0 items-center gap-2 border px-5 py-3 text-[10px] uppercase tracking-widest transition-colors ${
                activeTab === tab.id
                  ? "border-[#171717] bg-[#171717] text-white"
                  : "border-[#D8D6D0] bg-white text-[#77736C] hover:border-[#A58A64]"
              }`}
            >
              {tab.icon}
              {tab.label}
            </button>
          ))}
        </nav>

        {/* Profile */}
        {activeTab === "profile" && (
          <section className="mt-8">
            <div className="border border-[#D8D6D0] bg-white p-6 md:p-9">
              <SectionHeading
                icon={<Building2 size={19} />}
                title="Business Information"
              />

              <div className="mt-7 grid grid-cols-1 gap-6 md:grid-cols-2">
                <ReadOnlyField
                  label="Registered Business Name"
                  value={profile.businessName}
                />

                <ReadOnlyField
                  label="Vendor Reference"
                  value={profile.vendorCode}
                />

                <ReadOnlyField
                  label="Business Type"
                  value={profile.businessType || "Not provided"}
                />

                <ReadOnlyField
                  label="GSTIN"
                  value={profile.gstin || "Not provided"}
                />
              </div>

              <div className="mt-9 border-t border-[#E5E2DC] pt-8">
                <SectionHeading
                  icon={<User size={19} />}
                  title="Authorised Contact Details"
                />

                <form
                  onSubmit={handleProfileSubmit}
                  className="mt-7 space-y-6"
                >
                  <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                    <Field label="Contact Person">
                      <input
                        value={contactPerson}
                        onChange={(event) =>
                          setContactPerson(event.target.value)
                        }
                        maxLength={120}
                        required
                        disabled={saving}
                        className="vendor-settings-input"
                      />
                    </Field>

                    <Field label="Registered Email">
                      <input
                        type="email"
                        value={email}
                        onChange={(event) =>
                          setEmail(event.target.value)
                        }
                        maxLength={254}
                        required
                        disabled={saving}
                        className="vendor-settings-input"
                      />
                    </Field>

                    <Field label="Primary Phone">
                      <input
                        type="tel"
                        value={phone}
                        onChange={(event) =>
                          setPhone(event.target.value)
                        }
                        maxLength={20}
                        required
                        disabled={saving}
                        className="vendor-settings-input"
                      />
                    </Field>

                    <Field label="Alternate Phone">
                      <input
                        type="tel"
                        value={alternatePhone}
                        onChange={(event) =>
                          setAlternatePhone(event.target.value)
                        }
                        maxLength={20}
                        disabled={saving}
                        className="vendor-settings-input"
                      />
                    </Field>
                  </div>

                  <Field label="Business Address">
                    <textarea
                      value={businessAddress}
                      onChange={(event) =>
                        setBusinessAddress(event.target.value)
                      }
                      rows={3}
                      maxLength={500}
                      required
                      disabled={saving}
                      className="vendor-settings-input resize-y"
                    />
                  </Field>

                  <p className="text-xs leading-6 text-[#99958D]">
                    Changes to registered business identity, GSTIN
                    or legal details must follow the studio&apos;s
                    verification process. They cannot be changed
                    through this contact-details form.
                  </p>

                  <button
                    type="submit"
                    disabled={saving}
                    className="inline-flex items-center gap-3 bg-[#171717] px-7 py-4 text-[10px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:opacity-50"
                  >
                    <Save size={15} />
                    {saving ? "Saving..." : "Save Contact Details"}
                  </button>
                </form>
              </div>
            </div>
          </section>
        )}

        {/* Notifications */}
        {activeTab === "notifications" && (
          <section className="mt-8 border border-[#D8D6D0] bg-white p-6 md:p-9">
            <SectionHeading
              icon={<Bell size={19} />}
              title="Notification Preferences"
            />

            <p className="mt-4 text-xs leading-7 text-[#77736C]">
              Choose which account updates you want to receive.
              Essential security and account notices may still be
              delivered when necessary.
            </p>

            <form
              onSubmit={handlePreferencesSubmit}
              className="mt-8"
            >
              <div className="space-y-1">
                <PreferenceRow
                  label="Project Updates"
                  description="New assignments, changes in scope and project status."
                  checked={notificationPreferences.projectUpdates}
                  disabled={saving}
                  onChange={(value) =>
                    updatePreference("projectUpdates", value)
                  }
                />

                <PreferenceRow
                  label="Invoice Updates"
                  description="Invoice submissions, review decisions and rejections."
                  checked={notificationPreferences.invoiceUpdates}
                  disabled={saving}
                  onChange={(value) =>
                    updatePreference("invoiceUpdates", value)
                  }
                />

                <PreferenceRow
                  label="Payment Updates"
                  description="Verified payments and remittance notifications."
                  checked={notificationPreferences.paymentUpdates}
                  disabled={saving}
                  onChange={(value) =>
                    updatePreference("paymentUpdates", value)
                  }
                />

                <PreferenceRow
                  label="Dispute Updates"
                  description="Finance responses and dispute resolution progress."
                  checked={notificationPreferences.disputeUpdates}
                  disabled={saving}
                  onChange={(value) =>
                    updatePreference("disputeUpdates", value)
                  }
                />

                <PreferenceRow
                  label="Studio Announcements"
                  description="Operational updates and relevant studio notices."
                  checked={notificationPreferences.studioAnnouncements}
                  disabled={saving}
                  onChange={(value) =>
                    updatePreference("studioAnnouncements", value)
                  }
                />
              </div>

              <div className="mt-9 border-t border-[#E5E2DC] pt-8">
                <h3 className="font-serif text-xl text-[#171717]">
                  Delivery Channels
                </h3>

                <div className="mt-5 space-y-1">
                  <PreferenceRow
                    label="Email Notifications"
                    description="Receive supported account notifications by email."
                    checked={notificationPreferences.emailNotifications}
                    disabled={saving}
                    onChange={(value) =>
                      updatePreference("emailNotifications", value)
                    }
                  />

                  <PreferenceRow
                    label="WhatsApp Notifications"
                    description="Receive eligible notifications through the official business messaging channel."
                    checked={notificationPreferences.whatsappNotifications}
                    disabled={saving}
                    onChange={(value) =>
                      updatePreference("whatsappNotifications", value)
                    }
                  />
                </div>

                <p className="mt-5 text-xs leading-6 text-[#99958D]">
                  WhatsApp delivery requires valid consent and
                  an active, approved messaging integration.
                  Enabling this preference does not itself create
                  consent or guarantee message delivery.
                </p>
              </div>

              <button
                type="submit"
                disabled={saving}
                className="mt-8 inline-flex items-center gap-3 bg-[#171717] px-7 py-4 text-[10px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:opacity-50"
              >
                <Save size={15} />
                {saving ? "Saving..." : "Save Preferences"}
              </button>
            </form>
          </section>
        )}

        {/* Security */}
        {activeTab === "security" && (
          <section className="mt-8 space-y-6">
            <div className="border border-[#D8D6D0] bg-white p-6 md:p-9">
              <SectionHeading
                icon={<LockKeyhole size={19} />}
                title="Account Security"
              />

              <p className="mt-4 text-xs leading-7 text-[#77736C]">
                Protect your vendor account by keeping your
                credentials private and updating your password
                when necessary.
              </p>

              <div className="mt-7 flex flex-col justify-between gap-5 border-t border-[#E5E2DC] pt-7 sm:flex-row sm:items-center">
                <div className="flex items-start gap-4">
                  <KeyRound
                    size={20}
                    className="mt-1 text-[#A58A64]"
                  />

                  <div>
                    <h3 className="text-sm text-[#33312D]">
                      Password
                    </h3>

                    <p className="mt-2 text-xs text-[#99958D]">
                      Update your account password securely.
                    </p>
                  </div>
                </div>

                <button
                  type="button"
                  onClick={onChangePassword}
                  className="w-fit border border-[#D8D6D0] px-6 py-3 text-[10px] uppercase tracking-widest text-[#77736C] hover:border-[#A58A64] hover:text-[#A58A64]"
                >
                  Change Password
                </button>
              </div>

              <div className="mt-7 border-t border-[#E5E2DC] pt-7">
                <h3 className="text-sm text-[#33312D]">
                  Email Address Verification
                </h3>

                <p className="mt-2 text-xs leading-6 text-[#77736C]">
                  Your registered email is used for important
                  account communication. Changing it should require
                  verification of the new address.
                </p>

                <div className="mt-4 flex flex-col gap-3 sm:flex-row">
                  <button
                    type="button"
                    onClick={() => void handleEmailChange()}
                    disabled={saving}
                    className="w-fit bg-[#171717] px-6 py-3 text-[10px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:opacity-50"
                  >
                    Request Email Change
                  </button>
                </div>
              </div>
            </div>

            <div className="flex items-start gap-4 border border-[#D8D6D0] bg-white p-6">
              <ShieldCheck
                size={21}
                className="mt-1 shrink-0 text-[#A58A64]"
              />

              <div>
                <h3 className="text-sm text-[#33312D]">
                  Account Access Protection
                </h3>

                <p className="mt-2 text-xs leading-7 text-[#77736C]">
                  Account authentication, session expiry, access
                  revocation and vendor permissions must be
                  enforced by the backend.
                </p>
              </div>
            </div>
          </section>
        )}

        {/* Feedback */}
        {(validationError || error || successMessage) && (
          <div
            role={error || validationError ? "alert" : "status"}
            className={`mt-7 flex items-start gap-3 border p-5 ${
              error || validationError
                ? "border-[#E3C9C5] bg-[#FAF3F1] text-[#805B55]"
                : "border-[#D7E2D2] bg-[#F0F5EE] text-[#547A51]"
            }`}
          >
            {error || validationError ? (
              <AlertCircle size={18} className="mt-0.5 shrink-0" />
            ) : (
              <CheckCircle2 size={18} className="mt-0.5 shrink-0" />
            )}

            <p className="text-xs leading-6">
              {validationError || error || successMessage}
            </p>
          </div>
        )}

        {/* Footer */}
        <footer className="mt-12 border-t border-[#D8D6D0] pt-6">
          <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
            ARCHEON DESIGN STUDIO / CONFIDENTIAL VENDOR WORKSPACE
          </p>
        </footer>
      </div>
    </main>
  );
}

function SectionHeading({
  icon,
  title,
}: {
  icon: ReactNode;
  title: string;
}) {
  return (
    <div className="flex items-center gap-4">
      <span className="text-[#A58A64]">{icon}</span>

      <h2 className="font-serif text-2xl text-[#171717]">
        {title}
      </h2>
    </div>
  );
}

function Field({
  label,
  children,
}: {
  label: string;
  children: ReactNode;
}) {
  return (
    <label className="block">
      <span className="mb-3 block font-mono text-[9px] uppercase tracking-widest text-[#77736C]">
        {label}
      </span>

      {children}
    </label>
  );
}

function ReadOnlyField({
  label,
  value,
}: {
  label: string;
  value: string;
}) {
  return (
    <div>
      <p className="font-mono text-[9px] uppercase tracking-widest text-[#99958D]">
        {label}
      </p>

      <p className="mt-3 break-words text-sm text-[#33312D]">
        {value}
      </p>
    </div>
  );
}

function PreferenceRow({
  label,
  description,
  checked,
  disabled,
  onChange,
}: {
  label: string;
  description: string;
  checked: boolean;
  disabled: boolean;
  onChange: (checked: boolean) => void;
}) {
  return (
    <label className="flex cursor-pointer items-start justify-between gap-5 border-b border-[#E5E2DC] py-5 last:border-b-0">
      <span className="min-w-0">
        <span className="block text-sm text-[#33312D]">
          {label}
        </span>

        <span className="mt-2 block text-xs leading-6 text-[#99958D]">
          {description}
        </span>
      </span>

      <input
        type="checkbox"
        checked={checked}
        disabled={disabled}
        onChange={(event) => onChange(event.target.checked)}
        className="mt-1 h-4 w-4 shrink-0 accent-[#A58A64]"
      />
    </label>
  );
}

"use client";

import { useMemo, useState, type FormEvent } from "react";
import {
  LifeBuoy,
  Plus,
  Search,
  MessageSquare,
  Clock3,
  CheckCircle2,
  AlertCircle,
  FileText,
  Building2,
  IndianRupee,
  ShieldCheck,
  ArrowUpRight,
  X,
} from "lucide-react";

export type VendorSupportCategory =
  | "Project Assignment"
  | "Invoice & Billing"
  | "Payment Issue"
  | "Cash Settlement"
  | "Dispute"
  | "Account Access"
  | "Documents"
  | "Other";

export type VendorSupportPriority =
  | "Low"
  | "Normal"
  | "High"
  | "Urgent";

export type VendorSupportStatus =
  | "Open"
  | "Assigned"
  | "In Progress"
  | "Awaiting Vendor Response"
  | "Resolved"
  | "Closed";

export interface VendorSupportMessage {
  id: string;
  message: string;
  senderLabel: string;
  sentAt: string;
  isVendorMessage: boolean;
}

export interface VendorSupportTicket {
  id: string;
  referenceCode: string;
  subject: string;
  category: VendorSupportCategory;
  priority: VendorSupportPriority;
  status: VendorSupportStatus;
  description: string;
  createdAt: string;
  updatedAt: string;
  relatedReference?: string;
  assignedTeam?: string;
  messages: VendorSupportMessage[];
}

export interface VendorSupportRequest {
  subject: string;
  category: VendorSupportCategory;
  priority: VendorSupportPriority;
  relatedReference: string;
  description: string;
}

interface VendorSupportCentreProps {
  tickets: VendorSupportTicket[];
  loading?: boolean;
  submitting?: boolean;
  error?: string;
  onCreateTicket: (
    request: VendorSupportRequest
  ) => void | Promise<void>;
  onOpenTicket?: (ticket: VendorSupportTicket) => void;
  onRefresh?: () => void;
}

type TicketFilter = "All" | VendorSupportStatus;

const CATEGORIES: VendorSupportCategory[] = [
  "Project Assignment",
  "Invoice & Billing",
  "Payment Issue",
  "Cash Settlement",
  "Dispute",
  "Account Access",
  "Documents",
  "Other",
];

const FILTERS: TicketFilter[] = [
  "All",
  "Open",
  "Assigned",
  "In Progress",
  "Awaiting Vendor Response",
  "Resolved",
  "Closed",
];

function formatDate(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
}

function getStatusStyle(status: VendorSupportStatus) {
  switch (status) {
    case "Resolved":
      return "bg-[#EAF1E8] text-[#547A51]";

    case "Closed":
      return "bg-[#ECEAE5] text-[#77736C]";

    case "In Progress":
    case "Assigned":
      return "bg-[#EAF0F5] text-[#58738C]";

    case "Awaiting Vendor Response":
      return "bg-[#F4EFE2] text-[#94743F]";

    default:
      return "bg-[#F8EAE7] text-[#9A5147]";
  }
}

function getPriorityStyle(priority: VendorSupportPriority) {
  switch (priority) {
    case "Urgent":
      return "bg-[#F8EAE7] text-[#9A5147]";

    case "High":
      return "bg-[#F4EFE2] text-[#94743F]";

    default:
      return "bg-[#ECEAE5] text-[#77736C]";
  }
}

function renderCategoryIcon(category: VendorSupportCategory, size: number) {
  switch (category) {
    case "Project Assignment":
      return <Building2 size={size} />;

    case "Invoice & Billing":
    case "Documents":
      return <FileText size={size} />;

    case "Payment Issue":
    case "Cash Settlement":
      return <IndianRupee size={size} />;

    case "Dispute":
      return <AlertCircle size={size} />;

    case "Account Access":
      return <ShieldCheck size={size} />;

    default:
      return <LifeBuoy size={size} />;
  }
}

export function VendorSupportCentre({
  tickets,
  loading = false,
  submitting = false,
  error,
  onCreateTicket,
  onOpenTicket,
  onRefresh,
}: VendorSupportCentreProps) {
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState<TicketFilter>("All");

  const [subject, setSubject] = useState("");
  const [category, setCategory] =
    useState<VendorSupportCategory>("Other");
  const [priority, setPriority] =
    useState<VendorSupportPriority>("Normal");
  const [relatedReference, setRelatedReference] = useState("");
  const [description, setDescription] = useState("");
  const [validationError, setValidationError] = useState("");

  const openCount = tickets.filter(
    (ticket) =>
      ticket.status !== "Resolved" &&
      ticket.status !== "Closed"
  ).length;

  const resolvedCount = tickets.filter(
    (ticket) => ticket.status === "Resolved"
  ).length;

  const filteredTickets = useMemo(() => {
    const query = search.trim().toLowerCase();

    return tickets.filter((ticket) => {
      const matchesSearch =
        !query ||
        ticket.referenceCode.toLowerCase().includes(query) ||
        ticket.subject.toLowerCase().includes(query) ||
        ticket.category.toLowerCase().includes(query) ||
        (ticket.relatedReference ?? "").toLowerCase().includes(query);

      const matchesFilter =
        filter === "All" || ticket.status === filter;

      return matchesSearch && matchesFilter;
    });
  }, [tickets, search, filter]);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (submitting) return;

    if (subject.trim().length < 5) {
      setValidationError(
        "Enter a subject containing at least 5 characters."
      );
      return;
    }

    if (description.trim().length < 20) {
      setValidationError(
        "Please describe your issue in at least 20 characters."
      );
      return;
    }

    setValidationError("");

    await onCreateTicket({
      subject: subject.trim(),
      category,
      priority,
      relatedReference: relatedReference.trim(),
      description: description.trim(),
    });

    // The parent should close this form only after
    // the backend confirms successful ticket creation.
  }

  function resetForm() {
    setSubject("");
    setCategory("Other");
    setPriority("Normal");
    setRelatedReference("");
    setDescription("");
    setValidationError("");
    setShowCreateForm(false);
  }

  if (loading) {
    return (
      <div className="min-h-80 bg-[#F2F0EB] p-8">
        <p className="text-sm text-[#77736C]">
          Loading support records...
        </p>
      </div>
    );
  }

  return (
    <main className="min-h-screen bg-[#F2F0EB] px-5 py-10 md:px-10 md:py-14">
      <div className="mx-auto max-w-7xl">

        {/* Header */}
        <header className="border-b border-[#D8D6D0] pb-9">
          <p className="font-mono text-[10px] uppercase tracking-[0.2em] text-[#A58A64]">
            Vendor Portal / Support
          </p>

          <div className="mt-5 flex flex-col justify-between gap-6 md:flex-row md:items-end">
            <div>
              <h1 className="font-serif text-4xl text-[#171717] md:text-5xl">
                Help & Support
              </h1>

              <p className="mt-4 max-w-2xl text-sm leading-7 text-[#77736C]">
                Contact the studio for assistance with assignments,
                invoices, payments, documents and account access.
              </p>
            </div>

            <button
              type="button"
              onClick={() => setShowCreateForm(true)}
              className="inline-flex w-fit items-center gap-3 bg-[#171717] px-7 py-4 text-[10px] uppercase tracking-widest text-white hover:bg-[#A58A64]"
            >
              <Plus size={16} />
              Create Support Ticket
            </button>
          </div>
        </header>

        {/* Summary */}
        <section className="mt-9 grid grid-cols-1 gap-px border border-[#D8D6D0] bg-[#D8D6D0] sm:grid-cols-3">
          <SummaryCard
            label="Total Tickets"
            value={String(tickets.length)}
            icon={<LifeBuoy size={19} />}
          />

          <SummaryCard
            label="Open Tickets"
            value={String(openCount)}
            icon={<Clock3 size={19} />}
          />

          <SummaryCard
            label="Resolved Tickets"
            value={String(resolvedCount)}
            icon={<CheckCircle2 size={19} />}
          />
        </section>

        {/* Global Error */}
        {error && (
          <div
            role="alert"
            className="mt-7 flex items-start gap-3 border border-[#E3C9C5] bg-[#FAF3F1] p-5"
          >
            <AlertCircle
              size={19}
              className="mt-0.5 shrink-0 text-[#9A5147]"
            />

            <p className="text-xs leading-6 text-[#805B55]">
              {error}
            </p>
          </div>
        )}

        {/* Create Ticket Form */}
        {showCreateForm && (
          <section className="mt-9 border border-[#D8D6D0] bg-white p-6 md:p-9">
            <div className="flex items-start justify-between gap-5">
              <div>
                <p className="font-mono text-[9px] uppercase tracking-widest text-[#A58A64]">
                  New Support Request
                </p>

                <h2 className="mt-3 font-serif text-3xl text-[#171717]">
                  Describe Your Issue
                </h2>
              </div>

              <button
                type="button"
                onClick={resetForm}
                disabled={submitting}
                aria-label="Close support form"
                className="text-[#77736C] hover:text-[#171717] disabled:opacity-40"
              >
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="mt-8 space-y-6">
              <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                <Field label="Issue Subject" required>
                  <input
                    value={subject}
                    onChange={(event) => setSubject(event.target.value)}
                    placeholder="Briefly describe the issue"
                    maxLength={150}
                    required
                    disabled={submitting}
                    className="vendor-support-input"
                  />
                </Field>

                <Field label="Support Category" required>
                  <select
                    value={category}
                    onChange={(event) =>
                      setCategory(
                        event.target.value as VendorSupportCategory
                      )
                    }
                    disabled={submitting}
                    className="vendor-support-input"
                  >
                    {CATEGORIES.map((item) => (
                      <option key={item} value={item}>
                        {item}
                      </option>
                    ))}
                  </select>
                </Field>

                <Field label="Priority" required>
                  <select
                    value={priority}
                    onChange={(event) =>
                      setPriority(
                        event.target.value as VendorSupportPriority
                      )
                    }
                    disabled={submitting}
                    className="vendor-support-input"
                  >
                    <option value="Low">Low</option>
                    <option value="Normal">Normal</option>
                    <option value="High">High</option>
                    <option value="Urgent">Urgent</option>
                  </select>
                </Field>

                <Field label="Related Reference (Optional)">
                  <input
                    value={relatedReference}
                    onChange={(event) =>
                      setRelatedReference(event.target.value)
                    }
                    placeholder="Invoice, project or settlement reference"
                    maxLength={100}
                    disabled={submitting}
                    className="vendor-support-input"
                  />
                </Field>
              </div>

              <Field label="Issue Description" required>
                <textarea
                  value={description}
                  onChange={(event) => setDescription(event.target.value)}
                  placeholder="Explain the problem, what happened and what assistance you need..."
                  rows={6}
                  maxLength={4000}
                  required
                  disabled={submitting}
                  className="vendor-support-input resize-y"
                />

                <p className="mt-2 text-right font-mono text-[9px] text-[#99958D]">
                  {description.length}/4000
                </p>
              </Field>

              <p className="text-xs leading-6 text-[#99958D]">
                Do not include passwords, authentication codes,
                bank credentials or unrelated client-confidential
                information in your support request.
              </p>

              {validationError && (
                <div
                  role="alert"
                  className="flex items-start gap-3 border border-[#E3C9C5] bg-[#FAF3F1] p-4"
                >
                  <AlertCircle
                    size={17}
                    className="mt-0.5 shrink-0 text-[#9A5147]"
                  />

                  <p className="text-xs text-[#805B55]">
                    {validationError}
                  </p>
                </div>
              )}

              <div className="flex flex-col-reverse justify-end gap-3 sm:flex-row">
                <button
                  type="button"
                  onClick={resetForm}
                  disabled={submitting}
                  className="border border-[#D8D6D0] px-7 py-4 text-[10px] uppercase tracking-widest text-[#77736C] disabled:opacity-40"
                >
                  Cancel
                </button>

                <button
                  type="submit"
                  disabled={submitting}
                  className="bg-[#171717] px-8 py-4 text-[10px] uppercase tracking-widest text-white hover:bg-[#A58A64] disabled:opacity-50"
                >
                  {submitting ? "Submitting..." : "Submit Support Request"}
                </button>
              </div>
            </form>
          </section>
        )}

        {/* Ticket List */}
        <section className="mt-12">
          <div className="flex flex-col justify-between gap-4 border-b border-[#D8D6D0] pb-5 md:flex-row md:items-end">
            <div>
              <p className="font-mono text-[10px] uppercase tracking-widest text-[#A58A64]">
                Support Management
              </p>

              <h2 className="mt-3 font-serif text-3xl text-[#171717]">
                Your Support Tickets
              </h2>
            </div>

            {onRefresh && (
              <button
                type="button"
                onClick={onRefresh}
                className="font-mono text-[10px] uppercase tracking-widest text-[#77736C] hover:text-[#A58A64]"
              >
                Refresh Tickets
              </button>
            )}
          </div>

          {/* Search */}
          <div className="relative mt-6">
            <Search
              size={17}
              className="absolute left-4 top-1/2 -translate-y-1/2 text-[#99958D]"
            />

            <input
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Search ticket, subject or reference..."
              aria-label="Search support tickets"
              className="h-12 w-full border border-[#D8D6D0] bg-white pl-11 pr-4 text-sm text-[#33312D] outline-none focus:border-[#A58A64]"
            />
          </div>

          {/* Filters */}
          <div className="mt-5 flex gap-2 overflow-x-auto pb-3">
            {FILTERS.map((item) => (
              <button
                key={item}
                type="button"
                onClick={() => setFilter(item)}
                aria-pressed={filter === item}
                className={`shrink-0 border px-4 py-3 text-[9px] uppercase tracking-widest ${
                  filter === item
                    ? "border-[#171717] bg-[#171717] text-white"
                    : "border-[#D8D6D0] bg-white text-[#77736C] hover:border-[#A58A64]"
                }`}
              >
                {item === "All" ? "All Tickets" : item}
              </button>
            ))}
          </div>

          {/* Results */}
          <div className="mt-5 space-y-4">
            {filteredTickets.length === 0 ? (
              <div className="border border-[#D8D6D0] bg-white px-6 py-16 text-center">
                <LifeBuoy
                  size={28}
                  strokeWidth={1.3}
                  className="mx-auto text-[#A58A64]"
                />

                <h3 className="mt-5 font-serif text-2xl text-[#171717]">
                  No support tickets found
